window.HB_TR["psalms"]["ks"]=["1. بابرکت چُھہ سُہ انسان یُس نہٕ بےٚ دیندارن ہٕندِس مشورس مَنٛز پکان چُھ، تہٕ نہ چُھ گۅنہگارن ہٕندِس وتہِ منز رُکاوٹ روزان، تہٕ نہ چُھہ حقارت کرن والٮ۪ن ہٕنزِ نشستس پیٹھ بِہتھ۔ {بدکار: یا بدکار}\n2.\\tمگر تسٕنز خوشی چھیہ خداوند سٕندِس شریعتس مَنٛز۔ تہٕ سُہ چُھ پننِس شریعتس مَنٛز دۅہ رات مراقبہٕ کران۔ \n3. تہٕ سُہ گژھہِ أکِس کُلِس ہٕندۍ پٲٹھۍ، یُس آبہٕ کِس دریاوَس سٍتـ̡ لگاونہٕ آمُت چُھ، یُس پننِس موسمس مَنٛز پھل دِیہِ۔ تٔمۍ سُند پنہٕ تہٕ گژھہِ نہٕ مرزاونہٕ۔ تہٕ یُس تہِ کرِ سُہ گژھہِ پھۅلُن۔ {مرزُن: حب۔ ختم گٔژھِ}\n4.\\tبدکار {چھہ} چھہ نہ تتھہ پاٹھۍ یُس واو کڈان چھہ۔ \n5. تێمہِ کِنۍ گژھِ نہٕ بدکار فیصلس مَنٛز کھڑا گژھُن، تہٕ گۅنہگار گژھِ نہٕ نیکوکارن ہٕنزِ جماعتس مَنٛز کھڑا سپدٕنـ̡ ۔ \n6.\\tکیازِ خداوند چُھ نیکوکارن ہٕنز وتھ زانان، مگر بدکارن ہٕنز وتھ گژھہِ ختم۔","1.\\tکافر کیازِ چھہِ غصہ کران تہ لوکھ چھہِ اکھ فضول چیز تصور کران؟ {غصہ: یا، ہنگامہ خیز جمع سپدان} {تصور: ہیب۔ مراقبہ}\n2. زمینہِ ہٕندِس بادشاہس کٔر پان مقرر تہٕ حُکُمران چھِ رٔلِتھ رٔلِتھ رٔلِتھ تہٕ تٔمۍ سٕندِس مسح شدٕ سٍتـ̡ رٔلِتھ مشورٕ کٔرِتھ، {وَنُن}۔ \n3. أسۍ پھٔٹرٲوِو تِہٕنزِ بندٕ ژٔٹِتھ تہٕ تِہٕنزِ رَزِ اسہِ نِش پھٔٹِو۔ \n4. یُس آسمانس منز بِہتھ آسہِ سُہ اسُن: خداوند کرِ تِمن طنز کرنہٕ۔ \n5. تیلہ کرِ سُہ پننِس غصس منز تِمن سٍتـ̡ کتھ کرنہٕ، تہٕ تِمن ہٕندِس غصس سٍتـ̡ پریشان کرُن۔ {vex: یا، مصیبت}\n6. توتہِ چُھس میہ پنُن بادشاہ پننہِ مقدس پہاڑس پیٹھ تھوومُت۔ {سیٹ: ہیب۔ مسح کٔرِتھ} {پیٹھ...: ہیب۔ زیونس پیٹھ، میانہِ پاکیزگی ہٕندِس پہاڑس پیٹھ}\n7. بہٕ کَرٕ حکمُک اعلان: خداوند چُھس مےٚ ووٚنمُت، تہٕ چُھکھ میٲنۍ نیٚچُو۔ از دۅہہ چُھس مے ژے زامُت۔ {فرمان: یا، اَکہِ حکمہٕ خٲطرٕ}\n8.\\tمیہ منگُن، تہٕ بہٕ دِیہ ژے تہٕ تُہند وراثت، تہٕ زمینہِ ہٕندِس اندِس حصس مۅکھہٕ۔ \n9. ژے پھُٹرٲوِو تِم ششتٕرِ سٕندِ لورِ سٍتـ̡ ۔ ژے کٔرِو تِم ٹُکرٕ ٹُکرٕ کٔرِتھ ۔ \n10. تێمہِ کِنۍ بٔنِو اے بادشاہو، اے زمینہِ ہٕندِس قاضیَن ہٕنز تعلیم دِنہٕ۔ \n11. خوفہٕ سٍتـ̡ کٔرِو خداوند سٕنز خدمت تہٕ تھرتھرٕ سٍتـ̡ شاد۔ \n12. نیچوِس بوسہ دِیُن، یێلہِ سُہ غصہٕ گژھہِ تہٕ تٔمِس وتہِ سٍتـ̡ ختم گٔژھِو، یێلہِ تٔمۍ سُند غصہٕ رژھ کھنڈ دِنہٕ ییہِ۔ تِم چھِ سُہ سارِنٕے سٍتـ̡ بابرکت یِمو أمِس پیٹھ بھروسہٕ چُھ کٔرِتھ۔","1. [داؤد سُند زبور، ییلہ سُہ پننِس نیچوِس ابسالوم نِش ژوٚل۔] خداوند، تِمو کِتھہ کٔنۍ چُھہ میہ پریشان کران! واریاہ چِھہ یِم میانہِ خلاف کھڑا سپدان چھِ۔ \n2.\\tواریاہ چھہِ یم میانہِ روحس متعلق ونان چھہِ، خدایہ سندِ خاطرہ چھہ نہ کانہہ مدد۔ سیلہ۔ \n3.\\tمگر ژے اے خدا، میانہِ خاطرہ اکھ ڈھال۔ میٲنۍ جلال تہٕ میانہِ کلہٕ تُلُن۔ {for: or, about}\n4. میہ کٔر پننہِ آوازِ سٍتـ̡ خداوند سٍتـ̡ فریاد تہٕ تٔمۍ بوز میہ پننہِ مقدس بالہٕ پیٹھ۔ سیلہ۔ \n5. بہٕ لوٚگ میہ لوٚگ تہٕ شوٚنگ۔ بہٕ ووت بیدار۔ کیازِ خداوند دِژ میہ رژھراونہٕ۔ \n6. بہٕ گژھٕ نہٕ دَہ ساسہٕ لُکن سٍتـ̡ کھوژان، یِمو میہ خٕلاف {پانہٕ} دِژمٕژ چھِ۔ \n7. اے خداوند، وۅتھٕ وُتھ؛ اے خدایہ، مے بچاو، کیازِ ژے چھُکھ میانین سارِنٕے دُشمن گالِس ہٕندِس أڈجہِ سٍتـ̡ مار دِژمُت۔ ژے چھُکھ کافرن ہٕندِ دند پھُٹرٲومٕتۍ۔ \n8. نجات چُھہ خداوند سٕندِس سٍتـ̡ چُھہ تُہٕندِس لُکہٕ سٍتـ̡ برکت دِنہٕ آمُت۔ سلہٕ۔","1. [نیگینوتس پیٹھ چیف موسیقار سٕندِس زبورس سٍتۍ، داؤد سُند زبور۔] اے میانہِ نیکی ہٕندِس خدایہِ سٕندِس خداہس سٍتـ̡ بوز مے بوزو۔ میانہِ سٍتـ̡ کٔر رحم تہٕ بوز میٲنۍ دُعا۔ {سردار...: یا، نگران} {کرُن...: یا، میانہِ سٍتـ̡ کرو مہربانی}\n2.\\tاے انسانو اولاد، کوتاہ کالس کرو میٲنۍ شان شرمندگی؟ {کتھ کال} کرو ژیہ فضول محبت، {تہٕ} لیز دِنہٕ پتہٕ؟ سیلہ۔ \n3. مگر زان زِ خداوند چُھ پانس خٲطرٕ خدایہ سُہ الگ کورمُت: خداوند بوزِ یێلہِ بہٕ أمِس بلاو۔ \n4.\\tخوفہٕ سٍتـ̡ کھڑا گژھُن، تہٕ گۅناہ کٔرِو نہٕ: پننِس بسترس پیٹھ کٔرِو پنُن دِل سٍتـ̡ کتھ باتھ تہٕ خاموش روزُن۔ سیلاہ۔ \n5. نیکی ہٕنز قربانی پیش کٔرِو، تہٕ خدایس پیٹھ تھٲوِو پَنُن بھروسہٕ۔ \n6.\\tواریاہ چھہِ ونان زِ اسہِ کُس کرِ اسہِ نیکی ہاونہٕ؟ اے خداوند، تُل پنُن گاش اسہِ پیٹھ۔ \n7.\\tژے کٔر میٲنس دلس منز خوشی تراونہٕ، تمہ وقتہٕ کھوتہٕ زیادٕ ییلہ تِہُند مَکٲے تہٕ تِہُند شرابُک ہُرٮ۪ر گوٚو۔ \n8. بہٕ کرٕ دۅشوے سُہ سُکوٗن سٍتـ̡ تہٕ شۄنگنہٕ، یێلہِ چُھہ تُہٕندِس سٍتـ̡ رٔٹِتھ روزُن، یێلہِ چُھہ خداوند، تُہٕندِس سٍتـ̡ چُ","1. [نیہلوتھس پیٹھ چیف موسیقار سُند، داؤد سُند زبور۔] اے خداوند، میانہِ مراقبس پیٹھ غور کرُن۔ \n2. میانہِ فریاد سٕنز آواز بوزو، میانہِ بادشاہ تہٕ میانہِ خدایہ سٕنز آواز، تکیازِ بہٕ کٔرٕ ژے خٲطرٕ دُعا۔ \n3. اے خداوند، میٲنۍ آواز گژھہِ صبحٲے بوزنہٕ۔ صُبحَس کَرٕ بہٕ ژے کُن دُعا دِنہٕ تہٕ تھوٚد کُن نظر۔ \n4. تِکیازِ تُہۍ چُھہ نہٕ تِژھ خدا یُس بُردی سٍتـ̡ خوش آسہِ، تہٕ نہ چُھہ بُرٕ سٍتـ̡ روزُن۔ \n5.\\tبیوقوف گژھِ نہٕ تۅہہِ ہٕندِس نظرس منز کھڑا روزُن: توے چھُکھ بدکار سارِنٕے کارکُن کٔرِتھ۔ {منز...: ہیب۔ تہنزِ نظرن برونہہ کُن}\n6. تُہۍ کرِ تِم تباہ یِم کتھ کران چھِ: خداوند کرِ خونریز تہٕ دھوکہ دِنہٕ وٲلِس انسانس نفرت۔{خون...: ہیب۔ خونُک تہٕ دھوکہٕ دِنُک انسان}\n7. مگر بہٕ یێلہِ تہٕ تێہٕندِس مُقدس مندرس مَنٛز یِنہٕ تہٕ تێنہِ ہٕندِس خوفس سٍتـ̡ کٔرٕ بہٕ تُہٕندِس مُقدس مندرس کُن عبادت کرنہٕ۔ {تُہند پاک...: ہیب۔ تیری پاکیزگی ہُند مندر}\n8. اے خداوند، میانین دُشمنن ہٕندِس سٍتـ̡ پننہِ نیکی مَنٛز رہنمٲیی۔ میانہِ بُتھِس برونہہ کُن کٔرِو پنٕنۍ وتھ سید۔ {میٲنۍ ...: ہیب۔ یِم میہ وچھان چھِ}\n9.\\tتِمن ہٕندِس ٲسس مَنٛز چُھنہٕ کانہہ وفاداری؛ تِہُند باطنی حصہ {چُھ} سٮ۪ٹھاہ بد کاری؛ تِہُند حلق {چُھ} یُس مقبرٕ چُھ، تِم چھِ پننہِ زبانہِ سٍتـ̡ خوشامد کران۔ {وفاداری: یا، سُہ چُھہ بٔرِتھ} {تِہٕندِس ٲسس﴾ ﴿تِہُند ٲسُن}\n10. اے خدایہ، تِم کرو تِم تباہ تِمن ہٕندِس مشورس سٍتـ̡ دِیُن تِمن کٔرِو تِمن ہٕندِس بٔڑِس سٍتـ̡ کٔرِتھ دِنہٕ۔ تِکیازِ تِمو کٔرِو تۅہہِ سٍتـ̡ بغاوت کٔرمٕژ۔ {تباہ کٔرِو...: یا، تِمن ہٕندِس مشورٕ سٍتـ̡ کٔرِو مُجرِم} {by...: یا، تِمن ہٕندِس مشورٕ سٍتـ̡\n11.\\tمگر یِم سارِنٕے تۅہہِ پیٹھ بھروسہٕ تھاوان چھِ، تِم گژھن ہمیشہ خوشی سان کرٛٮ۪کہٕ دِن، کیازِ تُہۍ چھِو تِمن ہٕندِس رٲچھ کران، تِم تہِ گژھن تُہٕندِس ناوَس سٍتـ̡ خوش گٔژھنـ̡ ۔ {بچاو...: ہیب۔ پردٕ کٔرِو، یا تِمن ہٕنز رٲچھ کٔرِو}\n12.\\tتۂ چُھہ خداوند، صالحن سٍتـ̡ برکت دِنہٕ۔ عنایت سٍتـ̡ کٔرِو تٔمِس سٍتـ̡ ڈھالہٕ سٍتـ̡ رٔٹِتھ ۔ {کمپاس: حب۔ تاج}","1. [نیگینوتھس پیٹھ شیمینتھس پیٹھ چیف موسیقارس تام، داؤد سُند زبور۔] اے خداوند، میہ کٔر نہ پننہِ غصہٕ سٍتـ̡ ملامت تہٕ نہ کٔر میہ پننہِ گرم ناراضگی سٍتـ̡ سزا دِنہٕ۔ {سردار...: یا، نگران} {شیمینتھ: یا، ٲٹھم}\n2. اے خداوند، میہ پیٹھ رحم کرُن؛ تکیازِ بہٕ چُھس کمزور: اے خداوند، میہ کر شفا۔ تکیازِ میانہِ اڈجہِ چھیہ پریشان۔ \n3.\\tمیون روح تہِ چھہ پریشان: مگر ژے اے خداوند، کوتاہ وقت؟ \n4.\\tاے خداوند، میانہِ روح بچاو: اے پننہِ رحمتہٕ خٲطرٕ بچاو۔ \n5.\\tتکیازِ مرنس منز چھہ نہ تۅہہ کانہہ یاد: قبرِ منز کُس کرِ تۅہہ شکر گزار؟ \n6. بہٕ چُھس پننہ آہ وُپھ سٍتۍ تھوٚکمت سارِوٕے رٲژ چھُس بہٕ پنُن بسترہ ژھارنہٕ خٲطرٕ بناوان؛ بہٕ چھُس پنُن کاؤچ پننیو اشو سٍتۍ آب دوان۔ {سارِنٕے...: یا، پرٮ۪تھ رٲژ}\n7. میٲنۍ أچھ چھِ غم کِنۍ کھٮ۪نہٕ آمٕژ۔ یہِ چھُ میانٮ۪ن سارِنٕے دُشمنن ہٕندِ وجہ سٍتۍ وٲنسہٕ گٔژھان۔ \n8. میہ نِش نیرِو، اے بدکار سارِوٕے کارکُن، تِکیازِ خداوند چُھ میانہِ روونٕچ آواز بوزمٕژ۔ \n9. خداوند چُھ میٲنۍ دُعا بوزمُت۔ خداوند کرِ میٲنۍ دُعا قبول۔ \n10.\\tمیانین سارِنٕے دُشمن گژھن شرمندہ تہٕ پریشان گژھن: تِم گژھن اچانک واپس یِن شرمندٕ۔","1. [داؤد سُند شِگائیون، یُس تٔمۍ خداوند سٕندِ خٲطرٕ گیوٚو، کُش بنیمنی سٕندِس کلامس متعلق۔] اے خدایہ میانہِ خدا، بہٕ چُھس توے پیٹھ بھروسہ کران: تِمن سارِنٕے نِش بچاوُن یِم مےٚ ستاونہٕ چِھ، تہٕ کٔرِکھ مےٚ نجات دِنہٕ: {لفظ: یا، کاربار}\n2.\\tیُس نہ میون روح شیرِ ہٕندۍ پٲٹھۍژٔٹِتھ تہٕ {یہ} چھُنہٕ کانہہ تہِ دِنہٕ خٲطرٕ۔ {نہٕ...: ہیب۔ نجات دِنہٕ وول نہٕ}\n3.\\tاے خدایہ، اگر میہ یہ کورمُت آسہِ؛ اگر میانین اتھن منز بدکاری آسہِ؛ \n4.\\tاگر میہ تس بد کار دِتھ یُس میہ سٍتۍ امن اوس۔ (آ، میہ چھہ تس نجات دِژمُت یُس بلا وجہ میون دشمن چھُ:)\n5.\\tدُشمن دِیُن میانہِ روحس ستاونہٕ تہٕ نِنہٕ یُن۔ آ، سُہ دِیُن میانہِ زُو زمینہِ پیٹھ، تہٕ میٲنۍ عزتُک رٔٹِتھ تھاوُن۔ سیلاہ۔ \n6. اے خداوند، پننِس غصس مَنٛز، میانین دُشمنن ہٕندِس غصہٕ سٍتـ̡ تھوٚد پَنُن پان تھوٚد: تہٕ بیدار گژھ میانہِ خٲطرٕ {یُس} فٲصلہٕ {یُس} یُس ژے حُکُم دِژمُت چُھ۔ \n7.\\tیِتھے پٲٹھـ̡ گژھن لُکن ہٕنزِ جماعت تۅہہِ سٍتـ̡ اندۍ پکھۍ گٔژھِتھ، تێمہِ مۅکھہٕ گژھہِ تۅہہِ ہٕندِ خٲطرٕ واپس۔ \n8. خداوند کرِ لوکن ہُند فیصلہٕ: اے خداوند، میانہِ نیکی مُطٲبق تہٕ میانہِ دیانت مُطٲبق کٔرِو میانہِ دیانت مُطٲبق۔ \n9. اے بدکارن ہٕنز بدکاری گژھہِ ختم۔ مگر نیک پرست کرو قایم کرنہٕ: کیازِ نیک خدا چُھ دلن تہٕ لگام آزماوان۔ \n10. میون دفاع چُھہ خدایہِ سُند، یُس دِلس منز سیدِ پٲٹھـ̡ بچاوان چُھ۔ {میا...: حب۔ میون بکلر چُھ خدایہ سٍتـ̡\n11. خدا چُھ نیکین سٍتـ̡ انصاف کران، تہٕ خدا چُھ پریتھ دۅہہ بدکارن سٍتـ̡ ناراض گژھان۔ {قاضی...: یا، چُھہ اکھ نیک قاضی}\n12. اگر نہٕ سُہ پھیرِ، سُہ کٔرِن تلوار۔ تٔمۍ کٔر کمان تہٕ تیار کٔرِتھ۔ \n13. تٔمۍ چھِ أمِس خٲطرٕ موتٕکۍ اوزار تہِ تیار کٔرۍمٕتۍ۔ سُہ چُھ پَنٕنہِ تیر ظالمن خلاف مقرر کران۔ \n14.\\tوچھ سُہ چُھ بدکاری سٍتـ̡ مُشکِل کٔرِتھ، تہٕ کٔرِن اپُز پٲدٕ کٔرِتھ۔ \n15.\\tتٔمۍ بنوو اکھ کھۄد، تہٕ کھٔنِتھ کھٔنِتھ پیوٚو کھۄلہِ مَنٛز۔ {تٔمۍ بنوو اکھ کھۄد: ہیب۔ تٔمۍ کٔر اکھ کھۄد}\n16.\\tتٔمۍ سٕنز شرارت گژھہِ پننِس کلس پیٹھ واپس، تہٕ تٔمۍ سُند تشدد گژھہِ تٔمۍ سٕندِس پانس پیٹھ واپس۔ \n17. بہٕ کَرٕ خداوند سٕنزِ نیکی مُطٲبق حمد تہٕ گٮ۪وٕ خداوند سٕندِ ناوٕچ تعریف۔","1. [گِٹیتھس پیٹھ چیف موسیقار سُند، داؤد سُند زبور۔] اے خداوند سٲنِس خداوند، سارِنٕے زمینس مَنٛز چُھ تُہند ناو کوتاہ بہتر! یٔمۍ چُھ پنُن جلال آسمانس پیٹھٕ تھوومُت۔ \n2.\\tبچن تہٕ دۄدٕ دِنہٕ والٮ۪ن ہٕندِس ٲسِس منزٕ چُھہ ژے دُشمن ہٕندِس دُشمن سٍتـ̡ طاقت مقرر کٔرمٕژ، یُتھ ژے ہێکہِ دُشمن تہٕ انتقام کرن وٲلِس سٍتـ̡ وُنہِ تہِ ہى۪کان۔ {مقرر کرنہٕ: ہیب۔ بُنیاد دِنہٕ}\n3. ییلہ بہٕ چُھس چانہِ آسمانس سٍتـ̡ تہٕ چُھس چُھہ تُہٕندِس آسمانس سٍتـ̡ وُچھان ، یُس ژے مقرر کورمُت چُھ، \n4.\\tانسان کیا چُھ، یُس تُہۍ أمِس یاد تھاوان چھُو؟ تہٕ انسان سُند نیٚچُو، یُس تہٕ ژٕ أمِس نِش گژھُن؟ \n5.\\tتکیازِ ژے چھُکھ سُہ فرشتن نِش رژھ کھنڈ پست بناومُت تہٕ تٔمِس جلال تہٕ عزتُک تاج لاگُن۔ \n6.\\tژے چُھہ أمِس پاگل کٔرِتھ پننین اتھن ہٕندِس کامہِ پیٹھ غلبہٕ حٲصل کرنہٕ خٲطرٕ۔ ژے چھُکھ سارِنٕے چیز تٔمۍ سٕندِس قدمن تل تھٲومٕتۍ: \n7.\\tسارِنٕے کۅکرِ تہٕ بیل، آ، تہٕ کھاہن ہٕندِس درندٕ۔ {سٲری ...: ہیب۔ ریوڑ تہٕ بیلہٕ سارِنٕے ہٕندِس دامنس منز}\n8.\\tہوہُک جاناوار تہٕ سمندرٕچ گاڈ، {تہٕ یُس تہِ} چُھ سمندرن ہٕنزِ وتن پیٹھ نیران۔ \n9. اے خداوند، سارِنٕے زمینس مَنٛز کوتاہ عظیم چُھہ تُہند ناو!","1.\\t[مُثلبن پیٹھ چیف موسیقارس سٍتۍ، داؤد سُند زبور۔] اے خداوند، بہٕ کٔرٕ ژے سٍتـ̡ سٲرۍسٕے دِلہٕ سٍتـ̡ تعریف۔ بہٕ کٔرٕ چانہِ سارِنٕے حیرت انگیز کامہِ ہاونہٕ۔ \n2. بہٕ کَرٕ ژے سٕندِس سٍتـ̡ خۅش تہٕ خۅش گٔیہِ: بہٕ گٮ۪وٕ چانہِ ناوٕچ تعریف، اے اعلیٰ ترین ۔ \n3.\\tییلہ میٲنۍ دُشمن پتھ کُن پھیرِ، تِم گژھن تۅہہِ ہٕندِس حضورس سٍتـ̡ پۯاونہٕ تہٕ ہلاک گٔژھن۔ \n4. کیازِ ژے چُھکھ میون حق تہٕ میون مقصد برقرار تھوومُت۔ ژے چُھکھ تختس پیٹھ صحیح فیصلہ کٔرِتھ۔ {برقرار تھوومُت...: ہیب۔ میون فیصلہٕ} {صحیح فیصلہ کٔرِتھ: حب۔ نیکی سٍتـ̡ فیصلہ کٔرِتھ}\n5. ژے کٔر کافرن ملامت کٔرِتھ، ژے کٔر بدکارن تباہ تہٕ تِہُند ناو چھُکھ ہمیشہٕ خٲطرٕ ہمیشہٕ خٲطرٕ دِژمُت۔ \n6. اے دُشمن، تباہی چھے ہمیشہٕ خٲطرٕ ختم: تہٕ توے کٔر شہر تباہ کرنہٕ۔ تِمن سٍتۍ گٔیہِ تِہُند یادگار ختم۔ {اے توہ...: یا، دُشمن ہٕنز تباہی چھے ہمیشہٕ خٲطرٕ ختم: تہٕ تِہٕندِس شہرس کٔر ژے تباہ وغیرہ}\n7. مگر خداوند روزِ ہمیشہٕ خٲطرٕ: تٔمۍ چُھ پنُن تخت فیصلہ کرنہٕ خٲطرٕ تیار۔ \n8. تہٕ سُہ کرِ دنیاہس نیکی سٍتـ̡ انصاف تہٕ سُہ کرِ لوکن ہُند فیصلہٕ۔ \n9. خداوند تہِ آسہِ مظلومن ہٕندِ خٲطرٕ پناہ گاہ، مصیبت وِزِ پناہ گاہ۔ {اکھ پناہ گاہ: حب۔ اکھ تھدِ جاے}\n10. تہٕ یِم تُہُند ناو زانان چُھ، تِم کٔرِن توے پیٹھ بھروسہٕ، کیازِ، خداوند، چُھہ نہٕ تِم تراوُن یِم تُہٕندِس ژھانڈنہٕ یِنہٕ وٲلۍ۔ \n11.\\tصیہنس مَنٛز روزَن وٲلِس خداوند سٕندِ حمد گٮ۪وُن: لوکن مَنٛز کرو تٔمۍ سٕندِ اعمال ہُند اعلان۔ \n12. ییلہ سُہ خونُک تفتیش کران چُھ، سُہ چُھ نہٕ تِم یاد تھاوان: سُہ چُھ نہٕ عاجزن ہُند فریاد مٔشِد کران۔ {عاجزی: یا، مُتٲثِر}\n13.\\tاے خداوند، میانہِ سٍتـ̡ رحم کرُن، میانہِ مصیبت {یُس بہٕ میہ سٍتـ̡ دِوان چُھہ} یُس میہ نفرت کران چُھ، تہٕ ژے چُھہ میہ موتٕچ دروازٕ پیٹھٕ تُلان۔ \n14. یُتھ بہٕ صیہون سٕنزِ کورِ ہٕندِس دروازس مَنٛز چانہِ سارِنٕے تعریفن ہٲوِتھ، بہٕ کَرٕ چانہِ نجات سٍتـ̡ شاد۔ \n15.\\tکافر چھہِ تتھ گڑھس منز ڈوبتھ یُس تمو بنوومت اوس، تتھ جالس منز یُس تمو ژوٗرِ تھوومت اوس، سہ چھہ پنن کھۅر رٹان۔ \n16.\\tخداوند چُھ سُہ فیصلہٕ {یُس} انجام دِوان چُھ، بدکار چُھ پننین اتھن ہٕنزِ کامہِ مَنٛز پھسنہٕ یوان۔ حِگائیون۔ سیلہ۔ {حِگایون: یعنی مراقبہٕ}\n17. بدکار یِن جہنمَس مَنٛز بَناونہٕ، {تہٕ} تِم سارِنٕے قوُم یِم خدایہ مٔشِد گٔژھِتھ چھِ۔ \n18.\\tتکیازِ محتاجن گژھہِ نہ ہمیشہ مشراونہ یُن: غریبن ہنز وۅمید گژھہِ نہ ہمیشہ ختم۔ \n19. اے خداوند، وۅتھٕ وُتھ؛ انسان گژھہِ نہٕ غالب گژھُن: کافرن ہُند فیصلہ گژھہِ تۅہہِ ہٕندِس نظرس مَنٛز کرنہٕ۔ \n20. اے خداوند، تِمن کرو خوفہٕ: {یُتھ} قومن گژھن پانس {مگر مگر} انسان زانن۔ سیلہ۔","1. اے خداوند، ژٕ کیازِ چُھکھ دوٗر کھڑا گومُت؟ {مصیبت وِزِ کیازِ چُھکھ ژٕ پنُن پان ژوٗرِتھ؟ \n2.\\tبدکار چھہ غریبن ستاونہ یوان: تم گژھن تمن چیزن منز رٹنہ یُن یُس تِمو تصور کورمُت چھُ۔ {بدکار...: ہیب۔ بدکار سٕندِس غرورس منز چھُ سُہ ستاوان}\n3. یِکیازِ بدکار چُھ پنہٕ نِس دِلٕچ خواہشس پیٹھ فخر کران، تہٕ لالچس سٍتـ̡ برکت دِوان، {یٔمِس} خداوند نفرت کران چُھ۔ {دِلُک: ہیب۔ روح﴾ {برکت دِوان...: یا، لالچ چُھ پانس برکت دِوان، سُہ چُھ خداوند سٕنز نفرت کران}\n4.\\tبدکار چھہ نہ خدایہ سندِ خیالس منز {خدایہ} ژھانڈان۔ {خدا چھہ...: یا، تسندۍ سٲری خیال چھہِ، خدا چھہ نہ کانہہ خدا}\n5. تٔمۍ سٕندِ وتہٕ چِھ ہمیشہٕ تکلیف دہ آسان۔ تُہند فٲصلہٕ چُھ تٔمۍ سٕندِس نظرِ نِش واریاہ زیادٕ: {یێلہِ} تٔمۍ سٕندِس سارِنٕے دُشمن ہٕندِس سٍتـ̡ چُھہ سُہ تِمن ہُند دُشمن دِوان۔ \n6. تٔمۍ چُھ پننِس دِلس مَنٛز وونمُت، بہٕ گژھٕ نہٕ مُشکِلَس مَنٛز۔ {زانہہ: ہیب۔ نسل تہٕ نسل}\n7.\\tتٔمۍ سٕندِس ٲسس چھُ بد دعا تہٕ دھوکہ دہی سٍتۍ بٔرِتھ: تسٕنزِ زبانہِ تل چھُ شرارت تہٕ باطل ۔ {دھوکہٕ: عبرانی۔ دھوکہٕ} {باطل: یا، بدکاری}\n8.\\tسُہ چُھ گامن ہٕندِس پوشہٕ جایہ بِہان: خفیہ جاین منز چُھ سُہ معصومن قتل کران: تسٕنزِ أچھ چھے غریبن سٍتـ̡ خۅد کٔرِتھ۔ {چھِ...: ہیب۔ پان چھُ ژوٗرِ}\n9.\\tسُہ چُھ پَنٕنِس گۅپھس مَنٛز شیرٕکۍ پٲٹھۍ ژوٗرِ پٲٹھۍانتظار کَران: سُہ چُھ غریبن رَٹنہٕ خٲطرٕ پیارس منز روزان: سُہ چُھ غریبن رَٹان ییلہ سُہ أمِس پننِس جالس منز کھینچ کوشش کران چُھ۔ {ژوٗرِ پٲٹھۍ: ہیب۔ خفیہ جاین منز}\n10.\\tسُہ چھُ کُن کُن کٔرِتھ، {تہٕ} پنُن پان عاجز کٔرِتھ، یُتھ غریبَن ہٕندِس مضبوٗط سٍتـ̡ پنہٕ نِس مضبوٗط سٍتـ̡ پَنُن پٲٹھۍ۔ {سُہ...: حب۔ سُہ چُھ پان پھُٹراوان} {by...: یا، پننِس مضبوٗط حصس منز}\n11.\\tتٔمۍ چُھ پننِس دِلس منز ووٚنمُت، خدایہ چُھ مٔشِد گومُت: سُہ چُھ پنُن بُتھ ژوٗرِ تھاوان۔ سُہ چُھ نہٕ زانہہ وُچھان۔ \n12. وۅتھُن، اے خداوند؛ اے خدایہ، پَنُن اَتھٕ تُلُن: عاجز گژھ نہٕ مٔشِل۔ {انکسار: یا، مُتٲثِر}\n13.\\tبدکار کیازِ چُھہ خدایہ سٍتـ̡ حقارت کران؟ تٔمۍ چُھ پننِس دِلس مَنٛز وونمُت، ژے چُھہ نہٕ یہِ ضروُرت کٔرِتھ۔ \n14.\\tژے وُچھمُت {یہ}؛ تکیازِ ژے چُھہ شرارت تہٕ بغض وچھان، یُس پننہِ اتھہٕ سٍتـ̡ بدلہٕ دِنہٕ خٲطرٕ: غریبَن چُھہ پانس پانس سٍتـ̡ دِوان۔ ژٕ چُھکھ بے باپ سُند مددگار۔ {کٔرِتھ: ہیب۔ تراوُن}\n15.\\tبدکار تہٕ بدکار سٕنز نٔر پھُٹرٲوِو تٔمۍ سٕنزِ بدکٲری ژھانڈِو {یوتام نہٕ کانہہ تہِ میلہِ}۔ \n16. خداوند چُھ ہمیشہ خٲطرٕ بادشاہ روزان: کافر گٔیہِ تٔمۍ سٕنزِ زمینہٕ نِش ختم۔ \n17.\\tخداوند، ژے چُھہ عاجزن ہٕنز خواہش بوزمٕژ: ژے کٔرِو تِہُند دِل تیار، تہٕ ژٕ کٔرِکھ پنُن کَن بوزُن: {تیار: یا، قٲیم}\n18.\\tبے باپ تہٕ مظلومن ہُند فیصلہ کرُن، یُتھ زٔمیٖنُک انسان گژھِ نہٕ مزید ظُلم کٔرِتھ۔ {ظلم: یا، خوفزد}","1. [اہم موسیقارس سٍتـ̡، {داؤد سُند زبور}] خداوند سٍتـ̡ چُھہ میہ پَنُن بھروسہٕ: کِتھہ پٲٹھـ̡ چُھہ میانہِ روحس سٍتـ̡ ژٔلِتھ ژٔلِتھ پنہٕ نِس پہاڑس کُنـ̡ \n2.\\tتکیازِ بدکار چھہ کمانس پیٹھ پنن تیر تیار کران، تاکہ تم چھہِ دلس سیتۍ سیدِ سیود گُلۍ۔ {رازدار: ہیب۔ اندھیرے منز}\n3. اگر بُنیاد تباہ گژھِ، نیک کیا ہیکہِ کٔرِتھ؟ \n4. خداوند چُھہ پننِس مقدس مندرس منز، خداوند سُند تخت {چُھ} آسمانس مَنٛز: تٔمۍ سٕنزِ أچھ چھے وُچھان، تٔمۍ سٕنزِ ٹٲرۍ چھے کوشش کران، انسانن ہٕندِس شُرۍ۔ \n5. خداوند چُھ نیکوکارن آزماونہٕ یوان: مگر بدکار تہٕ یُس تشددُک محبت کران چُھ، تٔمۍ سُند روح چُھ نفرت۔ \n6.\\tبدکارن پیٹھ گژھہِ سُہ پھند، نار تہٕ گندھ، تہٕ اکھ خوفناک طوفان: {یہِ آسہِ} تِہندِ پیالہ ہُند حصہٕ۔ {اکھ خوفناک...: یا، اکھ دزُن طوفان}\n7. تکیازِ نیک خداوند چُھ نیکی سٍتـ̡ محبت کران۔ تٔمۍ سُند بُتھ چُھ سیدِ سٍتـ̡ وُچھان۔","1. [شیمینتھس پیٹھ چیف موسیقارس تام، داؤد سُند زبور۔] مدد، خداوند؛ تکیازِ خدایہ انسان چُھ بند سپدان؛ تکیازِ وفادار چُھ انسانن ہٕندِس بچن منزٕ ناکام سپدان۔ {پیٹھ...: یا، ٲٹھمہِ پیٹھ} {مدد: یا، بچٲوِو}\n2.\\tتِم چھِ پرٮ۪تھ أکِس ہمساین سٍتـ̡ بےکار بولان: {سٍت} چاپلوسی سٍتـ̡ {تہٕ} دوٚگنہٕ دِل سٍتـ̡ چِھ تِم کتھ کران۔ {a double...: Heb. اکھ دِل تہٕ اکھ دل}\n3.\\tخداوند ژٹِن سارِنٕے خوشامد کَرن وٲلِس وٕٹھ، {تہٕ} سُہ زبنہٕ یُس مغرور کتھ کران چُھہ: {فخر: عبرانی۔ عظیم}\n4. کُس چُھ ووٚنمُت، سانہِ زبانہِ سٍتـ̡ چُھہ أسـ̡ سٍتـ̡ غٲلب۔ سانہِ وُٹھ {چُھ} سانہِ پٲٹھۍ: کُس چُھہ اسہِ پیٹھ مالک؟ {چُھ...: ہیب۔ چُھہ اسہِ سٍتـ̡\n5.\\tغریبن ہٕندِ ظلمہٕ خٲطرٕ، ضرورتمندَن ہٕندِ آہ سٍتـ̡ بێیہِ وُنہٕ بہٕ وُتھ، خداوند چُھ فرماوان۔ بہٕ کٔرٕ أمِس {أمِس نِش} سٍتـ̡ رٲچھ کٔرِتھ یُس أمِس سٍتـ̡ پھپھ دِوان چُھس۔ {پھپھ کٔرِتھ...: نتہٕ کرٕ أمِس پھنس}\n6.\\tخداوند سٕندِ کلام چھِ خالص لفظ: {یِتھ} رۄپہٕ یُس زمینہِ ہٕندِس بھٹس مَنٛز آزماونہٕ آمُت چھُ، سَتھ لٹہِ پاک کرنہٕ آمُت۔ \n7. اے خداوند، تِم تھاوُن یِمن ہٕندِس زمانس منز ہمیشہٕ خٲطرٕ رژھراونہٕ۔ {تِمن سٍتـ̡ رژھرُن: ہیب۔ سُہ وغیرہ: یعنی پرٮ۪تھ کانہہ وغیرہ}\n8. بدکار چِھ پرتھ طرفہٕ پکان، ییلہٕ بدکار انسان چِھ بلندی حٲصل کرنہٕ یوان۔ {مرد: ہیب۔ انسانن ہٕندِس فرزندن ہٕندِ}","1. [اہم موسیقارس تام، داؤد سُند زبور۔] اے خداوند، ژے کوتاہ تام روزِ میہ مٔشِل؟ ہمیشٔہ خٲطر? ژیہ کُس کالس کٔرِکھ میہ نِش پنُن بُتھ ژوٗرِتھ؟ {سردار...: یا، نگران}\n2. بہٕ کٲتِس کالس روزٕ پننِس روحس مَنٛز مشورٕ، دِلس مَنٛز روزُن غم؟ کُس کالس روزِ میون دُشمن میانہِ پیٹھ؟ \n3.\\tغور کرو {تہٕ بوزو} اے خدایہ میانہِ خدایہ: میانہِ أچھ ہلکہٕ کرُن، یێلہِ بہٕ نِندٕ موتُک {نِندٕ} \n4.\\tیُس میون دُشمن وَنُن زِ بہٕ چُھس أمِس خٕلاف فتح حٲصِل کٔرِتھ۔ {تہٕ} یِم مےٚ پریشان کران چھِ، تِم گژھن خۅش گَژھان۔ \n5. مگر میہ چُھہ چانہِ رحمتس پیٹھ بھروسہٕ کورمُت۔ میون دِل گژھہِ چانہِ نجات سٍتـ̡ شاد سپدُن۔ \n6. بہٕ گٮ۪وٕ خداوند سٕندِ خٲطرٕ، تِکیازِ تٔمۍ چُھ مےٚ سٍتـ̡ س","1. [اہم موسیقارس سٍتۍ، {اکھ زبور} داؤد سُند۔] بیوقوفن چُھ پننِس دِلس مَنٛز وونمُت، {چُھنہٕ کانہہ خدا}۔ تِم چِھ بدعنوان، تِمو چِھ مکروہ کٲم کٔرمٕژ، {چُھنہٕ} کانہہ تہِ نیکی کرِ۔ \n2. خداوند اوس اسمانہٕ پیٹھٕ انسانن ہٕندِس بچن کُن نظر، یہٕ وُچھنہٕ خٲطرٕ زِ کیا کانہہ چُھ یُس سمجھان چُھ، {تہٕ} خدایہِ ژھاران۔ \n3.\\tتِم سارِنٕے گٔیہِ، تِم چھِ {سارِنٕے} یِکہٕ وَٹہٕ گِندِتھ: {اَتہِ} چھُنہٕ کانہہ تہِ یُس نیکی کران چھُ، نہ، اکھ تہِ نہٕ۔ {گندُن: حب۔ بدبو}\n4. کیا بدکار سارِنٕے کارکُن چھا نہٕ کانہہ علم؟ یِم میانین لوکن کھیوان چِھہ یِتھٕ پٲٹھۍ تِم روٹی کھیوان چھِ، تہٕ خداوند سٕندِس سٍتـ̡ چُھہ نہٕ پُزار کران۔ \n5.\\tتِم ٲسۍ سٮ۪ٹھاہ خوفہٕ سٍتـ̡ خدایہ {چُھ} صالحن ہٕنزِ نسلس مَنٛز۔ {ٲس...: ہیب۔ تِم ٲسۍ خوفہٕ سٍتـ̡ کھوژان}\n6.\\tتۅہہ کٔر غریبن ہٕندِس مشورس شرمسار کرنہٕ، کیازِ خداوند چُھ تٔمِس پناہ گاہ۔ \n7. اے کاش اسرٲیلٕچ نجات آسہِ صیہون منزٕ نیرِتھ! یێلہِ خداوند پَنٕنـ̡ لُکہٕ ہٕندِس قٲد سٍتـ̡ واپس اَنِ، یعقوب گژھہِ خۅش، {تہٕ} اسرٲیلـ̡ گژھہِ خۄش۔ {اوہ...: حب۔ کُس دِیہِ}","1. [داؤد سُند زبور۔] اے خداوند، چانہِ خیمہ مَنٛز کُس روزِ؟ کُس روزِ چانہِ مقدس پہاڑس مَنٛز؟ {اَمہ مُقدس پہاڑس مَنٛز کُس روزِ؟ {اَمہ مُقدسٕمَس مَنٛز کُس روزِو؟ {اَمہ مُقدس}\n2. یُس سیدِ پٲٹھـ̡ پکان چُھ، نیکی کَران چُھ، تہٕ پَنٕنِس دِلس مَنٛز پٔزۍ پٲٹھـ̡ بولان چُھ۔ \n3.\\tیُس نہ پننہِ زبانہِ سٍتۍ غیبت کرِ، نہ ہمسایہ سٍتۍ بد کار کرِ، نہ کرِ پننِس ہمساین سٍتـ̡ ملامت کرنہٕ۔ {رٔٹِو...: یا، رٔٹِو، یا برداشت کرُن}\n4. یٔمۍ سٕنزِ نظرِ مَنٛز چھُ اکھ بدکار شخص بدنام کرنہٕ آمُت۔ مگر سُہ چُھ تِمن ہُند احترام کران یُس خداوند سُند خوف چُھ تھاوان۔ {یُس} چُھہ [پننِس} تکلیف دِنُک قسم کھیوان تہٕ بدلاوان چُھہ نہٕ۔ \n5.\\tیُس نہٕ پَنُن پونسہٕ سود خوری کٔرِتھ تہٕ نہ کرِ بے گناہ سٍتـ̡ بدلہٕ۔ یُس یِم کامہِ کٔرِتھ آسہِ سُہ گژھِ نہٕ زانہہ ہُراونہٕ یُن۔","1. [داؤد سُند مِختم۔] اے خدایہ کٔر مے رژھراونہٕ، کیازِ بہٕ چُھس توے پیٹھ بھروسہ کران۔ {مِختم: یا، اکھ سۄنہٕ زبور}\n2. {اے میانہِ روح}، ژے چُھہ خداوند سٍتـ̡ ووٚنمُت، تہٕ چُھہ میٲنۍ رُب چُھہ: میٲنۍ نیکی چُھہ نہٕ ژے تام پھٔہلِتھ ۔ \n3. {مگر} تِمن مقدسن خٲطرٕ یِم زمینس مَنٛز چھِ، تہٕ {بہترین} خٲطرٕ، یٔمِس مَنٛز {چھُ} میانہِ سارِوٕے خوشی چھِ۔ \n4.\\tتِہُند غم گژھہِ ہُرراونہٕ {یُس} بییِس {خدایہ} سٍتـ̡ جلدی کرُن: تِہُند شرابُک نذرانہ کرٕ نہٕ بہٕ دِنہٕ تہٕ تِہُند ناو پننِس وٹھس مَنٛز تُلنہٕ۔ {جلدی کرو...: یا دِیُن بییِس تحفہٕ}\n5. خداوند چُھہ میانہِ وراثتُک تہٕ میانہِ پیالہِ ہُند حصہٕ: ژے چُھکھ میانہِ قسمتُک حِصہٕ۔ {میانِس...: ہیب۔ میانہِ حِصہٕ}\n6.\\tمصرعہ چھہ میہ سیتۍ خۅش گژان {مقامات}؛ آ، میہ چھہ اکھ جان ورثہ۔ \n7. بہٕ کَرٕ خداوند سٕنز برکت یُس مےٚ مشورٕ دِژمُت چھُ: میٲنۍ لگام تہِ چھِ رٲژ ہٕندِس موسمس مَنٛز ہدایت دِوان۔ \n8. میہ چُھہ خداوند ہمیشہ پانس برونہہ کُن تھوومُت: کیازِ سُہ چُھہ میٲنس دچھنہِ اتھس پیٹھ، بہٕ گژھہِ نہٕ ہلاونہٕ یُن۔ \n9. تَمہِ کِنۍ چُھ میون دِل خۄش، تہٕ میون جلال چُھ شاد سپدان: میون ماز تہِ روزِ وۅمید سٍتـ̡ ۔ {آرام...: ہیب۔ اعتماد سان روزُن}\n10. تکیازِ ژے تراوِ نہ میون روح جہنمس منز۔ تہٕ نہ کرٕ ژے پنُن مقدس بد عنوانی وُچھنُک اجازت۔ \n11. ژے ہٲوِکھ مے زندگی ہٕنز وَتھ: چانہِ حضورس منز چھِ خوشی ہُند پورُن۔ تہندِس دچھنہِ اتھس پیٹھ چھِ ہمیشہ خٲطرٕ لذت۔","1. [داؤد سٕنز دُعا۔] اے خداوند، میانہِ فریاد بوزو، میانہِ دُعا بوزُن، {یُس نہٕ گٔژھِتھ چُھہ}۔ {دٔچھُن: ہیب۔ انصاف} {نہ...: حب۔ دھوکہٕ دِنہٕ ورٲے}\n2. میون جملہ گژھہِ چانہِ حضوری منزہ نیرُن۔ چانہِ أچھ وُچھن تِم چیز یِم برابر چھِ۔ \n3. ژے کٔر میون دِل ثٲبت؛ ژے کٔر رٲژ میہ نِش۔ ژے کٔر میہ آزماونہٕ، {تہٕ} لٔبِتھ نہٕ کیٚنٛہہ؛ بہٕ چُھس مقصود {یُس} میون چُھ نہٕ زیادٕ غلطی کٔرِتھ۔ \n4.\\tانسانن ہٕندِس کامہِ متعلق، چُھہ چانہِ چپنہِ ہٕندِ کلامٕ سٍتـ̡ میہ تباہ کرن وٲلـ̡ سٕنزِ وتہٕ نِش بچاومُت۔ \n5.\\tمیانہِ وتہِ پیٹھ تھپھ کٔرِتھ تھپھ کٔرِتھ، {یُس} میانہِ قدمن ہُند قدم ژٔلِتھ چھُنہٕ۔ {سلپ...: ہیب۔ گژھ نہٕ ہلُن}\n6.\\tمیہ چُھہ ژے بُلاونہٕ آمُت، یُتھ تہٕ ژے بوز میانہِ کُن، تہٕ بوز میون کلام۔ \n7. پَنٕنہِ حیرت انگیز محبتہٕ ہٲوِو یُس پنہٕ نِس دٔچھنِس اتھہٕ سٍتـ̡ تِمن ہٕندِس دٔچھنِس اتھس سٍتـ̡ بچاوان چُھ، یِم تِمن نِش پَنُن بھروسہٕ چُھہ کٔرِتھ یِم تِمن ہٕندِس دٔچھنِس اتھس سٍتـ̡ وۅتھان چِھ} {تُہٕندِس دٔچھنِس اتھس سٍتـ̡ چُھہ تُہٕندِس دٔچھنِس اتھس سٍتـ̡ پٲٹھـ̡ پٲٹھـ̡ بێیہِ سٍتـ̡ بچاوُن}\n8.\\tمیہ تھاو أچھ ہٕندِس تارٕ ہٕندۍ پٲٹھۍ، پنٕنۍ پَکھہٕ ہٕندِس ژھایہِ تل ژوٗرِ تھاوُن، \n9.\\tبدکار سٍتـ̡ یُس میہ ظلم کران چُھ، {یُس} میانین مہلک دُشمن سٍتـ̡ {یُس} چُھہ میہ سٍتـ̡ گٔژھان۔ {ظلم: عبرانی۔ فضول} {میانۍ...: ہیب۔ میانہِ دُشمن سٍتـ̡ روحس خلاف}\n10.\\tتِم چھِ پننہِ چربی سٍتـ̡ بٔرِتھ: چُھہ تِم فخرٕ سان کتھ کران۔ \n11.\\tتِمو چُھ وۅنۍ سانہِ قدمن منز گٔژھمٕتۍ: تِمو چھِ زمینہِ کُن أچھ نِوان ۔ \n12.\\tیتھے پاٹھۍ چھہ شیر (یُس} پننس شکارس لالچ کران تہ یتھے پاٹھۍ چھہ اکھ جوان شیر یُس خفیہ جاین منز روزان چھہ۔ {یتھہ پاٹھۍ...: ہیب۔ امس (یعنی یمن منز پریتھ کٲنسہِ) چھہ شیر ہیو یُس کۅکرُن یژھان چھُ} {لُکُن: ہیب۔ بِہتھ}\n13. اے خداوند، أمِس مایوس کرُن، تراوُن سُہ دِیُن: میانہِ روح بچاوُن بدکارن نِش، {یُس} تہنز تلوار: {مایوسی...: ہیب۔ تٔمۍ سُند بُتھ رُکٲوِو} {یُس چُھ: یا، ذریعہ}\n14.\\tتِمن انسانن سٍتـ̡ {یُس} تُہند اتھہٕ چُھ، اے خداوند، یِمن ہٕندِس دُنیاہس مَنٛز چُھہ پنُن حصہٕ تہٕ یِمن ہُند یٔڈ چُھہ پنہٕ نِس پوشہٕ سٍتـ̡ بٔرِتھ {خزانہ} سٍتـ̡ بٔرِتھ بٔرِتھ: تِم چھِ شُرٮ۪و سٍتـ̡ بٔرِتھ، تہٕ باقٕے پَنٕنـ̡ پَنٕنـ̡ شُرـ̡ پۯاونہٕ آمٕتـ̡ {یِم چھِ: یا، بذریعہ } {تِم...: یا، تِہٕندِس شُرِ سٍتـ̡ بٔرِتھ چُھ}\n15. یوٚتام بہٕ چُھس تُہند بُتھ نیکی سٍتـ̡ وُچھان، بہٕ گژھہٕ چانہِ ہِش سٍتـ̡ مطمئن۔","1. [اَکھ زبور داؤد سٕندِس خدایہِ سٕندِس خادمَس سٍتـ̡ یُس خداوند سٕندِس دۅہہٕ سٍتـ̡ امہِ بٲتٕکۍ کلام کتھ کٔرِتھ خداوند سٕندِ دُشمن ہٕندِ اتھہٕ نِش تہٕ ساؤل سٕندِ اتھہٕ نِش بچاوُن: تہٕ تٔمۍ ووٚنُن،] اے خداوند، میانہِ طاقتس سٍتـ̡ بہٕ کرٕ ژے سٍتـ̡ محبت۔ \n2. خداوند چُھہ میٲنۍ کُنہِ پتھر، تہٕ میون قعلہٕ تہٕ میٲنۍ نجات دِنہٕ وول۔ میٲنۍ خدا، میٲنۍ طاقت، یٔمِس پیٹھ بہٕ بھروسہٕ کرُن؛ میون بکلر، تہٕ میانہِ نجات ہُند ہارن، {تہٕ} میون تھدِ مینار۔ {میٲنۍ طاقت: ہیب۔ میٲنۍ کٔن}\n3. بہٕ کَرٕ خداوند سٕندِس تعریفس لایق، یُس تعریف کرنہٕ خٲطرٕ چُھس، یِتھٕ کٔنۍ گژھٕ بہٕ پننین دُشمنن نِش بچاو۔ \n4.\\tموتُک غم گۆو میہ گھیرِتھ تہٕ بے دینی نفرن ہٕندِس سٔہلابن سٍتـ̡ گۆو میہ خوف۔ {بد دین: ہیب۔ بلیال}\n5.\\tجہنمکۍ غم ٲسۍ میہ اندۍ پکھۍ: موتکۍ جال رُکٲوۍ میہ رُکاونہٕ۔ {غم: یا، ڈور}\n6. مُصیبت مَنٛز کٔر میہ خداوند سٕندِس کُن بُل، تہٕ کٔرٕن پننِس خداہس کُن فریاد تہٕ تٔمۍ بوز میٲنۍ آواز پننہِ مندرٕ منز، تہٕ میون فریاد آو تس برونہہ کُن، تہٕ تٔمۍ سٕندِس کنن مَنٛز۔ \n7.\\tاَمہ پَتہٕ لٔج زمینہٕ تہٕ لٔج تھرتھر۔ بالن ہٕنزِ بُنیاد تہِ گٔیہِ ہلہٕ تہٕ لٔگِتھ تکیازِ أمِس اوس شرارت۔ \n8.\\tتٔمۍ سٕنزِ نستہٕ منزٕ دوٚپ دوٚپ تہٕ ٲسس منزٕ نار دِژُن: اَمہ سٍتـ̡ گٔیہِ ژیلہٕ دِنہٕ۔ {تٔمۍ سٕنزِ نستہٕ منزٕ: حب۔ تٔمۍ سٕندِس سٍتـ̡ بیترِ}\n9.\\tتٔمۍ کٔر اسمانس تہِ نمُن، تہٕ ووت تہٕ انہِ گٹہِ اوس تٔمۍ سٕندِس قدمن تل۔ \n10.\\tتہٕ سُہ اوس أکِس کروبس پیٹھ سوار تہٕ وُڑُن: آ، سُہ اوس واو ہٕندِس پکھس پیٹھ وُڑان۔ \n11.\\tتمۍ بنوو انہِ گٹہِ پنُن راز۔ تمۍ سُند پویلین اوس اندۍ سیاہ آبس تہٕ آسمانک گٔنۍ اوٚبر۔ \n12.\\tتٔمِس برونہہ کُن گٔیہِ تٔمۍ سٕندِس گٔنِس گٔنِس اوٚبر، ڈولہٕ تہٕ نارٕکۍ ژیلہٕ۔ \n13.\\tخداوند تہِ دِژ آسمانس مَنٛز گرٛٮ۪ز، تہٕ اعلیٰ ترین دِژ پنٕنۍ آواز۔ اولہٕ {کٔن} تہٕ نارٕکۍ ژیلہٕ۔ \n14. آ، تٔمۍ سوٗزۍ پنٕنۍ تیر تہٕ پھٔٹِتھ ۔ تہٕ تٔمۍ کٔرٕن بجلی تہٕ تِم دِژٕن پریشان۔ \n15. اَمہِ پَتہٕ گٔیہٕ آبٕچ نالہٕ وُچھنہٕ، تہٕ اے خداوند، تُہنزِ نستہٕ ہٕندِس پھٹنہٕ سٍتـ̡ گٔیہٕ دنیاہٕچ بُنیاد دریافت۔ \n16.\\tتٔمۍ سوز ہیرِ پیٹھ، تٔمۍ نیو مے، تٔمۍ کٔر میہ واریاہو آبو منزٕ نیبر۔ {واریاہ : یا، عظیم}\n17.\\tتٔمۍ بچٲو میہ میٲنس مضبوط دُشمن نِش، تہٕ تِمن نِش یِم مےٚ نفرت کران ٲسۍ، تکیازِ تِم ٲسۍ میانہِ خٲطرٕ واریاہ مضبوط۔ \n18.\\tیِمو رُکٲوۍ میہ مُصیبت ہٕندِس دۅہس منز، مگر خداوند اوس میانہِ قیام ۔ \n19.\\tتٔمۍ اوٚن میہ أکِس بٔڈِس جایہِ تہِ۔ تٔمۍ کٔر میہ نجات دِنہٕ، تکیازِ سُہ اوس میہ سٍتـ̡ خۅش سپدان۔ \n20. خداوند دِژ میانہِ نیکی مُطٲبق انعام۔ میانہِ اتھن ہٕنزِ پاکیزگی مُطٲبق دِیُت تٔمۍ مےٚ بدلہٕ۔ \n21. تکیازِ میہ چُھہ خداوند سٕنزِ وتہٕ رٔٹمٕژ، تہٕ چُھس نہٕ بدکار سٍتـ̡ پننِس خدایہ سٕندِس نِش ہُریومُت۔ \n22.\\tتٔمۍ سٕندِ سارِنٕے فیصلہٕ ٲسۍ میہ برونہہ کُن، تہٕ مے کٔر نہٕ تٔمۍ سٕندِ قونوُن پانس نِش۔ \n23.\\tبہٕ اوسُس أمِس برونہہ کُن سیدِ سید، تہٕ بہٕ تھوو پنُن پان پننہِ بدکاری نِش۔ {برونہہ: حب۔ سٍت}\n24. تێمہِ کِنۍ چُھ خداوند میانہِ نیکی مُطٲبق بدلہٕ دِژمُت، پننِس نظرس منز میانین اتھن ہٕنزِ پاکیزگی مُطٲبق۔ {منز...: حب۔ تٔمۍ سٕنزِ أچھن برونہہ کُن}\n25. رحمان سٍتۍ کٔرِو تُہۍ پنُن پان رحم کٔرِتھ۔ أکِس نیک انسانس سٍتۍ کٔرِو توے پنُن پان سیدِ سید۔ \n26. پاکیزٕ سٍتـ̡ کٔرِو پَنُن پان پاک۔ تہٕ کُنہِ سٍتـ̡ کٔرِو پَنُن پان ہاونہٕ۔ {پَنُن پان ہٲوِو: یا کُشتی کٔرِو}\n27. تِکیازِ تُہۍ کٔرِو مُتٲثِر لُکن بچاو۔ مگر کٔرِو تھدِ نظرن ہُند دُبار۔ \n28. تکیازِ ژے کٔرِکھ میٲنۍ شمع: خداوند میون خدا کرِ میانہِ اندپُک گاش۔ {شمع: یا، شمع}\n29.\\tتکیازِ ژے سٍتۍ چھُس بہٕ أکِس لشکرس منز ژوٚلمُت۔ تہٕ خدایہ سٍتـ̡ ووت میہ دیوارس پیٹھ۔ {ژل...: یا، پھُٹمُت}\n30. {یوتام زَن} خدایہ، تٔمۍ سٕنز وتھ {چُھ} کامل: خداوند سُند کلام چُھ آزماونہٕ آمُت: سُہ چُھ تِمن سارِنٕے لوکن ہٕندِ خٲطرٕ اکھ بکلر یِم أمس پیٹھ بھروسہٕ کران چِھ۔ {کوشش: یا، نَفذ}\n31.\\tخدا کُس چُھہ خدایہ بچاوان؟ یا کُس چُھہ کُس چُھہ سٲنـ̡ خدایہ بچاوُن؟ \n32. {یہِ} چُھہ خدا یُس میہ طاقتہٕ سٍتـ̡ رٔٹان چُھ، تہٕ میانہِ وتھ کامل بناوان چُھ۔ \n33.\\tسُہ چُھ میانٮ۪ن کھۅرن ہٕندِس پٲٹھۍ، تہٕ میانٮ۪ن تھدٮ۪ن جاین پیٹھ بِہناوان چھُ۔ \n34. سُہ چُھ میانین اتھن جنگ ہیچھناوان، یُتھ زن میٲنۍ نرِ سٍتۍ لولہٕ ہُند کمان پھُٹراونہٕ ییہِ۔ \n35. ژے چُھکھ میہ پننہِ نجات ہٕنز ڈھال تہِ دِژمٕژ، تہٕ چُھہ دٔچھُن اتھہٕ رٔٹمُت تہٕ چُھہ چُھس بہٕ بٔڈ بنیومُت۔ {چانہِ نرمی...: یا چُھہ پننہِ نرمی سٍتـ̡ ژے مے ہُریر کٔرمٕژ}\n36.\\tژے کٔر میانہِ قدمہ بٔڈۍ مٲنِس تلہ کنہِ، یُتھ میانہِ کھۅر کھسنہٕ آمُت چھُ۔ {میانہِ کھۅر: ہیب۔ میٲنۍ کھۅر گٔیہِ}\n37.\\tمیہ کٔر پننین دُشمن ہُند تعاقب تہٕ تِمن ہٕندِس پَتہٕ لٔگِتھ تہٕ نہ ووت بہٕ دُبارٕ پھیُر یوٚت تام تِم ختم گٔیہِ۔ \n38.\\tمے چھُ تِم زخمی کٔرۍمٕتۍ زِ تِم ہیوٚک نہٕ تھوٚد کھٔسِتھ: تِم گٔیہِ میانٮ۪ن کھۄرن تَل پیوٚو۔ \n39.\\tکیازِ ژے کٔر میہ جنگس منز طاقتہٕ سٍتـ̡ بٔنِتھ تہٕ ژے کٔرِکھ میہ تل یِم میانہِ خلاف کھڑے گٔیہِ۔ {زیر کٔرِتھ: حب۔ کٔرِتھ}\n40. ژے دِژ میہ میانین دُشمنن ہٕنزِ گردن تہِ۔ یُتھ بہٕ کرٕ تِم تباہ کٔرِتھ یِم مےٚ سۭتۍ نفرت کران چھِ۔ \n41.\\tتِمو کٔر کُنہِ تہِ رژھراونہٕ خٲطرٕ، مگر تٔمۍ دِژ نہٕ تِمن جواب۔ \n42.\\tاَمہ پتہٕ کٔر میہ تِم واو برونہہ کُن گردِ ہٕندۍ پٲٹھۍ لۅکٹۍ: مے کٔر تِم سڑکن منز میژِ ہٕندۍ پٲٹھۍ ژھنان۔ \n43. ژے کٔر مے لوکن ہٕنزِ کوششہٕ نِش بچاو۔ تہٕ ژے بنوو مے کافرن ہُند سردار: اکھ قوم یُس نہٕ میہ زانان چُھ، سُہ کرِ میانہِ خدمت۔ \n44.\\tیُتھ یُتھ تِم میانہِ کُن بوزِ، تِم کٔرِن میانہِ فرمانبرداری: اجنبی گژھن میہ سٍتـ̡ تابع۔ {یێلہِ یێلہِ...: حب۔ کُن بوزنہٕ وِزِ}{تابع...: یا، دِیُن دِیُن فرمانبردار} {اجنبی: حب۔ اجنبی سٕندِس نیٚچو}\n45.\\tاجنبی گژھن ختم گژھن، تہٕ پننیو نزدیکی مقامو نِش گژھن کھوژان۔ {اجنبی: ہیب۔ اجنبی سٕندِ نیٚچو}\n46. خداوند چُھ زندٕ روزُن؛ تہٕ میانہِ کُنہِ کُنہِ سٍتـ̡ برکت دِنـ̡ تہٕ میانہِ نجات ہُند خدا گژھہِ تھزر۔ \n47. {یہِ} چُھہ خدا یُس میہ بدلہٕ چُھ، تہٕ میانہِ تل لُکن زیر کٔرِتھ۔ {انتقام: ہیب۔ انتقام دِیُن} {زیر کٔرِتھ: یا، تباہ کَرُن}\n48.\\tسُہ چُھہ میہ میانین دُشمنن نِش نجات دِوان: آ، ژے چُھکھ میہ تِمن ہٕندِس دُشمنس نِش تُلِتھ تُلِتھ یُس میہ خلاف کھڑا سپدان چُھہ، ژے چُھکھ مے تشددٕ نِش بچاومُت۔ {تشدد...: عبرانی۔ تشددُک انسان}\n49. اَمہِ مۄکھٕ کَرٕ بہٕ تُہُند شُکر ادا کَرُن، اے خداوند، کافرن مَنٛز، تہٕ کَرٕ تُہٕندِس ناوٕچ حمد گٮ۪وٕنۍ۔ {دِیو...: یا، اقرار کرُن}\n50. سُہ چُھ پننِس بادشاہس دِوان۔ تہٕ دِیُن پننِس مسح کرنہٕ آمتِس، داؤدس تہٕ تٔمۍ سٕندِس بولس ہمیشہٕ خٲطرٕ رحمت۔","1. [اہم موسیقارس سٍتۍ، داؤد سُند زبور۔] آسمانن چُھ خدایہ سُند جلال ظٲہر کران۔ تہٕ آسمانہٕ چُھ تٔمۍ سٕنز کٲم ہاوان۔ \n2. دۅہ چُھ کتھ کران، تہٕ رٲژ تام چُھ علم ظٲہر کران۔ \n3.\\t{اتہِ چھہ نہ کانہہ بول تہ نہ زبان، {ییتہِ} تہنز آواز بوزنہ یوان چھیہ۔ {کتہِ...: یا یمن ورٲے چھیہ تہنز آواز بوزنہٕ یوان: ہیب۔ تہنز آواز بوزنہٕ ورٲے چھیہ نہٕ}\n4.\\tتِہُند سُہ سٲرِسٕے زمینہٕ سٍتـ̡ ژٔلِتھ تہٕ تِہُند کلام چُھہ دُنیا کِس اندس تام۔ تِمن مَنٛز چُھ تِمن آفتابہٕ خٲطرٕ اکھ خیمہ قایم کورمُت، {لائن: یا، حکم، یا، ڈایریکشن}\n5.\\tیُس مہرازٕ پننہِ کمرہ منزہ نیران چھُ، {تہٕ} چھُ أکِس مضبوٗط انسان سٕندِ پٲٹھۍ ریس دوڑنہٕ خٲطرٕ شاد سپدان۔ \n6. تٔمۍ سُند نیرُن چُھ آسمانہٕ کِس اندس پیٹھ، تہٕ تٔمۍ سُند چکر چُھہ اَمہ کِس اندس تام، تہٕ اَمہ کِس گرمی نِش چُھہ نہٕ کانہہ تہِ پوشید۔ \n7. خداوند سُند شریعت {چُھ} کامل ، روح بدلاوُن: خداوند سٕنز گوٲہی {چُھ} پکہٕ پٲٹھۍ، عقلمند بناوُن سادٕ۔ {قانون: یا، نظریہ} {تبدیل: یا، بحال}\n8.\\tخداوند سُند حکم چُھ صحیح، دِلس خۅش کٔرِتھ: خداوند سُند حکم چُھہ پاکیز، اچھن گاش دِوان۔ \n9. خداوند سُند خوف {چُھ} پاک تہٕ ہمیشہٕ دٲیر: خداوند سُند فٲصلہٕ {چُھ} پٔز {تہٕ} پٲٹھۍ۔ {صحیح: ہیب۔ پٔز}\n10.\\tسۅنہٕ کھۅتہ زیادہ، آ، سۅنہٕ کھۅتہ زیادہ موٚدُر تہِ۔ {شہد چھُ: ہیب۔ شہد چھۅکھ تراوُن}\n11.\\tتِمن سٍتـ̡ چُھہ تُہٕندِس خادمس خبردار کرنہٕ آمُت: {تہٕ} تِمن ہٕندِس سٍتـ̡ چُھہ بٔڈ انعام۔ \n12.\\tکُس ہیکہِ {تسٕنز} غلطی سمجِتھ؟ ژے کٔر میہ راز {غلطی} نِش پاک۔ \n13.\\tپَنٕنـ̡ خادمَس تہِ بچاوُن گۅناہ نِش۔ تێلہِ گژھہِ نہٕ بہٕ سیدِ پٲٹھـ̡ تہٕ بہٕ روزٕ بٔڈِ گُناہ نِش بے قصور۔ {عظیم: یا، زیادٕ}\n14.\\tمیانہِ ٲسٕچ کتھ تہٕ میانہِ دِلُک مراقبہٕ گژھہِ چانہِ نظرِ منز قبول، اے خداوند، میٲنۍ طاقت تہٕ میٲنۍ نجات دِنہٕ وٲلۍ۔ {طاقت: ہیب۔ پتھر}","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور۔] خداوند چُھہ ژے مصیبت کِس دۅہس مَنٛز بوزان۔ یعقوب سٕندِ خدایہ سُند ناو چُھہ تُہُند بچاو۔ {بچاو...: ہیب۔ تھدِ مقامس پیٹھ تھاوُن}\n2. ژے سوز مقدس مقامہٕ پیٹھٕ مدد، تہٕ صیہون نِش کٔرِو پنُن مضبوٗط۔ {تُہٕنز مدد} {مضبوط: حب۔ سہارٕ}\n3. پَنٕنـ̡ سارِنٕے نذرانہ یاد تھاوُن، تہٕ پَنٕنـ̡ دزنہٕ آمٕژ قربانی قبول کٔرِو۔ Selah. {قبول: Heb. رٔٹِتھ کٔرِو: نتہٕ کٔرِو چربی کُن}\n4. پَنٕنہِ دِلہٕ مُطٲبِق عطا کٔرِو تہٕ پَنٕنـ̡ سارِنٕے مشورٕ پورٕ کٔرِو۔ \n5. أسۍ کٔرِو چانہِ نجات سٍتـ̡ شاد تہٕ پننِس خدایہ سٕندِس ناوٕ سٍتـ̡ کرو أسـ̡ {پنُنـ̡ جھنڈٕ﴾ قٲیم: خداوند کٔرِو تُہٕنزِ سارِنٕے عرضی پورٕ۔ \n6. وۅنۍ چُھس میہ زانان زِ خداوند چُھ پنُن مسح کرنہٕ آمُت نجات دِوان۔ سُہ بوزِ سُہ پننہِ مقدس آسمانہٕ پیٹھٕ پننہِ دچھنہِ اتھہٕ کہِ بچاونٕچ طاقتہٕ سٍتـ̡۔ {تٔمۍ سُند پاک...: ہیب۔ تٔمۍ سٕندِس پاکیزگی سُند جنت} {سٍت...: ہیب۔ نجات کہِ طاقتہٕ سٍتـ̡\n7. کینہہ چھہِ رتھن پیٹھ بھروسہ کران تہٕ کینہہ گُرِ پیٹھ: مگر اسہِ گژھہِ پننِس خدایہ سُند ناو یاد۔ \n8. تِم چھِ بۄن والنہٕ آمٕتۍ تہٕ پٔرۍمٕتۍ: مگر أسۍ چھِ زندٕ گٔمٕتۍ، تہٕ کھڑا گٔیہِ۔ \n9.\\tبچاو، خداوند: ییلہ أسۍ بلاوے سٍتـ̡ بادشاہ بوزُن۔","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور۔] اے خداوند، بادشاہ گژھہِ چانہِ طاقتہٕ سٍتـ̡ خوش۔ تہٕ تێنزِ نجات سٍتـ̡ کوتاہ کرِ سُہ شاد! \n2.\\tژے چھُکھ أمِس دِلٕچ خواہش دِژمٕژ، تہٕ چُھکھ نہٕ تٔمۍ سٕندِس وَٹھن ہٕنز درخواست رُکٲومٕژ۔ سیلہ۔ \n3. تِکیازِ ژے چھُکھ أمِس نیکی ہٕنزِ نعمتہٕ سٍتـ̡ رُکاونہٕ آمُت: تٔمِس کَلس پیٹھ تھووُکھ خٲلص سۄنہٕ سُند تاج۔ \n4.\\tتٔمۍ منگ ژےٚ زندگی تہٕ ژے دِژ أمِس دِژٕن، {حتیٰ کہ} دۅہن ہُند زیچھر۔ \n5. تٔمۍ سُند جلال چُھہ تُہنزِ نجات سٍتـ̡ بٔڈ تہٕ عزت تہٕ عظمت۔ \n6.\\tکیازِ ژے چھُ سُہ ہمیشہ خٲطرٕ بابرکت بناومُت: ژے چھُکھ سُہ پنہٕ نِس بُتھِس سٍتـ̡ سٮ۪ٹھاہ خۅش کٔرِمُت۔ {سُہ بنیوو سُہ زیادٕ...: حب۔ سُہ کٔرِو سُہ سُہ خۅش کَرُن}\n7. کیازِکہ بادشاہ چُھ خداوند سٕندِس رحمتہٕ سٍتـ̡ ہُند پٲٹھـ̡ ہُراونہٕ یِوان۔ \n8. تُہٕندِس دٔچھُن اَتھٕ سٍتـ̡ تہٕ تُہٕندِس دٔچھنِس اَتھٕ سٍتـ̡ تہٕ تُہٕندِس دٔچھنِس دٔچِھس سٍتـ̡ تُہٕ \n9.\\tژے بناو تِم پننہِ غصہٕ سٍتـ̡ نارٕ سٍتـ̡ بَناوُن: خداوند کرِ تِم پننِس قہر سٍتـ̡ نِنہٕ، تہٕ نار دِیہِ تِمن نِش۔ \n10.\\tتِہُند پھل تہٕ تِہُند بیول کٔرِو زمینہٕ سٍتـ̡ ختم کرنہٕ۔ \n11.\\tتکیازِ تِمو اوس تۅہہِ خلاف بد ارادہ تھاوان: تِمو کوٚر اکھ شرارتی چالُک تصور، {یُس} تِم ہیکن نہٕ {کٔرِتھ}۔ \n12.\\tتێلہِ کٔرِو تِمن پَنٕنـ̡ پَنٕنـ̡ پَنٕنـ̡ تِمن ہٕندِس بُتھِس سٍتـ̡ پَنٕنـ̡ پَنٕنـ̡ تُہٕندِس بُتھِس سٍتـ̡ تیار کٔرِتھ۔ {ژے کٔرِو...: نتہٕ کٔرِو تِمن ہٕندِس بُتھِس سٍتـ̡ {پَتہٕ: حَب۔ پھیُر}\n13. اے خداوند، پنہٕ نِس طاقتس سٍتـ̡ گژھہِ تُہٕندِس طاقتس سٍتـ̡ تُہٕندِس طاقتس سٍتـ̡ گیوان تہٕ تعریف کٔرِو۔","1.\\t[ایجیلتھ شہرس پیٹھ بٔڈۍ موسیقار سٍتۍ، داؤد سُند زبور۔] میانہِ خدا، میانہِ خدا، ژے کیازِ چھکھ میہ ترٲومُت؟ {ژے کیازِ} چھکھ میانہِ مدد کرنہٕ نِش دور، {تہٕ میانہِ گُرجہِ ہٕندِس کلامس نِش} {Aijeleth...: یا صبحُک ہِند} {مدد...: ہیب۔ میٲنۍ نجات}\n2. اے خدایہ، بہٕ چُھس دۅہلہِ روُن، مگر ژے چُھس نہٕ بوزان۔ تہٕ رٲژ ہٕندِس موسمس منز، تہٕ چُھس نہٕ ژھۄپہٕ۔ {am...: ہیب۔ میانہِ خٲطرٕ چُھنہٕ کانہہ خاموشی}\n3.\\tمگر ژے چھکھ مقدس {اے توہ} یُس اسرٲیلِچ حمد کران چھُ۔ \n4.\\tسانین آباؤ اجدادن کٔر توے پیٹھ بھروسہ: تِمو کٔر بھروسہٕ، تہٕ ژے کٔر تِمن بچاونہٕ۔ \n5. تِمو کٔر تۅہہِ نِش فریاد تہٕ نجات دِنہٕ: تِمو کٔر توے پیٹھ بھروسہٕ، تہٕ گٔیہٕ نہٕ پریشان۔ \n6. مگر بہٕ چُھس اکھ کیم، تہٕ کانہہ انسان۔ انسانن ہُند ملامت تہٕ لوکن ہٕنز حقارت۔ \n7.\\tیم سٲری یم میہ وچھان چھہِ تم چھہِ میہ ٹھٹھاہ کٔرتھ: تم چھہِ وٹھ کڈان، کلہ ہلاوان، {ونن}، {شوٹ...: ہیب۔ کھول}\n8.\\tأمِس خداہس پیٹھ بھروسہٕ {یُس} سُہ دِیہِ أمِس نجات دِنہٕ: سُہ دِیہِ أمِس مَنٛز خۄش۔ {أمِس پژھ کٔرِتھ...: حب۔ تٔمۍ کٔر پانَس پٲٹھۍ} {وُچھان...: یا، اگر سُہ خۅش آسہِ}\n9.\\tمگر ژے چھکھ سُہ یمۍ میہ رحمہ منزہ نیبر کڈُن: ژے کٔر میہ وۅمید {ییلہ بہٕ اوسس} میانہِ ماجہ ہٕندِس سینس پیٹھ۔ {didst...: یا تھووُن میہ رٲچھ منز}\n10. بہٕ اوسُس ژے پیٹھٕ دِنہٕ آمُت: ژٕ چھُکھ میانہِ ماجہ ہٕندِ یٔڈ پیٹھٕ میٲنۍ خدا۔ \n11.\\tمیہ نش گژھ نہ دور؛ مصیبت {چُھ} نزدیک؛ {چُھ} چُھہ نہٕ کانہہ تہِ مدد کرُن۔ {نہٕ...: ہیب۔ نہٕ کانہہ مددگار}\n12.\\tواریاہ داند چھہِ میہ اندۍ پکھۍمتۍ: بشانکۍ مضبوط {بیل} چھہِ میہ اندۍ پکھۍ رٔٹۍمٕتۍ۔ \n13.\\tتِمو کٔر میہ کُن پھیُر، {یِتھ} کۅکرِ تہٕ گُرجہٕ شیر۔ {گیپڈ...: ہیب۔ میہ خلاف کھول پنٕنۍ ٲس}\n14.\\tمیہ چھہ آبہِ ہندۍ پاٹھۍ وۅتلان تہ میہ چھیہ ساری اڈجہ نیبر نیران: میون دل چھہ موم ہیو۔ یہ چھہ میانین اندرمن منز پگلان۔ {نیبر...: یا، ژٹنہِ}\n15.\\tمیون طاقت چھُ برتن ہٕندۍ پٲٹھۍخشک گومُت۔ تہٕ میٲنۍ زبان چھیہ میانین مٔنزۍ مٔنزۍ ژٔٹِتھ \n16. تکیازِ ہونین چُھ میہ گھیرمُت: بدکارن ہٕنزِ مجلسن چُھ میہ گھیرمُت: تِمو کٔر میٲنس اتھن تہٕ کھۅرن ہٕندِس کھورِ سٍتـ̡ ۔ \n17.\\tبہٕ چھُس پنٕنۍ سارِنٕے أڈجہِ ؤنِتھ: تِم چھِ میہ وُچھان۔ \n18.\\tتِمو چھِ میٲنۍ پلو پانس منز الگ کٔرِتھ، تہٕ میٲنِس پوشاکَس پیٹھ لاٹری تراوان۔ \n19. مگر اے خداوند، اے میانہِ طاقت، ژٕ گژھ نہٕ میانہِ نِش دوٗر گژھُن، اے میانہِ طاقت، ژٕ کٔر میانہِ مددٕ خٲطرٕ جلدی۔ \n20.\\tمیون روح تلوار نِش بچاو۔ میون پیاری ہونہِ ہُند طاقتہٕ نِش۔ {میون پیاری: ہیب۔ میون کُنی} {طاقت: ہیب۔ اتھہ}\n21.\\tشیر سٕندِ ٲسِس نِش بچاوُن، کیازِ ژے چُھکھ مے یونیکورن ہٕندِس سینگَس سٍتـ̡ بوزمُت۔ \n22. بہٕ کَرٕ تُہند ناو پننین باین برونہہ کُن: بہٕ کرٕ چانہِ ہٕندِس تعریفس منز۔ \n23. یُس خداوند سُند خوف چُھ، تٔمِس سٕنز حمد کٔرِو۔ یعقوب سٕندِس بُلِس سٍتـ̡ کٔرِو تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ تسٕندِس سٍتـ̡ سٍتـ� \n24.\\tتکیازِ تٔمۍ کٔر نہٕ مُصیبت سٕندِس عذابس سٍتـ̡ حقارت تہٕ نفرت۔ نۂ چُھہ أمِس نِش بُتھ ژوٗرِ تھوومُت۔ مگر ییلہ تٔمۍ أمِس کُن فریاد دِژ، تٔمِس بوز۔ \n25. میٲنۍ تعریف: بہٕ کرٕ تِمن برونہہ کُن پنُن عہد یُس أمِس کھوژان چھُ۔ \n26. عاجز گژھن کھٮ۪وان تہٕ مطمئن: تِم گژھن خداوند سٕنز حمد کرٕن، یُس أمِس ژھاران چُھ، تُہند دِل روزِ ہمیشہٕ زندٕ۔ \n27. دنیاہٕکۍ سارِنٕے اندٕ گژھن خداوند سٕندِ کُن یاد تہٕ پھیرٕن: تہٕ قومن ہٕندِ سارِنٕے رشتہٕ دار گژھن توے برونہہ کُن عبادت کرنہٕ۔ \n28. بادشاہت چُھہ خداوند سُند تہٕ سُہ چُھ قومن مَنٛز گورنر۔ \n29.\\tزمینہِ پیٹھ یِم سارِنٕے چربی آسہِ تِم گژھن کھٮ۪وان تہٕ پوجا کٔرِتھ، یُس سارِوٕے مٔژِس مٔنزِس کُن وسان چھُ، سُہ گژھِ أمِس برونہہ کُن نمُن، تہٕ کانہہ تہِ ہیکہِ نہٕ پنُن روح زِندٕ تھٲوِتھ۔ \n30. اَکھ بیٛول گژھہِ أمِس خدمت کرنہٕ۔ یہِ گژھہِ أکِس نسلس تام خداوند سُند حساب دِنہٕ۔ \n31.\\tتِم یِن یِنہٕ وٲلِس لُکن برونہہ کُن پنٕنـ̡ نیکی ہُند اعلان یُس پٲدٕ سپدِ، یُس تٔمۍ کٔرِتھ {یہ} کرُن۔","1. [داؤد سُند زبور۔] خداوند چُھہ میٲنۍ چرواہ۔ بہٕ چُھس نہٕ یژھان۔ \n2.\\tسُہ چُھس میہ سبز مرگہٕ منز بٔنِتھ بٔنِتھ دِوان۔ {سبز...: ہیب۔ نرم گاسہٕ ہٕندۍ مرگہٕ} {توتہِ...: ہیب۔ خاموشی ہُند آب}\n3. سُہ چُھ میٲنۍ روح بحال کران: سُہ چُھ مےٚ پننہِ ناوٕ خٲطرٕ نیکی ہٕنزِ وتن پیٹھ نِوان۔ \n4. آ، یێلہِ بہٕ موتٕچ ژھایہِ ہٕنزِ وادی مٔنزۍ پکان چھُس، بہٕ کُنہِ تہِ بُرِس سٍتـ̡ خوفزدٕ کٔرِتھ، تکیازِ ژٕ چُھس میہ سٍتـ̡ تُہٕنزِ لٔر تہٕ تُہٕندِس لٔرِس سٍتـ̡ چھِ مے تسلی دِوان۔ \n5. ژے کٔر میانین دشمنن ہٕنزِ موجودگی منز میانہِ برونہہ کُن اکھ میز تیار: ژے کٔر میٲنس کلس تیٖلہٕ سٍتـ̡ مسح کرنہٕ۔ میون پیالہ چُھس وسان ۔ {anointest: Heb. چربی بناوُن}\n6. یٔقیٖنی طور روزِ میانہِ زندگی ہٕندِس سارِنٕے دۅہس منز نیکی تہٕ رحمت: تہٕ بہٕ روزٕ ہمیشہٕ خداوند سٕندِس گرس مَنٛز۔ {ہمیشہٕ خٲطرٕ: ہیب۔ دۅہن ہٕندِس طوالتس تام}","1. [داؤد سُند زبور۔] زمین چھیہ خداوند سٕنز، تہٕ اَمہ سٍتـ̡ پورٕ۔ دنیا، تہٕ تِم یِم اتھ منز روزان چھِ۔ \n2. تِکیازِ تٔمۍ چُھ یہِ سمندرَس پؠٹھ بُنیاد تھوومُت، تہٕ بَنٲوِن سٔلابن پؠٹھ قایم ۔ \n3. خداوند سٕندِس بالس پیٹھ کُس کھسِہ؟ یا کُس کرِ تٔمۍ سٕندِس مقدس مقامس پیٹھ کھڑا؟ \n4. یُس صاف اتھہٕ تہٕ پاک دل آسہِ۔ یٔمۍ نہٕ پنُن روح بکار کٔرِتھ تُلِتھ تہٕ نہ دھوکہٕ دِنہٕ سٍتـ̡ قَسم کٔرِمُت۔ {سُہ...: ہیب۔ اَتھن ہُند صفا}\n5. سُہ میلہِ خداوند سٕندِ طرفہٕ برکت، تہٕ خدایہِ سٕندِ نجات ہٕندِ طرفہٕ نیکی حٲصِل۔ \n6.\\tیِہ چُھہ تِمن ہُند نسل یُس أمِس ژھانڈان چُھ، یُس تُہند بُتھ ژھاران چُھ، اے یعقوب۔ سیلہ۔ {اے یعقوب: یا، اے یعقوب سُند خدا}\n7. پَنٕنۍ کلہٕ تُلِو، اے دروازٕ؛ تہٕ تُلِو تُلِو، اے ابدی دروازٕ۔ تہٕ جلال ہُند بادشاہ یِیہِ اژُن۔ \n8. یہِ جلال ہُند بادشاہ کُس چُھہ؟ خداوند چُھ طاقتور تہٕ طاقتور، خداوند چُھ جنگس مَنٛز طاقتور۔ \n9. اے دروازٕ، پَنٕنۍ کلہٕ تُلِو۔ تُلِو، اے ابدی دروازٕ۔ تہٕ جلال ہُند بادشاہ یِیہِ اژُن۔ \n10.\\tیہِ جلال ہُند بادشاہ کُس چُھ؟ لشکرن ہُند رب چُھ، سُہ چُھ جلال ہُند بادشاہ۔ سیلہ۔","1. [{داؤد سُند زبور}] اے خداوند، بہٕ چُھس پنُن روح تُلان۔ \n2. اے خدایہ، بہٕ چُھس ژے پیٹھ بھروسہٕ تھاوان: بہٕ گژھ نہٕ شرمندہ گژھُن، میٲنۍ دُشمن گژھن نہٕ میٲنس پیٹھ فتح حٲصل۔ \n3.\\tآ، یُس تہِ تۅہہِ انتظار کران آسہِ، سہ گژھہِ شرم کرُن، یُس بے وجہ خلاف ورزی کران آسہِ۔ \n4. اے خداوند، مے ہٲو پنٕنۍ وتہٕ۔ مے ہیچھناوٕنۍ پنٕنۍ وتہٕ۔ \n5. پَنٕنـ̡ پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھـ� \n6.\\tاے خداوند، چانۍ نرم رحمتہٕ تہٕ چانۍ محبتہٕ یاد تھاوُن۔ تکیازِ تِم چھِ پرانہِ پیٹھٕ رودمٕتۍ۔ {نرم...: ہیب۔ أنٛدرٕن}\n7. میانہِ جوانی ہٕندِ گۅناہ تہٕ میٲنۍ غلطی یاد تھاوٕن، اے خداوند، پننہِ رحمتہٕ مُطٲبِق تھاو مے پننہِ نیکی خٲطرٕ یاد۔ \n8. خیر تہٕ سیود چُھہ خداوند: تێمہِ مۅکھہ کرِ سُہ گۅنہگارن وتہِ ہیچھناوُن۔ \n9. عاجز کرِ سُہ فیصلس منز رہنمایی تہٕ عاجز کرِ سُہ پنٕنۍ وتھ ہیچھناوٕنۍ۔ \n10. خداوند سٕنزِ سارِنٕے وَتہٕ چِھہ رحمتہٕ تہٕ سچائی یُس تٔمۍ سٕندِس عہد تہٕ گوٲہی پیٹھ عمل کران چُھ۔ \n11. اے خداوند، پننہِ ناوٕ خٲطرٕ کٔر میانہِ ناکارہ معافی۔ تکیازِ یہ {چُھ} عظیم۔ \n12. سُہ کُس انسان چُھ یُس خداوند سُند خوف چُھ؟ سُہ کرِ سُہ تِتھۍ طریقس سٍتـ̡ ہیچھناوُن یُس سُہ ژٲرِ۔ \n13. تٔمۍ سُند روح روزِ آرام سان۔ تہٕ تٔمۍ سُند بُل گژھہِ زمینہِ ہُند وارث۔ {روزُن...: ہیب۔ نیکی سٍتـ̡ روزُن}\n14. خداوند سُند راز چُھ تِمن سٍتـ̡ یُس أمِس کھوژان چُھ، تہٕ سُہ کرِ تِمن پنُن عہد ہاونہٕ۔ {تہٕ...: یا، تہٕ تٔمۍ سُند عہد تہٕ تِمن ہُند زانہٕ دِنہٕ خٲطرٕ}\n15. میٲنۍ أچھ چِھہ ہمیشہ رب سٕندِس کُن تکیازِ سُہ کٔرِن میٲنۍ کھۅر جالہٕ منزٕ نِش۔ {تُلُن: ہیب۔ نیرُن}\n16.\\tمیہ کُن پھیُر، تہٕ کٔرِکھ میہ پیٹھ رحم۔ تکیازِ بہٕ چُھس ویران تہٕ مُصیبت زدہ گومُت۔ \n17.\\tمیانہِ دِلٕچ پریشٲنی چھے بڑان: {O} کٔر میہ مُصیبت نِش نیبر۔ \n18.\\tمیانہِ عذابَس تہٕ میانہِ دَگ وُچھِو۔ تہٕ میانہِ سارِنٕے گۅناہ معاف۔ \n19.\\tمیانین دُشمن سٍتـ̡ سمجھو۔ تکیازِ تِم چھہِ واریاہ نفرت۔ تہٕ تِم چھِ میہ سٍتـ̡ ظالمانہٕ نفرتس سٍتـ̡ نفرت۔ {ظالم...: Heb. تشددٕچ نفرت}\n20. اے میون روح رژھراوُن، تہٕ نجات دِیُن: بہٕ گژھ نہٕ شرمندہ گژھُن۔ تکیازِ بہٕ چُھس پانس پیٹھ بھروسہٕ تھاوان۔ \n21.\\tدیانت تہٕ پاکیزگی تھاوٕنۍ میہ رژھرٕنۍ۔ تکیازِ بہٕ چُھس چانہِ ہُند انتظار۔ \n22. اے خدایہ، اسرٲیلِس کٔرِو تٔمِس سارِنٕے مصیبتَو نِش نجات دِنہٕ۔","1. [{زبور} داؤد سُند زبور۔] اے خداوند، میہ کٔر فیصلہٕ۔ تکیازِ بہٕ چُھس پننہِ دیانت سٍتـ̡ پکان چُھس: مے چُھس خداوند سٍتـ̡ تہِ بھروسہٕ کورمُت؛ {لہذا} بہٕ چُھس نہٕ کھسُن۔ \n2. اے خداوند، میہ پرکھ تہٕ ثٲبت کرُن۔ میانہِ لگام تہٕ دِل آزمٲیِو۔ \n3.\\tچانہِ محبتہٕ سٍتـ̡ چُھہ میانین نظرن برونہہ کُن: تہٕ بہٕ چُھس چانہِ حقیقتس منز پکان ۔ \n4. بہٕ چُھس نہٕ بیکار نفرن سٍتۍ بِہتھ تہٕ نہ بہٕ گژھٕ بے کار سٍتـ̡ اژان۔ \n5. بہٕ چُھس بدکارن ہٕنزِ جمٲژ سٍتـ̡ نفرت۔ تہٕ بہٕ چُھس نہٕ بدکارن سٍتـ̡ بِہنہٕ آمُت۔ \n6. بہٕ کٔرٕ معصومیت سٍتـ̡ پنٕنـ̡ اتھہٕ چھلناوُن: یێلہِ بہٕ چُھس چانہِ قربان گاہ سٍتـ̡ گٔژھِتھ، اے خداوند: \n7.\\tیُتھ بہٕ کرٕ شُکرگٲری ہٕنزِ آوازِ سٍتۍ شایع کٔرِتھ، تہٕ چانہِ سارِنٕے حیرت انگیز کامین ہٕنز وَنُن۔ \n8.\\tخداوند، میہ چُھہ چانہِ گرٕچ بستی تہٕ تۅہہِ ہٕندِس عزتس سٍتـ̡ محبت کٔرمٕژ۔ {کتہِ...: ہیب۔ تیری عزتُک خیمہ ہُند}\n9.\\tمیون روح گۅنہگارن سٍتـ̡ جمع کٔرِتھ، تہٕ نہ کٔرِو میانہِ زُو خونریز سٍتـ̡ سٍتـ̡ جمع کٔرِتھ: {جمع کرُن...: نتہٕ نِو نہٕ} {خونریز...: ہیب۔ خونُک مرد}\n10.\\tیمۍ سٕندِس اتھس مَنٛز چھُ شرارت، تہٕ تِہُند دٔچھُن اَتھٕ چھُ رُشوَت سٍتـ̡ بٔرِتھ۔ {پورٕ...: ہیب۔ بٔرِتھ}\n11.\\tمگر بہٕ پَنُن پاکیزگی پٲٹھـ̡ پٔکِتھ: بہٕ کٔرِو میہ نجات تہٕ رحم کٔرِتھ۔ \n12. میون قدم چُھ برابر جایہِ کھڑا آسان: بہٕ کرٕ بہٕ رٔبِس برکت دِنہٕ۔","1. [{داؤد سُند زبور}] خداوند {چُھ} میون گاش تہٕ میٲنۍ نجات بہٕ کُس کھوژٕ بہٕ؟ خداوند {چُھ} میانہِ زندگی ہُند طاقت؛ بہٕ کٔمِس سٍتـ̡ کھوژُن؟ \n2.\\tییلہ بدکار، {حتیٰ کہ} میون دُشمن تہٕ میٲنۍ دُشمن میانہِ ماز کھٮ۪نہٕ خٲطرٕ آیہ، تِم گٔیہِ ٹھوکر کھٔسِتھ پیوٚو۔ {آو...: ہیب۔ میہ خلاف آو برونہہ کُن}\n3. یودوَے اکھ میزبان میانہِ خلاف ڈیرٕ تراوُن، میون دِل گژھہِ نہٕ خوفز: یودوَے میہ خلاف جنگ گژھہِ وُتھ، اتھ {مرضی} مَنٛز گژھہِ بہٕ یقین تھاوُن۔ \n4. اَکھ {چیز} چُھس بہٕ خداوند سٕندِس گرس مَنٛز روزُن، یُس بہٕ ژھاران چُھس؛ یُتھ بہٕ روزٕ خداوند سٕندِس گرس مَنٛز روزُن، خداوند سٕنز خوبصورتی وُچھِتھ تہٕ تٔمۍ سٕندِس مندرس مَنٛز پرژھہٕ گٲر کٔرِتھ۔ {خوبصورتی: یا، لذت}\n5. تکیازِ مصیبت وِزِ سُہ کرِ میہ پننِس خیمہ کِس رازس مَنٛز ژوٗر۔ سُہ کرِ میہ أکِس کَنہِ پتھرس پیٹھ۔ \n6. تہٕ وۅنۍ گژھہِ میون کلہ پانس اندۍ پکھۍ پننین دشمنن پیٹھ، تێلہِ کٔرٕ بہٕ تسٕندِس خیمہ خانس مَنٛز خوشی ہٕنز قربانی۔ بہٕ گیو، آ، بہٕ گٮ۪وٕ خداوند سٕندِ تعریف۔ {خوشی: ہیب۔ کرٛٮ۪کہٕ}\n7. اے خداوند، بوزو، {یێلہِ} بہٕ پننہِ آوازِ سٍتـ̡ چُھس روٝحہِ سٍتـ̡ تہٕ کٔرِو میانہِ سٍت \n8.\\t{ییلہ ژے ووٚن}، ژے ژھانڈ میون بُتھ؛ میانہِ دِل ووٚن ژے چانہِ بُتھ، خداوند، بہٕ ژھانڈ بہٕ۔ {ییلہ...: یا، میانہِ دِل ووٚن ژے ووٚن، میون بُتھ ژھانڈُن وغیرہ}\n9. پَنُن بُتھ مہ ژوٗرِ میہ نِش۔ پَنُن خادمُک شَرارتہٕ سٍتـ̡ تھاوُن: ژٕ چُھکھ میٲنۍ مدد۔ اے میانہِ نجات ہٕندِس خدایہِ سٍتـ̡ مہ تراوُن تہٕ نہ تراوُن۔ \n10.\\tییلہ میون مول تہٕ میانہِ موج میہ ترٲوِن، تیلہِ کرِ رب میہ تُلان۔ {رٔٹِو...: ہیب۔ میہ جمع کرُن}\n11. اے خداوند، میہ ہیچھناوو پنٕنۍ وتھ تہٕ میانین دشمنن ہٕندِ وجہ سٍتـ̡ کٔرِو میہ سیدِ وتہِ پٲٹھۍ۔ {اکھ سادٕ...: عبری۔ سادٕچ وتھ} {میانۍ...: حب۔ یِم میہ وچھان چھِ}\n12. میہ کٔر نہٕ میانین دُشمنن ہٕنزِ مرضی ہٕندِس تابع کرنہٕ، کیازِ میہ خلاف چھِ اپُز گواہ کھڑا گٔمٕتۍ، تہٕ یِتھٕ پٲٹھۍ چھِ ظُلم دِوان۔ \n13. {بہٕ اوسُس بیہوش گومُت}، یوتام نہٕ بہٕ زندٕ سٕندِس ملکس مَنٛز خداوند سٕنز نیکی وُچھنُک یقین آسہٕ ہا۔ \n14. خداوند سُند انتظار کرُن: رٔژ ہمت تھاوُن، تہٕ سُہ کرِ تُہند دِل مضبوٗط: بہٕ چُھس ونان خداوند سُند انتظار۔","1. [{داؤد سُند زبور}] اے خداوند، میانہِ کُنہ\n2.\\tمیانہِ دعاہچ آواز بوزو، ییلہ بہٕ ژے فریاد کران چھُس، ییلہ بہٕ چانہِ مقدس آراجس کُن اتھہ تُلان۔ {تُہُن...: یا، چانہِ مقدس مقامس کُن تُلِتھ\n3.\\tبدکارن تہٕ بدکارن سٍتـ̡ کٔرِو نہٕ میہ پانس سٍتـ̡ ، یِم پننین ہمساین سٍتـ̡ امن کتھ کران چِھہ، مگر تِہندِس دِلس مَنٛز چُھ شرارت {چُھ}۔ \n4.\\tتِمن ہٕندِ اعمال مُطٲبق دِیُن تہٕ تِمن ہٕنزِ کوششہِ ہٕنزِ بدکاری مُطٲبق: تِمن دِیُن تِمن ہٕندِس اتھہٕ سٍتـ̡ کٲم کرنہٕ پتہٕ۔ تِمن دِیُن تِمن ہُند صحرا۔ \n5. تِکیازِ تِم چِھ نہٕ خداوند سٕندِس کامہِ سٍتـ̡ تہٕ تٔمۍ سٕندِس اتھن ہٕندِس عملہِ ہُند خیال تھاوان، سُہ کرِ نہٕ تِمن تباہ تہٕ تِمن ہٕندِس تعمیرس سٍتـ̡ ۔ \n6. خداوند سُند مُبارک، تِکیازِ تٔمۍ چُھ میانہِ دُعاے ہٕنز آواز بوزمٕژ۔ \n7. خداوند چُھہ میٲنۍ طاقت تہٕ میٲنۍ ڈھال؛ میانہِ دِل چُھس أمِس پیٹھ بھروسہٕ تہٕ بہٕ چُھس مدد سپدان: تێمہِ مۄکھٕ چُھس میون دِل سٮ۪ٹھاہ شاد سپدان۔ تہٕ بہٕ کَرٕ پننہِ گیونہٕ سٍتـ̡ تسٕندِس تعریف۔ \n8. خداوند چُھہ تِہُند طاقت، تہٕ سُہ چُھہ پنہٕ نِس مسح کرنہٕ آمٕژ سٕنز نجات دِنٕچ طاقت۔ {تِہُن: یا، تٔمِس} {بچاوُن...: ہیب۔ نجات ہٕنز طاقت}\n9. پَنٕنـ̡ لُکھ بچاوُن، تہٕ پَنٕنـ̡ وَرثس کٔرِو برکت: تِمن تہِ کھیٛاوُن، تہٕ تُلِو تِمن ہمیشہٕ خٲطرٕ۔ {کھؠن: یا، حکم}","1. [داؤد سُند زبور۔] اے طاقتور، خداوند سُند جلال تہٕ طاقت دِیُو۔ {اے طاقتور: ہیب۔ اے طاقتور سٕندِ فرزندو}\n2. خداوند سٕندِس ناوُک جلال دِیُو؛ پاکیزگی ہٕنزِ خوبصورتی مَنٛز کٔرِو خداوند سٕنز عبادت۔ {جلال ...: ہیب۔ تٔمۍ سٕندِس ناوُک عزت} {منز...: یا، تٔمۍ سٕندِس شاندار مقدس مقامس منز}\n3. خداوند سٕنز آواز چُھہ آبس پیٹھ: جلال ہُند خدا چُھ گرٛٮ۪جہ دِوان: خداوند چُھ واریہن آبن پیٹھ۔ {واریاہ : یا، عظیم}\n4. خداوند سٕنز آواز {چُھ} طاقتور؛ خداوند سٕنز آواز {چُھ} عظمتس سٍتـ̡ بٔرِتھ ۔ {طاقتور: ہیب۔ طاقتس منز} {پور...: حب۔ عظمتس منز}\n5. خداوند سٕنز آواز چُھ دیودار پھُٹراوان؛ آ، خداوند چُھ لبنان کِس دیودار پھُٹراوُن۔ \n6.\\tسُہ چُھ تِمن تہِ بَچھرِ ہٕندۍ پٲٹھۍوُن تراوان۔ لبنان تہٕ سیریون چھُ جوان یونیکورن ہٕندۍ پٲٹھۍ۔ \n7. خداوند سٕنز آواز چِھ نارٕچ نار تقسیم کران۔ {تقسیم: ہیب۔ کُٹتھ آوٹ}\n8. خداوند سٕنز آواز چھے بیابان ہلاوان۔ خداوند چُھ کادیش کِس بیابانس ہلاوان۔ \n9.\\tخداوند سٕنز آواز چھے ہِندِس کُنہِ\n10. خداوند چُھ سیلابس پیٹھ بِہتھ۔ آ، خداوند چُھ ہمیشہٕ خٲطرٕ بادشاہ بِہان۔ \n11. خداوند دِیہِ پننین لوکن طاقت دِنہٕ۔ خداوند کرِ پننین لوکن امن سٍتـ̡ برکت۔","1. [اکھ زبور {تہٕ} گیت {at} داؤد سٕندِس گرٕ سٕندِس وقف سٍتـ̡ ۔ اے خداوند، بہٕ کٔرٕ ژے سٕنز تعریف۔ کیازِ ژے چُھس مے تھوٚد کٔرمٕژ، تہٕ چُھنہٕ میانین دُشمن میہ پیٹھ شاد کرنہٕ خٲطرٕ بنوومُت۔ \n2. اے خداوند میانہِ خدایہ، میہ کٔر ژے نِش فریاد تہٕ ژے کٔر میہ شفا۔ \n3.\\tاے خداوند، ژے چھُکھ میون روح قبرِ منزٕ تُلمت تہٕ ژے تھووُکھ میہ زِندٕ، یُتھ بہٕ گژھہٕ نہٕ کھۅنہٕ کھۅنہٕ کُن بۄن۔ \n4. اے خداوند سٕندِس سٍتـ̡ گیوُن، اے تٔمۍ سٕندِس پاکیزگی ہٕندِس یادس پیٹھ کٔرِو شُکر۔ {at...: یا، یادگارس کُن}\n5.\\tتمۍ سندِ غصہ خاطرہ {برداش} کُنہِ ساعتہ تمۍ سندِ حقس منز چھہ زندگی {is} زندگی: روُن ہیکہِ اکس رٲژ تام روزان، مگر خوشی {یِتھ} صبحس چھِ۔ {تمۍ سُند غصہ...: ہیب۔ تمۍ سٕندِس غصس منز چُھ صرف اکھ لمحہ} {أکِس رٲژ خٲطرٕ: ہیب۔ شامس چُھ} {خوشی: ہیب۔ گیون}\n6.\\tتہٕ پننہِ خوشحالی منز ووٚن میہ زِ بہٕ گژھہِ نہٕ زانہہ تہِ ہلاونہٕ۔ \n7. اے خداوند، ژے کٔر پننہِ عنایت سٍتـ̡ میون پہاڑ مضبوط، ژے کٔر پَنُن بُتھ ژوٗر، {تہٕ} بہٕ گۆو پریشان۔ {بنوو...: ہیب۔ میٲنِس پہاڑس خٲطرٕ کٔر طاقت}\n8. اے خداوند، میہ کٔر ژے نِش دُعا۔ تہٕ میہ کٔر خداوند سٕنز دُعا۔ \n9.\\tییلہ بہٕ کھۅنہِ کھۅنہِ منز گژھہِ میانہِ خونس منز کیا فٲید؟ کیا گردِ چانہِ تعریف؟ کیا یہ کرِ چانہِ حقیقتُک اعلان؟ \n10. اے خداوند، بوز تہٕ میانہِ پیٹھ رحم کرُن: اے خداوند، بہٕ بٔنِو میٲنۍ مددگار۔ \n11. ژے کٔر میانہِ خٲطرٕ میون ماتم نژنس مَنٛز، تہٕ ژے کٔرٕکھ میٲنۍ بۄٹہٕ پلو تہٕ خۅش گٔژھمٕژ۔ \n12.\\tیُتھ زِ {میانہِ} جلال گژھہِ تۅہہِ سٍتـ̡ تعریف، تہٕ ژھۄپہٕ روزُن نہٕ۔ اے خدا، بہٕ کَرٕ ژے ہمیشہٕ خٲطرٕ شُکرگزار۔ {میٲنۍ عظمت: یعنی، میٲنۍ زبان، یا میانہِ روح}","1. [اہم موسیقارس تام، داؤد سُند زبور۔] اے خداوند، بہٕ چُھس پانس پیٹھ بھروسہٕ تھاوان؛ بہٕ گژھ نہٕ زانہہ شرمندٕ: پنٕنۍ نیکی سٍتـ̡ دِژ میہ بچاو۔ \n2.\\tپَنُن کَن کٔرِو میہ کُن نَمُن؛ مے کٔرِو جلدی رَلاون: ژٕ بَنُن میٲنۍ مضبوٗط پتھر، یُس میہ بچاونہٕ خٲطرٕ اکھ گرٕ بچاو۔ {میانۍ...: ہیب۔ میہ کُن اَکھ کُن طاقتُک پٲٹھۍ}\n3. تۅہہ خٲطرٕ چُھہ میٲنۍ کَنہِ تہٕ میٲنۍ قعلہٕ۔ تێلہِ کٔر پننہِ ناوٕ خٲطرٕ مے رہنُمٲیی تہٕ رہنُمٲیی کٔرِو۔ \n4.\\tمیہ کٔڈِتھ کٔڈِتھ یُس تمو میانہِ خاطرہ تھوومُت چھُ، تکیازِ ژے چھُکھ میٲنۍ طاقت۔ \n5. بہٕ چُھس پنُن روح تُہنٛدِس اتھس مَنٛز حوالہٕ کران: اے خداوند سُہ خدا، ژے چُھس مےٚ نجات دِژمُت۔ \n6. بہٕ چُھس تِمن سٍتـ̡ نفرت کٔرمٕژ یِم اپُزِ بےکار سٍتـ̡ چِھہ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡ \n7. بہٕ روزٕ چانہِ رحمتَس مَنٛز خۄش تہٕ خۄش، تِکیازِ ژے چُھکھ میانہِ مصیبت سٍتـ̡ غور کٔرمٕژ۔ ژے چُھکھ مُصیبتن مَنٛز میانہِ روح زانان۔ \n8.\\tتہٕ چُھس نہٕ مے دُشمن ہٕندِس اتھس منز بند کٔرِتھ: ژے چُھکھ میٲنۍ قدم أکِس بٔڈِس کمرس منز تھٲومٕتۍ۔ \n9.\\tاے خداوند، میہ پیٹھ رحم کرُن، کیازِ بہٕ چُھس مصیبتَس مَنٛز: میٲنۍ أچھ چھے غمس سٍتـ̡ کھٲلِتھ، {ہاں}، میون روح تہٕ میٲنۍ یٔڈ۔ \n10. تکیازِ میانہِ زندگی چھے غمس سٍتۍ گُزٲرمٕژ، تہٕ میانہِ ؤری چھے شۅنگہٕ سٍتـ̡ گُزٲرمٕژ: میانہِ بدکاری سٍتـ̡ چُھہ میٲنۍ طاقت ختم سپدان، تہٕ میٲنۍ أڈجہِ چِھہ ختم گٔمٕژ۔ \n11.\\tبہٕ اوسُس پننین سارِنٕے دُشمنن منز، خاص کر پننین ہمساین منز، تہٕ پننین واقفَن ہُند خوف: یِمو میہ وُچھمُت اوس، تِم ژٔلِتھ ژٔلِتھ ژٔلِتھ۔ \n12.\\tبہٕ چُھس مٔرِتھ مٔرِتھ ذہنس منز: بہٕ چُھس پھُٹمُت بانہٕ ہٕندۍ پٲٹھۍ۔ {اکھ پھُٹمُت...: ہیب۔ اکھ برتن یُس ختم سپدان چُھ}\n13.\\tکیازِ میہ بوز واریاہن ہُند بہتان : پریتھ طرفہٕ اوس خوف: ییلہ تمو میانہِ خلاف رٔلتھ مشورٕ کٔرۍ، تِمو کٔر میون زُو نِنُک منصوبہٕ۔ \n14.\\tمگر میہ کٔر توے پیٹھ بھروسہ، اے خداوند، میہ ووٚنمُت، تہٕ چُھہ میٲنۍ خدا۔ \n15.\\tمیون زمانہ چُھہ تُہندس اتھس منز: میانین دشمنن ہٕندِ اتھہٕ نِش تہٕ یِمن نِش یِم میہ ستاوان چھِ۔ \n16.\\tپَنُن بُتھ کٔرِو پَنٕنِس خادمَس سٍتـ̡ چمکُن: پننہِ رحمتہٕ خٲطرٕ کٔرِو مے بچاو۔ \n17.\\tاے خداوند، میہ گژھ نہ شرمندہ گژھُن۔ کیازِ میہ چُھہ ژے بُلاونہٕ آمُت: بدکار گژھن شرمندہ گژھن، {تہٕ} قبرِ منز گژھن ژھۄپہٕ۔ {ژھۄپہٕ...: یا، ژٔٹِتھ کٔرِو}\n18.\\tاپُز وُٹھ گژھہِ ژھۄپہٕ کٔرِتھ۔ یِم نیکوکارن خلاف فخرٕ تہٕ حقارت سان کتھ کران چھِ۔ {غمگین...: ہیب۔ اکھ مشکل چیز}\n19.\\t{اوہ} کوتاہ بٔڈ چُھہ چانۍ نیکی، یُس ژے تِمن ہٕندِ خٲطرٕ تھوومُت چھُ، یُس ژے کھوژان چھُ۔ {یُس} ژے تِمن ہٕندِ خٲطرٕ کٔرِمُت یُس توے انسانن ہٕندِس فرزندس برونہہ کُن پژھ تھاوان چُھ! \n20.\\tژے تھاوُن تِم پننہِ موجودگی ہٕندِس رازس منز انسانہ سٕندِس غرورس نِش ژوٗرِ تھاوُن: ژے تھاوُن تِم ژوٗرِ پٲٹھۍ، زبانن ہٕندِس کشمکش نِش ۔ \n21.\\tبابرکت {بَن} خداوند: کیازِ تٔمۍ ہٲو میہ أکِس مضبوٗط شہرس مَنٛز پنٕنۍ حیرت انگیز مہربانی ہٲومٕژ۔ {مضبوط: یا، تار لٔگِتھ}\n22.\\tکیازِ میہ ووٚن جلدی منز زِ بہٕ چُھس چانہِ أچھن برونہہ کُن ژٹنہٕ آمُت، توتہِ بوز ژے میانہِ دُعا ہٕنز آواز ییلہ بہٕ ژے فریاد دِژمُت۔ \n23. اے خداوند سٕندِس سارِنٕے مُقدسَن سٍتـ̡ محبت کرُن: {تکیازِ} خداوند چُھ ایماندارن رٲچھ کران، تہٕ فخر کرن وٲلِس سٍتـ̡ سٍتـ̡ انعام۔ \n24. اصل ہمت تھاوُن، تہٕ سُہ کرِ تُہند دِل مضبوط، یُس خداوند سٕنز وۅمید تھاوان چھُ۔","1. [{زبور} داؤد، مشکیل سُند۔] بابرکت {کیا سُہ چُھ} یُس غلطی {چُھ} معافی دِنہٕ آمُت، {یُس} گۅناہ {چُھ} کور کورمُت۔ {اکھ زبور...: یا، داؤد سُند اکھ زبور دِنہٕ آمُت}\n2. بابرکت چُھہ سُہ انسان یٔمِس سٍتـ̡ خداوند بدکاری ہُند الزام چُھ نہٕ دِوان، تہٕ یٔمِس روحس مَنٛز چُھنہٕ کانہہ دھوکہ دِنہٕ آمُت۔ \n3.\\tییلہ میہ ژھۅپہ کٔرتھ، میانہِ اڈجہ ٲس سٲرۍسٕے دۅہس گڑبڑ کٔرتھ۔ \n4.\\tدۅہ تہٕ رٲژ ٲس چانۍ اَتھٕ میہ پیٹھ گٔژھمٕژ: میون نمی چھُ رٮ۪تہٕ کالہٕ کِس خشک سالی منز تبدیل۔ سیلہ۔ \n5. میہ کٔر ژے برونہہ کُن پنُن گۅناہ قبول، تہٕ پنُن گناہ چھُس نہٕ ژوٗرِ تھوومُت۔ میہ ووٚن، بہٕ کٔرٕ خداہس برونہہ کُن پنٕنۍ غلطی ہُند اقرار ۔ تہٕ ژے کٔر میانہِ گۅناہ ہُند گناہ معاف۔ سیلاہ۔ \n6. یێمہِ سٍتـ̡ پرٮ۪تھ کانہہ یُس خدایہ آسہِ تۅہہِ سٍتـ̡ دُعا دُعا کٔرِتھ، یێلہِ تہٕ بێیہِ آبہٕ کِس سٔلابن مَنٛز گژھن نہٕ تِم أمِس نِش وٲتِتھ۔ {کِنہِ...: ہیب۔ ژھانڈنہٕ سٍتـ̡\n7. ژٕ چُھکھ میٲنۍ روزنٕچ جاے ژٕ کٔرِکھ مے مُصیبت نِش بچاوُن؛ ژٕ کٔرِکھ مےٚ نجات ہٕندِس بٲتس سٍتـ̡ گھیرٕنـ̡ ۔ سلہٕ۔ \n8.\\tبہٕ کرٕ ژے ہیچھناوُن تہٕ تۅہہ ہیچھناوُن یتھ وتہِ ژے گژھِ: بہٕ کٔرٕ ژے پننہ اچھو سٍتـ̡ رہنُمٲیی کٔرِتھ۔ {رہبر...: ہیب۔ مشورٕ دِیُن، میٲنۍ نظر آسہِ توے پیٹھ}\n9.\\tگُرِ ہٕندۍ پٲٹھۍ، {یا} گُرِ ہٕندۍ پٲٹھۍ، {یٔمِس نہٕ کانہہ فِکر} آسہِ، یٔمۍ سٕندِس ٲسِس گُرِ تہٕ لگام سٍتۍ رٔٹِتھ گژھِ، نتہٕ یِم تۅہہِ نزدیک۔ \n10. بدکارن خٲطرٕ گژھن واریاہ غم مگر یُس خداوند پیٹھ بھروسہ کرِ، سُہ کرِ تس اندۍ پکھۍ رحمت۔ \n11.\\tخداوند سٍتـ̡ گژھِو خوش تہٕ خوش گژھو، اے نیک لوگو، تہٕ یێلہِ سارِنٕے {یێلہِ} دِل دِلہٕ سٍتـ̡ دِل دِنہٕ آمٕژ چھِ، خوشی خٲطرٕ کٔرِو کرٛٮ۪کہٕ۔","1. اے نیک لوگو، خداوند سٕندِس سٍتـ̡ کٔرِو شاد سپدُن: {تکیازِ} چُھہ نیک سٍتـ̡ تعریف۔ \n2. خدایہ سٕندِ حمد کٔرِو ہارپ سٍتـ̡ تہٕ دہن تارن ہُند ساز۔ \n3. أمِس گٮ۪وُن اکھ نوٚو بٲتھ بَڑِ شورٕ سٍتۍ گِندُن مہارت سان گِندُن۔ \n4. خداوند سُند کلام {چُھ} صحیح؛ تہٕ تٔمۍ سٕنز سٲری کٲم {چِھ} پٔزۍ پٲٹھۍ۔ \n5. سُہ چُھ نیکی تہٕ فیصلہٕ سٍتـ̡ محبت کران: زمین چُھ خداوند سٕنزِ نیکی سٍتـ̡ بٔرِتھ۔ {نیکی: یا، رحمت}\n6.\\tخداوند سٕندِ کلامَس سٍتـ̡ بنیوو اسمان۔ تہٕ تِمن ہُند سارِوٕے لشکر اوس تٔمۍ سٕندِ ٲسٕچ شہس سٍتـ̡ بنیومُت۔ \n7.\\tسُہ چُھ سمندرُک آب أکِس ڈھیرس سٍتـ̡ جمع کران: سُہ چُھ ذخیرن مَنٛز سرٛنٮ۪ر تراوان۔ \n8. سارِنٕے زمینہٕ گژھہِ خداوند سٕندِ سٍتـ̡ خوفزدہ گژھُن: دُنیاہٕکۍ سارِنٕے بسکیٖن دِنہٕ یِن أمِس سٍتـ̡ خوفزدہ گٔژھِتھ۔ \n9.\\tتکیازِ تٔمۍ کٔر کتھ تہٕ یہِ اوس {کرنہٕ}۔ تٔمۍ دِژ حُکُم، تہٕ سُہ کھڑا کھڑا۔ \n10. خداوند چُھ کافرن ہٕندِس مشورس کُن انان: سُہ چُھ نہٕ لوکن ہٕندِس چالس کُنہِ تہِ اثر تھاوان۔ {انن: ہیب۔ مایوس کران}\n11. خداوند سُند مشورٕ چُھ ہمیشہٕ خٲطرٕ قایم روزان، تٔمۍ سٕندِ دِلُک خیال چُھ سارنٕے نسلن خٲطرٕ۔ {سارنٕے خٲطرٕ...: ہیب۔ نسلہٕ تہٕ نسلہٕ خٲطرٕ}\n12. سُہ قوم چُھ بابرکت یٔمۍ سُند خدا چُھ خداوند چُھ؛ تہٕ سُہ لُکھ یُس تٔمۍ پننہِ وراثتہٕ خٲطرٕ چُھ ژٲرمُت۔ \n13. خداوند چُھ آسمانہٕ سٍتـ̡ وُچھان۔ سُہ چُھ سارِنٕے اِنسانن ہٕندِس فرزندس وُچھان۔ \n14.\\tپننہِ بستی ہٕنزِ جایہِ پیٹھٕ چُھ سُہ زمینہٕ کین سارِنٕے بسکینن وُچھان۔ \n15. سُہ چُھ تِہندِ دِل ہِوُے بناوان ۔ سُہ چُھ تِہٕندِس سارِنٕے کامہِ پیٹھ غور کران۔ \n16.\\tکانہہ تہِ بادشاہ چُھہ نہٕ یُس أکِس لشکرس سٍتـ̡ بچاوان چُھہ: طاقتور انسان چُھہ نہٕ زیادٕ طاقتہٕ سٍتـ̡ بچاونہٕ یِوان۔ \n17.\\tگُرِ چُھہ حفاطتہٕ خٲطرٕ اکھ فضول چیز: نہ ہیکہِ سُہ پننہِ زبردست طاقتہٕ سٍتۍ کانہہ تہِ دِتھ۔ \n18.\\tوُچھِو خداوند سٕنز نظر تِمن پیٹھ یِم أمِس کھوژان چھِ، تِمن پیٹھ یِم تٔمۍ سٕنزِ رحمتٕچ وۅمید چھِ۔ \n19.\\tتِہُند روح مرنہٕ نِش نجات دِنہٕ خٲطرٕ، تہٕ قحطس مَنٛز زندٕ تھاوُن۔ \n20. سون روح چُھ خداوند سُند انتظار کران: سُہ چُھ سانہِ مدد تہٕ سون ڈھال۔ \n21. تکیازِ سون دِل گژھہِ أمِس مَنٛز شاد گژھُن، کیازِ أسۍ چُھ تٔمۍ سٕندِس پاک ناوس پیٹھ بھروسہٕ کورمُت۔ \n22. اے خداوند، چانۍ رحمت گژھہِ اسہِ پیٹھ، یتھہ پاٹھۍ أسۍ توے سٍتـ̡ وۅمید کران چھِ۔","1. [{زبور} داؤد سُند، ییلہ تٔمۍ ابیمیلکس برونہہ کُن پنُن ورتاو بدلوو۔ یُس أمِس ژٔلِتھ ژٔلِتھ تہٕ سُہ ژٔلِتھ دِنہٕ آمُت۔ {ابیمیلک: یا، آخش}\n2. میانہِ روح کرِ أمِس خداوند سٕندِس سٍتـ̡ فخر کرنہٕ: عاجز بوزنہٕ تہٕ خۅش گژھن۔ \n3. اے خداوند کٔرِو میانہِ سٍتـ̡ تٔمِس س \n4.\\tمیہ کٔر خداوند سٕندِ سٍتـ̡ تہٕ تٔمۍ بوز تہٕ بێیہِ میہ سارِنٕے خوفہٕ نِش بچاوُن۔ \n5.\\tتِمو گٔیہِ أمِس کُن نظر، تہٕ گٔیہِ ہلکہٕ، تہٕ تِہٕندِس بُتھِس گٔیہِ نہٕ شرمندٕ۔ {ہلکہٕ گٔیہِ: نتہٕ گٔیہِ تِم أمِس کُن بہت}\n6.\\tأمِس بِچارس کٔر دِژ، تہٕ خداوند بوٗز تہٕ بچٲوُن سُہ سارِوٕے مصیبت نِش نِش۔ \n7. خداوند سُند فرشتہٕ چُھ تِمن اندۍ پٔکھۍ ڈیرٕ تراوان یُس أمِس خوفزدہ چُھ، تہٕ چُھ تِمن نجات دِوان۔ \n8. اے چکھ تہٕ وُچھو زِ خداوند {چُھ} اصل: بابرکت {چُھ} انسان {یُس} یُس أمِس پیٹھ بھروسہ کران چُھ۔ \n9. اے خداوند سُند خوف تھاوُن، اے تٔمۍ سٕندِس مُقدس، کیازِکہِ یِمن ہٕندِس سٍتـ̡ چُھہ نہٕ تِمن ہٕندِس سٍتـ̡ کانہہ ضرورت یُس أمِس سٍتـ̡ کھوژان چُھہ \n10. جوان شیرن چِھ کمی تہٕ فاقہٕ چِھ: مگر یُس خداوند سُند تلاش کران چُھ، تِم گژھن نہٕ کُنہِ نیکی چیزٕچ ضرورت۔ \n11.\\tیِمو بچو، میانہِ کتھ بوزو: بہٕ ہیچھناوٕ ژے خداوند سُند خوف۔ \n12. کُس انسان چُھ یُس زندگی ہُند خواہش، {تہٕ} چُھ {واریہ} دۅہن محبت کران، یُس سُہ نیکی وُچھِتھ؟ \n13. پَنٕنۍ زبان تھاو بد نِش تہٕ چپنہٕ نِس وٕٹھس بد کَرنہٕ نِش۔ \n14. بدی نِش دور گژھُن، تہٕ نیکی کٔرِو۔ امن ژھارِو، تہٕ اَمیُک تعاقب کرُن۔ \n15.\\tخداوند سٕنزِ أچھ چِھہ نیکوکارن کُن، تہٕ تٔمۍ سٕندِس کَن چِھہ تِہٕنزِ فریاد خٲطرٕ یلہٕ۔ \n16.\\tخداوند سُند بُتھ چُھہ تِمن خلاف یُس بد کار کران چُھ، یُس تِمن ہُند یاد زمینہٕ نِش ژٹِتھ چھُ۔ \n17.\\t{نیکوکار} چُھ فریاد دِوان، تہٕ خداوند چُھ بوزان تہٕ تِمن سارِنٕے مصیبتن نِش نجات دِوان۔ \n18.\\tخداوند چُھہ تِمن ہٕندِس نزدیک، یُس پھُٹمُت دِل چُھ، تہٕ یِمن ہٕندِس دِلس سٍتـ̡ نجات دِوان چُھ۔ {کُن...: ہیب۔ دِل پھُٹِتھ دِلِس سٍتـ̡ {پشیمان سٍتـ̡ چُھہ} {پشیمان سٍتـ̡ دِل دِنہٕ آمُتـ̡ ۔ تہٕ چُھہ تِمن ہٕندِس دِلس سٍتـ̡ نجات دِوان۔ {to...: Heb. دِل پھُٹِس سٍتـ̡ {پچھتاوٕ سٍتـ̡ ﴿ روٝحہِ سٍتـ̡\n19. واریاہ چِھہ صالحین ہٕندِ عذاب، مگر خداوند چُھ سُہ سارِوٕے نِش نجات دِوان۔ \n20.\\tسُہ چُھ پنٕنۍ سارِنٕے أڈجہِ تھاوان: یِمو منزٕ چُھنہٕ اکھ تہِ پھُٹمُت۔ \n21.\\tبدکار مارِ بدکارن تہ یُس نیکین سٍتـ̡ نفرت کران آسہِ تم گژھن ویران کرنہٕ۔ {ویران: یا، مجرم}\n22. خداوند چُھ پَنٕنـ̡ خادمَن ہُند روح نجات دِوان: تہٕ یێمِس سٍتـ̡ أمِس پیٹھ بھروسہٕ آسہِ نہٕ تِمن مَنٛز گژھِ نہٕ کانہہ تہِ ویران گٔژھِتھ۔ {ویران : یا، قصور}","1. [{داؤد سُند زبور}] اے خداوند، تِمن سٍتـ̡ کٔرِو یِم میانہِ سٍتـ̡ جدوجہد کران چِھہ، تِمن سٍتـ̡ کٔرِو جنگ یِم میانہِ خلاف لڑان چِھہِ۔ \n2. ڈھال تہٕ بکلرس تھپھ کٔرِتھ، تہٕ میانہِ مدتہٕ خٲطرٕ کھڑا کھڑا گژھُن۔ \n3.\\tنیزٕ تہِ کٔڈِتھ تہٕ یِمن سٍتـ̡ رُکٲوِو تِمن خلاف یُس میہ ستاوان چُھس، میانہِ روحس ونُن، بہٕ چُھس تُہند نجات دِوان۔ \n4.\\tتِم گژھن پریشان تہٕ شرمندہ کرنہٕ یُن یُس میانہِ روحس ژھاران چھُ، تِم گژھن واپس پھیرن تہٕ یُس میانہِ دکھ ہُند سبب بنان چھُ۔ \n5.\\tتِم گژھن ہوہس برونہہ کُن گۅپھ ہٕندۍ پٲٹھۍ: تہٕ خداوند سُند فرشتہٕ گژھہِ تِمن ہُند تعاقب کرُن۔ \n6.\\tتِہٕنزِ وَتھ گژھہِ انہِ گٹہِ تہٕ رِژٕنـ̡ تہٕ خداوند سُند فرشتہٕ گژھہِ تِمن ستاونہٕ یُن۔ {اندھیر...: ہیب۔ انہِ گوٚٹ تہٕ رِکُن}\n7.\\tتکیازِ بلا وجہ چھُ تِمو میانہِ خٲطرٕ پنُن جال ژوٗرِ تھوومُت، {یُس} بغٲر وجہ چھُ تِمو میانہِ روحہٕ خٲطرٕ کھننہٕ آمُت۔ \n8.\\tتٔمِس سٍتـ̡ بێیہِ تباہی یُس أمِس سٍتـ̡ پۯاوُن؛ تہٕ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ تٔمِس پۯاونہٕ آمُت چُھہ تٔمِس سٍتـ̡ پۯاونہٕ آمُت۔ {at...: Heb. یُس نہٕ تس پتاہ چُھ}\n9. تہٕ میٲنۍ روح روزِ خداوند سٕندِس سٍتـ̡ خۅش تہٕ سُہ روزِ تٔمۍ سٕنزِ نجات سٍتـ̡ شاد۔ \n10.\\tمیانہِ سارِنٕے أڈجہِ وَنُن، اے خداوند، یُس چُھہ ژے ہیوٗ یُس غریبس تٔمِس نِش بچاوان چُھ، یُس أمِس سٍتـ̡ زیادٕ طاقتور چُھ، آ، غریبن تہٕ محتاجن نِش یُس أمِس خراب کران چُھ؟ \n11.\\tاپُز گواہ گٔیہِ وۅتھان۔ تِمو کٔر میٲنِس الزام {تِمَن} یِم نہٕ میہ پتاہ ٲسۍ۔ {غلط...: ہیب۔ غلط گواہ گٔیہِ} {تِم...: ہیب۔ تِمو پرژھ مے}\n12.\\tتِمو دِژ میہ بُرِس سٍتـ̡ نیکی خٲطرٕ انعام۔ {خراب: ہیب۔ محروم}\n13.\\tمگر میانہِ خٲطرٕ، ییلہ تم بیمار ٲسۍ، میون پلو اوس روزٕ سٍتـ̡ عاجز کٔرِتھ پنُن روح۔ تہٕ میٲنۍ دُعا گۆو پننِس سینس مَنٛز واپس۔ {عاجزی: یا، مُتٲثِر}\n14.\\tمیہ اوس پنن پان تتھہ پاٹھۍ برتاو کران زِ {سُہ اوس}میون دوس {یا} بٲے: میہ کٔر گۅب سٍتۍ نمُن، یُس پننہِ ماجہ ہُند ماتم کران چھُ۔ {سٍتـ̡ سٍتـ�\n15.\\tمگر میانہِ مصیبت منز گٔیہ تِمو خۅش تہٕ جمع گٔیہِ پان جمع کٔرِتھ: {آ}، میہ کٔر پان میہ خلاف جمع تہٕ میہ ٲس نہٕ خبر۔ تِمو ژٔٹۍ {me}، تہٕ بند کٔرِتھ نہٕ: {مُصیبت: ہیب۔ رُکُن}\n16.\\tدعوتن مَنٛز منافق طنز کٔرِتھ کٔر تِمو میہ دندٕ دندٕ دِتھ۔ \n17.\\tخداوند، ژے کوتاہ کالس وچھان؟ میانہِ روح بچاو تِہندِ تباہی نِش، شیرن نِش میانہِ پیاری۔ {ڈارلنگ: ہیب۔ صرف اکھ}\n18.\\tبہٕ کٔرٕ ژے بٔڈِس جماعتس مَنٛز شُکرگزار: بہٕ کٔرٕ تۅہہِ ہٕندِس تعریفس مَنٛز۔ {واریاہ زیادٕ: ہیب۔ مضبوط}\n19. یِم میٲنۍ دُشمن چھِ تِم گژھن نہٕ میانہِ سٍتـ̡ ناجائز طور خۅش گٔژھن: {تہِ} تِم گژھن أچھ أچھ سٍتـ̡ أچھ دِنہٕ یُس کُنہِ وجہہ ورٲے میہ سٍتـ̡ نفرت کران چُھ۔ {غلط: ہیب۔ اپز}\n20.\\tتِکیازِ تِم چھِنہٕ امن کَران، مگر تِم چھِ تِمن خلاف دھوکہٕ دِوان یِم زمینس مَنٛز خاموش چھِ۔ \n21.\\tآ، تِمو کٔر میہ خلاف پنُن بوش کھوٚل، {تہٕ} وونُن، آہا، آہا، سانہِ أچھ چھے وُچھمٕژ۔ \n22. {یہِ} ژے وُچھمُت، اے خداوند: ژھۄپہٕ نہٕ روزُن: اے خدا، میانہِ نِش گژھ نہٕ دور۔ \n23. پَنُن پان ہِلٲوِو، تہٕ میانہِ فٲصلس سٍتـ̡ ہوشیار گژھُن، میانہِ خدایہ تہٕ میانہِ رَب سٍتـ̡ ۔ \n24. اے خداوند میانہِ خدایہ، پننہِ نیکی مُطٲبق کٔر میہ فٲصلہٕ۔ تہٕ تِم گژھن نہٕ میانہِ سٍتـ̡ خوش گژھن۔ \n25.\\tتِم گژھن نہ پننین دلن منز ونن، آہ، تِتھے پٲٹھۍ، اسہِ تہِ گژھہِ نہٕ ونُن، اسہِ چُھ سُہ نِگِلہٕ نِمُت۔ {آہ...: حب۔ آہ، آہ، سون روح}\n26.\\tتِم گژھن شرم تہٕ اِکہٕ وٹہٕ افراتفری ہٕندِس سٍتـ̡ یُس میانہِ دَمہٕ سٍتـ̡ خۅش سپدان چُھ، تِمن گژھن شرم تہٕ بے عزتی سٍتـ̡ لٔگِتھ یُس میانہِ خٕلاف بٔرِتھ بٔرِتھ۔ \n27.\\tتِم گژھن خوشی سٍتـ̡ کرٛٮ۪کہٕ دِن، تہٕ خۅش گژھن یُس میانہِ نیک مقصدس سٍتـ̡ احسان کران چُھہ: آ، تِم گژھن لگاتار وَنُن، خداوند گژھہِ بڑاونہٕ یُن، یُس پننِس بندہ سٕنزِ خوشحالی سٍتـ̡ خوش آسہِ۔ {راستباز...: ہیب۔ نیکی }\n28. تہٕ میٲنۍ زبان روزِ سٲرۍسٕے دۅہس چانہِ نیکی ہٕنز کتھ کرنہٕ۔","1. [اہم موسیقارس سٍتـ̡، خداوند سٕندِس خادم سُند زبور] بدکارن ہٕنز گناہ چھے میٲنِس دِلس مَنٛز ونان زِ تٔمِس نظرن برونہہ کُن چُھنہٕ خدایہ سُند کانہہ خوف ۔ \n2.\\tتکیازِ سُہ چُھ پننین نظرن منز پنُن پان خوشامد کران، یوتام نہٕ تٔمۍ سٕنز بدکاری نفرت آمیز لبنہٕ ییہِ۔ {یوتام ...: ہیب۔ تٔمۍ سٕنز بدکاری ژھانڈنہٕ خٲطرٕ نفرت}\n3.\\tتٔمۍ سٕندِ کُنہِ کتھہِ ہٕندِس کلامَس چھِ بدکار تہٕ دھوکہٕ: تٔمۍ چھُ عقلمند روزُن، {تہٕ} نیکی کرنہٕ خٲطرٕ ترٲومُت۔ \n4.\\tسُہ چُھ پننِس بسترس پیٹھ شرارت کَران۔ سُہ چُھ پَنُن پان تِتھۍ پٲٹھۍ بِہان {یُس نہٕ نیکی چُھ}؛ سُہ چُھ نہٕ بدی سٍتـ̡ نفرت۔ {شرارت: یا، باطل چُھ}\n5. اے خداوند، تُہٕنٛز رحمت، {چُھ} آسمانس مَنٛز؛ {تہٕ}تُہٕنٛز وفاداری {واتہِ} اوٚبرَن تام۔ \n6. تُہند راستبازی {چُھ} بٔڈۍ پہاڑن ہٕندۍ پٲٹھۍ؛ تُہند فٲصلہٕ {چُھ} اکھ بٔڈ سرٛوٚن: اے خداوند، ژے چُھکھ انسان تہٕ درندٕ رژھراوُن۔ {the...: ہیب۔ خدایہ سٕندِ پہاڑ}\n7. اے خدایہ، چانہِ محبتہٕ کوتاہ عظیم چھُ! تێمہِ کِنۍ چھُ انسانن ہٕندِس شُرِ پَنُن پَنُن پَکھہٕ پَکھہٕ سٍتـ̡ پَنُن بھروسہٕ کٔرِتھ۔ {بہترین: ہیب۔ قیمتی}\n8. تِم گژھن تُہٕندِس گرٕ سٍتـ̡ سٍتـ̡ سٍتـ̡ مُطمئن۔ تہٕ ژے کٔرِو تِمن پنٕنـ̡ لذتن ہٕندِس دٔریاوُس چُھہ چُھس۔ {سٍتـ̡ ...: Heb. آب دِنہٕ}\n9. تِکیازِ ژے سٍتـ̡ چُھہ زندگی ہُند چشمہٕ: تێہٕندِس گاشس مَنٛز چُھہ أسـ̡ گاش وُچھان۔ \n10. اے تِمن سٍتـ̡ پَنٕنۍ محبتہٕ تھاوٕنـ̡ یُس تُہٕندِس زانان چُھہ، تہٕ پَنٕنـ̡ نیکی دِل دِلس سٍتـ̡ تھاوُن۔ {جٲری: عبرانی۔ زیچھر کٔرِو}\n11.\\tغرورُک قدم گژھہِ نہٕ میانہِ خلاف تہٕ بدکار سُند اتھہٕ گژھہِ نہٕ میہ ہٹاونہٕ۔ \n12.\\tبدکاری ہٕندِ کارکُن چھِ پٔرِتھ: تِم چھِ بٔنِتھ تہٕ وۅتھنہٕ ہٕندِس قٲبِل گٔژھِتھ ہیکان۔","1. [{داؤد سُند زبور}] بدکارن ہٕندِ وجہ سٍتـ̡ گژھ نہٕ پانس پریشان کرُن، تہٕ نہ گژھ بدکارن سٍتـ̡ حسد۔ \n2. تِم یِن جلدٕے گاسہٕ ہٕندۍ پٲٹھۍژٹنہٕ، تہٕ سبٕز کُلہِ ہٕندۍ پٲٹھۍ مرزاونہٕ۔ \n3. خداوند سٍتـ̡ بھروسہ کرُن، تہٕ نیکی کٔرِو۔ {یێلہِ} روزُن زمینس مَنٛز روزُن، تہٕ یێلہِ گژھہِ ژے کھؠنہٕ یِنہٕ۔ {پٔزۍ: ہیب۔ پٔزۍ پٲٹھۍ، یا، استقامت}\n4. خداوند سٕندِس سٍتـ̡ کٔرِو پنُن پان تہِ خۄش۔ تہٕ سُہ دِیہِ تُہٕندِس دِلٕچ خواہش۔ \n5. پَنٕنـ̡ وَتھ کٔرِو خداوند سٍتـ̡ وابستہٕ؛ تٔمِس پیٹھ تہِ کرو بھروسہٕ۔ تہٕ سُہ کرِ {یہِ} پورٕ۔ {Committ...: Heb. پَنٕنـ̡ وَتھ پۯاوُن}\n6. تہٕ سُہ کرِ تُہند نیکی گاشہٕ پٲٹھۍ، تہٕ تُہند فٲصلہٕ دُپہرُک پٲٹھۍ۔ \n7. خداوند سٕندِس سٍتـ̡ آرام کرُن، تہٕ تٔمِس سٍتـ̡ پۯاوُن پۯاوُن: یُس پننہِ وتہِ منز کامیاب سپدِ، تٔمِس شخصہٕ سٕندِ سٍتـ̡ یُس بدکار چُھہ اَنـ̡ دِنہٕ آمُتـ̡ پى۪ٹھ۔ {آرام کٔرِو: Heb. خاموش روزُن}\n8.\\tغصہٕ نِش بنٛد کٔرِو تہٕ غصہٕ ترک: بُرٕ کَرنہٕ خٲطرٕ گژھِ نہٕ پانس کُنہِ تہِ پٲٹھۍ۔ \n9. بدکار یِن ژٹنہٕ، مگر یُس خداوند سُند انتظار کرُن، تِم گژھن زمینہِ ہُند وارث۔ \n10.\\tکینژس کالس تہ بدکار گژھہِ نہ {بنہِ}: آ، ژیہ گژھہِ تمۍ سنزِ جایہ غور کرُن، تہ یہ گژھہِ نہ {بنہِ}۔ \n11. مگر عاجز گژھن زمینہِ ہُند وٲرث۔ تہٕ گژھن پانس سُہ سٍتـ̡ خۅش کٔرِتھ۔ \n12.\\tبدکار چھہ انصافس خلاف سازش کران، تہ دند کٔرتھ تس پیٹھ دندٕ دوان۔ {plotteth: یا، عمل کران}\n13. خداوند کرِ أمِس پیٹھ اسُن، تکیازِ سُہ چُھ وُچھان زِ تٔمۍ سُند دۅہ چُھ یِوان۔ \n14.\\tبدکارو کٔر تلوار کٔڈِتھ تہٕ کمان کٔرِتھ غریبن تہٕ محتاجن ژھیننہٕ خٲطرٕ، {تہٕ} یِمن سٍتـ̡ کتھ باتھہِ ہٕندِس سٍتـ̡ مارنہٕ مۅکھہٕ۔ {یِتھ...: ہیب۔ سیدِ وتہٕ}\n15.\\tتِہٕنزِ تلوار گژھہِ تِہندِس دِلس مَنٛز اژنہٕ، تہٕ تِہٕنزِ کمان یِن پھُٹراونہٕ۔ \n16.\\tیُس کُنہِ نیکی شخصس سٍتـ̡ چُھہ واریاہن بدکارن ہٕندِ دولتس کھۅتہٕ بہتر آسان۔ \n17.\\tبدکارن ہٕندِ ہٕندِ ہتھیار گژھن پھُٹنہٕ، مگر خداوند چُھ نیکوکارن ہٕنز رٲچھ کران۔ \n18.\\tخداوند چُھ نیک سٍتـ̡ دۅہہٕ زانان: تہٕ تِہُند وَراثت روزِ ہمیشہٕ خٲطرٕ۔ \n19.\\tبد وقتس منز گژھن نہ تِم شرمسار گژھن: تہٕ قحط کِس دۅہس منز گژھن تِم تسلی بخش۔ \n20. مگر بدکار گژھن ختم تہٕ خداوند سٕندِ دُشمن گژھن کۅکرِ ہٕندِس چربی ہٕندۍ پٲٹھۍ: تِم گژھن کھٮ۪ن؛ تِم گژھن دوٚہس مَنٛز کھٮ۪نہٕ۔ {چربہٕ: ہیب۔ قیمتی}\n21. بدکار چُھ قرضہٕ دِوان، تہٕ دُبارٕ چُھ نہٕ دِوان: مگر نیک چُھ رحم کَران، تہٕ دِوان دِوان۔ \n22. یُس أمِس سٕندِ سٍتـ̡ بابرکت آسہِ، سُہ گژھہِ زمینہِ ہُند وٲرث۔ تہٕ یُس أمِس سٍتـ̡ لعنتُک شُمار آسہِ، یِن ژٹنہٕ۔ \n23. اَکھ {اصل} انسان سٕندِ قدمن چُھ خداوند سٕندِ دٔسۍ حُکُم دِنہٕ آمُت: تہٕ سُہ چُھ پننہِ وتہِ سٍتـ̡ خۅش سپدان۔ {حُکُم: یا، قٲیم}\n24. یێلہِ تہِ سُہ پیٚیہِ نہٕ پوٗرٕ پٲٹھـ̡ دِنہٕ: کیازِ خداوند چُھ أمِس پنہٕ نِس اتھہٕ سٍتـ̡ رٔٹِتھ تھاوان۔ \n25. بہٕ چُھس جوان تہٕ {وُن} چُھس بُزرگ۔ توتہِ چُھس نہٕ میہ وُچھمُت نیکی تہٕ نہ تٔمۍ سٕندِس بُلِس روٹی منگان۔ \n26. {سُہ چُھ} ہمیشہ رحم کرُن، تہٕ دِنہٕ آمُت۔ تہٕ تٔمۍ سُند بُل {چُھ} بابرکت ۔ {ہمیشہٕ: ہیب۔ سارِوٕے دۅہ}\n27. بدی نِش نیرُن تہٕ نیکی کٔرِو۔ تہٕ ہمیشہٕ روزُن۔ \n28. کیازِ خداوند چُھ فیصلس محبت کران، تہٕ پننین مقدسن تراوُن نہٕ۔ تِم چِھ ہمیشہٕ خٲطرٕ رژھراونہٕ آمٕتۍ: مگر بدکارن ہُند بیول گژھہِ ژٹنہٕ۔ \n29.\\tصالحین گژھہِ زمینہِ ہُند وٲرث، تہٕ روزِ اَتھ مَنٛز ہمیشہٕ روزُن۔ \n30.\\tصالحن ہٕنز ٲس ٲس حکمتٕچ کتھ کران، تہٕ تسٕنز زبان چھے فیصلہٕ کِس بارس منز کتھ کران۔ \n31.\\tتٔمۍ سٕندِس خدایہ سُند قانون {چُھ} تٔمۍ سٕندِس دِلس مَنٛز۔ تٔمۍ سٕندِس قدمس منز گژھِ نہٕ کانہہ تہِ قدم۔ {قدم: یا، گَژھان}\n32. بدکار چُھ نیکوکارس وُچھان تہٕ أمِس مارنٕچ کوشش کران۔ \n33. خداوند تراوِ نہٕ أمِس اتھس منز، تہٕ نہ کرِ أمِس سزا دِنہٕ وِزِ أمِس مذمت۔ \n34.\\tخداوند سُند انتظار کرُن، تہٕ تٔمۍ سٕنزِ وتہِ تھاوُن، تہٕ سُہ کرِ تۅہہِ زمینہِ ہُند وٲرث۔ \n35.\\tمیہ وچھ بدکار سٮ۪ٹھاہ طاقتس منز، تہٕ سَبٕز کُلِس ہٕندۍ پٲٹھۍ۔ {اکھ سبز...: یا، اکھ سبز کُل یُس پننہِ میژِ منز کھسان چُھ}\n36.\\tتوتہِ گۆو سُہ تہٕ لو، سُہ اوس نہٕ: آ، میہ ژھانڈمُت، مگر سُہ ہیوٚک نہٕ لٔبِتھ۔ \n37.\\tکٲمل {انسان} نشان زد کرُن، تہٕ وُچھِو سیدِ سٍتـ̡ {یہ} انسان {چُھ} سُند خاتمہٕ۔ \n38. مگر بدکار گژھن یکوٹہ ختم کرنہٕ: بدکارن ہُند انجام گژھہِ ژٹنہٕ۔ \n39.\\tمگر صالحن ہنز نجات چھیہ خداوند سٕنز: {سُہ چُھ} مصیبت وِزِ تِہنز طاقت۔ \n40. تہٕ خداوند کرِ تِمن مدد تہٕ نجات دِیہِ، سُہ کرِ تِمن بدکارن نِش بچاو، تہٕ تِمن بچاوِ تِکیازِ تِم چھِ أمِس پیٹھ بھروسہٕ تھاوان۔","1. [داؤد سُند زبور، یاد پاونہٕ خٲطرٕ۔] اے خداوند، میہ کٔر نہٕ پننہِ غضبتس سٍتـ̡ ملامت کرنہٕ۔ \n2.\\tچانہِ تیر چُھس میہ منز رٔٹِتھ تہٕ چانہِ اتھہٕ چُھس دَگ دِوان۔ \n3.\\t{چانہِ غصہٕ سٍتـ̡ چُھہ نہٕ میٲنِس مازس مَنٛز کانہہ صحیح۔ نۂ چُھہ میانین گۅناہ سٍتـ̡ میانین اڈجن منز کانہہ آرام۔ {آرام: ہیب۔ امن، یا صحت}\n4.\\tمیانہِ خٲطرٕ چھِ میانہِ گُرِ ہٕندِس کَلس پیٹھ: یِم چھِ میانہِ خٲطرٕ واریاہ گۄب۔ \n5.\\tمیانہِ بے وقوفی کنۍ چھہ میٲنۍ زخم بدبو۔ \n6. بہٕ چُھس پریشان گومُت؛ بہٕ چُھس سٮ۪ٹھاہ نمُت بہٕ چُھس سٲرۍسٕے دۅہس ماتم کران۔ {پریشان: ہیب۔ رٔلِتھ}\n7. تکیازِ میانہِ کمر چھیہ اکھ نفرت آمیز {بیمار} سٍتۍ بٔرِتھ تہٕ {میٲنس مازس منز} چھہ نہ کانہہ صحیح۔ \n8.\\tبہٕ چُھس کمزور تہٕ دَگ پھُٹمُت: بہٕ چُھس دِل چہ بے قراری ہٕندِ وجہ سٍتۍ گُرٕ دِژمُت۔ \n9. خداوند، میٲنۍ سورے خٲہش چُھہ ژے برونہہ کُن۔ تہٕ میٲنۍ آہ چُھس نہٕ ژے نِش پوشیدٕ۔ \n10.\\tمیون دِل چُھس، میون طاقت چھُ ناکام گژھان: یوٚت تام میانین اچھن ہُند گاش، سُہ تہِ چُھ میہ نِش ختم۔ {گٔیہِ...: ہیب۔ چُھنہٕ میہ سٍتۍ}\n11.\\tمیانۍ عاشق تہٕ یار چھہِ میانہِ دگ نِش دور۔ تہٕ میانہِ رشتہٕ دار چھِ دور کھڑا روزان۔ {سور: ہیب۔ سٹروک } {میانہِ رشتہٕ دار: یا، میانین ہمساین}\n12.\\tیِم تہِ چھِ میانہِ زندگی ژھاران تہٕ یِم میانہِ دُکھ ژھاران چھِ، تِم چھِ سٲرۍسٕے دۅہس دھوکہ دِنُک تصور کران۔ \n13.\\tمگر میہ بوز نہٕ بہرِ {انسان}۔ تہٕ {بہٕ} اوسُس أکِس کُنہِ \n14.\\tیتھہ پاٹھۍ اوسس میہ اکھ تِتھِس انسانس ہٕندۍ پٲٹھۍ، یُس نہٕ بوزان چُھ، تہٕ یٔمۍ سٕندِس ٲسس منز چھُنہٕ کانہہ ملامت تہِ۔ \n15.\\tتێلہِ چُھس توے سٍتـ̡ وۅمید کٔرِتھ، اے خداوند، تێہہ بوزُن، اے خداوند میانہِ خدا۔ {منز...: یا، بہٕ چُھس انتظار} {بوزو: یا، جواب}\n16.\\tکیازِ میہ ووٚنمُت، {بوزو}، نتہٕ گژھن تِم میانہِ خٲطرٕ شاد گژھن: ییلہ میون کھۅر رٔسِتھ چھِ، تِم چھِ میانہِ خۅش سپدان۔ \n17.\\tکیازِ بہٕ چُھس رُکاونہٕ خٲطرٕ تیار، تہٕ میون غم {چُھ} مُسلسل میانہِ برونہہ کُن۔ {رُکاونہٕ خٲطرٕ: ہیب۔ رُکاونہٕ خٲطرٕ}\n18. تکیازِ بہٕ کرٕ پنُن گناہ ہُند اعلان۔ بہٕ کرٕ پننِس گۅنہٕ خٲطرٕ افسوس۔ \n19.\\tمگر میٲنۍ دُشمن {چِھ} زندٕ، {تہٕ} تِم چھِ مضبوٗط: تہٕ یِم مےٚ غلط نفرت کران چھِ تِم چھِ ضرب گٔمٕتۍ۔ {زندٕ چھِ...: ہیب۔ زندٕ آسنہٕ کِنۍ، چھِ مضبوٗط}\n20.\\tتم تہِ یم نیکی خٲطرٕ بد کار کران چھہِ تم چھہِ میٲنۍ مخالف۔ تکیازِ بہٕ چھُس اتھ چیزس پیٹھ عمل کران یُس نیکی {چُھ}۔ \n21.\\tاے خدایہ، میہ گژھ نہ میہ نش دور گژھ۔ \n22. اے خداوند، میانہِ نجات دِنہٕ خٲطرٕ کٔرِو جلدی ۔ {to...: ہیب۔ میانہِ مدتہٕ خٲطرٕ}","1. [بٔڈ موسیقارس سٍتۍ، {حتیٰ کہِ} یہدوتون، داؤد سُند زبور۔] میہ ووٚن، بہٕ کرٕ پننین طریقن پیٹھ دھیان زِ بہٕ کرٕ نہٕ پننہِ زبانہِ سٍتـ̡ گناہ کرنہٕ: بہٕ تھاوٕ پنُن ٲسس لگام سٍتۍ، ییلہ زن بدکار میانہِ برونہہ کنہِ آسہِ۔ {میون ٲس...: ہیب۔ اکھ لگام، یا، میٲنس ٲسس خٲطرٕ}\n2.\\tمیہ اوس خاموشی سٍتۍ گونگ، میہ تھوو پنُن سکون، {حتیٰ کہ} نیکی نشہِ۔ تہٕ میون غم گۆو ہلچل مژ۔ {ہلچل: ہیب۔ پریشان}\n3.\\tمیون دِل اوس پانس اندر گرم، ییلہ بہٕ نار دزان اوسس: {پتہٕ} وون میہ پننہ زبانہِ سٍتۍ، \n4.\\tخداوند، میہ کرو میون انجام تہ میانین دۅہن ہند پیمائش، یہ کیا چھہِ؛ تہ میہ گژھہِ پتاہ زِ بہٕ کوتاہ کمزور چھُس}۔ {کتھہ پاٹھۍ...: یا، میہ کیا ٹایِم چھُ}\n5.\\tوچھ ژے بنیوو میانہِ دۅہ {یتھہ پاٹھۍ} اتھہٕ سٍتـ̡ تہٕ میٲنۍ وٲنسہِ {چُھ} ژے برونہہ کنہِ کُنہِ تہِ نہٕ: پٔزۍ پٲٹھۍ چھُ پرٮ۪تھ کانہہ انسان پننہِ بہترین حالتس منز {چُھ} سراسر بےکار۔ سیلہ۔ {at...: Heb. سیٹل}\n6.\\tیقینا چھہ پریتھ انسان بیکار پکان تہ یُس بیکار چھہ پکان تہ یہ چھہ نہ خبرے زِ تم کُس کرِ جمع کرِ۔ {اکھ فضول...: ہیب۔ اکھ تصویر}\n7. تہٕ وُن، خداوند، بہٕ کیا چُھس انتظار؟ میٲنۍ وۅمید چُھہ ژے منز۔ \n8.\\tمیانہِ سارِنٕے گناہ نِش بچاو: مے بناو نہٕ بیوقوفن ہُند ملامت ۔ \n9. بہٕ اوسُس گونگ، میہ اوس نہٕ پنُن بوش کھولمُت۔ کیازِ ژے کٔر {یہ}۔ \n10.\\tپنُن سٹروک کٔرِو میہ نِش: بہٕ چُھس چانہِ اَتھٕ ہٕندِس دَباہٕ سٍتـ̡ ژٔٹِتھ ژٔلِتھ۔ {blow: Heb. تصادم}\n11.\\tییلہ ژیہ ملامت کٔرِتھ انسانس بدکاری ہٕندِس سٍتـ̡ صحیح کٔرِتھ، تێلہِ چھِو تٔمۍ سٕنز خوبصورتی کیم ہٕندۍ پٲٹھـ̡ ضایع کٔرِتھ، یقینا چھُ پرٮ۪تھ کانہہ انسان باطل۔ سیلہ۔ {تسُند...: حب۔ یُس أمِس مَنٛز یژھہٕ آسُن چھُ}\n12.\\tاے خداوند، میٲنۍ دُعا بوز تہٕ میانہِ فریاد بوزُن۔ میانین اشون سٍتـ̡ مہٕ تھپھ کٔرِتھ، کیازِ بہٕ چُھس ژے سٍتـ̡ اَکھ اجنبی تہٕ یِتھٕ پٲٹھۍ میانین سارِنٕے آبن ہٕندِ پٲٹھۍ۔ \n13.\\tاے میہ بچاو، یُتھ بہٕ نیرنہٕ برونہہ تہٕ بہٕ گژھہٕ نہٕ مزید طاقت حٲصل کٔرِتھ۔","1.\\t[اہم موسیقارس سٍتۍ، داؤد سُند زبور۔] میہ کٔر صبرٕ سٍتـ̡ خداوند سُند انتظار۔ تہٕ سُہ کٔر میہ کُن رۄخ، تہٕ بوزُن میٲنۍ فریاد۔ {میہ اوس انتظار...: ہیب۔ انتظارس منز کٔر میہ انتظار}\n2.\\tتٔمۍ کٔر میہ تہِ أکِس خوفناک کھۅلہٕ منز، میژِ منزٕ نیبر، تہٕ تھووُن میٲنۍ کھۅر أکِس کنہِ پتھرس پیٹھ، {تہٕ} کٔرٕن میون وُچھُن قٲیم۔ {an...: Heb. شورُک اکھ کھنڈ}\n3. تہٕ تٔمۍ تھوو میٲنِس ٲسس مَنٛز اکھ نۆو بٲت، {حتیٰ کہ} سٲنِس خدایہ سٕنز تعریف: واریاہ گژھن وُچھن، تہٕ کھوژان تہٕ خداہس پیٹھ بھروسہ کرُن۔ \n4. بابرکت چُھہ سُہ انسان یُس خداوند سُند امانت بناوان چُھ، تہٕ مغرورن ہُند احترام کرُن چُھہ نہٕ تہٕ یُس اپُز کُن پھیران چُھ۔ \n5.\\tواریاہ چھہِ، اے خدایہ میانہِ خدایہ، تۅہہِ ہٕندِ حیرت انگیز کامہِ {یُس} ژے کٔرۍمٕتۍ، تہٕ تُہند خیال {یُس} اسہِ خٲطرٕ چھُ: تِم ہیکو نہٕ تۅہہِ ہٕندِ خٲطرٕ گنزراونہٕ یِتھ: {اگر} بہٕ اعلان کٔرِتھ تہٕ کتھ کٔرِتھ، تِم چھِ گنزراونہٕ کھوتہٕ زیادٕ۔ {تِم ہیکن نہٕ کٔرِتھ...: یا، کانہہ تہِ ہیکہِ نہٕ تِمن ہُند حُکُم کٔرِتھ}\n6.\\tقربانی تہٕ نذرانہ یُس نہٕ ژے یژھان اوس۔ میٲنۍ کَن کٔرِتھ ژے کٔرۍمٕتۍ: دزنہٕ آمٕژ نذرانہ تہٕ گۅنہٕ نذرانہ چُھہ نہٕ ژے ضروری۔ {کھولنہٕ: ہیب۔ کھٔننہٕ}\n7.\\tاَمہ پتہٕ ووٚن مے، لو، بہٕ آو یُس کتابہ ہٕندِس جلدس مَنٛز {یہ} میانہِ متعلق لیکھنہٕ آمُت چھُ، \n8. بہٕ چُھس چانہِ مرضی پورٕ کٔرِتھ خۅش گژھان، اے خدایہ: آ، تُہند شریعت {چُھ} میٲنِس دِلس منز۔ {اندر...: ہیب۔ میانِس أندرس منز}\n9.\\tمیہ کٔر عظیم جماعتس منز نیکی ہنز تبلیغ: اے خداوند، ژے چھکھ نہ پنہٕ نِس وٹھ رُکاونہٕ آمُت۔ \n10. میہ چُھہ نہٕ چانۍ نیکی پننِس دِلس مَنٛز ژوٗرِ تھوومٕژ۔ مے چُھس تُہٕنز وفاداری تہٕ تُہٕنزِ نجات ہُند اعلان کورمُت: مے چُھنہٕ تُہٕنز محبتہٕ تہٕ تُہٕنزِ حقیقتُک عٔظیٖم جمٲژ نِش ژوٗرِ تھوومُت۔ \n11. اے خداوند، پَنٕنۍ نرم رحمتہٕ مہ کٔرِو نہٕ میانہِ نِش رُکاونہٕ۔ \n12. تکیازِ بے شمار بُرِیو چھِ میہ اندۍ پکھۍ گٔمٕتۍ: میٲنۍ بدکاریو چھِ میہ رٔٹمٕژ، یُتھ بہٕ ہیوٚک نہٕ ہیوٚر کٔرِتھ۔ تِم چھِ میانہِ کلہٕ کِس مَس کھۅتہٕ زیادٕ: اَمہِ مۄکھٕ چُھس میون دِل ناکام گٔژھان۔ {گرُن: ہیب۔ فورسکیتھ}\n13.\\tاے خداوند، میہ نجات دِنہٕ خٲطرٕ گژھ خۅش گژھُن: اے خداوند، میانہِ مدتھ کرنہٕ خٲطرٕ کرٕ جلدی۔ \n14. تِم گژھن شرمندہ تہٕ پریشان گژھن یِم میانہِ روحس تباہ کرنہٕ خٲطرٕ ژھاران چھِ۔ تِم گژھن پتھ کُن کڈنہٕ یِن تہٕ یِم مےٚ بد خواہش۔ \n15.\\tتِم گژھن پننہِ شرمندگی ہٕندِس انعامس خٲطرٕ ویران گژھن یُس میہ ونان چھِ، آہا، آہا۔ \n16.\\tیُس تۅہہِ ژھاران چُھہ، تُہٕندِس نجات سٍتـ̡ گژھن خوشی تہٕ خۅش گژھُن: یێلہِ تُہٕنزِ نجات سٍتـ̡ محبت کرٕنـ̡ تہٕ یێلہِ گژھہِ خداوند سٍتـ̡ بٔرِتھ روزُن۔ \n17. مگر بہٕ چُھس غریب، تہٕ محتاج۔ {توتہِ}خداوند چُھس میانہِ مُتلق سوچان: تہٕ چُھکھ میٲنۍ مدد تہٕ نجات دِنہٕ وول۔ اے خدایہ، کُنہِ تہِ رُکُن نہٕ۔","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور۔] سُہ چُھہ بابرکت {چُھ} یُس غریبن پیٹھ غور کران چُھ: خداوند کرِ تس مصیبت وِزِ نجات دِنہٕ۔ {غریب: یا، کمزور، یا بیمار} {وقتس منز...: ہیب۔ بد سٕندِس دۅہس منز}\n2. خداوند کرِ أمِس رٲچھ تہٕ زندٕ تھاوُن۔ {تہٕ} سُہ گژھہِ زمینس پیٹھ برکت حٲصل کرنہٕ: تہٕ توے کٔرِو نہٕ تس دُشمن ہٕندِس مرضس تام واتناوُن۔ {توہ...: یا تہٕ کرٕ نہٕ نجات دِنہٕ}\n3. خداوند کرِ تس بسترس پیٹھ مضبوط: توے کرِ تٔمۍ سٕنزِ بیمارِ سٍتـ̡ تٔمۍ سُند سارِوٕے بستر۔ {بناوُن: ہیب۔ پھیرُن}\n4. میہ ووٚن، اے خداوند، میانہِ سٍتـ̡ رحم کرُن: میانہِ روحُک شفا دِیُن۔ تکیازِ مے چُھہ ژے سٍتـ̡ گۅناہ کورمُت۔ \n5.\\tمیانہِ دُشمن چھِ میانہِ مُتلق بد کتھ کران، سُہ کر مرِ تہٕ تٔمۍ سُند ناو گژھہِ ختم۔ \n6. تہٕ اگر سُہ {مے} وچھنہٕ یِوان چُھ، سُہ چُھ باطل کتھ کران: تٔمۍ سُند دِل چُھ پانس سٍتـ̡ بدکاری جمع کران۔ {ییلہ} سُہ نیبر نیران چُھ، سُہ چُھ ونان {یہ}۔ \n7.\\tسٲری یُس میہ نفرت کران چھہِ تم چھہِ میہ خلاف سرگوشی کران: میانہِ خلاف چھہِ تم میانہِ دکھ دوان۔ {میانۍ...: ہیب۔ میانہِ خاطرہ بد کار}\n8.\\tاکھ بد بیمار، {تِم} چُھہ أمِس سٍتـ̡ ژٔٹِتھ تہٕ {وُن} یێلہِ سُہ چُھہ نہٕ وُتھٕ وُتھان۔ {an...: Heb. اکھ چیز بِلیال}\n9.\\tآ، میون پنن مانوس یار، یس پیٹھ میہ بھروسہٕ اوس، یمۍ میانہِ روٹی کھیوٚو، تُل میہ سیتۍ کھیوٚن۔ {میانۍ...: ہیب۔ میانہِ امن ہند انسان} {تُلتھ...: ہیب۔ بٔڈِتھ}\n10. مگر اے خداوند، ژٕ کٔر میانہِ سٍتـ̡ رحم کٔرِتھ، تہٕ تھوٚد کٔرِتھ یُتھ بہٕ تِمن ہُند بدلہٕ دِیُن۔ \n11.\\tاَمہِ سٍتـ̡ چُھس بہٕ زانان زِ ژے چُھہ میہ احسان کران، تکیازِ میون دُشمن چُھنہٕ میہ پیٹھ فتح حٲصل کٔرِتھ۔ \n12.\\tتہٕ یێلہِ تہٕ تێہہ کٔر میانہِ دیانت سٍتـ̡ تہٕ کٔرٕکھ میہ ہمیشہٕ خٲطرٕ پننہِ بُتھِس برونہہ کُن۔ \n13. اَمہِ سٍتـ̡ چُھہ اَبـ̡ سٍتـ̡ اَبـ̡ سٍتـ̡ خدایہِ سٍتـ̡ بابرکت سپدُن۔ آمین تہٕ آمین۔","1.\\t[اہم موسیقار، مشکیل، کورہ سٕندِس فرزندن ہٕندِ خٲطرٕ۔] یِتھٕ پٲٹھـ̡ چُھہ آبہٕ کِس نالہٕ پَتہٕ پٲٹھـ̡ میانہِ روح ژے پَتہٕ پٲٹھـ̡ خدایہ۔ {مشکیل...: یا، اکھ زبور یُس فرزندن ہٕنز تعلیم دِوان چُھ، وغیرہ} {panteth: Heb. Brayeth}\n2. میون روح چُھ خدایہِ سٕندِ خٲطرٕ، زندٕ خدایہِ سٕندِ خٲطرٕ ترش: بہٕ کر یِنہٕ تہٕ خدایہ سٕندِ برونہہ کُن ظٲہر سپدُن؟ \n3.\\tمیانہِ اوٚش چھہ دۅہس تہ راتس میون ماز بنیومُت، ییلہ زن تم میہ مسلسل ونان چھہِ، تہند خدا کتہِ چھُ؟ \n4. ییلہ بہٕ یِم {چیز} یاد پیوان چھُس، بہٕ چُھس پانس مَنٛز پنُن روح تراوان: کیازِ بہٕ اوسُس تِمن سٍتـ̡ خدایہ سٕندِس گرس کُن، خوشی تہٕ تعریفٕچ آوازٕ سٍتـ̡ گۆو بہٕ تِمن سٍتـ̡ خدایہ سٕندِس گرس تام، یُس مقدس دۅہ تھاوان اوس۔ \n5.\\tاے میانہِ روح، ژے کیازِ چھکھ دِنہٕ آمُت؟ تہٕ {کیازِ} چھکھ ژے میہ منز پریشان؟ توے چھکھ خدایس سٍتۍ وۅمید تھاوان: کیازِ بہٕ کٔرٕ توتہِ تسٕندِ بُتھِ ہٕندِ مدتہٕ سٍتـ̡ تسٕندِس حمد سٍتـ̡۔ {cast: Heb. نمُت} {تعریف: یا، شُکرہ ادا کرُن} {امہِ خٲطرٕ...: یا، تٔمۍ سٕنز موجودگی چھِ نجات}\n6.\\tاے خدایہ، میون روح چھہ پانس اندر تراونہ آمت: امہ مۅکھہ چھہ میہ ژے اردن کِس سرزمینس پیٹھ، تہ ہرمونیٹس پیٹھ، بالہ مزار پیٹھ۔ {بال...: یا، لۅکٹۍ بال}\n7.\\tچانہِ آبہٕ ہٕندِس شورس سٍتـ̡ گۆو سرٛوٚن: چانہِ سٲرۍسٕے لہرٕ تہٕ تُہٕنزِ لہرٕ گٔیہِ میہ پیٹھ۔ \n8. {توتہِ}خداوند کرِ دۅہلہِ پننہِ محبتُک حُکُم، تہٕ رٲژ گژھہِ تٔمۍ سُند گٮ۪وُن میانہِ سٍتـ̡ تہٕ میانہِ زندگی ہٕندِس خدایس سٍتـ̡ میانہِ دُعا دُعا۔ \n9.\\tبہٕ وَنُن خدایس پنٕنۍ کٔنہِ، ژے کیازِ چھُکھ مٔشِد گومُت؟ دُشمن سٕندِ ظلمہٕ سٍتـ̡ کیازِ چُھس بہٕ ماتم کٔرِتھ؟ \n10. {یِتھ} میانین اڈجن منز تلوار تھٲوِتھ، میانین دُشمن چھِ میہ ملامت کران۔ ییلہ زن تِم دۅہٕ میہ ونان چھِ، تُہند خدا کتہِ چُھ؟ {تلوار: یا، مارُن}\n11.\\tاے میانہِ روح، ژے کیازِ چھکھ ژے دِنہٕ آمُت؟ تہٕ ژٕ کیازِ چُھکھ میٲنس اندر پریشان؟ تہٕ ژٕ چُھکھ خدایس سٍتـ̡ وۅمید کٔرِتھ، تکیازِ بہٕ کٔرٕ وُنہِ تہِ تٔمِس سٕنز حمد کٔرِتھ، یُس میانہِ بُتھِ ہُند صحت چُھ، تہٕ میانہِ خدایہ سٕندِس سٍتـ̡ ۔","1.\\tاے خدایہ کٔر میہ فیصلہ تہ کٔر أکِس بدکار قومس خلاف میانہِ مقدمہ کٔرِتھ: اے کٔر میہ دھوکہ دہی تہٕ بدکار انسانس نِش بچاو۔ {بدکار: یا، بے رحم} {دھوکہ باز...: ہیب۔ دھوکہ دہی تہٕ بدکاری ہُند آدم}\n2. تِکیازِ چُھکھ ژٕ میانہِ طاقتُک خدا: ژے کیازِ چھُکھ مےٚ ترٛاوان؟ بہٕ کیازِ چھُس دُشمن سٕندِ ظلمہٕ سٍتۍ ماتم کٔرِتھ؟ \n3. اے پَنُن گاش تہٕ پَنُن پٲٹھۍ۔ تِم أنِن مےٚ پَنٕنِس مُقدس بالس تہٕ تُہٕندِس خیمَس مَنٛز۔ \n4.\\tتیلہ گژھ بہٕ خدایہ سٕندِس قربان گاہس پیٹھ، خدایہ سٕندِس سٍتـ̡ پنٕنۍ سٮ۪ٹھاہ خوشی: آ، ہارپَس پیٹھ کٔرٕ بہٕ ژے تعریف، اے خدایہ میانہِ خدایہ۔ {میٲنۍ زیادٕ...: ہیب۔ میانہِ خوشی ہٕنز خوشی}\n5.\\tاے میانہِ روح، ژے کیازِ چھُکھ ژے دِنہٕ آمُت؟ تہٕ ژٕ کیازِ چھُکھ میٲنِس اندر پریشان؟ خدایس سٍتـ̡ وۅمید کٔرِتھ، تکیازِ بہٕ کٔرٕ وُنہِ تہِ تسٕندِس حمد سٍتـ̡ یُس میانہِ بُتھِ ہُند صحت چُھ، تہٕ میانہِ خدایہِ سٍتـ̡ ۔","1.\\t[کورہ سٕندِس نیچوین ہٕندِس اہم موسیقارس تام، مشکیل۔] اسہِ چُھ پننیو کنو سٍتـ̡ بوزمُت، اے خدایہ، سانیو آباؤ اجدادو چُھ اسہِ وَننہٕ آمُت، {ژے کیا کٲم کٔرِتھ، پرانہِ زمانس منز۔ {Maschil: or, of Instruction}\n2. کِتھہ کٔنۍ کٔرِکھ ژے پننہِ اتھہٕ سٍتـ̡ کافر ژٔٹِتھ تہٕ کٔرِکھ تِم کٔڈِتھ ۔ {کِتھہٕ کٔن} کٔرِکھ لُکن مُتٲثِر تہٕ کٔرِکھ تِم کٔڈِتھ کٔرِتھ۔ \n3. تِکیازِ تِمو ہیوٚک نہٕ پننہِ تلوار سٍتـ̡ زمینہٕ حٲصل کٔرِتھ، تہٕ تِمن ہٕندِ نٔرِ ہٕندِس نٔرِس سٍتـ̡ تہٕ تُہٕندِس بُتھِس سٍتـ̡ ہُند گاش، تکیازِ ژے اوس تِمن سٍتـ̡ احسان کٔرِتھ۔ \n4. اے خدایہ، تہٕ چُھکھ میٲنۍ بادشاہ، یعقوب سٕندِ خٲطرٕ نجات دِنُک حُکُم۔ \n5. چانہِ سٍتـ̡ کٔرِو أسـ̡ پَنٕنـ̡ دُشمن ہٕندِس دُشمن ہٕندِس سٍتـ̡ پٲٹھـ̡ پى۪ٹھ۔ \n6. کیازِ بہٕ کرٕ نہٕ پننِس کمانس پیٹھ بھروسہٕ تہٕ نہ کرٕ میون تلوار بچاو۔ \n7. مگر ژے بچٲوۍ اسہِ سانین دُشمنن نِش تہٕ تِم کٔرِکھ شرمندہ یِم اسہِ سٍتـ̡ نفرت کران ٲسۍ۔ \n8.\\tأسۍ چھِ خدایس سٍتـ̡ سارِوٕے دۅہہٕ فخر کران تہٕ چُھہ تُہند ناو ہمیشہٕ خٲطرٕ تعریف۔ سیلہ۔ \n9. مگر ژے چھُکھ ژٔٹِتھ تہٕ اسہِ شرمسار کٔرِتھ۔ تہٕ گژھ نہٕ سانہِ فوجہٕ سٍتـ̡ نیران۔ \n10.\\tژے چُھہ اسہِ دُشمن نِش پتھ کُن تراوان: تہٕ یِم اسہِ سٍتـ̡ نفرت کران چھِ، تِم چھِ پانس سٍتـ̡ برباد کران۔ \n11.\\tژے دِژ اسہِ کۅکرِ ہٕندۍ پٲٹھۍ، ماز خٲطرٕ۔ تہٕ کٔرِکھ اسہِ کافرن مَنٛز پھٔٹِتھ۔ {یِتھٕ پٲٹھۍ...: ہیب۔ مازٕکۍ کۅکر}\n12.\\tتوے کٕنُن پَنٕنـ̡ پَنٕنـ̡ لُکھ کٕنـ̡ تہٕ چُھہ نہٕ تِمن ہٕندِس قٲمتس سٍتـ̡ ہُرراوُن۔ {for...: Heb. دولتٕ ورٲے }\n13.\\tژے چھکھ سانین ہمساین ملامت کران، تمن ہنز حقارت تہٕ طنز کران یُس اسہِ اندۍ پکھۍ چھِ۔ \n14. توے بناو اسہِ کافرن مَنٛز اکھ ضمنی لفظ، لوکن مَنٛز کلہٕ ہلاونہٕ۔ \n15.\\tمیانہِ پریشانی چھیہ میہ برونہہ کنہِ مسلسل تہ میانہِ بُتھِ ہنز شرم چھیہ میہ ؤلتھ، \n16.\\tتٔمِس سٕنزِ آوازِ خٲطرٕ یُس ملامت تہٕ کفر کران چُھ؛ دُشمن تہٕ انتقام کَرن وٲلِس سٍتـ̡ ۔ \n17. یِہ سورُے چُھ اسہِ سٍتـ̡ آمُت۔ توتہِ چُھہ نہٕ أسـ̡ تُہٕندِس عہدس مَنٛز اپُز سٍتـ̡ کٲم کٔرمٕژ۔ \n18.\\tسانہِ دِل چھہ نہ پتھ کُن پھیران، نہ چھہ سانۍ قدم تہِ وتہِ نشہِ پتھ کُن آمت۔ {قدم: یا، گژان}\n19. یۆدوَے ژے دَگ کٔرِتھ اسہِ ڈریگن ہٕنزِ جایہ پھُٹرٲومٕژ تہٕ اسہِ چھُکھ موتُک ژھایہ دِژمُت۔ \n20. اگر أسـ̡ پننِس خدایہِ سُند ناو مٔشِد گومُت، یا کُنہِ اجنبی خدایس کُن اتھہٕ پھٔہلٲوِتھ چُھہ؛ \n21.\\tخدایہ کرِ نہ یہ ژھانڈان؟ تکیازِ سُہ چُھ دِلُک راز زانان۔ \n22. آ، چانہِ خٲطرٕ چھِ أسۍ سٲرۍسٕے دۅہہٕ مارنہٕ یِوان۔ أسۍ چھِ ذبح کرنہٕ خٲطرٕ کۅکرِ ہٕندۍ پٲٹھۍ۔ \n23.\\tبیدار، اے خداوند، کیازِ چُھکھ شوٚنگتھ؟ وۅتھٕ وُتھ، تراوُن نہٕ ہمیشہٕ خٲطرٕ۔ \n24.\\tژے کیازِ چھکھ پنُن بُتھ ژوٗرِ تھاوان، {تہٕ} سانہِ مصیبت تہٕ سون ظلم مٔشِد کٔرِتھ؟ \n25.\\tتکیازِ سانہِ روح چھہ گردِ سٍتـ̡ نمُن: سانہِ یٔڈ چُھہ زمینہِ سٍتـ̡ ژٔٹِتھ ژٔٹان۔ \n26.\\tسانہِ مددٕ خٲطرٕ وۅتھٕ وُتھ، تہٕ پننہِ رحمتہٕ خٲطرٕ کٔرِو اسہِ نجات دِنہٕ۔ {سانہِ خٲطرٕ...: ہیب۔ اسہِ خٲطرٕ اکھ مدد}","1.\\tشوشنیم پیٹھ، کورہ کین نیچوین ہندِ خاطرہ، مشکیل، عشقن ہند نغمہ۔] میون دل چھہ اکھ اصل کتھ کران: میہ چھہ تمن چیزن ہنز کتھ کران یم میہ بادشاہس سیتۍ واٹھ دِژمژ چھہِ: میون زبان چھہ اکھ تیار ادیب سند قلم۔ {مشکیل: یا، ہدایت} {چھہ اندۍ پکھۍ: ہیب۔ بُلتھ، یا، بلبل}\n2. تُہۍ چُھکھ اِنسانن ہٕندِس بچن ہٕندِ کھۅتہٕ زیادٕ خوبصورت: فضل چُھہ چُھس چُھہ چُھہ تُہٕندِس وَٹھس مَنٛز دِنہٕ آمُت، تێمہِ مۄکھٕ چُھہ خداین ژے ہمیشہٕ خٲطرٕ برکت۔ \n3. پَنٕنہِ تلوار لٲگِو پَنٕنہِ زَرِ پیٹھ، اے {سارِوٕے کھۄتہٕ زیادٕ} عظمت، پننہِ شان تہٕ عظمتَس سٍتۍ۔ \n4. تہٕ پننہِ عظمتس مَنٛز کٔرِو سچائی تہٕ نرمی سٍتـ̡\n5. تُہٕندِس تیر چھِ بادشاہ سٕندِس دُشمن ہٕندِس دِلس مَنٛز تیز۔ {یَتھ سٍت} لوٗکھ چھِ تۅہہِ تل پیوان۔ \n6. تُہند تخت، اے خدایہ، {چُھ} ہمیشہٕ خٲطرٕ: تُہٕندِ بادشٲہی ہُند عصا {چُھ} اکھ صحیح عصا۔ \n7. توے چُھہ نیکی تہٕ بدکاری سٍتـ̡ محبت کران: تێمہِ مۅکھہٕ چُھہ خدایہ، تُہند خدا، چُھہ ژے پننین سٲتھین ہٕندِس سٍتـ̡ خوشی ہٕندِس تیٖلہٕ سٍتـ̡ مسح کورمُت۔ \n8.\\tچانہِ سارِنٕے پلو {خوشبو} تہٕ ایلو، {تہٕ} کیسیا، ہاتھی دندن ہٕندِس محلو منز، ییمہ سٍتۍ تِمو ژے خۅش کٔرۍ۔ \n9. بادشاہن ہٕنزِ کورِ آسہٕ تۅہہِ ہٕنزِ معزز زنانن منز: تۅہہِ دچھنہِ اتھس پیٹھ ٲس اوفیر سٕندِس سونہٕ سٍتـ̡ ملکہ کھڑا۔ \n10. اے کورِ بوز تہٕ غور کرُن، تہٕ کٔرِو پنٕنۍ کَن کُن۔ پنٕنۍ لوکھ تہٕ پنٕنۍ مٲلۍ سُند گرٕ تہِ مٔشِد کرُن۔ \n11. یِتھے پٲٹھۍ کرِ بادشاہ تُہٕندِ خوٗبصوٗرتی ہُند سٮ۪ٹھاہ خواہش، کیازِ سُہ چُھ تُہُند مالک۔ تہٕ تٔمۍ سٕنز عبادت کٔرِو۔ \n12.\\tتہٕ صور سٕنز کورِ آسہِ اَکھ تحفہٕ ہیتھ ۔ {حتیٰ کہ} لُکن مَنٛز امیر تہِ کرِ تۅہہِ ہٕندِس احسانس سٍتـ̡ ۔ {احسان: حب۔ بُتھ}\n13.\\tبادشاہ سٕنز کورِ چھے سارِنٕے شاندار: تٔمۍ سُند پلو چھُ سونہٕ سُند پوش۔ \n14. سُہ یِن سٕژِ ہٕندِس پلوس منز بادشاہس نِش اننہٕ: یِم کُنوارِ أمِس پَتہٕ یِن تٔمۍ سٕندِس سٲتھی یِن توے نِش اننہٕ۔ \n15. خوشی تہٕ خوشی سان یِن تِم اننہٕ: تِم گژھن بادشاہ سٕندِس محلس مَنٛز اژنہٕ۔ \n16.\\tپننین مٲلن بدلہٕ گژھن تہند شُرۍ، یِم ژے سارِنٕے زمینس مَنٛز شہزادٕ بنٲوِو۔ \n17. بہٕ بناوٕ تُہند ناو سارِنٕے نسلن مَنٛز یاد تھاونہٕ خٲطرٕ، تَمہِ مۄکھٕ کَرٕ لوٗکھ ہمیشہٕ خٲطرٕ تۅہہِ ہٕنز تعریف۔","1. [کورہ سٕندِس نیچوِس خٲطرٕ بٔڈ موسیقارس تام، الموتھس پیٹھ اکھ نغمہٕ۔] خدا چُھ سون پناہ گاہ تہٕ طاقت، مصیبتس منز اکھ واریاہ موجودٕ مدد۔ {for: or, of}\n2. لہذا گژھہِ نہ اسہِ خوف، یودوے زمین ہٹاونہ ییہ، تہ پہاڑ گژھن سمندرس منز نِنہ۔ {درمیان...: ہیب۔ سمندرن ہند دل}\n3.\\t{اگرچہ} اَمہ کِس آبس چھُ گٔژھان {تہٕ} پریشان گومُت، {اگرچہ} پہاڑ چھِ اَمہ سٍتۍ لرزان۔ سیلاہ۔ \n4. {اَکھ دٔریاو} چُھ، یێمہِ سٍتـ̡ نالہٕ خدایہِ سٕندِس شہرس خوش کرِ، یُس خدایہ سٕندِس خیمہ ہُند مقدس {جاے} چُھ۔ \n5.\\tخدا {چُھ} تس منز؛ سُہ گژھِ نہٕ ہُرراونہٕ یُن: خدا کرِ أمِس مدد، {تہٕ یہ} سُلہٕ سُلہٕ۔ {تہٕ...: ہیب۔ ییلہ صبحُک ظٲہر سپدِ}\n6.\\tکافر گٔیہِ غصہٕ، بادشٲہی گٔیہِ ہلکہٕ: تٔمۍ کٔر پنٕنۍ آواز، زمین گٔیہِ پٔگۍ۔ \n7. لشکرن ہُند رب {چُھ} اسہِ سٍتـ̡ یعقوب سُند خدا {چُھ} سون پناہ گاہ۔ سیلہ۔ {سانہِ...: حب۔ سانہِ خٲطرٕ اکھ تھوٚد مقام}\n8. آو، وُچھِو خداوند سٕنزِ کامہِ، تٔمۍ کٔر زمینس مَنٛز کیا ویران کٔرۍ۔ \n9. سُہ چُھ جنگ زمینہِ ہٕندِس اندس تام بند کَران۔ سُہ چُھ کمان پھُٹراوان، تہٕ نیزٕ ژٹان چُھ؛ سُہ چُھ رتھٕ نارس مَنٛز زالان۔ \n10. خاموش روزُن، تہٕ زان زِ بہٕ چُھس خدایہ: بہٕ گژھہٕ کافرن مَنٛز بلندی حٲصل کرنہٕ، بہٕ گژھہٕ زمینس مَنٛز بلند۔ \n11. لشکرن ہُند رب چُھہ اسہِ سٍتـ̡ یعقوب سُند خدا چُھہ سانہِ پناہ گاہ۔ سیلاہ۔","1. [بٔڈۍ موسیقارس کُن، کورہ سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ اکھ زبور۔] اے ژرِ پوٚپ پَنٕنۍ اتھہٕ، اے سارِنٕے لوکو۔ فتح ہٕنزِ آوازٕ سٍتـ̡ کٔرِو خدایس سٍتـ̡ کرٛٮ۪کہٕ۔ {for: or, of}\n2.\\tخداوند سٍتـ̡ چُھہ خوفناک۔ {سُہ چُھ} سارِنٕے زمینس پیٹھ اکھ بۆڈ بادشاہ۔ \n3. سُہ کرِ اسہِ تل لُکن تہٕ قومن سانہِ قدمن تل زیر کرنہٕ۔ \n4. سُہ کرِ سانہِ خٲطرٕ سانہِ وراثتُک انتخاب، یعقوب سٕنز عظمت، یُس أمِس محبت کران اوس۔ سیلاہ۔ \n5. خدایہ چُھ کرٛٮ۪کہٕ سٍتـ̡ وُچھمُت، خداوند چُھہ بُرٕچ آوازٕ سٍتـ̡ وُچھان۔ \n6. خدایہ سٕندِ حمد گٮ۪وُن، تعریفن گٮ۪وُن: سٲنِس بادشاہس سٍتـ̡ گیوُن، تعریف۔ \n7. خدایہ چُھہ سارِنٕے زمینُک بادشاہ چُھہ: سمجھہٕ سٍتـ̡ گیوان تعریف۔ {سٍتـ̡: یا، پریتھ کانہہ یُس آسہِ}\n8. خدا چُھ کافرن پیٹھ بادشاہی: خدا چُھ پننہِ پاکیزگی ہٕندِس تختس پیٹھ بِہتھ۔ \n9.\\tلُکن ہٕندِ شہزادٕ چھِ اَکہٕ وٹہٕ جمع کرنہٕ آمٕتۍ، حتیٰ کہ ابراہیم سٕندِ خدایہِ سٕندِ لُکھ تہِ چھِ: تِکیازِ زمینٕچ ڈھال چھِ خدایہ سٕندِس سٍتـ̡ سٍتـ̡ سُہ سُہ سٍتـ̡","1. [اکھ نغمہٕ {تہٕ} زبور کورہ سٕندِس فرزندن خٲطرٕ۔] عظیم {چُھ} خداوند سٕندِس شہرس مَنٛز، {منز} تٔمۍ سٕندِس پاکیزگی ہٕندِس پہاڑس مَنٛز۔ {for: or, of}\n2. صورت حال خٲطرٕ خوبصورت، پورٕ زمینچ خوشی، {is} پہاڑ صییون، {پیٹھ} شمالک طرف، عظیم بادشاہ سُند شہر۔ \n3.\\tخدا چھہ پننین محلن منز پناہ گاہ ماننہ یوان۔ \n4. کیازِ، بادشاہ ٲسۍ جمع گٔمٕتۍ، تِم گٔیہِ اَکہٕ وٹہٕ اَکہٕ وٹہٕ۔ \n5.\\tتِمو وُچھ {یہِ، تہٕ} تِمو گٔے حٲران۔ تِم گٔیہِ پریشان، {تہٕ} ژٔلِتھ ژٔلِتھ۔ \n6.\\tتتہِ لوٚگ تمن پیٹھ خوف، {تہِ} دگ ہیو زنانہِ ہٕندِس مصیبتس منز۔ \n7.\\tژے چھکھ ترشِش سٕندِس جہازس مشرِقی واو سٍتۍ پھُٹراوُن۔ \n8. یِتھ کٔنۍ أسـ̡ بوزمُت چُھ، یێلہِ چُھہ أسـ̡ خدایہِ سٕندِس شہرس مَنٛز وُچھمُت: خدا کرِ یہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ۔ سیلاہ۔ \n9. أسـ̡ چُھہ چانہِ ہٕندِس مندرس مَنٛز سونٛچمُت، اے خدایہ۔ \n10. اے خدایہ، تُہٕندِ ناوٕ مُطٲبق چُھہ تُہند حمد زمینہٕ کِس اندس تام: تُہند دٔچھُن اَتھٕ چُھ نیکی سٍتـ̡ بٔرِتھ۔ \n11.\\tصیون پہاڑ گژھہِ شاد گژھُن، یہوداہ سٕنزِ کورِ گژھن پننہِ فیصلہٕ سٍتـ̡ خۄش۔ \n12.\\tصییونس اندۍ پکھۍ پکان تہ تس اندۍ پکھۍ پھیُرُن: امکۍ برج وَنُن۔ \n13.\\tتٔمۍ سٕندِس قلعس پیٹھ نظر تھاوُن، تٔمۍ سٕندِس محلس پیٹھ غور کرُن۔ یُتھ زن تۅہہ ینہ واجنہِ نسلس وَنُن۔ {مارک...: ہیب۔ پَنُن دِل تھاوُن} {غور کٔرِتھ: یا، تھوٚد}\n14. یێمہِ سٍتـ̡ خدا چُھہ سُہ چُھہ ہمیشہٕ خٲطرٕ سون خدا: سُہ روزِ سانہِ موتس تام رہنما۔","1.\\t[اہم موسیقارس کُن، کورہ سٕندٮ۪ن نیچوین خٲطرٕ اکھ زبور۔] یہ بوزو، سارِنٕے {یے} لوکو۔ دُنیاہٕکۍ سارِنٕے {یے} بسکین: {for: or, of}\n2. کم تہٕ تھد، امیر تہٕ غریب، اِکہٕ وٹہٕ۔ \n3.\\tمیانہِ دِلُک مراقبہٕ گژھہِ عقلہٕ سٍتـ̡ کتھ کرنہٕ۔ تہٕ میانہِ دِلُک مراقبہٕ {گژھہِ} فہم سٍتـ̡ ۔ \n4.\\tبہٕ کٔرٕ پنُن کَن تمثیلس کُن رُکاونہٕ: بہٕ کھولہٕ پنُن سیاہ کلام ہارپس پیٹھ۔ \n5. میہ کیازِ گژھہِ بدکار دۅہن منز کھوژان، {ییلہِ} میانہِ کھورِ ہٕنز بدکاری میہ اندۍ پکھۍ گٔژھِ۔ \n6. تِم یِم پننِس دولتس پیٹھ بھروسہٕ کران چھِ، تہٕ پننِس دولتس پیٹھ فخر کران چھِ۔ \n7. یِمو منزٕ ہیکہِ نہٕ کُنہِ تہِ پٲٹھـ̡ پننِس بٲیِس فدٕ دِتھ، تہٕ نہ ہیکہِ خدایس أمِس فدیہ دِتھ۔ \n8. (تِہٕندِ روحٕچ نجات خٲطرٕ {چُھ} قۭمتی تہٕ یہِ چُھ ہمیشہٕ خٲطرٕ ختم سپدُن:)\n9.\\tزِ سُہ گژھہِ ہمیشہٕ زندٕ، {تہٕ} گژھہِ نہٕ بدعنوانی وُچھن۔ \n10.\\tکیازِ سُہ چُھ وُچھان زِ عقلمند چھِ مران تہٕ یِتھے پٲٹھۍ چھُ بیوقوف تہٕ وحشی شخص ماران تہٕ پنُن مال باقین پیٹھ تراوان۔ \n11.\\tتِہُند باطنی خیال چُھہ زِ تِہُند مکانہٕ {روزِ ہمیشہٕ خٲطرٕ}، {تہٕ} سارِنٕے نسلن تام روزن۔ تِم چھِ {پنٕنۍ} زمینن پننین ناوَن پیٹھ ونان۔ {سٲری ...: ہیب۔ نسل تہٕ نسل}\n12. بہر حال انسان چُھ نہٕ عزتس منز روزان: سُہ چُھ درندن ہٕندۍ پٲٹھۍ{یُس} ختم سپدان چُھ۔ \n13.\\tیِہُند وَتھ چھُ تِہٕنزِ حماقت: توتہِ چھُ تِہٕندِس اولادَس مَنٛز تِمن ہٕندِس کلامَس منظوٗر کَران۔ سیلہ۔ {منظوٗر...: ہیب۔ تِہٕندِس ٲسس مَنٛز خۅش}\n14.\\tیِم چھِ قبرِ منز دفن کرنہٕ آمٕتۍ۔ موت چُھ تِمن کھٮ۪وان؛ تہٕ صُبحَس چھُ یِمن پیٹھ غلبہٕ حٲصِل سپدان۔ تہٕ تِہُند خوٗبصوٗرتی آسہِ قبرِ مَنٛز کھٮ۪نہٕ یِوان۔ {خوبصورتی: یا، قوت} {قبرِ منز...: یا، قبر آسہِ تِمن منز پرٮ۪تھ أکِس سٍتـ̡ روزن}\n15.\\tمگر خدا کرِ میانہِ روح قبرِ ہندِ طاقتہٕ نِش نجات دِنہٕ، تکیازِ سُہ کرِ میہ قبول۔ سیلہ۔ {طاقت: ہیب۔ اتھہ} {قبر: یا، جہنم}\n16.\\tییلہ انسان امیر سپدِ، ییلہ تٔمۍ سٕندِس گرس ہُند جلال ہُرراوُن گژھہِ تہٕ تٔمۍ سٕندِس گرس ہُند جلال ہُرراوُن۔ \n17.\\tییلہ سُہ مرِ سُہ گژھہِ نہٕ کانہہ تہِ نِنہٕ: تٔمۍ سُند جلال گژھہِ نہٕ تس پتہٕ وسُن۔ \n18. یودوَے سُہ زندٕ روزِتھ کٔر تٔمۍ پَنٕنِس روحس برکت تہٕ {انسان} کٔرِو تۅہہِ ہٕنز تعریف، یێلہِ تہٕ ژے پانس سٍتـ̡ خیر کٔرِو۔ {یێلہِ...: ہیب۔ تٔمۍ سٕنزِ زندگی منز}\n19.\\tسُہ گژھہِ پننین مٲلن ہٕندِس نسلس مَنٛز۔ تِم گژھن نہٕ زانہہ گاش وُچھان۔ {سُہ...: ہیب۔ روح کرُن}\n20.\\tانسان {یعنی} عزتس منز، تہٕ سُہ چُھ نہٕ سمجھان، تِمن درندن ہٕندۍ پٲٹھۍ{یُس} مران چُھ۔","1. [زبور آساف۔] قادر مطلق خدایہ {حتیٰ کہ}خداوند چھہ کتھ کٔرمٕژ، تہٕ آفتابہٕ کھسنہٕ پیٹھٕ وُسنہٕ تام زمینس بلاوُن۔ {of...: یا، آساف سٕندِ خٲطرٕ}\n2. صہیون منز، خوبصورتی ہند کمال، خدایہ چُھ چمکُن۔ \n3. سون خدا گژھہِ یِنہٕ، تہٕ ژھۄپہٕ روزِ نہٕ: أمِس برونہہ کُن نار دِیہِ، تہٕ تس اندۍ پٔکھۍ آسہِ سٮ۪ٹھاہ طوفان۔ \n4. سُہ کرِ ہیرِ پیٹھٕ آسمانس تہٕ زمینس کُن بلاوُن، یُتھ سُہ پننین لوکن ہُند فیصلہ کرِ۔ \n5. میانین مقدسن کٔرِو میانہِ خٲطرٕ جمع کرنہٕ۔ یِمو قربانی دِتھ میانہِ سٍتـ̡ عہد کورمُت چُھ۔ \n6. تہٕ آسمانن کرِ پننہِ نیکی ہُند اعلان: کیازِ خدایہ چُھ پانس انصاف کران۔ سیلہ۔ \n7. اے میانہِ قومہٕ بوزو، تہٕ بہٕ کَرٕ کَتھ اے اسرٲیل، تہٕ بہٕ کَرٕ تُہٕندِس خلاف گوٲہی دِوان: بہٕ چُھس خدا، {حتیٰ کہ} چُھس تُہند خدا۔ \n8. بہٕ کَرٕ نہٕ ژےٚ پننہِ قربانی یا تہندِ دزنہٕ خٲطرٕ ملامت کرنہٕ، {یُس میہ برونہہ کُن روزُن}۔ \n9.\\tبہٕ کٔرٕ نہٕ تُہٕندِ گَرٕ منزٕ کانہہ تہِ داند نٮ۪بر، تہٕ نہ کٔرِہ سُہ تہندِ گَرِ منزٕ کُنہِ \n10.\\tجنگلُک پرٮ۪تھ کانہہ جانور چھُ میٲنۍ تہٕ ساس بالن پیٹھ چارواے۔ \n11.\\tبہٕ چھُس پہاڑن ہٕندِس سارِنٕے جاناوارس زانان: تہٕ میدانٕکۍ جنگلی جانور {چھِ} میانۍ۔ {ماین: ہیب۔ میہ سٍتۍ}\n12.\\tاگر میہ فاقہٕ آسہِ، بہٕ وَنُن نہٕ ژےٚ: تکیازِ یہ دنیا چھُ میون تہٕ اَمہ سٍتـ̡ پورٕ۔ \n13.\\tبہٕ کیا بہٕ بیلن ہُند ماز کھٮ۪وان، یا ژھاوُن ہُند خوُن؟ \n14. خدایہِ سُند شُکر ادا کٔرِو۔ تہٕ پَنُن عہد کٔرِو خدایہِ سٕندِس سٍتـ̡ ۔ \n15. تہٕ مُصیبت ہٕندِس دۅہہٕ کٔرِو مے بُلاون: بہٕ کٔرٕ ژے نجات تہٕ ژٕ کٔرٕ میانہِ حمد کٔرٕنۍ۔ \n16. مگر بدکار خدا چُھ ونان زِ ژے کیا چُھہ میانہِ قونونن ہُند اعلان کرنہٕ خٲطرٕ، یا ژے کیا کرُن میون عہد پننِس ٲسس منز؟ \n17.\\tژے وُچھِتھ تہٕ میانہِ کلامَس پَتہٕ کٔرِتھ۔ \n18.\\tییلہ ژے کانہہ چور وُچھو، تیلہِ کٔرِو تٔمِس سٍتـ̡ رضامندی تہٕ کٔرٕکھ زناکارن سٍتـ̡ شرکت۔ {hast...: Heb. تُہند حصہ اوس سٍتـ̡\n19.\\tژے چُھہ پَنُن بُرِس دِوان تہٕ تُہٕنز زبان چھِ دھوکہٕ دِوان۔ {دِیُن: ہیب۔ سوزُن}\n20. تہٕ تہٕ چُھکھ پننِس بٲیِس خلاف کتھ کران۔ تہٕ چُھکھ پنٕنِس ماجہِ ہٕندِس نیچوِس سٍتـ̡ بدنام کٔرِتھ۔ \n21.\\tیِم {چیز} کٔرِتھ تہٕ میہ کٔر ژھۅپہ۔ ژے اوس سوچان زِ بہٕ اوسُس ژے ہیوٗ یُتھ {یُتھ} یُس ژے ہیو اوسس: {مگر} بہٕ کٔرٕ ژے ملامت تہٕ کٔرٕ تِمن ہٕنزِ نظرن برونہہ کُن ترتیب۔ \n22.\\tوۅنۍ وُچھِو یُس خدایہ مٔشِل کٔرِو، نتہٕ بہٕ ژٔٹِتھ تہٕ کانہہ تہِ آسہِ نہٕ دِنہٕ خٲطرٕ۔ \n23. یُس تہِ تعریف کرِ، سُہ چُھس میہ جلال دِوان: تہٕ یُس {تسٕن} کتھ باتھہِ ہُند حکم دِیہ، سُہ کرٕ بہٕ خدایہ سٕنز نجات ہاونہٕ۔ {یہ...: ہیب۔ یُس پنٕنۍ وتھ دِوان چُھ}","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور، ییلہ ناتھن پیغمبر أمِس نِش آو، سُہ باتھ شیبا گٔژِھتھ آو۔] اے خدایہ، پننہِ محبتہٕ مطٲبق کٔر میہ پیٹھ رحمت: پننہِ نرم رحمتٕچ کثرت مطٲبق کٔر میٲنۍ خطا مٹاو۔ \n2. میانہِ گۅناہ نِش صاف کرُن تہٕ میانہِ گۅنہہ نِش صاف کرُن۔ \n3. کیازِ بہٕ چُھس پنٕنۍ غلطی تسلیم کران: تہٕ میون گۅناہ چُھہ میہ برونہہ کُن۔ \n4.\\tژے سٍتـ̡ چُھہ ژے سٍتـ̡ گۅناہ کورمُت، تہٕ یێلہِ تہٕ ژے کٔرِو تہٕ یێلہِ \n5. وچھ میہ ٲس بدکاری منز شکل دژمژ۔ تہٕ گۅنہٕ سٍتـ̡ کٔر میانہِ ماجہ حاملہٕ۔ {حاملہ...: حبری۔ گرم کرُن}\n6.\\tوچھ ژے چُھہ باطنی حصن منز حقیقژ ہُند خواہش: تہٕ پوشیدٕ حصس مَنٛز کٔرِکھ میہ حکمت زانن۔ \n7. میہ کٔرِو ہِسپ سٍتـ̡ صاف تہٕ بہٕ گژھہٕ شیٖنہٕ کھۅتہٕ سفید۔ \n8.\\tمیہ کٔر خوشی تہٕ خوشی بوزناوُن۔ {یُس} یُس ژے پھُٹمُت چھُ، تِم گژھن خۅش گژھن۔ \n9. پَنُن بُتھ کٔرِو میانہِ گۅنہہ نِش ژوٗر، تہٕ میٲنۍ سارِنٕے گُناہ کٔرِو مَٹاونہٕ۔ \n10. اے خدایہ، میانہِ مَنٛز بناو اکھ صاف دِل؛ تہٕ کٔرِو میٲنِس اندر اکھ صحیح روح تازٕ۔ {صحیح: یا، مستقل}\n11. مے کٔر نہٕ پننہِ حٲضِری نِش دوٗر ۔ تہٕ نِش نہٕ پنُن پاک روح میانہِ نِش نِش۔ \n12. پنہٕ نِس نجات ہٕنز خوشی کٔرِو میہ واپس۔ تہٕ رژھ \n13. {پتہٕ} بہٕ ہیچھناوٕ ناکارن پنٕنۍ وتھ ۔ تہٕ گنہگار گژھن توے کُن تبدیل۔ \n14.\\tاے خدایہ، اے خدا، میانہِ نجات ہُند خدا، تہٕ میٲنۍ زبان کرِ چانہِ نیکی ہٕندِ خٲطرٕ بَڑِ گٮ۪وُن۔ {خون: حب۔ خون}\n15. اے خداوند، میٲنۍ وٕٹھ کھولٕن، تہٕ میٲنۍ ٲس کٔرٕ چانۍ تعریف۔ \n16.\\tتکیازِ ژے چھُنہٕ قربانی دِنُک خواہش۔ نتہٕ دِیُس بہٕ دِیُن: ژے چھُنہٕ دَزنہٕ سٍتـ̡ خۅش گٔژھان۔ {نتہٕ...: یا یُس بہٕ کرُن}\n17. خدایہ سٕنز قربانی چھِ پھُٹمُت روح: اکھ پھُٹمُت تہٕ پشیمان دِل، اے خدایہ، ژے کٔرِو نہٕ حقارت کٔرِتھ۔ \n18.\\tصہیونس سٍتـ̡ کرو پننہِ خوشی سٍتـ̡ نیکی کٔرِتھ: یروشلمٕچ دیوارٕ بناوٕنـ̡ ۔ \n19. تیلہٕ گژھ تُہۍ نیکی ہٕنزِ قربانیَن سٍتـ̡ خۅش گٔژِھتھ تہٕ سٲرۍسٕے سٍتـ̡ سٍتـ̡ دِنہٕ آمٕتـ̡ تۯێلہِ تُہٕندِس قربان گاہَس پى۪ٹھ۔","1. [اَکھ زبور داؤد سٕندِس موسیقارس مَشِلَس سٍتـ̡، یێلہِ دۆگ ادومی آو تہٕ ساؤلس ووٚنُن تہٕ وونُن زِ داؤد چُھہ اہیمیلک کِس گرس مَنٛز آمُت۔] اے طاقتور انسان، کیازِ چُھکھ پانس شرارت کٔرِتھ؟ خدایہ سٕنز نیکی {چِھ} مسلسل۔ {مشکیل: یا، ہدایت}\n2.\\tچانۍ زبان چھیہ شرارت کران۔ تیزۍ استرا ہٕندۍ پٲٹھۍ، دھوکہ دہی سان کٲم کران۔ \n3. ژے چُھہ نیکی کھۅتہٕ زیادٕ بدی سٍتـ̡ محبت کران۔ {تہٕ} نیکی بولنہٕ بجایہ اپُز ۔ سیلہ۔ \n4.\\tژے چھکھ سارِنٕے کھٮ۪نہٕ وٲلِس لفظس خۅش کران، اے دھوکہ دِنہٕ واجنہِ زبان۔ {اے ژے...: یا، تہٕ دھوکہ دہی زبان}\n5.\\tیِتھے پٲٹھـ̡ کرِ خدایہ ژے ہمیشہٕ خٲطرٕ تباہ کٔرِتھ، سُہ کٔرِو ژے نِش نِش تہٕ ژے کٔرِن زندٕ سٕندِ سرزمینہٕ منزٕ نِش نِش کڈِتھ۔ سیلاہ۔ {تباہی...: ہیب۔ ژے مار دِیُن}\n6. نیک تہِ گژھن وُچھن، تہٕ خوفزدہ تہٕ اسُن أمِس سٍتـ̡ ہُن: \n7. لو، {یہ} چُھہ سُہ انسان {یُس} خدایہ سُند طاقت بنیوو۔ بلکہ کورُن پننِس دولتس پیٹھ بھروسہٕ، {تہٕ} پننِس بدکارس منز کوٚرُن پنُن پان مضبوط۔ {بدکاری: یا، مادہ}\n8. مگر بہٕ چُھس خدا سٕندِس گرس مَنٛز سبز زیتون کُلِس ہٕندۍ پٲٹھۍ: بہٕ چُھس ہمیشہ ہمیشہ خدایہ سٕنزِ رحمتَس پیٹھ بھروسہٕ تھاوان۔ \n9. بہٕ کَرٕ تۅہہِ ہمیشہٕ خٲطرٕ تعریف، تکیازِ ژے چُھہ یہ کورمُت: تہٕ بہٕ کرٕ چانہِ ناوُک انتظار۔ کیازِ یہِ چُھہ چُھہ چانہِ مُقدسن برونہہ کُن اصل۔","1.\\t[مہلاتس پیٹھ بٔڈ موسیقار، مشیل، {اکھ زبور} داؤد سُند۔] بیوقوفن چُھ پننِس دِلس منز وونمُت، {چُھنہٕ کانہہ خدا}۔ تِم چِھ بدکار تہٕ یِمو کٔر مکروہ بدکاری کٔرمٕژ: {چُھنہٕ کانہہ تہِ} یُس نیکی کرِ۔ {مشکیل: یا، ہدایت}\n2. خداین وُچھ آسمانہٕ پیٹھٕ انسانن ہٕندِس بچن کُن، یہٕ وچھنہٕ خٲطرٕ زِ کیا کانہہ تہِ چُھ یُس سمجھان چُھ، یُس خدایہ ژھاران چُھ۔ \n3.\\tیمن منز چھہ پریتھ کانہہ واپس گومت: تم چھہِ سراسر گند بنان۔ {اتہِ} چھہ نہ کانہہ تہِ نیکی کران، نہ، اکھ تہِ۔ \n4.\\tبدکار کارن چھا نہٕ کانہہ علم؟ یِم میانین لوکن کھیوان چِھہ یِتھٕ پٲٹھۍ تِم روٹی کھیوان چھِ: تِمو چُھ نہٕ خدایہ سٕندِ سٍتـ̡ پُراونہٕ آمُت۔ \n5.\\tتِمن ٲس سٮ۪ٹھاہ خوفہٕ، یێتہِ اوس نہٕ کانہہ خوفہٕ: کیازِ خداین چھُ تۅہہِ سٕنزِ أڈجہِ ژٔٹِتھ ژٔٹمٕژ، تکیازِ خداین کٔر تِمن حقارت۔ {ٲس...: ہیب۔ تِم ٲسۍ خوفہٕ کھوژان}\n6.\\tاے کاش اسرٲیلٕچ نجات آسہِ صیہون منزٕ نیرِتھ! یێلہِ خدا پَنٕنـ̡ لُکن ہُند قید واپس انِ، یعقوب گژھہِ خۅش، {تہٕ} اسرٲیلـ̡ گژھہِ خۄش۔ {اوہ...: حب۔ کُس دِیہِ نجات وغیرہ}","1. [نیگینوتس پیٹھ چیف موسیقار، مشکیل، {اکھ زبور} داؤد سُند، ییلہ زفیمس آو تہٕ ساؤلس وونُن، کیا ڈیوڈ چُھ نہٕ اسہِ نِش ژورِ روزان؟] اے خدایہ، پننہِ ناوٕ سٍتـ̡ بچاو مے تہٕ پننہِ طاقتہٕ سٍتـ̡ کٔر میہ فٲصلہٕ۔ {سردار...: یا، نگران} {مشکیل: یا، ہدایتُک}\n2. اے خدایہ، میٲنۍ دُعا بوزو۔ میانہِ ٲسٕچ کتھ بوز۔ \n3.\\tتکیازِ اجنبی چھہِ میانہِ خلاف کھڑا سپدان تہ ظالم چھہِ میانہِ روح ژھاران: تمو چھہ نہ خدایہ پانس برونہہ کنہِ تھوومت۔ سیلہ۔ \n4. وُچھو، خدا چُھہ میون مددگار: خداوند چُھ تِمن سٍتـ̡ یُس میانہِ روحس رژھراوان چُھ۔ \n5. سُہ دِیہِ میانین دُشمنن بُرِس سٍتـ̡ بدلہٕ: تِم ژٔٹِتھ ژٔٹِتھ ژٔٹِتھ پنہٕ نِس حقیقتس مَنٛز۔ {میٲنۍ ...: ہیب۔ یُس میہ وچھان چُھ}\n6. بہٕ کَرٕ ژےٚ خٲطرٕ آزادانہٕ طور قربان: اے خداوند، بہٕ کَرٕ چانہِ ناوٕچ تعریف۔ یِہ چُھہ اصل۔ \n7. تِکیازِ تٔمۍ کٔر مے سارِوٕے مصیبت نِش بچاوُن، تہٕ میانہِ أچھ وُچھمٕژ میانین دُشمنن پیٹھ۔","1. [نیگینوتس پیٹھ چیف موسیقار، مشکیل، {اکھ زبور} داؤد سُند۔] اے خدایہ میانہِ دُعا بوز تہٕ میانہِ دُعا نِش گژھ نہٕ پان پوش۔ {سردار...: یا، نگران} {مشکیل: یا، ہدایت}\n2.\\tمیہ کٔرِو توجہ تہٕ بوزو: بہٕ چُھس پننہِ شکایژ منز ماتم کران، تہٕ شور کٔرِتھ۔ \n3. دُشمن سٕنزِ آوازٕ سٍتـ̡ ، بدکارن ہٕندِ ظلمہٕ سٍتـ̡ ، کیازِ تِم چِھ میہ سٍتـ̡ بدکار سٍتـ̡ بدکار سٍتـ̡ دِنہٕ آمٕتـ̡ ۔ \n4.\\tمیون دِل چُھس دَگ دِوان: تہٕ موتُک خوف چھُ میہ پؠٹھ پٮ۪وان۔ \n5.\\tخوف تہٕ تھرتھر آو میہ پیٹھ، تہٕ وحشت چھیہ میہ مغلوب کٔرمژ۔ {مغلوب گٔژھمُت: ہیب۔ کورُن}\n6.\\tتہٕ میہ ووٚن، اے کاش میہ آسہ کۅتر ہیو پکھہ! {تیلہِ} اوسس بہٕ وُڈان تہٕ آرام کٔرتھ۔ \n7.\\tلو، {تیلہِ} بہٕ دور دور پھیرُن، {تہٕ} بیابانن منز روزُن۔ سیلہ۔ \n8.\\tبہٕ کٔر واو طوٗفان نِش ژلنس جلدی۔ \n9.\\tاے خداوند، تِہٕنزِ زبانہِ کٔرِو تِہٕنزِ زبانہِ ہٕندِس تباہی سٍتـ̡ تِکیازِ مے وُچھمُت شہرس مَنٛز تشدد تہٕ کشمکش ۔ \n10.\\tدۅہ تہٕ رات چھِ تِمن ہٕندِس دیوارس پیٹھ نژان: شرارت تہٕ غم تہِ چھِ۔ \n11.\\tبدکاری چھیہ اتھ منز: دھوکہ دہی تہٕ فریب تہٕ دھوکہ دہی چھیہ نہ تٔمۍ سٕنزِ سڑکہِ نشہِ نیران۔ \n12.\\tتکیازِ {یہ} اوس نہٕ کانہہ دُشمن {یُس} میہ ملامت کٔرِتھ۔ تیلہ ہیوٚک بہٕ ہیوٚک {یہ} برداشت کٔرتھ: نہ اوس {یہ} یُس میہ نفرت کران {یُس} اوس میہ خلاف {پانس} بڑاومُت۔ تیلہ اوسس میہ پانس نِش ژورِ: \n13.\\tمگر {یہ اوس} توے اکھ انسان میون برابر، میون رہبر تہٕ میون واقف۔ {میون برابر: ہیب۔ میانہِ درجہٕ مطٲبق}\n14.\\tأسۍ رٔٹۍ رٔلِتھ مٔٹھۍ مشورٕ، {تہٕ} گٔیہِ خدایہ سٕندِس گرس کُن۔ {أسۍ...: حب۔ یُس مٔٹھۍ مشورہٕ دِژ}\n15.\\tتِمن پیٹھ گژھن موت رٔٹِتھ، {تہٕ} گژھن تِمن جہنمس مَنٛز، تکیازِ بدکاری {چُھ} تِمن مَنٛز {تہٕ}۔ {جہنم: یا قبر}\n16. یوتام میانہِ خٲطرٕ، بہٕ کَرٕ خدایہِ سٕندِس سٍتـ̡ پَز۔ تہٕ خداوند کرِ مے بچاو۔ \n17.\\tشامس تہٕ صبحس تہٕ دوپہرس تہٕ دُپہرٕ بہٕ دُعا تہٕ بَڑِ روُن: تہٕ سُہ بوزِ میٲنۍ آواز۔ \n18.\\tتٔمۍ کٔر میانہِ روح سُکوٗن سٍتـ̡ یُس میہ خلاف جنگہٕ سٍتـ̡ نجات دِژمُت، تکیازِ واریاہ ٲسۍ میہ سٍتـ̡ ۔ \n19.\\tخدا کرِ تِمن بوزُن، تہٕ دِیہِ تِمن سٍتـ̡ یُس پرانہِ زمانس منز روزان چُھ۔ سلہٕ۔ تِکیازِ تِمن چُھنہٕ کانہہ تبدیلی آمٕژ، لہذا چُھہ نہٕ تِم خدایہِ سٍتـ̡ کھوژان۔ {کیازِ...: یا، یێمِس سٍتـ̡ تہِ چُھہ نہٕ کانہہ تبدیلی سپدِتھ، توتہِ چُھہ تِمن سٍتـ̡\n20. تٔمۍ چُھ پَنُن اَتھٕ تُلِتھ یُس أمِس سٍتـ̡ امن آسہِ، تٔمِس چُھ پَنُن عہد پھُٹروومُت۔ {پھُٹروُن: عبری۔ ناپاک کٔرِتھ}\n21.\\t{امۍ سٕندِ ٲسٕکۍ لفظ} ٲسۍ تھنہٕ کھۅتہٕ نرم مگر جنگ {اوس} تٔمۍ سٕندِس دِلس منز: تٔمۍ سٕندۍ لفظ ٲسۍ تیٖلہٕ کھۅتہٕ نرم، توتہِ ٲسۍ تِمو تلوار کڈان۔ \n22. پَنُن بار تراوُن خداوند سٕندِس پٲٹھۍ، تہٕ سُہ کرِ نہٕ تۅہہِ رژھراونہٕ۔ {بوج: یا، تحفہٕ}\n23.\\tمگر اے خدایہ، تِمن ہٕندِس دۅہس مَنٛز واتناوُن: خونریز تہٕ دھوکہ دِنہٕ وٲلِس انسان گژھن نہٕ پنٕنـ̡ نصف دۅہہٕ زِندٕ۔ مگر بہٕ کٔرٕ ژے پیٹھ بھروس۔ {خون...: ہیب۔ خونی تہٕ دھوکہٕ دِنہٕ وٲلۍ} {شُل...: ہیب۔ تِمن ہٕندِس نصف دۅہس منز گژھن نہٕ}","1. [جونتھیلمریکوکیمس پیٹھ، داؤد سٕندِس مِچٹمس پیٹھ بٔڈۍ موسیقارس سٍتۍ، ییلہ فلسطینیو سُہ گاتھس مَنٛز نِیو۔] اے خدایہ، میانہِ خٲطرٕ رحم کرُن، کیازِ انسان کرِ میہ نِگِلہٕ۔ سُہ چُھ دۅہٕ دۅہہٕ دٲیرٕ سُند ظُلم کران۔ {مِختم...: یا، داؤد سُند سنہری زبور}\n2.\\tمیٲنۍ دُشمن چھِ دۅہہٕ دۅہہٕ گِلہِ نِوان: تِکیازِ {تِم} چھِ واریاہ یِم میانہِ خلاف لڑان چھِ، اے تُہۍ چھِ۔ {دُشمن: ہیب۔ مُشٲہِدٕ}\n3. بہٕ کمہِ وقتہٕ کھوژان چھُس، بہٕ کَرٕ ژےٚ پیٹھ بھروسہٕ۔ \n4. بہٕ کَرٕ خدایس مَنٛز تٔمۍ سٕندِس کلامٕچ تعریف، خدایس مَنٛز چُھس پَنُن بھروسہٕ تھوومُت۔ بہٕ چُھس نہٕ خوفہٕ زِ ماز کیا ہیکہِ میٲنس سٍتـ̡ کٔرِتھ۔ \n5.\\tپریتھ دۅہہ چھہِ تم میانہِ کلام: تہند سٲری خیال چھہِ میہ خلاف بد کار۔ \n6.\\tتِم چھِ پان جمع کران، تِم چھِ پنُن پان ژوٗرِ تھاوان، تِم چھِ میانہِ روحُک پیاران تہٕ میانہِ قدمن ہُند نشان زد کران۔ \n7. کیا تِم گُننہٕ سٍتـ̡ بچہٕ؟ اے خدایہ، غصہٕ سٍتـ̡ دِیُت لُکھ دِنہٕ۔ \n8.\\tژے چھکھ میانہِ آوارہ ونان: میانہِ اوٚش تراوُن پننہِ بوتلہِ منز: {کیا تِم چھہِ نہٕ پننہِ کتابہِ منز؟ \n9.\\tییلہ بہٕ ژے کُن وُچھان چھُس، تیلہِ گژھن میٲنۍ دُشمن واپس پھیرُن: یێلہِ چُھس بہٕ پتاہ ؛ تکیازِ خدایہ چُھہ میانہِ خٲطرٕ۔ \n10. خدایس منز کرٕ بہٕ {تسٕندِس} کلامٕچ حمد تہٕ خداوند سٕندِس کلامس سٍتـ̡ تعریف۔ \n11.\\tمیہ چھہ خدایس پیٹھ بھروسہ کورمُت: بہٕ گژھہِ نہ کھوژان زِ انسان کیا ہیکہِ میانہِ سٍتۍ کٔرِتھ۔ \n12. اے خدایہ، چانہِ عہد چھُس میہ پیٹھ: بہٕ کٔرٕ ژے تعریف۔ \n13. کیازِ ژے چُھہ میون روح مرنہٕ نِش بچٲومُت: {کیا ژٕ چُھہ} میانین قدمن پنہٕ نِش بچٲوِتھ، یُتھ بہٕ زندٕ سٕندِس گاشس منز خدایہ سٕندِ برونہہ کُن پٔکِتھ؟","1.\\t[اہم موسیقار، الٹاشِتھ، ڈیوڈ سٕندِس مِختمس سٍتۍ، ییلہ سُہ گۅپھِ منز ساؤلس نِش ژوٚل۔] اے خدایہ، میانہِ سٍتـ̡ رحم کرُن، تکیازِ میانہِ روح چُھس توے پیٹھ بھروسہ کران: آ، چانہِ پکھہٕ ہٕندِس ژھایہِ مَنٛز روزٕ بہٕ پنُن پناہ ، یوتام نہٕ یِمن آفتن ختم گژھن۔ {التاشیت: یا، تباہ نہ کرُن} {مِختم: یا، اکھ سنہری زبور}\n2. بہٕ کَرٕ خدایہِ سٕندِس سٍتـ̡ فریاد یُس میانہِ خٲطرٕ سارِنٕے چیزن انجام دِوان چُھ۔ \n3. سُہ سوزِ آسمانہٕ پیٹھ، تہٕ مے بچاوِ تٔمِس سٕندِس ملامت نِش یُس میہ نِگِلہٕ کرِ۔ سیلاہ۔ خدایہ دِیہِ پنٕنۍ رحمت تہٕ پَنُن حقیق۔ {نِش...: یا سُہ دِیہِ أمِس ملامت کَرُن}\n4. میون روح {چُھ}شیرن منز: {تہٕ} بہٕ چُھس {حتیٰ کہ} تِمن منز یِمن نار دِنہٕ آمُت چُھ، {حتیٰ کہ} انسانن ہٕندِ نیچو، یِمن ہٕندِ دند نیزٕ تہٕ تیر چِھ، تہٕ تِہنز زبان چِھ تیز تلوار۔ \n5.\\tاے خدایہ، آسمانس پیٹھ۔ {گژھہ} پنُن جلال {آسُن} سارِنٕے زمینہٕ پیٹھ۔ \n6.\\tتِمو چُھ میانین قدمن خٲطرٕ جال تیار کورمُت۔ میون روح چُھ نمُن: تِمو چُھ میانہِ برونہہ کُن اکھ کھۄڈ کھننہٕ آمُت، یتھ منز تِم پنہٕ پٲٹھۍ۔ سیلہ۔ \n7.\\tمیون دِل چُھہ ٹھیٖک، اے خدایہ، میون دِل چُھس ٹھیٖک: بہٕ گٮ۪وٕ تہٕ تعریف۔ {مقرر: یا، تیار}\n8.\\tبیدار گژھ میٲنۍ عظمت؛ بیدار، زبور تہٕ ہارپ: بہٕ چُھس سُلہٕ وۅتھان۔ \n9. اے خداوند، لُکن مَنٛز کَرٕ بہٕ تۅہہِ ہٕنز تعریف۔ \n10. تُہٕنٛز رحمت چھِ آسمانن خٲطرٕ بٔڑ، تہٕ تُہٕنٛز سچائی چھِ اوٚبرَن خٲطرٕ۔ \n11.\\tاے خدایہ، آسمانس پیٹھ، تُہند جلال گژھہِ سارِنٕے زمینہٕ پیٹھ۔","1. [اہم موسیقار، الٹاشیتھ، ڈیوڈ سٕندِس مِچٹمس تام۔] اے جماعت، کیا تُہۍ چھِو پٔزۍ پٲٹھـ̡ نیکی کتھ کران؟ اے انسانن ہٕندِس نیٚچو، کیا تُہۍ چھِو صحیح پٲٹھـ̡ فٲصلہٕ کران؟ {الٹاشِتھ...: یا کٔرِو نہٕ تباہ کٔرِو} {مِختم: یا، اکھ سۄنہٕ زبور}\n2.\\tآ، دِلس منز چھکھ بدکاری کران۔ تہۍ چھِو زمینہِ منز پننین اتھن ہُند تشدد تولان۔ \n3.\\tبدکار چھہِ رحمہ منزہ نیران: تم چھہِ زینہٕ وِزِ گُرِ گٔژھِتھ اپُز بولان۔ {یێلہِ...: ہیب۔ یٔڈ منز}\n4.\\tتِہُند زہر {چُھ} زہرٕ ہیوٗ زہرُک پٲٹھۍ: {تِم چھِ} ہِش زَرِ ہٕندۍ پٲٹھۍ{یُس} تٔمۍ سٕندِس کَن رُکاونہٕ آمُت۔ {زہر ہٕندۍ پٲٹھۍ: ہیب۔ ہِشر مُطٲبق بیترِ} {adder: or, asp}\n5.\\tیُس نہ دلکش سنز آواز بوزان آسہِ، یُس نہ زانہہ تہِ عقلمندی سان دلکش آسہِ۔ {دلکش...: یا، یُس نہ زانہہ چالاک آسہِ}\n6.\\tاے خدایہ، تِہٕندِس ٲسس مَنٛز پھُٹرٲوِو تِہٕندِس دندٕ سٍتـ̡ شیرن ہٕندِ بٔڈۍ دند، اے خدا۔ \n7.\\tیِم گژھن آبہٕ سٍتـ̡ یُس لگاتار وسان چُھہ: {ییلہ} سُہ [پنُن کمان} پَنٕنہِ تیر چلاونہٕ خٲطرٕ موڑان چُھ، تِم گژھن ٹُکرٕ ٹُکرٕ کٔرِتھ ژٹنہٕ۔ \n8.\\tیُتھ زن اکھ ہۅنگجہ {یُس} پگلان چھُ، {یِمو منزٕ پرٮ۪تھ کُنہِ} گزرُن: {یِتھ} زنانہِ ہٕندِ بے وقعت زٮ۪نہٕ سٍتۍ، {یُتھ} تِمن ہُند آفتاب وُچھُن نہٕ۔ \n9.\\tامہ برونہہ زِ تۅہہِ کُنہِ وُپھ سٍتـ̡ نِنـ̡ تہٕ دۅشوے زندٕ تہٕ {پننِس} قہر سٍتـ̡ نِنہٕ۔ {دۅنوے...: ہیب۔ یُتھ زِندٕ ہیو غصہٕ}\n10.\\tنیک گژھہِ خۅش ییلہ سُہ انتقام وُچھِ، سُہ کرِ بدکارن ہٕندِس خونس سٍتـ̡ پَنٕنـ̡ کھۅر چھلناوُن۔ \n11.\\tیُتھ زن انسان وَنُن زِ پٔزۍ پٲٹھـ̡ چُھہ صالحن ہُند ثواب چُھہ یُس زمینس مَنٛز انصاف کران چُھ۔ {اَکھ انعام...: Heb. پھل بیترِ}","1. [بٔڈۍ موسیقار، التاشیت، داؤد سٕندِس مِختامس کُن؛ ییلہ ساؤلن سوزمُت، تہٕ تِمو کٔر أمِس مارنہٕ خٲطرٕ گرٕ وُچھان۔] اے خدایہ، میہ کٔر میانین دُشمنن نِش بچاو، یِم میانہِ خلاف کھڑے سپدان چھِ۔ {التاشیت...: یا، تباہ کرُن نہٕ} {مِختم: یا، اکھ سنہری زبور} {بچاو...: حب۔ مے تھزرس پیٹھ تھاوُن}\n2. مےٚ کٔر بدکاری ہٕندِس کارکُنَو نِش بچاوُن، تہٕ بچاوُن خونی نفرَن نِش۔ \n3. تِکیازِ تِم چھِ میانہِ روحُک انتظار کران: طاقتور چھِ میانہِ خلاف جمع گٔمٕتۍ۔ اے خداوند، نہ میانہِ گۅنہٕ سٍتـ̡ تہٕ نہ میانہِ گۅنہٕ سٍتـ̡ ۔ \n4.\\tتِم چھِ ژلان تہٕ پان تیار کٔرِتھ {میانہِ} غلطی ورٲے تہٕ وُچھِو۔ {مدد: ہیب۔ ملاقات}\n5. تێمہِ کِنۍ، اے خداوند، اسرٲیلُک خدا، بیدار گژھ سارنٕے کافرن ہٕندِس دورس مۅکھہٕ: کُنہِ تہِ بدکار سٍتـ̡ گژھ نہٕ رحم۔ سیلاہ۔ \n6. تِم چھِ شامَس واپس یِوان: تِم چھِ ہونہِ ہٕندۍ پٲٹھۍ شور کَران، تہٕ شہرَس منٛز نژان چھِ۔ \n7.\\tوچھو تِم چُھس چُھہ بوزان۔ \n8.\\tمگر اے خداوند، تِمن پیٹھ اسُن۔ توے گژھہِ سارِنٕے کافرن ہُند طنز کرنہٕ۔ \n9.\\t{تٔمۍ سٕندِس طاقتہٕ سٍتـ̡ بہٕ چُھس چانہِ ہُند انتظار: کیازِ خدایہ {چُھ} میون بچاو۔ {دفاع: ہیب۔ تھدِ مقام}\n10.\\tمیانہِ رحمتُک خدا کرِ میہ رُکاونہٕ: خدایہ دِیہ میہ پننین دشمنن پیٹھ {میانہِ خواہش} وُچھن۔ {دشمن: ہیب۔ مبصرین}\n11. تِم مٲرِو نہٕ، یێلہِ میانہِ لُکھ مٔشِد گَژھن: تِم پھٔہلٲوِو پننہِ طاقتہٕ سٍتـ̡ ۔ تہٕ یِم أنِو، اے خداوند، سانہِ ڈھال۔ \n12.\\tتِمن ہٕندِس گۅناہ سٍتـ̡ چُھہ تِمن ہٕندِس فخرس سٍتـ̡ تہٕ بد دعا تہٕ اپُز کٔرِتھ تہٕ یُس تِم کتھ کران چھِ۔ \n13. غصہٕ سٍتـ̡ کھٮ۪وان {تِم} کھٮ۪وُن، یُتھ نہٕ تِم {بٔنِتھ} تہٕ تِمن زانن زِ خدا چُھ یعقوبس مَنٛز زمینہٕ کِس اندس تام حکمرٲنی کران۔ سیلاہ۔ \n14.\\tتہٕ شامس گژھن تِم واپس۔ {تہٕ} تِم کرٕن ہونین ہٕندۍ پٲٹھۍ، تہٕ شہرس اندۍ پکھۍ نژان۔ \n15.\\tتِم گژھن ماز خٲطرٕ ہیوٚر بوٚن پھیُرُن، تہٕ اگر نہٕ تِم مطمئن گژھن تیلہِ گژھن رنجش۔ {ماز خٲطرٕ: ہیب۔ کھٮ۪نہٕ خٲطرٕ} {تہٕ رنجش...: یا اگر نہٕ تِم مطمئن گٔژھن، تیلہِ روزن تِم سارِوٕے راتس روزُن}\n16. مگر بہٕ گٮ۪وٕ چانہِ طاقتُک گٮ۪و۔ آ، بہٕ گٮ۪وٕ صبحٲے چانہِ رحمتُک بَڑِ پٲٹھۍ: تِکیازِ ژٕ ٲسٕکھ میانہِ مصیبت ہٕندِس دۅہہٕ میٲنۍ دفاع تہٕ پناہ گاہ۔ \n17.\\tاے میانہِ طاقت، بہٕ گیوُن: خدایہ چُھہ میانہِ رحمتُک خدا۔","1. [شوشنیدوتس پیٹھ اہم موسیقار، داؤد سٕندِس مکتم سٍتۍ، ہیچھناونہٕ خٲطرٕ؛ ییلہ تٔمۍ آرامنہاریم تہٕ آرامزوبہ سٍتـ̡ کوشش کٔر، ییلہ یوآب واپس، تہٕ نونہٕ کِس وادی مَنٛز کٔرٕن ادوم سٕندِس بارہ ساس سٍتـ̡ مارٕ۔] اے خدایہ، ژے کٔر اسہِ کُن پھیُر، ژے چھکھ اسہِ پھیُرۍمٕتۍ، ژے چھکھ ناراض گومُت۔ اے پَنُن پان دُبارٕ اسہِ کُن پھیرُن۔ {مِختم: یا، اکھ سۄنہٕ زبور} {بکھرِتھ: ہیب۔ پھُٹمُت}\n2. ژے کٔر زمینہِ لرِ لرز؛ ژے چھکھ یہ پھُٹرٲومُت: اَمہ سٍتـ̡ پھُٹراوُن؛ تکیازِ یہ چُھہ لرزان۔ \n3.\\tژے ہٲوۍ پننین لوکن مشکل چیز: ژے چھکھ اسہِ حیرانگی ہُند شراب۔ \n4.\\tژے دِژ تِمن اکھ جھنڈٕ یُس تۅہہِ کھوژان چھُ، یُس حقیقتہٕ سٍتـ̡ ظٲہر سپدِ۔ سیلہ۔ \n5.\\tیُتھ چُھہ تُہند محبوب نجات دِنہٕ یُن۔ پنُن دچھُن اتھہٕ بچاوُن تہٕ بوزُن۔ \n6. خداین چُھ پننِس پاکیزگی مَنٛز کتھ کٔرمٕژ۔ بہٕ کٔرٕ شاد تہٕ بہٕ کٔرٕ شیکیمس تقسیٖم تہٕ وادی سُکوتھ کٔرِتھ۔ \n7. گلعاد {چُھ} میٲنۍ تہٕ منسیٰ {چُھ} میٲنۍ کلہٕ؛ افرائیم تہِ {چُھ} میانہِ کلہٕ سٕنز طاقت؛ یہوداہ {چُھ} میون قانون دِنہٕ وول ؛ \n8. موآب {چُھ} میٲنۍ واش پاٹ؛ اَدومَس پیٹھ کٔرِو بہٕ پنُن جوتُر: فِلِستیاہ، میانہِ مۅکھٕ کٔرِو ژے فتح۔ {فتح...: یا، ژٕ کٔرِو میہ پیٹھ فتح: (ستم ظریفی سٍتۍ}\n9. کُس کرِ میہ {مضبوط} شہرس منز؟ کُس کرِ میہ ایڈومس مَنٛز؟ {مضبوط...: ہیب۔ طاقتُک شہر؟}\n10.\\tاے خدایہ، {کُس اوسُکھ نہٕ اسہِ ژٔٹمُت؟ تہٕ {تو} اے خدایہ، {کُس} اوس نہٕ سانہِ فوجہٕ سٍتـ̡ نیبر نیران؟ \n11.\\tاسہِ دِیو مصیبت نِش مدد: بیکار {چُھ} انسان سٕنز مدد۔ {انسان سٕنز مدد: ہیب۔ نجات وغیرہ}\n12. خدایہ سٕندِ سٍتـ̡ کرو أسـ̡ بہادری سٍتـ̡ کٔرِتھ، تکیازِ سُہ چُھہ سانین دُشمنن ہُند پٲٹھـ̡ دِنہٕ۔","1.\\t[نیگینہ پیٹھ اہم موسیقارس سٍتۍ، داؤد سُند زبور۔] اے خدایہ، میٲنۍ فریاد بوزو۔ میانہِ دُعا سٍتـ̡ کٔرِو۔ \n2.\\tزمینہِ ہندِ اندس پیٹھ کرٕ بہٕ ژے کُن فریاد ییلہ میون دِل مغلوب گژھہِ: مے نِو تتھ کُنہِ کُنہِ کُن یُس میانہِ کھۅتہٕ تھوٚد چھُ۔ \n3.\\tتکیازِ ژے چھکھ میانہِ خاطرہ پناہ گاہ، {تہٕ} دشمنس نِش اکھ مضبوط مینار۔ \n4. بہٕ روزٕ چانہِ خیمہ مَنٛز ہمیشہٕ روزُن: بہٕ کَرٕ چانہِ پَکھہٕ ہٕندِس پوشیدس پیٹھ بھروسہٕ۔ سیلاہ۔ {بھروسہٕ: یا کٔرِو میٲنۍ پناہ گاہ}\n5. اے خدایہ، ژے چُھہ میٲنۍ عہد بوزمُت: ژے چُھکھ تِمن ہُند وراثت دِژمُت یُس تُہند ناو کھوژان چھُ۔ \n6.\\tژے کٔرِو بادشاہ سٕنزِ وٲنسہِ زیٹھراوُن: {تہٕ} تٔمۍ سٕندِس وٲنسہِ ہٕندِس وٲنسہِ۔ {توہ...: ہیب۔ ژے کٔرِو بادشاہ سٕندِس دۅہس منز دۅہ ہُریر} {یِتھ...: ہیب۔ بطور نسل تہٕ نسل}\n7. سُہ روزِ ہمیشہٕ خٲطرٕ خدایہِ سٕندِس برونہہ کُن: اے رحمتُک تہٕ سچائی تیار کرُن، {یُس} أمِس رژھراوِ۔ \n8. یِتھٕ پٲٹھۍ گٮ۪وٕ بہٕ چُھس ہمیشہٕ خٲطرٕ چانہِ ناوٕچ تعریف، یُتھ بہٕ روزٕ پنُن عہد پورٕ کٔرِتھ۔","1. [اہم موسیقارس سٍتۍ، یہدوتونس سٍتۍ، داؤد سُند زبور۔] پٔزۍ پٲٹھـ̡ چُھہ میون روح خدایہ سُند انتظار: أمِس سٍتـ̡ چُھہ میٲنۍ نجات دِوان۔ {پٔزۍ: یا، صرف} {انتظار: ہیب۔ چُھہ ژھۄپہٕ}\n2. سُہ چُھ صرف میٲنۍ کَنہِ تہٕ میٲنۍ نجات {سُہ چُھ} میٲنۍ بچاو۔ بہٕ گژھِ نہٕ زیادٕ متٲثر۔ {دفاع: حب۔ تھدِ جاے}\n3. ژیہ کٲتِس کالس انسانس سٍتۍ شرارت کرنُک تصور کٔرِتھ؟ تم یِو سارِنٕے مارنہٕ: یِتھٕ پٲٹھۍ، تہٕ یِتھٕ پٲٹھۍ۔ \n4.\\tتِم چھِ صرف تٔمِس سٍتـ̡ دِنہٕ خٲطرٕ مشورٕ دِوان: تِم چھِ اپُزس سٍتـ̡ خوش کران: تِم چھِ پننہِ ٲسِس سٍتـ̡ برکت دِوان، مگر تِم چھِ باطنی طور بد دعا کران۔ سلہٕ۔ {باطنی پٲٹھۍ: حب۔ تِمن ہٕندِس باطنی حصس منز}\n5.\\tمیانہِ روح، صرف خدایہ سٍتـ̡ انتظار کرُن۔ تکیازِ میانہِ وۅمید چھیہ تس نِش۔ \n6. سُہ چُھ صرف میٲنۍ کَنہِ تہٕ میٲنۍ نجات : {سُہ چُھ} میٲنۍ بچاو۔ بہٕ گژھِ نہٕ ہلاونہٕ یُن۔ \n7. خدایس مَنٛز چُھہ میٲنۍ نجات تہٕ میٲنۍ عظمت: میانہِ طاقتٕچ پتھر، {تہٕ} میٲنۍ پناہ گاہ، {چُھ} خدایس مَنٛز۔ \n8.\\tپریتھ ساعتہ کرو تس پیٹھ بھروسہ۔ {یۅہ} لوکو کٔرِو پنُن دِل أمِس برونہہ کُن: خدا چُھ سانہِ خٲطرٕ پناہ گاہ۔ سیلہ۔ \n9.\\tیقینا کم درجکۍ انسان {چھہ} فضول، {تہٕ} تھدِ درجکۍ انسان {چھہ} اکھ اپُز: توازن تھاونہ خاطرہ چھہِ تم {چھہ} سراسر {باطل} کھوتہ زیادہ ہلکہ۔ {مجموعہ: یا، ہشر}\n10.\\tظلمس پیٹھ مہٕ بھروسہٕ کرُن، تہٕ لوٹنس منز گژھِ نہٕ بیکار: اگر دولتس منز ہُرٮ۪ر گژھہِ، پَنُن دِل تھاوُن نہٕ تِمن پیٹھ۔ \n11. خداین چُھ اکہِ لٹہِ کتھ کٔرمٕژ۔ میہ چُھ یہ دۄیہِ لٹہِ بوزمُت۔ سُہ طاقت {چُھ} خدایہ سُند ۔ {طاقت: یا، طاقت}\n12. اے خداوند، تہِ چُھہ تۅہہ رحمت، تکیازِ توے چُھہ پریتھ انسانس تٔمۍ سٕندِ کامہِ مُطٲبق دِوان۔","1. [داؤد سُند زبور، ییلہ سُہ یہوداہ کِس بیابانس مَنٛز اوس۔] اے خدایہ، توے چُھکھ میٲنۍ خدا۔ سُلہٕ چُھس بہٕ ژے ژھانڈان: میون روح چُھ چانہِ خٲطرٕ ترش، میون ماز چُھ ژے خٲطرٕ ترسان۔ {ترش: ہیب۔ تھکاوُن} {کتہِ...: آبہٕ ورٲے}\n2. چانۍ طاقت تہٕ تُہند جلال وُچھنہٕ خٲطرٕ، یِتھ کٔنۍ مے چُھہ ژے مقدس مقامس منز وُچھمُت۔ \n3. تِکیازِ تُہٕندِ محبتہٕ سٍتـ̡ چُھہ زندگی کھۅتہٕ بہتر، میٲنۍ چپنہٕ سٍتـ̡ چُھہ ژے تعریف۔ \n4. یِتھٕ پٲٹھۍ کَرٕ بہٕ ژے زندٕے آسنہٕ وِزِ تہٕ بہٕ تُلِتھ پنٕنۍ اَتھٕ تُلِتھ تہ \n5.\\tمیون روح گژھہِ {سٍت} میرو تہٕ چربی ہٕندۍ پٲٹھۍمطمئن سپدُن۔ تہٕ میانہِ ٲسس کٔرِ خۅش وُٹھہٕ سٍتۍ {ژے} تعریف: {میرو: ہیب۔ موٹۍ}\n6.\\tییلہ بہٕ ژے پننِس بسترس پیٹھ یاد کرُن، {تہٕ} رٲژ ہٕندِس پہرِ منز کٔرِو ژے پیٹھ مراقبہٕ۔ \n7. تِکیازِ ژٕ چُھکھ میٲنۍ مدد کٔرمٕژ، لہذا بہٕ کَرٕ چانہِ پَکھہٕ ہٕندِس ژھایہِ مَنٛز خۄش۔ \n8. میون روح چُھ ژے پَتہٕ سختی سان پَکان: تُہند دٔچھُن اَتھٕ چُھ مےٚ تھپھ کَران۔ \n9. مگر یِم {یُس} میانہِ روح ژھاران چھِ، تِم گژھن زمینہِ ہٕندِس بنمِس حصس مَنٛز۔ \n10.\\tتِم گژھن تلوار سٍتـ̡ پَسنہٕ: تِم گژھن پۅژھہٕ پٲٹھـ̡\n11. مگر بادشاہ گژھہِ خدایہ سٍتـ̡ شاد سپدُن۔ یُس پریتھ شخص أمِس سٍتـ̡ قَسم کٔرِ، سُہ گژھہِ جلال حٲصِل کرنہٕ، مگر یُس اپُز بولان چُھ، سُہ گژھہِ رُکاونہٕ یُن۔","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور۔] اے خدایہ، میانہِ دعاہس منز بوز میٲنۍ آواز: دُشمن سٕندِ خوفہٕ نِش بچٲو میون زُو ۔ \n2. بدکارن ہٕندِس خفیہ مشورس نِش کٔرِو مے ژوٗر۔ بدکارن ہٕنزِ بغاوتس نِش: \n3.\\tیِم تلوار ہٕندۍ پٲٹھۍ، {تہٕ} تیر چلاونہٕ خٲطرٕ کمان نِوان چھِ، {حتیٰ کہ} تلخ لفظ: \n4.\\tتاکہ تم گژھن ژوٗرِ پٲٹھۍکامل کُن گولہِ چلاوان: اچانک چھِ تِم أمِس گولہِ چلاوان، تہٕ کھوژان نہٕ۔ \n5.\\tتِم چھِ پانس حوصلہٕ افزایی کران {منز} أکِس بد معاملس منز: تِم چھِ پوشہٕ رٔٹِتھ پھیپھ تراونٕچ کتھ کران۔ تِم چھِ ونان زِ تِم کُس وُچھِو؟ {معاملہٕ: یا، کتھ باتھ} {منز...: ہیب۔ پنٕنۍ پھندٕ ژوٗرِ تھاونہٕ خٲطرٕ}\n6.\\tتِم چھِ بدکاری ژھانڈان۔ تِم چھِ محنتی سان تلاش کران: پرٮ۪تھ أکِس سُند باطنی {خیال} تہٕ دِل {چُھ} سرٛوٚن۔ {تِم...: یا، أسۍ چھِ تِمن سٍتۍ کھٮ۪وان یُس تِمو پوٗرٕ پٲٹھۍ ژھانڈان چھُ} {اکھ محنتی...: ہیب۔ اکھ ژھانڈنہٕ آمُت}\n7.\\tمگر خدایہ دِیہِ تِمن تیر سٍتـ̡ گولہِ۔ اچانک گژھن تِم زخمی۔ {کیا تِم...: ہیب۔ تِہُند زخم گژھہِ}\n8.\\tیێلہِ گژھن تِم پنٕنـ̡ پَنٕنـ̡ پى۪ٹھـ̡ پى۪ٹھ۔ \n9. تہٕ سارِنٕے انسان گژھن خوفزدہ تہٕ خدایہ سٕنزِ کامہِ ہُند اعلان کرُن۔ تِکیازِ تِم گژھن تٔمۍ سٕندِس عملس مُتعلِق دانشمندی سان غور کرُن۔ \n10. صالحین گژھہِ خداوند سٍتـ̡ خوش تہٕ تس پیٹھ بھروسہٕ کرُن۔ تہٕ سارِنٕے دِلس سٍتـ̡ گژھن جلال حٲصل کرنہٕ۔","1.\\t[اہم موسیقارس سٍتۍ، اکھ زبور {تہٕ} داؤد سُند نغمہٕ۔] اے خدایہ، سیونس مَنٛز چُھہ تۅہہِ ہٕندِ خٲطرٕ تعریف: تہٕ ژے سٍتـ̡ گژھہِ عہد کرنہٕ۔ {انتظار: ہیب۔ چُھہ ژھۄپہٕ}\n2. اے یُس دعا بوزان چُھہ، تۅہہِ سٍتـ̡ یِیہِ سارِنٕے ماز یِنہٕ۔ \n3.\\tبدکاری چھیہ میانہِ خلاف غالب: {یوتۍ}سانہِ گناہ مۅکھہ تہِ چھکھ تم صاف کٔرتھ۔ {بدکاری: ہیب۔ لفظ، یا، بدکارین ہند معاملہ}\n4. بابرکت چُھہ سُہ انسان یُس ژٲرِتھ چُھہ تہٕ ژے نِش واتناوُن، یُس تُہٕندِس دربارس مَنٛز روزُن، أسـ̡ گٔژھِو تُہٕندِس گَرٕچ نیکی سٍتـ̡ مطمئن۔ \n5. نیکی سٍتـ̡ خوفناک چیزن سٍتـ̡ چُھہ اسہِ جواب دِنہٕ، اے سانہِ نجات ہُند خدا۔ {کُس} چُھہ زمینہِ ہٕندِس سارِنٕے اندس سٍتـ̡ تہٕ سمندرٕ سٍتـ̡ دوٗر روزن وٲلِس سمندرس سٍتـ̡ یُس یقین چُھہ: \n6.\\tیُس پننہِ طاقتہٕ سٍتۍ پہاڑ بٔنِتھ بٔنِتھ چھُ۔ {وجود} سٍتـ̡ بٔرِتھ \n7.\\tیُس سمندرن ہُند شور، تہنزِ لہرن ہُند شور تہٕ لُکن ہُند ہنگامہٕ رُکاوٹ کران چھُ۔ \n8.\\tیِم تہِ چھِ تُہٕندِس نِشانہٕ سٍتـ̡ کھوژان: تُہۍ چھِو صُبح تہٕ شامٕچ نیرُن خۅش کرنہٕ خٲطرٕ بناوان۔ {شاد: یا، گٮ۪وُن}\n9.\\tژے چُھکھ زمینہٕ وُچھان، تہٕ آب دِوان تہٕ ژے چُھکھ خدایہ سٕندِ دٔریاوٕ سٍتـ̡\n10.\\tژے چھکھ اَمہ کِس بالہٕ سٍتۍ وافر آب دِوان: ژے چھکھ اَمہ کِس کۅکرس سٍتۍ نرم بناوان: ژے چھکھ اَمہ کِس چشمس برکت دِوان۔ {بٔستِل: یا، وَسُن وَسُن} {بناوُن...: ہیب۔ اَتھ کٔرِتھ کٔرِتھ}\n11.\\tژے چھکھ ؤریس پننہِ نیکی سٍتۍ تاج لاگان۔ تہٕ تۅہہ وتہِ چھیہ چربی تراوان۔ {سٍتۍ: ہیب۔ سٍت}\n12.\\tتِم چھِ بیابان ہٕندِس مرگہٕ گاہَس پیٹھ تراوان: تہٕ لۅکٹۍ بالہٕ چھِ پریتھ طرفہٕ خۅش گژھان۔ {شاد...: ہیب۔ خوشی سٍتۍ گٔژھِتھ چھِ}\n13.\\tمرگہٕ چِھہ پَلہٕ رٔٹِتھ بٔرِتھ۔ وادی تہِ چھِ مَکٲے سٍتـ̡ ؤلِتھ ۔ تِم چِھ خوشی سٍتـ̡ کرٛٮ۪کھ دِوان، تِم تہِ چِھ گیوان ۔","1. [اہم موسیقارس کُن، اکھ بٲتھ {یا} زبور۔] خدایہ سٍتـ̡ کٔرِو خوشی ہُند شور، سارِنٕے زمینہٕ: {سارِنٕے ...: ہیب۔ سارِنٕے زمینہٕ}\n2.\\tتٔمۍ سٕندِ ناوُک عزت: تٔمۍ سٕندِ تعریفس کٔرِو شاندار۔ \n3.\\tخدایس ونُن، ژیہ کوتاہ خوفناک چُھہ پننہِ کامہِ منز! پننہِ طاقتہٕ سٍتـ̡ کٔرِو تُہند دُشمن پان پانس سٍتـ̡ تابعدار۔ {تابع...: یا، فرضی فرمانبرداری: ہیب۔ اپُز}\n4. سارِوٕے زمینہٕ کٔرِن تۅہہِ ہٕنز عبادت تہٕ گٮ۪وُن تۅہہِ خٲطرٕ۔ تِم گٮ۪وَن تُہُند ناو۔ سیلاہ۔ \n5.\\tیِو خدایہ سٕندِ کامہِ وُچھِو: {سُہ} چُھہ انسانہٕ سٕندِس بچن سٍتـ̡ خوفناک سٍتـ̡ خوفناک س� \n6.\\tتِمو بنوو سمندرس خشک {زمین}: تِم گٔیہِ پیدل سٔلبس منز: تتہِ گٔیہِ أسۍ أمِس سٍتـ̡ خۅش۔ \n7. سُہ چُھ ہمیشہٕ خٲطرٕ پننہِ طاقتہٕ سٍتـ̡ حکومت کران۔ تٔمۍ سٕنزِ أچھ چھے قومن وُچھان: باغی گژھن نہٕ پانس تھزراونہٕ۔ سیلاہ۔ \n8. اے خدایہِ سٕندِس خدایہِ سٍتـ̡ برکت دِیُن، تہٕ تٔمۍ سٕندِ تعریفٕچ آواز بوزناوٕنـ̡ ۔ \n9.\\tیُس سانہِ روحس زندگی منز رٔٹتھ تھاوان چھُ، تہٕ سانہِ قدمن ہٕندِس قدمس رٔٹِتھ تھاوان چھُ۔ {ہولڈتھ: ہیب۔ پُٹیتھ}\n10. اے خدایہ، ژے کٔر اسہِ ثٲبت: ژے کٔر اسہِ آزماونہٕ، یِتھٕ پٲٹھۍ رۄپہٕ آزماونہٕ آمُت۔ \n11.\\tژے ووت اسہِ جالس منز۔ ژے کٔر سانہِ کمرس پیٹھ عذاب۔ \n12.\\tژے کٔر انسانس سٍتـ̡ سوارِ سٍتـ̡\n13. بہٕ ژٕ ژے گَرٕ دٔزِتھ نذرانہ ہٮ۪تھ: بہٕ کَرٕ ژے پنُن عہد \n14.\\tیُس میانہِ وُٹھ وُچھمُت چھُ، تہٕ میانہِ ٲسِس کتھ کٔرمٕژ، ییلہ بہٕ مُشکِلس منز اوسس۔ {کٔرِتھ: ہیب۔ کھولنہٕ}\n15.\\tبہٕ کٔرٕ ژے کُنہِ سٍتـ̡ دِنہٕ آمُت۔ بہٕ کٔرٕ ژھاوٕلِس سٍتـ̡ دانٛد دِنہٕ۔ سلہٕ۔ {fatlings: Heb. Marrow}\n16.\\tیِو یُس خدایہ سٍتـ̡ کھوژان چُھ، تہٕ بہٕ کرٕ اعلان زِ تٔمۍ کیا چُھ میانہِ روحہٕ خٲطرٕ کورمُت۔ \n17.\\tمیہ کٔر أمس پننہ ٲسس سٍتۍ، تہٕ سُہ آو میانہِ زبانہِ سٍتـ̡ تعریف۔ \n18. اگر بہٕ پننِس دِلس مَنٛز بدکاری سمجھان چھُس، خداوند بوزِ نہٕ {me}: \n19. {مگر} پٔزۍ پٲٹھـ̡ چُھ خداین بوزمُت {مے}؛ تٔمۍ چُھ میانہِ دُعا ہٕنزِ آوازِ ہُند جواب دِژمُت۔ \n20.\\tبابرکت خدایہ، یمۍ نہ میانہِ دُعا تہٕ نہ تٔمۍ سٕنز رحمت میانہِ نِش پتھ کٔرۍ۔","1. [نیگینوتس پیٹھ چیف موسیقارس سٍتۍ، اکھ زبور {یا} نغمہٕ۔] خدا کرِ اسہِ پیٹھ رحم تہٕ اسہِ برکت دِنۍ۔ {تہٕ} کرِ تٔمۍ سُند بُتھ اسہِ پیٹھ چمک؛ سیلہ۔ {سردار...: یا، نگر} {اَپ: ہیب۔ سٍت}\n2. یُتھ تُہٕنز وَتھ گژھہِ زمینہِ پٲٹھـ̡ زاننہٕ، سارِنٕے قومن مَنٛز گژھہِ تُہٕندِس بچاونٕچ صحت۔ \n3. اے خدایہ، لوکھ گژھن تۅہہِ تعریف کرنہٕ۔ سارِنٕے لُکھ گٔژھن تُہٕندِس تعریف۔ \n4. اے قومن گژھن خۅش تہٕ خوشی خٲطرٕ گیون: کیازِ تہٕ توے کرٕ لوکن ہُند انصاف تہٕ زمینس پیٹھ قومن پیٹھ حکومت کرٕنۍ۔ سیلہ۔ {حکومت: ہیب۔ لیڈ}\n5. اے خدایہ، لوکھ گژھن تۅہہِ تعریف کرنہٕ۔ سارِنٕے لوٗکھ گژھن تُہٕندِ تعریف۔ \n6.\\t{تیلہِ} دِیہ زمینہِ ہُند اضافہٕ۔ {تہٕ} خدایہ، {حتیٰ کہ} سون خدا، کرِ اسہِ برکت۔ \n7. خدا کرِ اسہِ برکت۔ تہٕ زمینہِ ہٕندِس سارِنٕے اندس گژھن أمِس سٍتـ̡ خوفزدٕ۔","1. [بٔڈۍ موسیقارس سٍتـ̡، اکھ زبور {یا} داؤد سُند نغمہٕ۔] خدایہ گژھہِ وۅتھُن، تٔمۍ سٕندِس دُشمن گژھن منتشر کرنہٕ: تِم تہِ گژھن أمِس برونہہ کُن ژلُن۔ {امہ برونہہ...: حب۔ تٔمۍ سٕندِس بُتھِس پیٹھ}\n2. یێلہِ دوٚہہ ژٔلِتھ گٔژھِو بدکار خدایہ سٕندِس حضورس سٍتـ̡ \n3.\\tمگر نیک آسن خۅش گژھن۔ خدایہ سٕندِ برونہہ گژھن خۅش گژھن: آ، تِم گژھن سٮ۪ٹھاہ خۅش سپدُن۔ {سٮ۪ٹھاہ زیادٕ...: ہیب۔ خوشی سٍتـ̡ خوش گژھُن}\n4. خدایہ سٕندِ خٲطرٕ گٮ۪وُن، تٔمۍ سٕندِس ناوٕچ تعریف: یُس اسمانس پیٹھ سوار سپدان چُھ، تٔمِس سٕندِس ناوٕ سٍتـ̡ کرو تسٕندِس سٍتـ̡ شاد تہٕ أمِس برونہہ کُن شاد سپدُن۔ \n5.\\tبے باپ سُند مول تہٕ بیواہ ہُند قاضی، {چُھ} خدا سٕندِس مقدس مکانس منز۔ \n6. خدا چُھ کُنُے خاندانن مَنٛز کُنُے روزان: سُہ چُھ تِم نِوان یِم زنجیرن سٍتـ̡ بٔنِتھ چِھ، مگر باغی چھِ خشک {زمینہٕ} مَنٛز روزان۔ {خاندانن منز: حب۔ أکِس گرس منز}\n7.\\tاے خدایہ، ییلہ تہٕ ژے پننین لوکن برونہہ کُن نیرِو، ییلہ تہٕ ژے بیابانن مَنٛز پکان ٲس۔ سیلاہ: \n8.\\tزمینہِ لوٚگ تہ آسمانن تہِ پیوٚو خدایہ سٕندِس حضورس سٍتـ̡ {حتیٰ کہ} سینا تہِ گۆو خدایہِ سٕندِس حضورس سٍتـ̡ {ہُراونہٕ}۔ \n9. اے خدایہ، ژے سوز واریاہ روٗد، ییمہ سٍتـ̡ ژے پنُن وراثت پٲٹھـ̡ پۯاوُن۔ {سوزُن: ہیب۔ کٔرِو} {تصدیق کٔرِو: حب۔ تصدیق کٔرِو}\n10. تُہٕنزِ جماعت چھے اَتھ مَنٛز روزمٕژ: اے خدایہ، چُھہ غریبن ہٕندِ خٲطرٕ پنٕنۍ نیکی تیار کٔرمٕژ۔ \n11. خداوند دِیُت لفظ: عظیم {اوس} تِمن ہٕنز صحبت یِمو {it} شایع کٔرۍ۔ {کمپنی: Heb. فوج}\n12.\\tفوجن ہٕندِس بادشاہس ژٔلِتھ ژٔلِتھ تہٕ یُس گَرِ منز روزان اوس، تٔمۍ کٔر غُنیمت بٲگراونہٕ۔ {کیا...: ہیب۔ ژٔلِتھ}\n13.\\tیێلہِ تہِ چھِو بانہٕ سٍتـ̡ رۄپہٕ سٍتـ̡ ؤلِتھ کۅتر سٕندِ پکھہٕ تہٕ تٔمۍ سٕندِس پکھہٕ سٍتـ̡ رۄپہٕ سٍتـ̡ بٔنِتھ تہٕ تٔمۍ سٕندِس پکھہٕ سٍتـ̡ رۄپہٕ سٍتـ̡ سٍتـ̡ پکھہٕ سٍ \n14.\\tییلہ خداین بادشاہ اتھ منز پھیُرِتھ کٔرۍ، سُہ اوس سالمنس منز شینہٕ ہیوٗ سفید۔ {اتھ منز...: یا، أمِس خٲطرٕ، سُہ}\n15.\\tخدایہ سُند پہاڑ {چُھ} بشنُک بال۔ اَکھ تھوٚد بال۔ \n16. اے تھدِ بالہٕ کیازِ چھُکھ وۄٹھ دِوان؟ {یہِ} چُھہ سُہ بالہٕ {یُس} یُس خدا روزُن چُھ یژھان۔ آ، خداوند روزِ اَتھ مَنٛز ہمیشہٕ خٲطرٕ۔ \n17.\\tخدایہ سٕندِ رَتھٕ چھِ وُہ ساس، {حتیٰ کہ} ساسہٕ بٔدۍ فرشتہٕ: خداوند {چُھ} یِمن مَنٛز {یِتھ} سیناہس مَنٛز، مُقدس {مقام} مَنٛز۔ {حتیٰ کہ...: یا واریاہ ساس}\n18.\\tژے ووت تھزرس پیٹھ، تہٕ چُھکھ قٲد کٔرِتھ تہٕ ژے ہٕندِ خٲطرٕ تحفہٕ حٲصل کٔرۍمٕتۍ۔ آ، {یێلہِ} باغین خٲطرٕ، یُتھ خداوند خدا روزِ {تِمن منز}۔ {انسانن خٲطرٕ: ہیب۔ انسانس منز}\n19.\\tبابرکت {بنہِ} خدا، {یُس} چُھہ اسہِ دۅہہٕ {فٲیدٕ دِنہٕ سٍتـ̡ دِوان، حتیٰ کہِ سانہِ نجات ہُند خدا} تہِ۔ سیلہ۔ \n20. {یُس سُہ چُھ} سُہ خدا {چُھ} نجات ہُند خدا۔ تہٕ خدایہِ سُند خدا {چُھ} موتُک مسلہٕ۔ \n21.\\tمگر خدایہ کرِ پننین دُشمنن ہُند کلہ زخم تہٕ یُس وُنہِ تہِ پننِس گناہ سٍتـ̡ روزِ۔ \n22.\\tخداوند ووٚن بہٕ اَنہٕ بَشَن پؠٹھٕ دُبارٕ اَننہٕ، بہٕ اَننہٕ سمندرٕ کِس سرٛنیٚرِ منزٕ دُبارٕ اَننہٕ: \n23.\\tیُتھ زِ تُہند کھۄر گژھہِ {چانہِ} دُشمن ہٕندِس خونس مَنٛز، {تہٕ} تہٕ تُہٕندِس ہونین ہٕنز زبان یِتھۍ سٍتـ̡ ڈباونہٕ۔ {ڈُباونہٕ: یا، وۄزل}\n24. اے خدایہ، تِمو چُھ تُہند وُچھمُت وُچھمُت، اے خدایہ۔ {حتی} چُھہ میانہِ خدایہ، میانہِ بادشاہ سٕندِس حرمس مَنٛز وُچھمُت۔ \n25.\\tگیون وٲلۍ گٔیہِ برونہہ کُن، سازن پیٹھ کھلٲڑۍ {پتہٕ} پتہٕ۔ ﴿تِمن منز﴾ تہٕ لٔگِتھ گِندنہٕ واجنہِ لڑکہِ ہٕندِس سٍتۍ گِندان۔ \n26.\\tخدایہ کٔرِو اِسرٲیلِکِس چشمہٕ سٍتـ̡ خدایہِ سٕندِس اجتماعس مَنٛز برکت دِنـ̡ {حتیٰ کہ}۔ {پیٹھ...: یا، یُس اسرٲیلِکِس چشمہٕ سٍتـ̡ چُھ}\n27.\\tیِمن ہٕندِس حکمرانس سٍتـ̡ {چُھ} لۄکُٹ بنیامین {سٍت}، یہوداہ کِس شہزادس {تہٕ} تِہٕندِس مجلسس سٍتـ̡، زبولونٕکۍ شہزادٕ، {تہٕ} نفتالی ہٕندِس شہزادس سٍتـ̡ چُھہ {تہٕ تِہٕندِس﴾ سٍتـ̡ {تہٕ﴾ تِہٕندِس حُکُمرس سٍتـ̡ {تہٕ ﴿ تِہٕندِس بادشاہس سٍتـ̡ {تہٕ تِہٕندِس سٍتـ̡ چُھہ یِمن ہ\n28. چانہِ خداین چُھ چانہِ طاقتُک حُکُم دِژمُت: اے خدایہ، یُس ژے اسہِ خٲطرٕ کورمُت چُھ، سُہ کرُن مضبوط۔ \n29. یروشلمس مَنٛز چُھہ تُہٕندِس مندرس سٍتـ̡ بادشاہ اَنـ̡ تۅہہِ نِش تحفہٕ۔ \n30.\\tنیزٕ بردارن ہٕنزِ صحبت، بیلن ہٕندِس بٔڑِس سٍتۍ، لُکن ہٕندِس بَچھرٕ سٍتـ̡ ملامت کٔرِو، {یوتام نہٕ پرٮ۪تھ کانہہ رۄپہٕ رۅپہٕ سٍتـ̡ پانس تابع کرِ: تِم لُکھ پھٔرِو یِم جنگس منز خۅش گٔژھِتھ چھِ۔ {صحبت...: یا، نِش کٔرِن درندٕ} {بکھرِن...: یا، سُہ چھُ بکھرِتھ}\n31. شہزادٕ یِن مصرہٕ منزٕ نیبر۔ ایتھوپیا کرِ جلدٕے خدایس کُن اتھہٕ پھٔہلاونہٕ۔ \n32. اے زمینہِ ہٕندِس بادشاہتَس سٍتـ̡ گیو خدایہِ سٕندِ خٲطرٕ۔ اے خدایہِ سٕندِ حمد گٮ۪وُن؛ سلہٕ: \n33.\\tیُس آسمانن ہٕندِس آسمانس پیٹھ سوار چُھ، {یُس پرانہِ زمانہٕ اوس}۔ یُس پَنُن آواز سوزان چُھ، {تہٕ یہ} اکھ زبردست آواز۔ {سوزُن...: ہیب۔ دِیو}\n34.\\tخدایس سٍتـ̡ کٔرِو طاقت: تٔمۍ سٕنز عظمت {چُھ} اسرٲیلِس پیٹھ، تہٕ تٔمۍ سٕنز طاقت {چُھ} اوٚبرن مَنٛز۔ {اوبر: یا، آسمان}\n35. اے خدا، {توہ} چُھہ پنہٕ نِس مقدس مقامو منزٕ خوفناک: اسرٲیلُک خدا {چُھ} سُہ یُس پننِس لوکن طاقت تہٕ طاقت دِوان چُھ۔ بابرکت {خدا}","1.\\t[شوشنیمس پیٹھ چیف موسیقارس سٍتۍ، {اکھ زبور} ڈیوڈ سُند۔] اے خدایہ بچاو۔ تکیازِ آب چھہ میانِس روحس منز اژان۔ \n2.\\tبہٕ چھُس سرٛنِس آبس منز ڈوبُن، ییتہِ نہٕ کانہہ کھڑا چھُس: بہٕ چھُس سرٛنِس آبس منز آمُت، ییتہِ سٔلاب چھُ میہ وسان چھُ۔ {سرٛوٚن گٔرۍ: ہیب۔ سرٛنٮ۪رُک دلد} {سرٛوٚن آب: ہیب۔ آبُک سرٛنٮ۪ر}\n3.\\tبہٕ چُھس پننہِ رونہٕ سٍتـ̡ تنگ گومُت: میون حلق چُھس خشک گومُت: میٲنۍ أچھ چھِ پننِس خدایہِ سُند انتظار کٔرِتھ ناکام گٔمٕژ۔ \n4. یِم مےٚ بغٲر کُنہِ وجہہ سٍتـ̡ نفرت کران چِھ، تِم چِھہ میانہِ کلہٕ سٕندِ مَلہٕ کھۅتہٕ زیادٕ: یِم مے تباہ کَرٕن، {بٔنِتھ} میانہِ دُشمن ہٕندِس دُشمن سٍتـ̡ چِھہ طاقتور: تێلہٕ کٔر مے سُہ {سُہ} بحال یُس نہٕ مے نِش نِیومُت۔ \n5. اے خدایہ، ژے چھکھ میٲنۍ بیوقوفی زانان۔ تہٕ میٲنۍ گۅناہ چھِنہٕ ژے نِش پوشیدٕ۔ {گناہ: عبری۔ قصور}\n6. اے خدایہِ لشکرن ہٕندِس خدایہِ سٍتـ̡ گژھن نہٕ میانہِ خٲطرٕ شرمندٕ گژھُن، اے اسرٲیلُک خدا، یِم تہٕ تُہٕندِ خٲطرٕ ژھاران چھِ، تِم گژھن نہٕ میانہِ خٲطرٕ پریشان گٔژھنـ̡ ۔ \n7. کیازِکہ چانہِ خٲطرٕ چُھس میہ ملامت کٔرمٕژ۔ شرم چُھس میٲنس بُتھس ؤلِتھ۔ \n8. بہٕ چُھس پننین باین ہٕندِ خٲطرٕ اجنبی تہٕ ماجہ ہٕندٮ۪ن شُرین ہٕندِ خٲطرٕ اجنبی بنیومُت۔ \n9. تِکیازِ تُہٕندِس گرٕکہِ جوشَن چُھ مے کھٮ۪ومُت۔ تہٕ یِمو تۅہہِ ملامت کٔرمٕژ چھِ، تِمن ہٕنز ملامت چھے میہ پٲٹھۍ۔ \n10.\\tییلہ میہ رووُن، {تہٕ روزٕ سٍتـ̡ پنُن روح سزا دِژ، سُہ اوس میانہِ ملامت خٲطرٕ۔ \n11.\\tمیہ بنوو بۅٹہ پلو تہِ۔ تہٕ بہٕ بنیوو تِمن ہٕندِ خٲطرٕ اکھ محاورٕ۔ \n12.\\tیُس دروازس منز بِہتھ چھہِ تم چھہِ میہ خلاف کتھ کران۔ تہٕ میہ اوس شرابس ہند نغمہ۔ {شراب: ہیب۔ تیز شراب}\n13. مگر میانہِ خٲطرٕ، میانہِ دُعا چُھہ ژے سٍتـ̡ چُھہ خداوند، یێلہِ چُھہ تُہٕندِس سٍتـ̡ سٍتـ̡ قبول۔ \n14.\\tبہٕ کٔرِو مَلہٕ منزٕ نِش نجات دِنہٕ، تہٕ بہٕ گژھ نہٕ تِمن نِش نجات دِنہٕ یِم مےٚ نفرت کران چھِ، تہٕ سرٛنِس آبہٕ نِش نِش نجات دِنہٕ۔ \n15.\\tآبُک سٔلاب گژھہِ نہ میہ سٍتـ̡ س� \n16.\\tاے خداوند، بوزو میٲنۍ سٍتـ̡ تێلہِ چُھہ چانہِ محبتہٕ سٍتـ̡ خیر چُھہ: پنہٕ نـ̡ نرم رحمتـ̡ مُطٲبق کٔرِو میہ کُن پھیرُن۔ \n17.\\tتہٕ پَنُن بُتھ کٔرِو نہٕ پَنٕنِس خادمَس نِش پوشہٕ۔ تِکیازِ بہٕ چُھس مُشکِلَس مَنٛز: بوزُن جلدی کٔرِو۔ {بوٗزِو...: ہیب۔ مے بوزنہٕ خٲطرٕ کٔرِو جلدی}\n18.\\tمیٲنس روحس نزدیک واتناوُن، {تہٕ} چھُ یہ نجات دِن: میانین دُشمنن ہٕندِ وجہ سٍتـ̡ کٔرِو میہ نجات دِنہٕ۔ \n19.\\tژے چھے میٲنۍ ملامت تہٕ میٲنۍ شرم تہٕ میٲنۍ بے عزتی زانمٕژ: میٲنۍ دُشمن چھِ ژے برونہہ کُن۔ \n20.\\tملامت کٔر میون دِل پھُٹراوُن؛ تہٕ بہٕ چھُس بٔرِتھ بٔرِتھ: تہٕ بہٕ اوسُس کینہہ رحم کھالنہٕ خٲطرٕ ژھانڈان، مگر {اتہِ} اوس نہٕ کانہہ تہِ۔ تہٕ تسلی دِنہٕ خٲطرٕ، مگر میہ لوٚب نہٕ۔ {نِنہٕ خٲطرٕ...: ہیب۔ میہ سٍتۍ ماتم کرنہٕ خٲطرٕ}\n21.\\tیِمو دِژ میہ ماز خٲطرٕ گال تہِ۔ تہٕ میٲنس پیاسس منز دِژ میہ سرکہ چنہٕ خٲطرٕ۔ \n22.\\tتِہُند میز گژھہِ تِمن برونہہ کُن جال بَنُن: تہٕ {یُس یُس {تِہٕندِ} فلاح و بہبودٕ خٲطرٕ آسُن آسُن، {سُہ گژھہِ اکھ جال بنہِ}۔ \n23.\\tتِمن ہٕنزِ أچھ گٔژھِن گٔژھِن، یُتھ نہٕ تِم وُچھن؛ تہٕ یِمن ہٕندِس کمرس گژھہِ لَرٕنـ̡ لَگاونہٕ یِنـ̡ ۔ \n24. تِمن پیٹھ تراوُن پنُن غصہٕ، تہٕ پَنُن غصہٕ دِیُن تِمن پیٹھ رٔٹِتھ۔ \n25.\\tتِہٕندِس بستی گژھہِ ویران آسٕنۍ۔ {تہٕ}تِمن ہٕندِس خٲمَن مَنٛز روزُن نہٕ۔ {تِہُند بَہٲیِش﴾ {تِہُند بَہٲیِش﴾ {ہَب﴾ تِہُند محل} {کُنہِ تہِ...: حَب۔ اَتہِ گژھہِ نہٕ کانہہ بسکیٖن آسُن}\n26.\\tتکیازِ تِم چھِ تِمن سٍتـ̡ یێمِس سٍتـ̡ ژے مارمُت چُھ، تہٕ تِم چھِ تِمن ہٕندِس غمس سٍتـ̡ کتھ کران یِمن ژے ژے زخمی کٔرِمٕژ چھِ۔ {تِم...: ہیب۔ تُہند زخم}\n27.\\tیِمن ہٕنزِ بدکٲری سٍتـ̡ تہٕ یِم گژھن نہٕ تُہنزِ نیکی ہٕندِس سٍتـ̡ شٲمل کرنہٕ۔ {بدکاری کُن...: یا، بدکاریُک سزا، وغیرہ}\n28.\\tیِم گژھن زندٕ سٕنزِ کتابہٕ منزٕ مٹاونہٕ یِن، تہٕ گژھن نہٕ نیکوکارن سٍتـ̡ لیکھنہٕ یُن۔ \n29. مگر بہٕ چُھس غریب تہٕ غمگسار آسان: اے خدایہ، چانہِ نجات دِیُن مے تھزرس پیٹھ۔ \n30.\\tبہٕ کٔرٕ خدایہ سٕندِ ناوٕچ حمد گٮ۪ونہٕ سٍتـ̡ تہٕ کرٕ تس شُکرگزاری سٍتـ̡ بڑاونہٕ۔ \n31.\\t{یہِ} تہِ کرِ خداوند سٕندِ سٍتـ̡ یێمِس سٍتـ̡ \n32.\\tعاجز گژھہِ وُچھن {یہِ، تہٕ} خۅش گژھُن: تہٕ تُہند دِل روزِ زندٕ یُس خدایہ ژھاران چھُ۔ {انکسار: یا، نرم}\n33.\\tیِکیازِ خداوند چُھ غریبن بوزان تہٕ پننین قٲدن سٍتـ̡ حقارت کران چُھہ نہٕ۔ \n34.\\tآسمانس تہٕ زمینہِ ہٕندِس سمندرن تہٕ پریتھ چیزس سٍتـ̡ یُس اتھ منز پکان چُھ، سُہ تعریف۔ {حرکت کٔرِتھ: ہیب۔ ژٔلِتھ}\n35. کیازِ خدا کرِ صیون بچاو، تہٕ یہوداہ ہٕکۍ شہر بناوِ یُتھ تِم روزن تہٕ یِمن ہٕندِس قبضس منز روزن۔ \n36.\\tتٔمۍ سٕندِس خادمَن ہُند بُول تہِ گژھہِ اَتھ وٲرثس منز۔","1. [اہم موسیقارس سٍتـ̡، {اکھ زبور} داؤد سٕندِس یادس مۅکھہٕ۔] {جلدی کرُن} اے خدایہ، میہ نجات دِنہٕ خٲطرٕ۔ اے خداوند، میانہِ مدتھ کرنہٕ خٲطرٕ کرو جلدی ۔ {مدد...: ہیب۔ میانہِ مددٕ خٲطرٕ}\n2.\\tتِم گژھن شرم تہٕ پریشان گژھن یُس میانہِ روحس ژھاران چھُ، تِم گژھن پتھ کُن پھیرُن، تہٕ یِم میانہِ دکھ ہُند خواہش۔ \n3.\\tتِمن گژھن پننہِ شرمندگی ہٕندِ انعامہٕ خٲطرٕ واپس پھیرنہٕ یُن یُس ونان چھِ، آہا، آہا۔ \n4. یُس تۅہہِ ژھاران چُھہ تُہٕندِس سٍتـ̡ خوش گژھن تہٕ خوش گژھُن، تہٕ یُس تُہٕنزِ نجات سٍتـ̡ محبت کران چُھ، تێلہِ گژھہِ خدایہ سٍتـ̡ بٔرِتھ روزُن۔ \n5. مگر بہٕ چُھس غریب تہٕ محتاج: اے خدایہ، ژٕ چُھکھ میٲنۍ مدد تہٕ نجات دِنہٕ وول تہٕ میٲنۍ نجات دِنہٕ وٲلۍ۔ اے خداوند، کُنہِ تہِ رُکُن نہٕ۔","1. اے خداوند، بہٕ چُھس پانس پیٹھ بھروسہ کرُن: بہٕ گژھ نہٕ زانہہ تہِ پریشٲنی ہُند شکار۔ \n2. پَنٕنـ̡ نیکی سٍتـ̡ کٔرِو مے نجات تہٕ بہٕ بچاونٕچ کوشش کرٕنـ̡ ۔ \n3.\\tژٕ بٔنِتھ میانہِ مضبوٗط بَسٲیِن، یَتھ مَنٛز بہٕ لگاتار روزِتھ: ژے چھُکھ میہ بچاونُک حُکُم دِژمُت۔ تِکیازِ ژے چھُکھ میٲنۍ کَنہِ تہٕ میٲنۍ قعلہٕ۔ {بٔنِو...: حَب۔ ژٕ بٔنِو میانہِ سٍتـ̡ بستی ہٕندِس کَنہِ خٲطرٕ}\n4. اے میانہِ خدایہ، بدکارن ہٕندِ اتھہٕ نِش، بدکار تہٕ ظالم انسان سٕندِ اتھہٕ نِش نجات دِنہٕ۔ \n5.\\tاے خدایہِ سٍتـ̡ چُھہ میٲنۍ وۅمید تہٕ چُھہ میانہِ جوانی پیٹھٕ میٲنۍ بھروسہٕ۔ \n6.\\tژے سٍتـ̡ چُھس بہٕ کٔرِتھ کٔرِتھ: ژے چھُس سُے یُس میانہِ ماجہ ہٕندِس أندرٕ منزٕ کڈمُت چھُس: میٲنۍ تعریفہٕ روزِ ژے سٍتـ̡ مُسلسل۔ \n7. بہٕ چُھس واریاہن ہٕندِ خٲطرٕ عجائب ہُند پٲٹھۍ۔ مگر ژٕ چُھکھ میٲنۍ مضبوٗط پناہ گاہ۔ \n8.\\tمیانہِ ٲسِس سٲرۍسٕے دۅہس چانہِ تعریفس سٍتۍ بٔرِتھ تہٕ چانہِ عزتہٕ سٍتـ̡ بٔرِتھ۔ \n9. بُزرگ سٕندِس زمانس منز کٔرِو نہٕ مے تراوُن۔ ییلہِ میون طاقت کمزور گژھہِ تہٕ مہ تراوُن نہٕ۔ \n10.\\tمیانہِ دُشمن چھِ میانہِ خلاف کتھ کران۔ تہٕ یِم میانہِ روحُک انتظار کران چھِ، تِم چھِ اِکہٕ وٹہٕ مشورٕ دِوان، {لے...: ہیب۔ وُچھِو، یا وُچھِو}\n11.\\tیہ ونِتھ زِ خداین چُھ أمِس ترٲومُت: ستاو تہٕ نِش نِن؛ کیازِکہِ {أمِس} چُھہ نہٕ کانہہ تہِ نجات دِنہٕ خٲطرٕ۔ \n12. اے خدایہ میانہِ نِش دور گژھ نہٕ: اے خدایا، میانہِ مددٕ خٲطرٕ کٔر جلدی۔ \n13.\\tتِم گژھن مغالطہٕ تہٕ کھٮ۪نہٕ یِن یِم میانہِ روحُک دُشمن چھِ۔ تِم گژھن ملامت تہٕ بے عزتی سٍتۍ پوشِتھ یُس میانہِ دُکھ ژھاران چھُ۔ \n14. مگر بہٕ روزٕ مسلسل وۅمید تہٕ توتہِ کرٕ چانہِ زیادٕ کھوتہٕ زیادٕ تعریف۔ \n15. میٲنۍ ٲس چانۍ نیکی تہٕ سٲرۍسٕے دۅہس منز چانۍ نجات ظٲہر کٔرِتھ۔ کیازِ بہٕ چُھس نہٕ تِمن ہٕندِس تعدادس پتاہ۔ \n16. بہٕ گژھہٕ خداوند خدا سٕندِ طاقتہٕ سٍتـ̡ تہٕ بہٕ کَرٕ چانہِ نیکی ہُند ذِکر۔ \n17.\\tاے خدایہ، ژے چھے میہ جوانی پیٹھے ہیچھناومٕژ: تہٕ وُنیُک تام چھُس میہ چانہِ حیرت انگیز کامہِ ہُند اعلان کورمُت۔ \n18.\\tوۅنۍ تہِ ییلہ بہٕ بُزرگ تہٕ سرسبز آسہِ، اے خدایہ، مہ تراوُن نہٕ۔ یوتام نہ میہ تُہند طاقت {یَتھ} نسلس تام ہٲوِ، {تہٕ} تُہند طاقت یِنہٕ وٲلِس {یِنہٕ وٲلِس} سٍتـ̡ ۔ {ییلہ...: ہیب۔ بُزرگ تہٕ سرمئی مس تام} {تُہند طاقت: ہیب۔ تُہند نٔر}\n19. اے خدایہ، تہنز نیکی تہِ چھیہ واریاہ تھد، یمۍ عظیم کٲم کٔرمٕژ چھِ: اے خدا، یُس ژے ہیو چھُ! \n20.\\tژے، یمۍ میہ بٔڈ تہٕ تکلیف دِژمٕژ چھِ، تہٕ کرٕ میہ دُبارٕ زندٕ، تہٕ کرٕ میہ زمینہٕ کِس گہرایی منزٕ دُبارٕ تُلنہٕ۔ \n21. ژٕ کٔرِکھ میٲنۍ عظمت، تہٕ کٔرِکھ مےٚ پرٮ۪تھ طرفہٕ تسلی دِنہٕ۔ \n22.\\tبہٕ تہِ کٔرٕ تۅہہِ سٍتـ̡ تسٕندِ سٍتـ̡ تعریف، اے خدایہ، اے خدایہ، ژے سٍتـ̡ گیوُن، اے اسرٲیلـ̡ پاک۔ {زبور: عبرانی۔ زبورُک ساز}\n23.\\tییلہ بہٕ ژے گیوُن چُھس میٲنۍ وُٹھ سٮ۪ٹھاہ خۅش سپدان۔ تہٕ میون روح، یُس ژے نجات دِژمُت چھُ۔ \n24. میٲنۍ زبان تہِ روزِ سٲرۍسٕے دۅہس چانہِ نیکی ہٕنز کتھ کرنہٕ، تکیازِ تِم چھِ پریشان گٔمٕتۍ، تِکیازِ تِم چھِ شرمندہ کرنہٕ آمٕتۍ، یِم میانہِ تکلیف ژھاران چھِ۔","1. [{اکھ زبور} سُلیمان سٕندِ خٲطرٕ۔] اے خدایہ، بادشاہس دِیُن پنُن فٲصلہٕ تہٕ بادشاہ سٕندِس نیچوِس سٍتـ̡ دِیُن پنُن حق۔ {for: or, of}\n2. سُہ کرِ تُہٕندِس لُکن سٍتـ̡ نیکی سٍتـ̡ تہٕ تُہٕندِس غریبن ہُند فٲصلہٕ دِنہٕ۔ \n3.\\tپہاڑ کٔرِن لوکن تہٕ لۅکٹٮ۪ن بالن ہٕندِس نیکی سٍتـ̡ امن حٲصل۔ \n4.\\tسُہ کرِ لوکن ہٕندِس غریبن ہُند فیصلہٕ، سُہ کرِ ضرورتمندن ہٕندِس شُرِس بچاوُن، تہٕ ظٲلم کرِ ٹُکرٕ ٹُکرٕ کرُن۔ \n5. تِم روزِ تۅہہِ کھوژان یوتام آفتاب تہٕ زون سارِنٕے نسلن منز روزِ۔ \n6.\\tسُہ گژھہِ ژٹنہٕ آمتس گاسہِ پیٹھ روٗد ہٕندۍ پٲٹھۍ، یُس زمینس آبہٕ دِوان چھُ۔ \n7. تٔمۍ سٕندِس دۅہس مَنٛز روزِ نیکوکار پھۅلان۔ تہٕ یوتام زوٗن روزِ روزِ۔ {یوت تام زوٗنہِ...: ہیب۔ یوتام نہٕ زوٗن آسہِ}\n8. سمندرٕ پیٹھہ سمندرس تام تہٕ دریاو پیٹھہ زمینہِ ہندس اندس تام تہِ آسہِ تس سلطنت۔ \n9. یِم بیابانن منز روزان چھِ، تِم گژھن أمِس برونہہ کُن نمن۔ تہٕ تٔمۍ سٕندِس دُشمن ہٕندِس دُشمن ہٕندِس گردس ژٹنہٕ۔ \n10.\\tترشِش تہٕ جزیرٕکۍ بادشاہ أنِن تحفہٕ: شیبا تہٕ سیبا ہٕندِ بادشاہ دِن تحفہٕ۔ \n11. آ، سارِنٕے بادشاہ گژھن أمِس برونہہ کُن پٮ۪وان: سارِنٕے قومہٕ گژھن تٔمِس سٕنزِ خدمت۔ \n12. یێلہِ سُہ چُھہ مُشکِلَن دِنہٕ وِزِ نجات دِنہٕ یێلہِ سُہ چُھہ دِنہٕ یێلہِ سُہ چُھہ دِنہٕ آمُت۔ غریب، تہٕ سُہ تہِ یُس نہٕ کانہہ مددگار آسہِ۔ \n13. سُہ کرِ غریبن تہٕ ضرورتمندن بچاوٕن، تہٕ ضرورتمندن ہٕنز روح بچاو۔ \n14. سُہ کرِ تِہُند روح دھوکہ دہی تہٕ تشددٕ نِش نجات دِنہٕ۔ تہٕ تِہُند خوُن آسہِ تٔمِس نظرس مَنٛز قیمتی ۔ \n15. تہٕ سُہ گژھہِ زندٕ، تہٕ أمِس یِیہِ شیبا سٕندِ سۄنہٕ سٍتـ̡ دِنہٕ۔ تٔمِس خٲطرٕ تہِ یِیہِ دُعا کرنہٕ۔ {تہٕ} روزِ أمِس تعریف۔ {دِنہٕ یِن: حَب۔ اَکھ دِیُن}\n16.\\tبالن ہٕندِس تھزرس پیٹھ آسہِ زمینہِ مَنٛز مَکٲے ہُند اکھ موٚٹھ۔ اَمہ ہُند پھل گژھہِ لبنان ہٕندۍ پٲٹھۍ، تہٕ شہرٕکۍ پٲٹھۍ، زمینہٕ کِس گاسہٕ ہٕندۍ پٲٹھۍ۔ \n17. تٔمۍ سُند ناو روزِ ہمیشہٕ خٲطرٕ: تٔمۍ سُند ناو روزِ آفتابس تام روزُن: تہٕ {انسان} روزِ أمِس مَنٛز برکت: سارِنٕے قومہٕ گژھن أمِس بابرکت وَنان۔ {برداشت: ہیب۔ بے} {تٔمۍ سُند ناو آسہِ...: ہیب۔ یُس نیچو آسہِ پننِس مٲلہِ سُند ناو ہمیشہٕ خٲطرٕ جٲری روزُن}\n18.\\tخداوند خدا، اسرٲیلُک خدا، یُس صرف حیرت انگیز کٲم کران چُھ۔ \n19. تہٕ تٔمۍ سُند شاندار ناو گژھہِ ہمیشہٕ خٲطرٕ بابرکت تہٕ سٲرۍسٕے زمینہٕ گژھہِ تٔمۍ سٕندِس جلال سٍتـ̡ بٔرِتھ۔ آمین، تہٕ آمین۔ \n20. یسی سٕندِس نیچوِس داؤد سٕنز دُعا گٔیہِ ختم۔","1. [زبور عصاف۔] پٔزۍ پٲٹھـ̡ چُھہ خدا اسرٲیلس سٍتـ̡ خیر تہٕ یێلہِ تہِ چُھہ پاک دِل آسنس سٍتـ̡ ۔ {of: or, for} {پٔزۍ پٲٹھۍ: یا، توتہِ} {of...: Heb. دِل سٍتـ̡ پاک}\n2.\\tمگر میانہِ کھۅر ٲسۍ لگ بھگ ژٔلۍمٕتۍ۔ میون قدم اوس وارہ وارہ پٲٹھۍ۔ \n3.\\tکیازِ میہ اوس بیوقوفن پیٹھ حسد کران، {ییلہ میہ بدکارن ہنز خوشحالی وچھ۔ \n4.\\tتکیازِ {تِہندِس مرنس منز} چھُنہٕ کانہہ بند: مگر تِہُند طاقت {چُھ} مضبوٗط۔ {فرم: ہیب۔ چربی}\n5. تِم {چِھ} چِھنہٕ باقٕے نفرن ہٕندۍ پٲٹھـ̡ مصیبتس مَنٛز۔ نۂ چِھ تِم {باقٕے} مردن ہٕندۍ پٲٹھـ̡ مُتٲثِر گٔژھان۔ {منز...: Heb. باقین مردن ہٕندِس مصیبتس منز} {یِتھٕ پٲٹھۍ: Heb. with}\n6. تَمہِ مۄکھٕ چُھ تِمن ہٕندِس زنجیرس سٍتـ̡ گٔژھِتھ ۔ تِمن ہٕندِس پٲٹھـ̡ چُھہ تِمن سٍتـ̡ پٲٹھـ̡ لٔگـ̡ ۔ \n7.\\tتِمن ہٕنزِ أچھ چھِ موٹۍ سٍتۍ نیران: تِمن چھُ دِل سٍتۍ زیادٕ آسان۔ {ہاو...: ہیب۔ دِلُک خیال پاس کٔرِو}\n8.\\tتِم چھِ بدکار تہٕ ظلمس مُتلِق بدکار کتھ کران: تِم چھِ تھدِ پٲٹھۍ۔ \n9.\\tتِمو چُھ پنُن وات آسمانس کُن تھووُن، تہٕ تِہٕنز زبان چھے زمینس مَنٛز پکان ۔ \n10. تَمہِ کِنۍ چھِ تٔمۍ سٕندِ لُکھ یور واپس یِوان: تہٕ یِمن ہُند آب چُھہ بٔرِتھ دِنہٕ آمُت۔ \n11. تہٕ تِم چھِ ونان زِ خدایہ کِتھہ کٔنۍ چُھ زانان؟ تہٕ کیا اعلیٰ حضرت سٕندِس مَنٛز چھُ علم؟ \n12.\\tوُچھِو یِم بد دین، یِم دُنِیاہَس مَنٛز خوشحال چھِ۔ تِم چھِ دولتس مَنٛز ہُران۔ \n13. پٔزۍ پٲٹھۍ چھُ مے پنُن دِل صاف کورمُت تہٕ معصومیت سٍتۍ چھلنہٕ آمُت۔ \n14.\\tسارِنٕے دۅہس سٍتـ̡ چُھس بہٕ دِنہٕ آمُت، تہٕ پرٮ۪تھ صُبحَس چُھس عذاب دِنہٕ آمُت۔ {عذاب: حب۔ میٲنۍ عذاب}\n15.\\tاگر بہٕ وَنُن، بہٕ کَرٕ یِتھٕ پٲٹھۍ کَتھ کَرٕن؛ وُچھ، بہٕ کَرٕ چانہِ شُرٮ۪ن ہٕندِس نسلس خٕلاف۔ \n16.\\tییلہ میہ یہ زانُن سونچ، یہ {اوس} میانہِ خاطرہ سیٹھا تکلیف دوان۔ {تہِ...: ہیب۔ میانین اچھن منز محنت}\n17.\\tیوتام نہ بہٕ خدایہ سٕندِس مقدس مقامس مَنٛز ووت {پتہٕ} گۆو میہ تِہُند خاتمہٕ۔ \n18.\\tیقینا ژے کٔرِکھ تِم رِکٕنـ̡ جاین تہٕ ژے کٔرِکھ تِم تباہی کُن۔ \n19.\\tتِم کِتھہ کٔنۍ چھِ ویران گٔمٕتۍ، یِتھ کٔنۍ أکِس لمحس منز! تِم چھِ سراسر دہشت ہُند شکار سپدان۔ \n20.\\tخوابکۍ پٲٹھۍ، ییلہ {اکھ} بیدار سپدِ؛ {تو}، اے خداوند، ییلہ ژے بیدار گژھہِ، تہندِ شکلہِ ہنز حقارت۔ \n21.\\tیتھہ پاٹھۍ گۆو میون دل غم، تہ میہ آو پننین لگام منز ژکھ۔ \n22.\\tتیوت بیوقوف اوسس، تہٕ جٲہل: بہٕ اوسُس ژے برونہہ کُن اکھ درندٕ۔ {جٲہل: حب۔ میہ ٲس نہٕ پتاہ {ہیبس برونہہ}۔ سٍت}\n23.\\tبہٕ چُھس ژے سٍتـ̡ مسلسل روزان: ژے چُھس میٲنس دچھنہِ اتھس سٍتـ̡ تھپھ کٔرِتھ۔ \n24.\\tژے کٔرِکھ میہ پننہِ نصیحتہٕ سٍتـ̡ رہنُمٲیی تہٕ پَتہٕ کٔرِکھ میہ جلال حٲصِل۔ \n25. بہٕ کُس چُھس آسمانس مَنٛز {توے ورٲے}؟ تہٕ {یُس} زمینس پیٹھ چُھہ نہٕ کانہہ {یُس} یُس بہٕ چانہٕ سٍتـ̡ یژھان چُھس۔ \n26.\\tمیون ماز تہٕ میون دِل چُھ ناکام سپدان: {مگر} خدا {چُھ} میانہِ دِلٕچ طاقت، تہٕ میون حصہٕ چُھ ہمیشہٕ خٲطرٕ۔ {طاقت: ہیب۔ راک}\n27.\\tیِمن نِش یِم دوٗر چھِ، تِم چھِ ختم گٔمٕتۍ، یِم پانس نِش بدکار سپدان چھِ۔ \n28.\\tمگر میانہِ خاطرہ چُھہ خدایس نزدیک گژھُن اصل: میہ چُھ خداوند خدایس پیٹھ بھروسہٕ کورمُت، یُتھ بہٕ چانہِ سارِنٕے کامہِ ہُند اعلان کرِ۔","1. [آساف سُند مشکیل۔] اے خدایہ، ژے کیازِ چُھکھ ہمیشہٕ خٲطرٕ دِژمُت؟ {کیازِ} چُھہ تُہند غصہٕ پننہِ مرگہٕ ہٕندِس دامنس سٍتـ̡ دِوان؟ {مشکیل...: یا، آساف سٕندِ خٲطرٕ اکھ زبور دِنہٕ خٲطرٕ}\n2. پنٕنۍ جماعت یاد تھاوُن، {یُس} ژے پرانہِ پیٹھٕ ہیوٚتمُت چھُ؛ پننہِ وراثتُک لاٹھ، {یُس} ژے چھُکھ رٔٹمُت؛ یہِ پہاڑ صییون، یَتھ مَنٛز ژے روزان چھُ۔ {لاٹھ: یا، قبیلہٕ}\n3.\\tپَنٕنۍ کھۅر تُلِو دٲیرِ ہٕندِس ویرٲنِس کُن۔ {حتیٰ کہ} سٲری {یُس} دشمنن چھُ مقدس مقامس منز بدکار کورمُت۔ \n4. تُہٕندِس دُشمن چِھ تُہنزن جماعتن منز گُرجہٕ دِوان۔ تِمو چِھ پَنٕنـ̡ نشانہٕ {for} سٍتـ̡ قٲیم کٔرِتھ۔ \n5.\\t{اکھ انسان} اوس مشہوٗر، تکیازِ تٔمۍ اوس گٔنٮ۪ن کُلٮ۪ن پیٹھ کلہٕ تُلان۔ \n6.\\tمگر وۅنۍ چھہِ تِم کۅلہٕ تہٕ ہتھو سٍتۍ اکی ساتہٕ تِمن ہٕنز کھنمژ کٲم پھٹراوان۔ \n7. تِمو چُھ تُہٕندِس مُقدس مَنٛز نار دِژمُت، تِمو چُھکھ تُہٕندِس ناوُک بَسٲیِتھ ناپاک کٔرِمُت۔ {تِمو چُھ تُہٕندِس مُقدس سٍتـ̡ نارس کُن سوزمُت}\n8. تِمو ووٚن پننِس دِلس مَنٛز، أسۍ کرو یِم اِکہٕ وَٹہٕ تباہ کٔرِتھ: تِمو چھِ زمینس مَنٛز خدایہِ سٕندِ سارِنٕے عبادت خانہٕ زٲلِمٕتۍ۔ {تباہ کٔرِو: ہیب۔ بریک}\n9.\\tاسہِ چھہ نہ پننین نشانن وچھان: {چھُنہ} کانہہ پیغمبر تہ نہ چھہ اسہِ منز کانہہ تہِ یس یہ زانان آسہِ زِ کٲژا کال۔ \n10. اے خدایہ، مُخٲلِف کٲتِس کالس دِیہِ ملامت ؟ دُشمن کَرٕ تُہٕندِس ناوَس ہمیشہٕ خٲطرٕ توہین کَرٕن؟ \n11.\\tژیہ کیازِ چھکھ پنُن دچھُن اتھہ تہِ کڈان۔ پننہِ چھۅکہِ منزہ کٔڈِتھ کٔڈِتھ کٔڈِتھ۔ \n12. خدا چُھہ میٲنۍ پرانہِ بادشاہ، یُس زمینہِ مَنٛز نجات دِوان چُھ۔ \n13. ژے کٔر پننہِ طاقتہٕ سٍتۍ سمندرس تقسیم: ژے کٔر آبس منز ڈریگن ہٕندِس کلس پھٔٹِتھ۔ {تقسیم: ہیب۔ پھُٹ} {ڈریگن: یا، وہیل}\n14.\\tژے چھُکھ لیویتھن سٕندِس کلس ٹُکرٕ ٹُکرٕ کٔرِتھ، {تہٕ} دِیُن أمِس بیابانن منز روزن والٮ۪ن لُکن خٲطرٕ ماز دِنہٕ۔ \n15. ژے ژٔٹۍ چشمہ تہٕ سیلاب: ژے کٔر طاقتور دریاو خشک کرنہٕ۔ {طاقت...: ہیب۔ طاقتٕکۍ دریاو}\n16.\\tدۅہ چھہ تۅہہ، رات تہِ چھہ تۅہہ: ژے چھہ گاش تہ آفتاب تیار کورمت۔ \n17.\\tژے کٔر زمینہِ ہٕندِس سارِنٕے سرحدن ہٕندِس سٍتـ̡ تہٕ وندٕ بنوومُت۔ {بنووُن: ہیب۔ بنیوو تِم}\n18.\\tیہ یاد تھاوُن، یُس دشمنن ملامت کورمُت، اے خداوند، تہٕ {یہ} بیوقوف لوکو چُھ تُہند ناو بدنام کورمُت۔ \n19. اے پنہٕ نِس کچھوٕ سُند روح مہ دِیُن بدکارن ہٕندِس بٔڈِس سٍتـ̡ دِنہٕ: پنہٕ نِس غریبن ہٕنزِ جماعت ہمیشہٕ خٲطرٕ مٔشِد گژھ نہٕ۔ \n20.\\tعہد کِس احترامس کٔرِو: تکیازِ زمینہِ ہٕندِس تاریک مقامس چھِ ظلمن ہٕندِس بستہٕ سٍتـ̡ بٔرِتھ۔ \n21. اے مظلوم گژھ نہٕ شرمندہ گژھُن: غریبن تہٕ محتاجن گژھن تُہند ناوٕچ تعریف۔ \n22. اے خدایہ، وۅتھٕ وُچھِو پنُن مقصد: یاد تھاوُن زِ بیوقوف کِتھہ پٲٹھـ̡ چُھ تۅہہِ دۅہہٕ ملامت کران۔ \n23. پَنٕنـ̡ دُشمن ہٕنز آواز مہ مٔشِد گٔژھِتھ: یِمن ہُند ہنگامہ چُھ تۅہہِ سٍتـ̡ ہُران۔ {ہُرٮ۪ر: عبرانی۔ کھسُن}","1. [بٔڈ موسیقار، التاشیت، اکھ زبور {یا} آساف سُند نغمہٕ۔] اے خدایہ، أسۍ چھِ شُکر ادا کران، {تۅہہِ} چھِ أسۍ شُکر ادا کران: کیازِ {یہ} چُھہ تُہند ناو تُہند عجیب، کامہِ ہُند اعلان کرُن۔ {التاشیت: یا، تباہ نہ کرُن} {of: یا، for}\n2. ییلہ بہٕ جماعت وصول کرِ، بہٕ کٔرٕ صحیح فیصلہٕ۔ {وصول کرو...: یا، اکھ مقرر وقت}\n3.\\tزمین تہٕ اَمہ ہٕندِس سارِنٕے بسکیٖن دِنہٕ آمٕتۍ: بہٕ چُھس اَمہ کِس تھَم رٔٹِتھ ۔ سیلاہ۔ \n4. میہ ووٚن بیوقوفن زِ بیوقوفَن تہٕ بدکارن تہٕ بدکارن ہٕندِس سینگ تُلِتھ نہٕ تُلُن: \n5.\\tپَنُن سینگ تُلِو نہٕ تھزرس پیٹھ: کَتھ کٔرِو نہٕ سخٕت گردنہٕ سٍتۍ۔ \n6.\\tترقی خاطرہ {cometh} نہ مشرقس پیٹھ، نہ مغرب پیٹھ، نہ جنوبس پیٹھ۔ {جنوب: ہیب۔ صحرا}\n7.\\tمگر خدا چُھ قاضی: سُہ چُھ اَکھ دِوان تہٕ بییِس بِہناوان چُھ۔ \n8.\\tیِکیازِ خداوند سٕندِس اتھس مَنٛز چُھ اکھ پیالہ تہٕ شراب چُھہ وۄزُل۔ یہِ چُھ رَلاونہٕ سٍتـ̡ بٔرِتھ بٔرِتھ۔ تہٕ سُہ چُھہ اَمہ سٍتـ̡ تراوان: مگر اَمہ سٍتـ̡ چُھہ سارِنٕے بدکار ژٔٹِتھ ژٔلِتھ {تہٕ} چِھہ چُھہِ۔ \n9. مگر بہٕ کرٕ ہمیشہٕ خٲطرٕ اعلان۔ بہٕ گٮ۪وٕ یعقوب سٕندِس خدایہِ سٕندِ تعریف۔ \n10. بدکارن ہٕندِ سارِنٕے سینگ تہِ ژٹنہٕ یِن۔ {مگر} نیکوکارن ہٕندِ سینگ گژھن تھزر۔","1.\\t[نیگینوتس پیٹھ اہم موسیقارس سٍتۍ، زبور {یا} آساف سُند نغمہٕ۔] یہوداہَس مَنٛز چُھ خدا زانان: تٔمۍ سُند ناو {چُھ} اسرٲیلس مَنٛز عظیم۔ {سردار...: یا، نگران} {of: یا، for}\n2. سلیمس مَنٛز تہِ چُھ تٔمۍ سُند خیمہ تہٕ صہیونس مَنٛز تٔمۍ سُند روزنٕچ جاے۔ \n3.\\tتتہِ چھُ سُہ تیر کمان، ڈھال تہٕ تلوار تہٕ جنگہٕ کٔرِتھ۔ سیلاہ۔ \n4. ژٕ چُھکھ شکارٕ کِس پہاڑو کھۅتہٕ زیادٕ شاندار تہٕ بہترین۔ \n5.\\tدِل گٔیہِ خراب گٔمٕتۍ، تِمو چُھہ شوٚنگمُت تہٕ تِمن ہٕندِس اتھہٕ لٔبِتھ آسہٕ نہٕ۔ \n6.\\tاے یعقوب سٕندِس خدایہِ سٕندِس ملامت سٍتـ̡ چُھہ رَتھ تہٕ گُر دۅشوے نِندِتھ دِنہٕ آمٕتـ̡ ۔ \n7. تۅہہِ، {حتیٰ کہ} تہِ، تہٕ کُس ہیکہِ تۅہہِ نظرِ منز کھڑا سپدِتھ ییلہ ژیہ ژیہ ناراض آسہِ۔ \n8. ژے کٔر اسمانس پیٹھ فیصلہٕ بوزنہٕ۔ زمینہِ کھوژ، تہٕ ٲس خاموش ، \n9.\\tییلہ خدایہ ووت فیصلہٕ، زمینہِ ہٕندِس سارِنٕے عاجزن بچاونہٕ مۅکھہٕ۔ سیلاہ۔ \n10. یقینا انسان سُند قہر کرِ تۅہہِ تعریف: باقی قہر تہِ کرِ ژے رُکاونہٕ۔ \n11.\\tعہد کرُن، تہٕ خدایہ سٕندِس خداہس دِیُن، یێمہِ سٍتـ̡ خوفہٕ گژھہِ آسن۔ {أمِس سٍتـ̡ ...: ہیب۔ خوفہٕ کرُن}\n12. سُہ کرِ شہزادن ہُند روح ژٹُن: {سُہ چُھ} زمینہٕ کین بادشاہن خٲطرٕ خوفناک۔","1. [بٔڈۍ موسیقارس کُن، یہدوتونس کُن، آساف سُند زبور۔] میہ کٔر پننہ آوازِ سٍتـ̡ خدایس نِش فریاد تہٕ پننہ آوازِ سٍتـ̡ خدایہِ سٍتـ̡ تہٕ تٔمۍ دِژ میہ کُن۔ {of: or, for}\n2.\\tپننہِ مصیبت ہٕندِس دۅہس منز گۆو میہ خدایہ سٕندِس دۅہہٕ سٍتـ̡ ژٔلِتھ تہٕ رُکُن نہٕ: میانہِ روحس کٔر تسلی دِنہٕ نِش انکار۔ {دَگ: ہیب۔ اَتھ}\n3.\\tمیہ اوس خدایہ یاد، تہٕ پریشان گومُت: میہ کٔر شکایت، تہٕ میون روح گۆو مغلوب ۔ سیلہ۔ \n4.\\tژے چھکھ میانین اچھن بیدار گژھان: بہٕ چُھس تیوٗت پریشان زِ بہٕ چُھس نہٕ کتھ کٔرِتھ۔ \n5.\\tمیہ چھہ پرانہِ زمانہ قدیم زمانہ کین ؤرین پیٹھ غور کوٚرمت۔ \n6.\\tبہٕ چُھس رٲژ پنُن بٲتھ یاد پاونہٕ خٲطرٕ بلاوان: بہٕ چُھس پننِس دلس سٍتۍ کتھ کران: تہٕ میانہِ روحن کٔر محنتی تلاش۔ \n7. کیا خداوند کرِ ہمیشہٕ خٲطرٕ تراوُن؟ تہٕ کیا سُہ روزِ نہٕ وُنہِ تہِ مہربانی؟ \n8.\\tتسُند رحم چھا ہمیشہٕ خٲطرٕ پاک گومُت؟ کیا {تٔمِس} وعدٕ چُھ ہمیشہٕ خٲطرٕ ناکام سپدان؟ {ہمیشہٕ خٲطرٕ: ہیب۔ نسل تہٕ نسلہٕ؟}\n9.\\tخدایہ چھہ مہربانی کرُن مٔشِد گومُت؟ کیا تس چھہ غصس منز پنُن نرم رحم بند کورمُت؟ سیلہ۔ \n10.\\tتہٕ میہ ووٚن، یہ چھیہ میٲنۍ کمزوری {مگر بہٕ یاد روزِ} خداتعالیٰ سٕندِ دچھنہٕ اتھہٕ سٕندِ ؤری۔ \n11. بہٕ کرٕ خداوند سٕنز کٲم یاد: یقینا بہٕ کرٕ تُہند پرانہِ عجائبات یاد۔ \n12. بہٕ کَرٕ چانہِ سارِنٕے کامہِ مُتعلِق تہٕ کَتھ کَرٕ تہٕ چانہِ کامہِ مُتعلِق کَتھ کَرٕنـ̡ ۔ \n13. اے خدایہ، تُہٕنز وَتھ {چُھ} مقدس مقامس منز: کُس چُھ {سانہِ} خدایہ ہیو عظیم خدا؟ \n14.\\tتُہۍ چُھہ سُہ خدا یُس عجایب کران چُھ، تہٕ ژے چُھہ لوکن مَنٛز پنُن طاقتُک اعلان کورمُت۔ \n15.\\tژے کٔر پننہِ نٔرِ سٍتـ̡ یعقوب تہٕ یوسف سٕندِس نیچوِس نِش نجات دِنہٕ۔ سیلاہ۔ \n16.\\tآبن وُچھ ژے اے خدایہ، آبن وُچھ ژے تِم ٲسۍ کھوژان: سرٛنٮ۪ر تہِ گٔیہِ پریشان۔ \n17.\\tاوٚبرن تروو آب: آسمانن کٔر اکھ آواز: تہند تیر تہِ گٔیہِ نیبرِم۔ {ترووُن...: ہیب۔ آبہٕ سٍتۍ آو تراونہٕ}\n18.\\tچانہِ گجگرٕچ آواز ٲس آسمانس منز: بجلی کٔر دنیاہس ہلکہٕ: زمین لٔج تھرتھر تہٕ تھرتھر۔ \n19.\\tتہنز وتھ چھیہ سمندرس منز، تہٕ تہنز وتھ چھیہ عظیم آبس منز، تہٕ تہند قدم چھہ نہ معلوم۔ \n20. توے کٔر موسیٰ تہٕ ہارون سٕندِ اتھہٕ سٍتـ̡ پَنٕنـ̡ پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھ۔","1.\\t[آشفُک مشکیل۔] اے میانہِ لوکو، میانہِ شریعت کٔرِو کٔرِتھ کٔرِتھ۔ {مشکیل...: یا، آسافس خٲطرٕ اکھ زبور دِنہٕ خٲطرٕ}\n2.\\tبہٕ کٔرٕ أکِس تمثیلس منز پنُن بوش کھولُن: بہٕ کٔرٕ پرانہِ کالہٕ سٍتـ̡ کٔرِتھ: \n3.\\tیُس اسہِ بوزمُت تہٕ زانان چھُ، تہٕ سانین مٲلن چھُ اسہِ وَننہٕ آمُت۔ \n4. أسۍ ہٲوِو نہٕ تِمن ہٕندِس بچن نِش ژوٗرِتھ، یِنہٕ وٲلِس نسلس تام خداوند سٕنز حمد تہٕ تٔمۍ سٕنزِ طاقت، تہٕ تٔمۍ سٕنزِ حیرت انگیز کامہِ ہٲوِتھ ۔ \n5. تکیازِ تٔمۍ کٔر یعقوبس مَنٛز اکھ گوٲہی قایم، تہٕ کوٚرُن اسرٲیلِس مَنٛز اکھ قانون مقرر کرنہٕ، یُس تٔمۍ سانین مٲلن ہُند حکم دِیُت زِ تِم گژھن پننین شُرین زاننہٕ۔ \n6.\\tیُتھ زِ یِنہٕ واجنہِ نسلہٕ گژھہِ {تِم} شُرۍ تہِ زانن {یِم} زٮ۪نہٕ یِن؛ {یُس} گژھن وۅتھٕ وُتھٕ تہٕ پننین شُرین ہُند اعلان کرُن: \n7. یُتھ زن تِم خدایس سٍتـ̡ وۅمید کٔرِتھ، تہٕ خدایہِ سٕنزِ کٲم مٔشِد گژھن نہٕ بلکہ تٔمۍ سٕندِس حکمس پیٹھ عمل کٔرِتھ: \n8.\\tتہٕ ہیکہِ نہٕ پننین مٲلن ہٕندۍ پٲٹھۍ، اکھ ضدی تہٕ باغی نسل۔ اکھ نسل {یُس} اوس نہٕ پنُن دِل ٹھیٖک کٔرِتھ، تہٕ یٔمۍ سُند روح اوس نہٕ خدایس سٍتـ̡ رٔٹِتھ تھاوان۔ {یہ...: حب۔ یُس نہٕ تِہُند دِل تیار کٔرِتھ}\n9.\\tافرائیم سٕندِ اولاد، {ہتھیار ہیتھ {تہٕ} کمان ہیتھ گٔیہِ جنگہٕ کِس دۅہس منز واپس۔ {نِنہٕ: حب۔ پھیُرُن}\n10. تِمو کٔر نہٕ خدایہِ سُند عہد پورٕ، تہٕ تٔمۍ سٕندِس شریعتس مُطٲبِق پکنہٕ نِش کوٚرُکھ انکار۔ \n11. تہٕ تٔمۍ سٕنز کٲم تہٕ تٔمۍ سٕندِ عجائبات مٔشِد گٔیہِ۔ \n12.\\tعجیب کتھہ کٔرِتھ کٔر تِمن ہٕندِس مٲلِس سٕندِس نظرس منز، مصر کِس سرزمینس منز، زوآن کِس میدانس منز۔ \n13.\\tتٔمۍ کٔر سمندرٕ تقسیٖم، تہٕ دِژُن تِم نیرُن۔ تہٕ تٔمۍ بنوو آب أکِس ڈھیرس ہٕندِس پٲٹھۍ۔ \n14.\\tدۅہلہِ تہِ اوس سُہ اوٚبرٕ سٍتـ̡ تہٕ سارِوٕے رٲژ نارٕ سٍتـ̡ رٔلِتھ رٔٹان۔ \n15.\\tتٔمۍ کٔر بیابانن مَنٛز کٔنہِ کٔنۍ، تہٕ دِتُن {تِم} بٔڈِ سرٛنٮ۪ر سٍتـ̡ شراب۔ \n16.\\tتٔمۍ أنِن کٔنہِ کٔنہِ منزٕ نالہٕ تہِ، تہٕ دِژُن آب دریاوَن ہٕندۍ پٲٹھۍ۔ \n17.\\tتہٕ تِمو کٔر بیابانس مَنٛز سارِوٕے کھۄتہٕ تھدِس سٍتـ̡ اِشتعال کٔرِتھ أمِس خٕلاف زیادٕ گۅنہٕ۔ \n18.\\tتہٕ تِمو کٔر خدایہ پننِس دِلس مَنٛز ماز منگِتھ لالچ۔ \n19. آ، تِمو کٔر خدایس خلاف کتھ کرنہٕ۔ تِمو ووٚن، کیا خدایہ ہیکہٕ بیابانن مَنٛز میز پیش کٔرِتھ؟ {فرنش: ہیب۔ آرڈر}\n20.\\tوُچھ تٔمۍ کٔنہِ کٔنہِ لوٚگ، آب ووٚتھ تہٕ نالہٕ ووٚتھ ووٚتھ؛ سُہ ہیکہٕ روٹی تہِ دِتھ؟ سُہ ہیکہٕ پننین لوکن خٲطرٕ ماز فراہم کٔرِتھ؟ \n21. تێمہِ کِنۍ بوز خداوند {یہ}، تہٕ گوٚو شرارت: یِتھٕ پٲٹھۍ آو یعقوبس سٍتـ̡ نار دِنہٕ، تہٕ اسرٲیلِس سٍتـ̡ تہِ ووت غصہٕ۔ \n22. کیازِ تِمو اوس نہٕ خدایس پیٹھ یقین تھاوان، تہٕ تٔمۍ سٕنزِ نجات پیٹھ اوس نہٕ بھروسہ: \n23. یێلہِ تٔمۍ اوس ہیرِ پیٹھٕ اوٚبرن ہُند حکم دِژمُت، تہٕ آسمانٕکۍ دروازٕ کھولٕن، \n24.\\tتہٕ اوسُن تِمن کھٮ۪نہٕ خٲطرٕ منا روٗدمُت، تہٕ ٲسٕن تِمن جنتُک مَکُل دِنہٕ آمُت۔ \n25.\\tانسان اوس فرشتن ہُند کھٮ۪ن کھٮ۪وان: تٔمۍ سوزُن پورٕ ماز ۔ {انسان...: یا، پریتھ کانہہ اوس طاقتور سُند روٹی کھٮ۪وان}\n26.\\tتٔمۍ دِژ آسمانس مَنٛز مشرقُک واو تہٕ پننہِ طاقتہٕ سٍتـ̡ أنِن جنوبُک واو۔ {وُپھ دِنہٕ خٲطرٕ: ہیب۔ گژھُن}\n27.\\tتِمن پیٹھ تہِ ووت ماز تہِ گردِ ہٕندۍ پٲٹھۍ، تہٕ سمندرٕچ سیکہِ ہیو پکھہٕ دار جاناوار: {پکھہٕ...: ہیب۔ پکھہٕ ہُند کۅکر}\n28.\\tتہٕ دِژ تِمن ہٕندِس خٲمس منز، تِمن ہٕندِس بستی اندۍ پکھۍ۔ \n29.\\tیێلہِ کٔر تِمو کھٮ۪وان تہٕ پوٗرٕ پٲٹھۍ، تِکیازِ تِمن دِژ تِمن ہٕنزِ خٲہش۔ \n30.\\tتِم ٲسۍ نہٕ پننہِ ہوس نشہِ الگ گٔمٕتۍ۔ مگر ییلہ تِہُند ماز {اوس} وُنہِ تہِ تہندِس ٲسس منز، \n31.\\tخدایہِ سُند قہر آو تِمن پیٹھ تہٕ مٲرِتھ سارِوٕے کھۄتہٕ موٚٹِتھ تہٕ دِتُن اِسرٲیلٕکۍ ژارنہٕ آمٕتۍ {انسان}۔ {سموٹ...: ہیب۔ کُن کُن بَناونہٕ آمُت} {ژٲرِو...: یا، نوجوان}\n32.\\tیِمو سارِنٕے کامہِ خٲطرٕ کٔر تِمو گۅنہہ، تہٕ تٔمۍ سٕندِس عجیب کامہِ پیٹھ یقین اوس نہٕ۔ \n33.\\tتێلہِ گۆو تِہُند دۅہ باطل تہٕ تِہٕندِس ؤری مصیبتس مَنٛز۔ \n34.\\tییلہ تِم مٲرِتھ تِمو أمِس ژھانڈنہٕ تہٕ تِمو گٔیہِ خدایہ سٕندِس سٍتـ̡ سُلہٕ پٲٹھۍ۔ \n35.\\tتہٕ تِمن اوس یاد زِ خدا اوس تِہُند کُنہِ پٲٹھۍ، تہٕ اعلیٰ خدایہ اوس تِہُند نجات دِنہٕ وول۔ \n36.\\tتوتہِ کٔر تِمو أمِس پننہِ چُھنہٕ سٍتـ̡ خوشامد تہٕ تِمو کٔر أمِس پنہٕ نِس زبانہٕ سٍتـ̡ اپُز۔ \n37. تِکیازِ تِہُند دِل اوس نہٕ أمِس سٍتـ̡ صحیح، تہٕ تِم ٲسۍ نہٕ تٔمۍ سٕندِس عہدس سٍتـ̡ مضبوط۔ \n38.\\tمگر سُہ {رحمت} آسنہٕ کِنۍ کٔرٕن تِمن ہٕندِس ظلمس معاف، تہٕ کوٚرُن نہٕ تِمن ہُند شَرارتہٕ ژٔٹِتھ تہٕ کوٚرُن نہٕ پنُن سورُے غصہٕ ژٔٹِتھ ۔ \n39.\\tتکیازِ تس اوس یاد زِ تم ٲسۍ ماز تہِ۔ اکھ واو یُس نیران چُھ، تہٕ یُس نہٕ دُبارٕ یِوان۔ \n40.\\tبیابانس منز کٲژاہ لٹہِ کٔرِکھ تمِس اِشارٕ دِنہٕ، {تہٕ} صحراوس مَنٛز غم! {وُچھُن: یا، بغاوت کٔرِو}\n41.\\tآ، تِمو پھیُر تہٕ خدایہ کٔرِکھ آزماونہٕ تہٕ کٔرٕن اسرٲیلُک پاک شخص۔ \n42.\\tتِمن اوس نہٕ تٔمۍ سُند اَتھٕ یاد، {تہٕ نہ} سُہ دۅہہ ییلہ تٔمۍ تِم دُشمن نِش نجات دِژ۔ {منز...: یا، مصیبت نِش}\n43.\\tکِتھہ پٲٹھـ̡ اوس تٔمۍ مصرس مَنٛز پنٕنۍ نشانہٕ تہٕ زوان کِس میدانس مَنٛز تٔمۍ سٕندِ عجائبات کٔرۍمٕتۍ: {wrought: Heb. Set}\n44.\\tتہٕ تِہٕندِس دریاوَس مَنٛز بَنوومُت۔ تہٕ تِہُند سٔہلاب، یُس نہٕ تِم چِنہٕ ہیوٚک نہٕ۔ \n45.\\tتٔمۍ سوٗزۍ تِمن منز مختلف قٕسمٕچ مَژٕ، یِمو تِم کھٮ۪وان ٲسۍ۔ تہٕ نِلہٕ مۄنٛڑٕج یِمو تِم تباہ کٔرۍ۔ \n46. تٔمۍ دِژ تِمن ہُند ہُریر تہٕ تِہنز محنت تہِ دِژ ٹِڈیس تام۔ \n47.\\tتِمن ہٕندِس کُلِس ژٔٹِتھ تہٕ تِہٕندِس کُلِس کُلِس تُلِتھ تباہ۔ {تباہ کٔرِتھ: ہیب۔ مارُن} {ٹھنڈ: یا، بٔڈۍ ڈولہٕ}\n48.\\tتِمن ہٕندِس چارو تہِ دِژُن تہٕ تِہُند گُرٕ تہٕ تِمن ہٕندِس گُرٕس دِنہٕ آمُت۔ {دِیُت...: ہیب۔ شُٹ کٔرِو} {گرم...: یا، بجلی}\n49.\\tتٔمۍ کٔر تِمن پیٹھ بد فرشتہٕ سوزِتھ پننہِ غصہٕ، غصہٕ تہٕ مصیبت ہٕنز شدت۔ \n50.\\tتٔمۍ کٔر پننہ شرارتچ وتھ۔ تٔمۍ بچٲو نہٕ تِہُند روح مرنہٕ نِش، بلکہ دیتُن تِہٕنز زُو وَباہس نِش۔ {تٔمۍ بنوو...: ہیب۔ تٔمۍ کٔر اکھ وتھ وزن} {زندگی...: یا، درندٕ مُرین}\n51.\\tتہٕ کٔرِن مصرس مَنٛز سارنٕے گۅڈنچہ اولاد مار۔ ہام کِس خیمہ خانس مَنٛز دِیُن {تِہٕندِ} طاقتُک سردار: \n52.\\tمگر بنووُن پننین لوکن ہٕندِ پٲٹھۍ، تہٕ کٔرٕن بیابانن مَنٛز رہبری کٔرِتھ۔ \n53.\\tتہٕ تِمو کٔر تِمن ہٕندِس دُشمن سٍتـ̡ سٍتـ̡ پٲٹھـ̡ پى۪ٹھـ̡ پى۪\n54.\\tتہٕ أنۍ تِم پننہِ مقدس جایہِ کِس اندس پیٹھ، {حتیٰ کہ} اتھ پہاڑس تام، یُس تٔمۍ سٕندِس دچھنہِ اتھہٕ سٍتۍ ہیوٚتمُت اوس۔ \n55.\\tتٔمۍ کٔرِن کافر تہِ تِمن برونہہ کُن تہٕ تِمن ہٕندِس خٲمَس مَنٛز رٔٹِتھ تہٕ کٔرٕن اسرٲیلٕکۍ قبیلہٕ پننین خیمن مَنٛز روزنہٕ۔ \n56.\\tتوتہِ کٔر تِمو اعلیٰ خدایہ سٕندِس فتنہ تہٕ اشتعال دِنہٕ، تہٕ تٔمۍ سٕنزِ گوٲہی تھووُکھ نہٕ۔ \n57.\\tمگر پتھ کُن پھیُر تہٕ پننین مٲلن ہٕندۍ پٲٹھۍبےٚ وفاداری سٍتـ̡ دِنہٕ آمُت۔ \n58.\\tتکیازِ تِمو کٔر أمِس پننیو تھزرس سٍتۍ شرارت ہُند شکار، تہٕ کٔرٕکھ سُہ پننہ کھٔنِتھ بُتلہٕ سٍتۍ حسد کرنہٕ۔ \n59.\\tییلہ خداین یہ بوز، سُہ گوٚو شرارت تہٕ کورُن اسرٲیلِس سٍتـ̡ سٮ۪ٹھاہ نفرت: \n60.\\tیُتھ تٔمۍ ترٲو شیلوہُک خیمہ {یُس} یُس تٔمۍ انسانن درمیان تھوو۔ \n61.\\tتہٕ دِژن پنُن طاقت قٲد تہٕ پنُن جلال دُشمن ہٕندِس اتھس منز۔ \n62. تٔمۍ دِژ پنٕنۍ قوم تہِ تلوارس حوالہٕ۔ تہٕ گوٚو پننہِ وراثتس پیٹھ شرارت۔ \n63.\\tنارن دِژ تِہٕندِس جوان نِش زٲلِتھ۔ تہٕ تِہٕنزِ کُنہِ کٔرِتھ آیہ نہٕ خانٛدر کرنہٕ۔ {دِنہٕ...: ہیب۔ تعریف}\n64.\\tتِہٕندِ پادٕرۍ گٔیہِ تلوار سٍتـ̡ تہٕ تِہٕنزِ بیواہ کٔر نہٕ کانہہ ماتم ۔ \n65.\\tتێلہِ گۆو خداوند نندر منزہ نیرِتھ بیدار، {تہٕ} أکِس طاقتور انسان سٕندۍ پٲٹھۍ، یُس شرابہٕ سٍتـ̡ کرٛٮ۪کھ دِوان چُھ۔ \n66.\\tتہٕ تٔمۍ دِژ پنہٕ نِس دُشمن ہٕندِس پٔتمِس حصس منز، تٔمۍ دِژ تِمن ہمیشہٕ ملامت کرنہٕ۔ \n67.\\tامہِ علاوٕ کوٚر تٔمۍ یوسف سٕندِس خیمہ نِش انکار، تہٕ کوٚرُن نہٕ افرائیم سٕندِس قبیلس منز انتخاب۔ \n68.\\tمگر ژٲر یہوداہ قبیلہٕ، کوہ صیون یُس تس محبت کران اوس۔ \n69.\\tتہٕ تٔمۍ بنوو پنُن مقدس مقام تھدِ {محل} ہٕندۍ پٲٹھۍ، یُس تٔمۍ ہمیشہٕ خٲطرٕ قایم کورمُت چھُ۔ {قٲیم: ہیب۔ قٲیم}\n70.\\tتٔمۍ ژٲر داؤد پنُن خادم تہٕ نِیوُن کۅکرِ منز۔ \n71.\\tیعقوب سٍتـ̡ یعقوب سٍتـ̡ پى۪ٹھ۔ {پٲٹھـ̡ ہیب۔ پَتہٕ}\n72.\\tتہ دِژ تِمن پننہ دِل چہ دیانت مطٲبق کھیوٚن۔ تہٕ دِژن پننیو اتھو ہٕنزِ مہارت سٍتـ̡ تِمن ہٕنز رہنمٲیی۔","1. [زبور آساف۔] اے خدایہ، کافر چُھہ چانہِ وراثتس مَنٛز آمُت۔ تُہند مقدس مندر چُھ تِمو ناپاک کٔرمُت؛ تِمو چُھ یروشلم ڈھیرس پیٹھ تھوومُت۔ {of: یا، for}\n2. تہندٮ۪ن خادمَن ہٕندِس لاشہٕ سٍتـ̡ چُھہ اسمانس کِس جاناوارن ماز دِژمُت، تہٕ تُہٕندِس مُقدسن ہُند ماز دِژُکھ زمینہٕ کِس درندَن خٲطرٕ۔ \n3.\\tتِمن ہُند خون چُھ یروشلمس اندۍ پکھۍ آبہٕ ہٕندۍ پٲٹھۍ۔ تہٕ {تِم} اوس نہٕ دفن کرنہٕ خٲطرٕ کانٛہہ تہِ۔ \n4.\\tأسۍ چھِ پننین ہمساین ہٕندِ خٲطرٕ ملامت بنان، تِمن ہٕندِ خٲطرٕ یِم اسہِ اندۍ پکھۍ چھِ۔ \n5. خداوند، کٲتِس کالس تام چُھہ؟ کیا ژٕ روزٕ ہمیشہٕ خٲطرٕ شرارت؟ چانۍ حسد گژھہٕ نارٕکۍ پٲٹھۍ دزان؟ \n6. پَنُن غصہٕ تراوُن تِمن کافرن پیٹھ یِم نہٕ تۅہہِ زانان آسہِ، تہٕ تِمن سلطنتن پیٹھ یِمو نہٕ تُہُند ناو چُھہ پکارمُت۔ \n7. تکیازِ یِمو چُھ یعقوب کھٮ۪وان تہٕ تٔمۍ سٕنز روزن جاے تباہ کٔرمٕژ۔ \n8.\\tاسہِ خلاف گژھہِ نہ پٔتِم بدکار یاد تھاوُن: چانۍ نرم رحمتہٕ کرٕن اسہِ رُکٲوِتھ جلدٕے رُکٲوِن: کیازِ أسۍ چھِ واریاہ پست کرنہٕ آمٕتۍ۔ {سٲبقہٕ...: یا تِمن ہٕنزِ بدکاری﴾\n9. اے سانہِ نجات ہٕندِس خدایہ، پننہِ ناوٕ کِس جلال خٲطرٕ کٔر اسہِ مدد، تہٕ پننہِ ناوٕ خٲطرٕ کٔر اسہِ نجات تہٕ سانہِ گۅناہ پاک کرُن۔ \n10.\\tکافر کیازِ چُھہ ونان، تہند خدا کتہِ چُھہ؟ سُہ گژھہِ سانہِ نظرِ منز کافرن مَنٛز زاننہٕ یُن، تہندٮ۪ن خادمَن ہُند خونُک انتقام۔ {انتقام: ہیب۔ انتقام}\n11.\\tقٲدِ سُند آہ گژھہِ پانس برونہہ کُن۔ پننہِ طاقتٕچ عظمتٕ مُطٲبق تھاو تِمن رژھراوُن یِم مرنہٕ خٲطرٕ مقرر کرنہٕ آمٕتۍ چھِ۔ {تُہٕن...: ہیب۔ تُہٕنز نٔر} {رژھرٕو...: ہیب۔ موتٕکۍ بچہٕ رژھراونہٕ}\n12.\\tتہٕ سانین ہمساین کٔرِو تِمن ہٕندِس سٍتـ̡ سَتھ گنہٕ تِمن ہٕندِس سٍتـ̡ ملامت کرنہٕ، یێمہِ سٍتـ̡ تِمو تُہٕندِس سٍتـ̡ ملامت کٔرمٕژ۔ \n13. یێلہِ چُھہ أسـ̡ تُہٕندِس لُکھ تہٕ تێہٕندِس مرگہٕ سٍتـ̡ ہمیشہٕ خٲطرٕ شُکر ادا کٔرِتھ، أسـ̡ سارِنٕے نسلن ہٕندِ خٲطرٕ چُھہ تُہٕندِس تعریفس ہاونہٕ۔ {سارِنٕے خٲطرٕ...: ہیب۔ نسلہٕ تہٕ نسلہٕ خٲطرٕ}","1.\\t[شوشانیمدوتھ پیٹھ سردار موسیقارس سٍتۍ، آساف سُند زبور۔] اے اسرٲیلٕکۍ پٔرۍ، یُس یوسفس ریوٕکۍ پٲٹھۍرہاونہٕ آمُت چھُ، کٔرِو کٔرِتھ۔ یُس کروبن منز روزان چُھ، ژے کٔرِو چمک۔ {of: or, for}\n2. اَفریم تہٕ بنیامین تہٕ منسی ہٕندِ دِلہٕ پٲٹھۍ، تہٕ یِن اسہِ بچاو۔ {یِو...: حب۔ نجات دِنہٕ خٲطرٕ آو اسہِ}\n3. اے خدایہ، اسہِ پھیُر دُبارٕ تہٕ پنُن بُتھ روشن کرُن۔ تہٕ أسۍ گژھہِ نجات دِنہٕ۔ \n4. اے خدایہِ لشکرن ہٕندِس خدایہ، ژے کُس کالس روزِ پننہِ لوکن ہٕنزِ دعاہٕ سٍتـ̡ ناراض؟ {be...: Heb. سموک}\n5.\\tتِمن دِیُن اوٚش روٚٹ۔ تہٕ دِیُن تِمن اوٚش دِنہٕ خٲطرٕ۔ \n6.\\tژے چھکھ اسہِ ہمساین سٍتـ̡ کشمکش کران: تہٕ سانۍ دُشمن چھِ پانہٕ وٲنۍ اَسُن۔ \n7. اے لشکرن ہٕندِس خدایہ، اسہِ دُبارٕ پھیُر تہٕ پنُن بُتھ روشن کرُن۔ تہٕ أسۍ گژھہِ نجات دِنہٕ۔ \n8.\\tژے کٔرِو مصرہٕ منزٕ اکھ بیل کٔرِتھ، تہٕ ژے کٔرِتھ کٔرِتھ۔ \n9.\\tژے کٔر اتھ برونہہ کنہِ {کمرہ} تیار، تہٕ کورُن اتھ سرٛوٚن موٗل رٹُن، تہٕ سُہ بٔرِتھ زمین۔ \n10.\\tبالہٕ ٲس اَمہ کِس ژھایہِ سٍتـ̡ ؤلِتھ، تہٕ اَمہ ہٕندِس کُلِس {ٲسٕن} ہٕندِس پٲٹھۍ۔ {نیُک...: ہیب۔ خدایہ سٕندِ دیودار}\n11.\\tتٔمۍ سوٗزۍ پنٕنۍ لنجہِ سمندرس کُن تہٕ پنٕنۍ لنجہِ دریاوس کُن۔ \n12.\\tژے کیازِ پھُٹرٲوۍ تٔمۍ سٕندِس لٔگِس پھُٹراوُن، یُتھ وتہِ وتہِ پکان چھِ، تِم چھِ أمِس تُلِتھ؟ \n13.\\tلٔکرِ منزٕ سور چھُ یہِ ضایع کران، تہٕ کھہُک جنگلی جانور چُھ یہِ کھٮ۪وان۔ \n14. واپس، اے لشکرن ہٕندِس خدایہِ سٍتـ̡ وُچھِو اسمانہٕ پیٹھٕ وُچھُن، تہٕ وُچھِو یَتھ وُچھِنـ̡ ۔ \n15.\\tتہٕ سُہ انگور باغ یُس تۅہہِ دچھنہِ اتھہٕ ووتمُت چھُ، تہٕ سُہ لٔر {یُس} ژے پانس خٲطرٕ مضبوٗط چھُ۔ \n16. {یہ} چُھہ نارٕ سٍتـ̡ زالنہٕ آمُت، {یہٕ چُھ} ژٹنہٕ آمُت: تِم چُھہ تُہٕندِس بُتھِ ہٕندِس ملامت سٍتـ̡ ماران۔ \n17.\\tپَنُن اَتھٕ آسُن پنہٕ نِس دٔچھِنہِ اَتھٕ وٲلِس شخصس پیٹھ، یُس ژے پانس خٲطرٕ مضبوٗط چھُ۔ \n18. یێلہِ پٲٹھـ̡ أسـ̡ ژے نِش واپس گژھُن: أسـ̡ زندٕ کرُن، تہٕ أسـ̡ چُھہ چانہِ ناوٕ پۯاوُن۔ \n19. اے خداوند، لشکرن ہٕندِس خدایہ، پنُن بُتھ کرُن دُبارٕ پھیُر؛ تہٕ أسۍ گژھہِ نجات دِنہٕ۔","1. [گِتِتھس پیٹھ بٔڈۍ موسیقار سٍتـ̡ {اکھ زبور} آسف سٕندِس سٍتـ̡ ۔ خدایہ سٕندِ خٲطرٕ گۆو بَڑِ پٲٹھۍ، یعقوب سٕندِس خداہس سٍتـ̡ کٔرِو خوشی ہُند شور۔ {آسافس﴾ سٍتـ̡ یا آساف سٕندِ خٲطرٕ}\n2.\\tاکھ زبور رٔٹِتھ أنِو زبور تہٕ اَنُن خۅش گُزٲر یُس زبور سٍتـ̡ دِنہٕ آمُت چھُ۔ \n3.\\tسٲنِس مقدس دعوتس پیٹھ مقرر وقتس پیٹھ وُپھو نوِ زوٗنہِ منز۔ \n4.\\tامہِ مۅکھہ اوس اسرٲیلُک اکھ قانون، {تہٕ} یعقوب سٕندِ خدایہ سُند قانون۔ \n5.\\tیہِ کٔر تٔمۍ یوسف سٕندِس مَنٛز اکھ گوٲہی دِنہٕ خٲطرٕ، یێلہِ سُہ مصرٕچ سرزمینہٕ مٔنزۍ درٛاو: {کتہِ} مے بوز اکھ زبان {یُس} یُس نہٕ میہ سمجھ آو۔ {ذریعہٕ: یا، خلاف}\n6.\\tمیہ کٔر تٔمۍ سُند پھیُر بونہٕ نِش: تٔمۍ سٕندِ اتھہٕ گٔیہِ برتن منز۔ {ٲس...: ہیب۔ گزریومُت}\n7.\\tژے کٔر مصیبت مَنٛز بُلاونہٕ تہٕ مے کٔر ژے نجات دِنہٕ۔ میہ دِژ ژے گجگرٕ کِس خفیہ جایہِ منز: مے کٔر ژے مریبہ کِس آبس پیٹھ ثٲبت ۔ سیلہ۔ {مریبہ: یا، جھگڑ}\n8. اے میانہِ قومہٕ بوزو، تہٕ بہٕ کٔرٕ ژے گوٲہی دِنہٕ: اے اسرائیل، اگر ژٕ میانہِ کتھ بوزو۔ \n9. توے مَنٛز گژھِ نہٕ کانہہ عجیب خدا۔ تہٕ نہ کُنہِ اجنبی خدایہ سٕنز عبادت کٔرٕنۍ۔ \n10. بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کہِ سرزمینہٕ منزٕ نیبر کڈُن، پنُن بوش کھولُن، تہٕ بہٕ کرٕ یہِ بٔرِتھ۔ \n11. مگر میانہِ لُکھ بوزِ نہٕ میانہِ آواز۔ تہٕ اسرٲیلِس کٔر نہٕ میہ منزٕ کانہہ تہِ۔ \n12.\\tتہ میہ ترٲو تِمن ہٕندِس دلن ہٕنزِ ہوس پیٹھ: {تہٕ} تِم پٔکِتھ پَنٕنـ̡ پنٕنـ̡ مشورن منز۔ {to...: یا، تِمن ہٕندِس دِلٕچ سختی کُن، یا، تخیل}\n13. اے کاش میانہِ لوکو آسہ میہ بوزمُت، {تہٕ} اسرٲیلِس آسہ میانین وتن پیٹھ پٔکۍمٕتۍ! \n14.\\tمیہ پزِ جلدٕے تِہٕندٮ۪ن دُشمن زیر کٔرِتھ، تہٕ یِمن ہٕندِس مُخٲلفن خلاف پنُن اتھہٕ پھیُرُن۔ \n15.\\tخداوند سٕندِس نفرتس پٲٹھـ̡ پَزِ پان أمِس سٍتـ̡ پیش کرُن: مگر تِہُند وقت گژھہِ ہمیشہٕ خٲطرٕ قایم روزُن۔ {تابع...: یا، دِژ فرضی فرمانبرداری: ہیب۔ اپُز}\n16.\\tتس پزِ تِمن کٕنُک بہتٔریٖن کُنُک تہِ کھٮ۪وان تہٕ کٔنہِ کٔنہِ ماچھ سٍتۍ تہِ گژھہِ میہ ژیہ تسلی دِنہٕ۔ {بہترین...: ہیب۔ کٕنُک چربی}","1. [اَصَف سُند زبور۔] خدا چُھ قادرن ہٕندِس اجتماعس مَنٛز کھڑا ۔ سُہ چُھ دیوتاہن مَنٛز فیصلہ کران۔ {آساف سُند: یا، آساف سٕندِس خٲطرٕ}\n2.\\tژیہ کٲتِس کالس کٔرِو بدکار سٍتـ̡ ناانصافی سٍتـ̡ تہٕ بدکارن ہٕندِس شخصس قبول۔ سیلہ۔ \n3. غریبن تہٕ بے باپ ہُند دفاع کرُن: مُصیبت زدہ تہٕ ضرورتمندَن سٍتۍ کٔرِو اِنصاف۔ {بچاو: ہیب۔ جج}\n4. غریبن تہٕ محتاجن کٔرِو نجات دِنہٕ: بدکارن ہٕندِ اتھہٕ نِش کٔرِو نجات دِنہٕ۔ \n5.\\tتِم چھِنہٕ پتاہ تہٕ نہ چھِ تِم سمجِتھ۔ تِم چھِ انہِ گٹہِ منز پکان: زمینٕچ سارِنٕے بُنیاد چھِ نیبر۔ {نٮ۪بر...: حب۔ منتقل کٔرِتھ}\n6. میہ چُھ ووٚنمُت، تم چِھ خدا۔ تہٕ تم سٲری چِھ اعلیٰ سٕندِ شُرۍ۔ \n7. مگر تم گژھو مردن ہندۍ پاٹھۍ مرُن، تہٕ شہزادن ہندۍ پٲٹھۍ۔ \n8. اے خدایہ، وُچھِو زمینُک فیصلہٕ، تکیازِ توے گژھہِ سارِنٕے قومن ہُند وارث۔","1.\\t[اکھ بٲتھ {یا} زبور آساف۔] اے خدایہ، ژھۅپہ تھاو نہ پانس سٍتـ̡ تہٕ رٔٹِتھ روزُن نہٕ خدایہ۔ {آسافُک: یا، آساف سٕندِس خٲطرٕ}\n2. تِکیازِ تُہٕندِس دُشمن چُھہ ہنگامہٕ کٔرِتھ، تہٕ یِم تۅہہِ سٍتـ̡ نفرت کران چِھ، تُلِکھ کلہٕ۔ \n3. تِمو کٔر تُہٕندِس لُکن خٕلاف چالاکی سان مشورٕ، تہٕ تُہٕندِس پوشیدٕ لوٗکن خلاف مشورٕ کٔرِتھ۔ \n4.\\tتِمو چُھ ووٚنمُت، یێلہِ أسـ̡ تِمن {قومہٕ} آسنہٕ نِش ژٔٹِتھ یُتھ زن اسرٲیلُک ناو گژھہِ نہٕ یادس منز روزُن۔ \n5.\\tتکیازِ تِمو چُھ اَکہِ رضامندی سٍتـ̡ رٔلِتھ مشورٕ کورمُت: تِم چِھہ تۅہہِ خٕلاف رٔلِتھ: {رضامندی: حب۔ دِل}\n6. ادوم تہٕ اسماعیلِین ہٕندِس خیمہ سٍتـ̡ موآب تہٕ ہجرینی ہٕندِس خیمہ سٍتـ̡ ۔ \n7. جبل تہٕ عمون تہٕ امالیک؛ صور کین بسکینن سٍتـ̡ فلسطینی۔ \n8. اسور تہِ چُھ تِمن سٍتـ̡ رٔلِتھ: تِمو چُھہ لوط سٕندِس بُرِس سٍتـ̡ رٔلِتھ ۔ سلہٕ۔ {holpen: Heb. بٔنِتھ چُھہ اَکھ نٔر کٔرِتھ}\n9.\\tتِمن سٍتـ̡ کرُن یِتھٕ پٲٹھـ̡ {to} مِدیانین ہٕندِس پٲٹھۍ۔ ﴿٭ \n10.\\t{یُس} اینڈورس منز ختم سپُد: تِم بنییہِ زمینہِ خٲطرٕ {یِتھ} گُبر۔ \n11.\\tتِہٕندِس رئیسَس بَنٲوِو عٔرِب تہٕ زِیب ہِوؠ پٲٹھۍ: آ، تِہٕندِس سارِنٕے شہزادن ہٕندِس پٲٹھۍ، زِلُمُنا ہٕندِس پٲٹھۍ۔ \n12. کُس ووٚن زِ أسۍ رٔٹِو خدایہ سٕندِ گرٕ پانس نِش نِنہٕ۔ \n13.\\tاے میانہِ خدایہ، تِم بناو چکرِ ہٕندۍ پٲٹھۍ۔ ہوہس برونہہ کُن کُنہِ۔ \n14. یێلہِ نار لٔکرِ دزان چُھ، تہٕ یێلہِ نار پہاڑن نارس سٍتـ̡ دِوان چُھ؛ \n15.\\tیێلہِ کٔرِو تِمن پنہٕ نِس طوفانس سٍتـ̡ ستاونہٕ، تہٕ تِمن کرو پنہٕ نِس طوفانس سٍتـ̡ خوفزدٕ۔ \n16. تِمن ہٕندِس بُتھِس بٔرِتھ یێلہِ تِم تێہُند ناو ژھارِن، اے خدا۔ \n17. تِم گژھن ہمیشہٕ خٲطرٕ پریشان تہٕ پریشان گژھن۔ آ، تِم گژھن شرمندہ کرنہٕ تہٕ فنا گژھن: \n18.\\tیُتھ زِ تۅہہِ یێمہِ سُند ناو {چُھ} یێمہِ سُند ناو {چُھ} یێمہِ سٍتـ̡ سارِنٕے زمینہٕ سٍتـ̡ سارِوٕے کھۄتہٕ تھوٚد چُھ۔","1. [گِتِتھس پیٹھ بٔڈ موسیقار سٕندِس خٲطرٕ، کورہ سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ اکھ زبور۔] اے لشکرن ہٕندِس مالکَس سٍتـ̡ چُھہ تُہند خیمہ کوتاہ خوش گَژھان۔ {نیچوَن ہٕندِ خٲطرٕ: یا نیچوین ہٕندِ}\n2. میون روح چُھہ خدایہ سٕندِ دربارٕ خٲطرٕ تہِ بے ہوش سپدان: میون دِل تہٕ میون ماز چُھ زندٕ خدایہ سٕندِ خٲطرٕ فریاد کران۔ \n3.\\tآ، چُھس اکھ مکانہٕ لوٚبمُت، تہٕ گِلہٕ نِنہٕ خٲطرٕ اکھ گرٕ ، یتہِ سُہ پنٕنۍ بچہٕ تہٕ تُہند قربان گاہ تراوِتھ، اے خداوند، میٲنۍ بادشاہ تہٕ میانہِ خدایہ۔ \n4. تُہٕندِس گَرَس مَنٛز روزَن وٲلِس مُبارکتَس مَنٛز: تِم چھِ وُنہِ تہِ تُہٕندِس تعریفَس مَنٛز دِوان۔ سیلاہ۔ \n5. بابرکت {چُھ} سُہ انسان یٔمۍ سُند طاقت {چُھ} توے مَنٛز؛ یٔمۍ سٕندِس دِلس مَنٛز {تِم} وتہٕ چھِ۔ \n6.\\t{یُس} وادی بکا منزہ نیران چھہ اتھ کۅر بناوان۔ روٗد تہِ چھہ تالابس منز بٔرِتھ۔ {باکا...: یا، شہتوت کُلۍ چھہِ أمس کۅر بناوان، بیترِ} {بٔرِتھ: ہیب۔ کٔرِتھ}\n7. تِم چِھ طاقتہٕ پتہٕ طاقتس تام گژان، {تِمو منزٕ پرٮ۪تھ کُنہِ} چُھ صیہونَس مَنٛز خدایہِ سٕندِ برونہہ کُن ظٲہر سپدان۔ {طاقت...: یا، کمپنی ٹو کمپنی}\n8.\\tاے خدایہِ خدایہ، میٲنۍ دُعا بوزو: اے یعقوب سُند خدا۔ سیلہ۔ \n9. اے خدایہ، سون ڈھال، تہٕ وُچھِو پنُن مسح کرنہٕ آمُت بُتھِس وُچھِو۔ \n10.\\tچانہِ دربارس منز اکہِ دۅہس خٲطرٕ {چُھ} ساس کھۅتہٕ بہتر۔ بہٕ اوسُس بدکار کِس خیمَن مَنٛز روزنہٕ بجایہ پننِس خدایہ سٕندِس گرس مَنٛز دربان روزُن۔ {میہ اوس...: ہیب۔ بہٕ چُھس بِہنہٕ بجایہ دروازس پیٹھ بِہُن}\n11. خداوند سٕندِ خٲطرٕ چُھ آفتاب تہٕ ڈھال: خداوند دِیہِ فضل تہٕ جلال دِنہٕ: سُہ کرِ نہٕ تِمن نِش کانہہ تہِ اصل چیز یُس سیدِ پٲٹھـ̡ پکان چُھ۔ \n12. اے لشکرن ہٕندِس خداوند، بابرکت چُھہ سُہ انسان یُس توے پیٹھ بھروسہ کران چُھ۔","1. [بٔڈۍ موسیقارس سٍتـ̡، کورہ سٕندِس نیچوین ہٕندِ خٲطرٕ اکھ زبور۔] اے خداوند، ژے چُھکھ پننہِ زمینہِ سٍتـ̡ احسان کٔرِتھ: ژے چُھکھ یعقوب سُند قید واپس انمُت۔ {نیچوین ہٕندِ خٲطرٕ: یا، نیچوین ہٕندِس خٲطرٕ} {سازگار: یا، خۅش گٔژھِ}\n2.\\tژے کٔر پننین لوکن ہٕنز بدکاری معاف، تہٕ ژے چھکھ تِہند سورے گۅناہ پردٕ کورمُت۔ سیلہ۔ \n3.\\tژے چھُکھ پنُن سورے غصہ ژٹمُت: ژے چھُکھ پنُن غصہٕ نِش پھیرمُت۔ {پنُن پان...: یا، پنُن غصہٕ گرم گژھنہٕ نِش}\n4. اے سانہِ نجات ہُند خدا، اسہِ بدلاوُن تہٕ اسہِ سٍتـ̡ کٔرِو پنُن غصہٕ ختم۔ \n5. کیا ژٕ روزٕ اسہِ سٍتـ̡ ہمیشہٕ خٲطرٕ ناراض؟ کیا ژٕ کٔرِکھ پنُن غصہٕ سارنٕے نسلن تام؟ \n6. کیا ژٕ کٔرِو نہٕ اسہِ دُبارٕ زندٕ کرنہٕ: یُتھ تُہند قوم گژھن توے سٍتـ̡ شاد گَژھن؟ \n7. اے خداوند، اسہِ ہٲو پنٕنۍ رحمت تہٕ اسہِ دِژ پنٕنۍ نجات ۔ \n8. بہٕ بوزٕ خدایہ کیا کتھ کرِ، تکیازِ سُہ کرِ پننین لوکن تہٕ پننین مقدسن سٍتـ̡ امن کتھ کرنہٕ، مگر تِم گژھن نہٕ دُبارٕ بیوقوفس کُن پھیرٕنـ̡۔ \n9. یقینا تٔمۍ سٕنز نجات چِھ تِمن نزدیک، یُس أمِس کھوژان چُھ، یُتھ زن سانہِ سرزمینس مَنٛز جلال روزِ۔ \n10. رحم تہٕ سچائی چھِ اَکہٕ وَٹہٕ مِلان۔ نیکی تہٕ امن چھِ اکھ أکِس بوسہ دِژمٕژ۔ \n11. سُہ گژھہِ زمینہِ منزٕ نیرُن۔ تہٕ نیکی گژھہِ آسمانہٕ پیٹھٕ نظر۔ \n12. آ، خداوند دِیہِ {یُس اصل چُھ}۔ تہٕ سانہِ زمینہِ دِیہِ أمِس ہُند اضافہٕ۔ \n13. نیکی گژھہِ أمِس برونہہ کُن۔ تہٕ کرِ تٔمۍ سٕندِس قدمن ہٕنزِ وتہِ پیٹھ۔","1. [داؤد سٕنز دُعا] اے خداوند، پَنُن کَن کُن کٔرِو بوزُن: کیازِ بہٕ چُھس غریب، تہٕ محتاج۔ {اَکھ دُعا...: یا، اَکھ دُعا، داؤد سُند زبور آسنہٕ کِنۍ}\n2. میانہِ روح رژھراوُن؛ تکیازِ بہٕ چُھس پاک: اے میانہِ خدایہ، پَنُن بَندٕ بچاو یُس توے پیٹھ بھروسہ کران چُھ۔ {پاک: یا، یُس ژے پسند کران چُھ}\n3. اے خداوند، میانہِ سٍتـ̡ رحم کرُن، کیازِ بہٕ چُھس ژے دۅہہٕ دۅہہٕ فریاد کران۔ {روزانہٕ: یا، سارِوٕے دۅہہ}\n4. پَنٕنـ̡ خادم سٕندِس روحس سٍتـ̡ کٔرِو خۅش: تِکیازِ اے خداوند، بہٕ چُھس پنُن روح تُلان۔ \n5. اے خداوند، چُھہ نیک تہٕ معٲفی دِنہٕ خٲطرٕ تیار۔ تہٕ تِمن سارِنٕے سٍتـ̡ چُھہ رحمتـ̡ سٍتـ̡ سٍتـ̡ یُس توے پکار کران چُھ، تہٕ چُھہ تِمن سارِنٕے سٍتـ̡ رحمتـ̡ سٍ \n6. اے خداوند، میانہِ دعاہٕ کٔرِو بوزُن۔ تہٕ میانہِ دُعا ہٕنزِ آوازِ سٍتـ̡ دِیُن۔ \n7.\\tمیانہِ مصیبت ہٕندِس دۅہہٕ کٔرٕ بہٕ ژے بُلاونہٕ، تکیازِ ژٕ کٔرِکھ میہ جواب۔ \n8.\\tخدایہِ مَنٛز چُھہ نہٕ تۅہہِ ہیوٗ کانہہ تہِ۔ تہٕ چُھہ نہٕ تُہٕندِس کامہِ ہِش کانہہ تہِ کامہِ۔ \n9. اے خداوند، سٲری قومہٕ یِم ژے بنوومٕژ چھِ، تِم گژھن تہٕ تۅہہِ برونہہ کُن عبادت کرنہٕ۔ تہٕ کٔرِن تُہند ناو جلال دِنہٕ۔ \n10. تِکیازِ تُہۍ چُھہ عظیم تہٕ حیرت انگیز کامہِ کٔرِتھ: تُہۍ چُھہ کُنی خدا۔ \n11. اے خداوند، مے ہیچھناوو پنٕنۍ وتھ بہٕ پَکُن چانہِ حقیقتس مَنٛز: پنُن دِل رٔلِتھ رٔلِتھ تہٕ چانہِ ناوٕ سٍتـ̡ خوفہٕ کٔرِتھ۔ \n12. اے خداوند میانہِ خدایہ، بہٕ کَرٕ چانہِ ہٕندِس سٍتـ̡ \n13.\\tبۆڈ چُھہ تُہند رحم تہٕ ژے کٔر میون روح بٔنِس جہنم نِش بچٲومُت۔ {جہنم: یا، قبر}\n14. اے خدایہ، مغرور گٔیہِ میانہِ خلاف بٔڑۍ، تہٕ تشددٕ سٍتـ̡ {انسان} ہٕنزِ مجلسو کٔر میانہِ روح ژھارنہٕ۔ تہٕ چُھکھ نہٕ تِمن برونہہ کُن تھوومُت۔ {تشدد: عبرانی۔ خوفناک}\n15.\\tمگر اے خداوند، چُھہ رحمت، رحمت، صبر تہٕ رحمتہٕ سٍتـ̡ سٍتـ̡ خدا ۔ \n16.\\tاے میہ کُن پھیرُن تہٕ رحم کرُن۔ پَنٕنـ̡ طاقت دِیُن پننِس خادمَس تہٕ بچٲوِکھ پننہِ خادمُک نیچو۔ \n17.\\tمیہ ہٲوِو اَکھ نِشانہٕ۔ یُس میہ نفرت کران چھُ، تِم گژھن وُچھِتھ شرمندٕ: کیازِ، خداوند، ژے کٔر میہ رٔٹِتھ تہٕ دِژ میہ تسلی دِنہٕ۔","1. [زبور {یا} کورہ سٕندِس نیچوین خٲطرٕ نغمہٕ۔] تٔمۍ سٕنز بُنیاد {چُھ} مقدس پہاڑن منز۔ {نیچوین خٲطرٕ: یا، نیچوین ہٕندِ}\n2. خداوند چُھ یعقوب سٕندِ سارِوٕے مکانہٕ کھۅتہٕ زیادٕ صییون کِس دروازس سٍتـ̡ محبت کران۔ \n3. اے خدایہ سُند شہر، چُھہ تۅہہِ مُتلق شاندار کتھ کرنہٕ آمٕژ۔ سیلہ۔ \n4.\\tبہٕ کٔرٕ تِمن سٍتـ̡ راحاب تہٕ بابل ہُند ذِکر، یُس میہ زانان چُھ، وُچھِو فلسطینی تہٕ صور، ایتھوپیاہس سٍتـ̡۔ یہِ {انسان} اوس تتہِ زامُت۔ \n5.\\tتہٕ صییون متعلق ییہ وننہٕ، یہ تہٕ سُہ انسان اوس أمس مَنٛز زامُت: تہٕ سارِوٕے کھۄتہٕ تھوٚد پان کرِ أمِس قایم کرنہٕ۔ \n6. خداوند کرِ گنزراونہٕ یێلہِ سُہ لُکن ہُند ذکر کرِ، {یہ} چُھ یہِ {انسان} تتہِ زامُت۔ سیلہ۔ \n7.\\tتہِ گیون والۍ تہِ چھہِ سازن پیٹھ کھلنہ آمتۍ:میانہِ سٲری چشمہ چھہِ ژے منز۔","1.\\tکورہ کین نیچوین ہندِ خاطرہ اکھ بٲتھ {یا} زبور، مہالتھ لینوتھس پیٹھ اہم موسیقار سٍتۍ، ہیمان عزراہیت سٕندِ مشکیل سٍتۍ۔] اے خدایہ میانہِ نجات ہُند خدا، میہ ووت ژے برونہہ کُن دۅہ {تہٕ} رٲژ ژے برونہہ کُن: {نیچوین ہندِ خاطرہ: یا، نیچوین ہندِ} {مشکیل...: یا، ہیمان عزراہیت سُند زبور، یُس ہیمان عزراہیت سُند زبور دِوان چُھ}\n2. میٲنۍ دُعا گژھہِ پانس برونہہ کُن: میانہِ فریاد کُن کٔرِو پنُن کُن کُن۔ \n3. تکیازِ میون روح چُھ پریشانیو سٍتـ̡ بٔرِتھ: تہٕ میٲنۍ زندگی چھے قبرس نزدیک۔ \n4.\\tبہٕ چُھس تِمن سٍتـ̡ گنزراونہٕ آمُت یُس کھۅنہٕ وُن چُھس: بہٕ چُھس أکِس انسانس سٍتـ̡ {یُس نہٕ کانہہ طاقت} چُھس: \n5.\\tمرن منز آزاد گژھُن، یِتھٕ پٲٹھۍ قبرِ منز مقتول چھِ، یُس نہٕ وُنہٕ یاد چھُ، تہٕ تِم چھِ تُہندِ اتھہٕ نِش ژٹنہٕ آمٕتۍ۔ {منز: یا، بذریعہ}\n6.\\tژے چھُکھ میہ سارِوٕے کھۄتہٕ بٔنِمِس کھۅڈس منز، انہِ گٹہِ منز، سرٛنِس مَنٛز ترٛٲومُت۔ \n7.\\tتُہند غصہٕ چھُ میہ سٍتـ̡ مُتٲثِر کٔرِتھ تہٕ ژے چُھہ پنہٕ نـ̡ سارِنٕے لہرٕ سٍتـ̡ مُتٲثِر کٔرِمُت۔ سِلہٕ۔ \n8.\\tژے چھُکھ میون واقفیت میہ نِش دور کٔرِتھ۔ ژے چھُکھ میہ تِمن ہٕندِ خٲطرٕ مکروہ بنوومُت: {بہٕ چُھس} بند گومُت، تہٕ بہٕ ہیوٚک نہٕ نیبر نیرِتھ۔ \n9. میانہِ أچھ چھے مصیبت سٍتـ̡ ماتم کران: اے خداوند، بہٕ چُھس پریتھ دۅہہ ژے پۯاومُت، مے چُھس ژے کُن پنُن اتھہٕ پھٔہلٲومُت۔ \n10.\\tکیا ژیہ کٔرِو مُردن عجائب کٔرِتھ؟ کیا مُردٕ وُچھِتھ تہٕ تۅہہِ ہٕندِس تعریفس کٔرِتھ؟ سیلاہ۔ \n11.\\tقبرِ منز گژھہِ چانۍ محبتُک اعلان کرنہٕ؟ {یا} تُہند وفاداری یِہ تباہی مَنٛز کرنہٕ؟ \n12.\\tچانۍ عجائب گژھہِ انہِ گٹہِ منز زاننہٕ؟ تہٕ چانۍ نیکی فراموشی ہٕندِس سرزمینس منز؟ \n13. مگر بہٕ چُھس ژے کُن فریاد دِژمُت، اے خدا۔ تہٕ صُبحس میٲنۍ دُعا رُکٲوِتھ ژے رُکاونہٕ۔ \n14.\\tخداوند، ژے کیازِ چھکھ میانہِ روحس نِش ژٔٹِتھ؟ {کیازِ} ژے چھکھ میہ نِش پنُن بُتھ ژوٗر تھاوان؟ \n15. بہٕ چُھس {مُتٲثِر} تہٕ {میانِ} جوانی پیٹھٕ مرنہٕ خٲطرٕ تیار: {ییلہٕ} بہٕ چُھس چانہِ دہشت ہُند شکار سپدان بہٕ چُھس پریشان۔ \n16.\\tچانۍ شدید غضب چھہ میہ پیٹھ ژٹان۔ چانہِ دہشت چھیہ میہ ژٹتھ ژٹمژ۔ \n17.\\tتِم ٲسۍ میہ اندۍ پکھۍ دۅہہ آبہٕ ہٕندۍ پٲٹھۍ۔ تِم ٲسۍ میہ اندۍ پکھۍ اندۍ پکھۍ آسان۔ {روزانہ: یا، سٲرۍسٕے دۅہ}\n18.\\tعاشق تہٕ یارس چھکھ میہ نِش دور تہٕ میانہِ واقفیت اندپِس منز ترٲومٕژ۔","1. [ایتھن عزراہیت سُند مشکیل۔] بہٕ گٮ۪وٕ خداوند سٕنزِ رحمتُک ہمیشہٕ خٲطرٕ: بہٕ کَرٕ پننہِ ٲسِس سٍتـ̡ تُہٕنز وفاداری سارنٕے نسلن تام واتناوُن۔ {مشکیل...: یا، ایتھن عزراہیت سٕندِ خٲطرٕ اکھ زبور، ہدایت دِنہٕ خٲطرٕ} {سارنٕے خٲطرٕ...: ہیب۔ نسل تہٕ نسلہٕ}\n2. تِکیازِ مےٚ چُھ ووٚنمُت، رحمت گژھہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ: تُہٕنٛز وفاداری کٔرٕن آسمانن مَنٛز قایم کرنہٕ۔ \n3. مے چُھس پننِس ژٲرِس سٍتـ̡ عہد کورمُت، مے چُھس پننِس خادمس سٍتـ̡ حلف کورمُت، \n4. بہٕ کَرٕ تُہند بُل ہمیشہٕ خٲطرٕ قٲیِم، تہٕ سارِنٕے نسلن خٲطرٕ بناوٕ تُہند تخت۔ سیلاہ۔ \n5. تہٕ اے خداوند، اے خداوند، تُہٕندِس عجائب سٍتـ̡ تہٕ چُھہ تُہٕندِس عجائب سٍتـ̡ تہِ سٍتـ̡ \n6. اسمانس مَنٛز کُس ہیکہِ خداوند سٕندِس سٍتـ̡ تشبیہ دِتھ؟ {کُس} ہیکو خداوند سٕندِس سٍتـ̡ تشبیہ دِتھ؟ \n7.\\tخدایس سٍتـ̡ گژھہِ خدایہ سٍتـ̡ خوفزدہ کرنہٕ یُن۔ \n8. اے خداوند، لشکرن ہُند خدا، کُس چُھہ ژے ہیوٗ مضبوط خداوند چُھہ؟ یا چُھہ تُہٕندِس اندۍ پٔکھۍ وفاداری؟ \n9.\\tژے چُھکھ سمندرٕچ لہرٕ وۅتھان تہٕ ژے چھکھ تِمن رُکاونہٕ یِوان۔ \n10.\\tژے چھُکھ راحابَس ٹُکرٕ ٹُکرٕ کٔرِتھ پھُٹرٲومُت، یُس مارنہٕ آمُت چھُ۔ ژے چھُکھ پَنٕنہِ مضبوٗط نٔرِ سٍتـ̡ پَنٕنـ̡ دُشمن پھٔٹِھمُت۔ {راحب: یا، مصر} {تُہُن...: حَب۔ پننہِ قوتُک نٔر}\n11.\\tآسمانن چھہ تۅہہ، زمین تہِ چھیہ تۅہہ: {یوتاہ دنیاہ} تہ امیک پورپور، ژے چھیہ تہنز بنیاد ترٲومژ۔ {مکمل آسن...: یا، اتھ منز چھہ سورے موجود}\n12.\\tشمالس تہٕ جنوبس منز تہِ چھکھ تِم تخلیق کٔرۍمٕتۍ: تیبر تہٕ ہرمون گژھن تُہندِ ناوٕ سٍتـ̡ شاد سپدان۔ \n13.\\tژے چھہ طاقتور نٔرۍ: تُہند دچھُن اتھہ چھہ مضبوط۔ {a...: ہیب۔ اکھ نٔر یُس طاقتور چھُ}\n14.\\tانصاف تہٕ فیصلہٕ چُھہ تُہندِ تختٕچ بسٲیِن: رحمت تہٕ سچائی گژھہِ تۅہہِ برونہہ کُن۔ {رہائش: یا، قیام}\n15. بابرکت چھُ تِم لُکھ یِم خوشی ہٕنز آواز زانان چھِ: اے خداوند، تِم گژھن تُہندِ بُتھِ ہٕندِس گاشس مَنٛز پَکُن۔ \n16. تُہٕندِس ناوٕ سٍتـ̡ روزن تِم سارِوٕے دۅہہٕ خۄش۔ تہٕ تُہٕندِس نیکی سٍتـ̡ گژھن تِم بلند۔ \n17.\\tتہِ چُھہ تِہٕندِس طاقتُک جلال تہٕ تُہٕندِس حقس مَنٛز گژھہِ سون سینگ تھزر۔ \n18.\\tخداوند سُند دفاع چُھہ تہٕ اسرٲیلُک پاک {چُھ} سون بادشاہ۔ {خداوند...: یا، سون ڈھال چُھ خداوند سُند، تہٕ سون بادشاہ چُھ اسرٲیلِک پاک سُند}\n19.\\tتێلہِ کٔر ژے پننِس مُقدسَس سٍتـ̡ وُچھِتھ تہٕ وونُن، مے چُھس {یُس} طاقتور سٍتـ̡ مدد دِژمُت۔ مے چُھہ لُکن مَنٛز ژارنہٕ آمُت {أکِس} تھزر۔ \n20. مے لوٚب داؤد پنُن خادم۔ میہ چُھ پنُن مقدس تیٖلہٕ سٍتـ̡ مسح کورمُت: \n21. یٔمِس سٍتـ̡ میون اَتھٕ قایم گژھہِ: میٲنۍ نٔر تہِ کرِ أمِس مضبوط۔ \n22. دُشمن گژھِ نہٕ أمِس سٍتـ̡ سزا دِنہٕ۔ تہٕ نہ کرِ بدکار سُند نیٚچُو۔ \n23.\\tتہٕ بہٕ کرٕ تٔمۍ سٕندِس دُشمن ہٕندِس بُتھِس برونہہ کُن، تہٕ یِمن سٍتـ̡ أمِس سٍتـ̡ نفرتـ̡ دِنہٕ آمُت۔ \n24. مگر میٲنۍ وفاداری تہٕ میٲنۍ رحمت گژھہِ أمِس سٍتـ̡ تہٕ میانہِ ناوٕ سٍتـ̡ تٔمۍ سُند سینگ بلند کرنہٕ۔ \n25.\\tبہٕ تھاوٕ تٔمۍ سُند اَتھٕ تہِ سمندرس مَنٛز، تہٕ تٔمۍ سُند دٔچھُن اَتھٕ دریاوَن مَنٛز۔ \n26. سُہ چُھہ میہ کُن فریاد دِنہٕ، تہٕ چُھہ میٲنۍ مول، میون خدا، تہٕ میانہِ نجات ہٕنز پتھر۔ \n27. تہٕ بہٕ بناوٕ سُہ گۅڈنیُک زٲنِتھ، یُس زمینہٕ کِس بادشاہو کھوتہٕ تھوٚد آسہِ۔ \n28. بہٕ کَرٕ میٲنۍ رحمت أمِس خٲطرٕ ہمیشہٕ خٲطرٕ، تہٕ میون عہد روزِ أمِس سٍتـ̡ مضبوط۔ \n29. تٔمۍ سُند بُل تہِ بناوٕ بہٕ ہمیشہٕ خٲطرٕ تہٕ تٔمۍ سُند تخت آسُن جنتُک دۅہہٕ۔ \n30. یێلہِ تٔمۍ سٕندِ شُرۍ میانہِ شریعت تراوٕن، تہٕ میانین فٲصلن مَنٛز پکان نہٕ۔ \n31.\\tاگر تِم میانہِ قونونن خلاف ورزی کٔرِن، تہٕ میانہِ حکمس پیٹھ عمل کرن نہٕ۔ {بریک: ہیب۔ ناپاک}\n32. تیلہٕ کٔرٕ بہٕ تِہٕنزِ لٔرِ سٍتـ̡ تہٕ تِہٕنزِ بدکاری ہٕندِس سٍتـ̡ وُچھمُت۔ \n33.\\tبہر حال بہٕ کٔرٕ نہٕ پنُن محبتہٕ أمِس نِش پوٗرٕ پٲٹھۍ، تہٕ نہ کرٕ پنٕنۍ وفاداری ناکام۔ {وِل...: حب۔ بہٕ کَرٕ نہٕ أمِس نِش خٲلی} {پَسُن: حب۔ اپُز}\n34. میون عہد پھُٹراوٕ نہٕ تہٕ نہ بدلاوٕ یُس میانہِ چپنہٕ منزٕ نیران چُھ۔ \n35.\\tاکہ لٹہِ چُھس میہ پننہِ پاکیزگی سٍتـ̡ حلف کورمُت زِ بہٕ کرٕ نہٕ داؤدس سٍتـ̡ اپُز۔ {یہ...: حب۔ اگر بہٕ اپُز چُھس}\n36. تٔمۍ سُند بُل روزِ ہمیشہٕ خٲطرٕ، تہٕ تٔمۍ سُند تخت روزِ میانہِ برونہہ کُن آفتاب۔ \n37.\\tیہ گژھہِ ہمیشہ خٲطرٕ زونہِ ہٕندِ پٲٹھۍ، تہٕ آسمانس مَنٛز وفادار گواہ روزِ۔ سیلہ۔ \n38.\\tمگر ژے چھُکھ ژے ژٔٹِتھ تہٕ نفرت کٔرمٕژ، ژے چُھکھ پنُن مسح کرنہٕ سٍتـ̡ شرارت کٔرمٕژ۔ \n39.\\tژے چھُکھ پننِس خادمُک عہد باطل کورمُت: ژے چھُکھ تٔمۍ سُند تاج زمینس پیٹھ تراوِتھ بے حرمتی کٔرمٕژ۔ \n40.\\tژے پھُٹرٲوۍ تٔمۍ سٕندِس سارِنٕے باڑ۔ ژے چھُکھ تٔمۍ سٕندِس مضبوٗط حصس برباد کٔرِتھ۔ \n41.\\tیُس وتہِ وتہِ نیران چھُ، سُہ چھُ پننین ہمساین ہٕندِ خٲطرٕ ملامت کران۔ \n42.\\tژے کٔر تٔمۍ سٕندِس دُشمن ہُند دٔچھُن اتھٕ قٲیم۔ ژے کٔر تٔمۍ سٕندِس سارِنٕے دُشمن خۅش کرنہٕ خٲطرٕ۔ \n43.\\tژے چھُکھ تٔمۍ سٕنزِ تلوارِ ہُند دھار تہِ پھیرمُت، تہٕ جنگس منز کھڑا کرنہٕ خٲطرٕ بنووُکھ نہٕ۔ \n44.\\tژے کٔر تٔمۍ سُند جلال بند تہٕ ترووُن تٔمۍ سُند تخت زمینس پیٹھ۔ {شاندار: ہیب۔ چمک}\n45.\\tتٔمۍ سٕندِ جوانی ہٕندِ دۅہ چھکھ ژے ژھوٚٹمُت: ژے کٔر أمِس شرم سٍتـ̡ ؤلِتھ۔ سیلہ۔ \n46.\\tخداوند، کٲتِس کالس روزُن؟ کیا ژٕ کٔرِکھ پنُن پان ہمیشہٕ خٲطرٕ ژوٗرِتھ؟ کیا تُہند قہر نارٕکۍ پٲٹھۍ دزان؟ \n47.\\tیاد تھاوُن میون وقت کوتاہ کم: ژے کیازِ چھکھ سارِنٕے انسان بیکار بنٲومٕتۍ؟ \n48.\\tسُہ کُس انسان چُھہ زندٕ روزان تہٕ موت وُچھِتھ نہٕ؟ سُہ کُس انسان چُھہ قبرِ ہٕندِس اتھہٕ نِش نجات دِنہٕ؟ سیلہ۔ \n49.\\tخداوند، کتہِ چُھہ تۅہہِ گۅڈنِچہ محبتہٕ کتہِ، یُس ژے پننہِ حقیقتس منز داؤدس سٍتـ̡ دٔرِتھ چُھہ؟ \n50. اے خداوند، پنہٕ نِس خادمَن ہُند ملامت یاد تھاوُن؛ {کتھہٕ پٲٹھۍ} بہٕ چُھس سارِنٕے طاقتور لُکن ہُند ملامت پننِس سینس منز برداش۔ \n51. یێمہِ سٍتـ̡ چُھہ تُہٕندِس دُشمنن ملامت کٔرمٕژ، اے خداوند۔ یێمہِ سٍتـ̡ تِمو چُھہ تُہٕندِس مسح کرنہٕ آمٕتـ̡ قدمن ہٕندِس قدمس ملامت کٔرمٕژ۔ \n52. خداوند سُند ہمیشہٕ خٲطرٕ بابرکت آسُن۔ آمین، تہٕ آمین۔","1. [موسیٰ سُند دُعا خدایہ سُند انسان۔] اے خداوند، ژے چُھہ سارِنٕے نسلن مَنٛز سانہِ روزنٕچ جاے رودمُت۔ {اکھ دُعا...: یا، اکھ دُعا، موسیٰ سُند زبور} {منز...: حب۔ نسل تہٕ نسلہٕ}\n2. پہاڑ نیرنہٕ برونہہ، یا کُنہِ تہِ ژے زمینہٕ تہٕ دنیاہٕچ تشکیل دِژمٕژ، حتیٰ کہ ازلی پیٹھٕ ابدی تام تہِ، تہٕ چُھہ خدا۔ \n3. تہٕ ژے چُھہ انسانس تباہی کُن پھیران۔ تہٕ وَنُن واپس، اے انسانہٕ سٕندِ اولاد۔ \n4.\\tساس ؤری چھہ تۅہہِ ہنزِ نظرِ منز {مگر مگر} یتھے پاٹھۍ راتھ ییلہ یہ پتھ کُن آسہِ، تہ {یتھہ پاٹھۍ} رٲژ پتھ کُن۔ {ییلہ...: یا، ییلہ سہ تمن گذران آسہِ}\n5.\\tژے چھکھ تِمن سٔلابن ہٕندۍ پٲٹھۍ، تِم چھِ {یِتھ} نِندٕرِتھ: صُبحَس {تِم چھِ} گاسہٕ ہٕندۍ پٲٹھۍ{یُس} کھسان چھُ۔ {بڑان...: یا، بدلاوان چھُ}\n6.\\tصبحس چھہ یہ پھۅلان تہ وۅتھان تہ وۅتھان۔ شامس چھہ یہ ژٹنہ یوان تہ وُچھان۔ \n7. تکیازِ أسۍ چُھہ چانہِ غصہٕ سٍتـ̡ کھسنہٕ آمُت، تہٕ چُھہ تُہٕندِس قٕسمس سٍتـ̡ پریشان گٔژھان۔ \n8. ژے کٔر سانہِ گناہ پانس برونہہ کُن، سانہِ راز {گناہ} پننہِ شکلہِ ہندس گاشس منز۔ \n9.\\tتکیازِ سانہِ سارِنٕے دۅہ چھِ تۅہہِ ہٕندِس قٕسمس سٍتـ̡ گُزٲرمٕتۍ: أسـ̡ پَنٕنـ̡ دٔلیلہٕ پٲٹھـ̡ {یُس وننہٕ آمُت چُھ}۔ {گزرُن...: Heb. پھیرُن} {بطور...: یا، مراقبہٕ کِس طورس پیٹھ}\n10.\\tسانین ؤرین ہندۍ دۅہ چھہِ تریہ ؤری تہ داہ ؤری۔ تہٕ اگر قوت کنۍ {تِم} ژور ؤری آسن، توتہِ چھِ تِہنز طاقت محنت تہٕ غم۔ تکیازِ یہ چھہ جلدے ژٹان تہ اسۍ چھہِ وُڈان۔ {دۅہ...: ہیب۔ سانین ؤرین ہندۍ دۅہ چھہِ ستتھ ؤری}\n11. چانہِ غصہٕ ہٕندِس طاقتس کُس چُھ زانان؟ چانہِ خوفہٕ مُطٲبق تہِ چُھہ تُہند غصہٕ تہِ۔ \n12.\\tتێلہِ ہیچھناوُن {اسہِ} پننین دۅہن گٔنزراوُن، یُتھ أسۍ ہێکہِ دِل داناہس پیٹھ لاگو کٔرِتھ۔ {لاگو کٔرِتھ: حب۔ یِنہٕ وول وجہ}\n13. اے خداوند، کٲتِس کالس واپس؟ تہٕ سُہ گژھہِ پننین خادمَن مُتلق توبہ کرُن۔ \n14. اے اسہِ کٔر پننہِ رحمتہٕ سٍتـ̡ سُلی تسلی دِنہٕ۔ یُتھ أسـ̡ سارِنٕے دۅہن خۅش روزُن تہٕ خۅش روزُن۔ \n15.\\tتِمن دۅہن مُطٲبق کٔرِو اسہِ خۅش یِمن دۅہن منز ژے اسہِ مُتٲثِر کٔرۍ، {تہٕ} تِمن ؤرین مُطٲبق کٔرِو اسہِ بُرٕ وُچھمُت۔ \n16. پنٕنۍ کٲم گژھہِ پننین خادمَن نِش ظٲہر تہٕ تِہندین شُرین ہٕندِس جلال سٍتـ̡ ظٲہر سپدٕنـ̡ ۔ \n17. تہٕ خداوند سُند خوٗبصوٗرتی گژھہِ اسہِ پیٹھ: تہٕ تێہہ کٔرِو سانہِ اتھن ہٕنز کٲم اسہِ پیٹھ قایم کرنہٕ۔ آ، سانہِ اتھن ہٕنز کٲم کٔرِو یہ قایم کرنہٕ۔","1. یُس خدایہ سٕندِس خفیہ مقامس مَنٛز روزان چُھ، سُہ روزِ قادر مطلق سٕندِس سایہ سٍتـ̡ روزُن۔ {Abide: Heb. Lodge}\n2. بہٕ چُھس خداوند سٕندِس بارس منز وَنُن، {سُہ چُھ} میون پناہ گاہ تہٕ میٲنۍ قعلہٕ: میون خدا۔ بہٕ کرٕ تس پیٹھ بھروسہٕ۔ \n3.\\tیقینا کرِ سُہ ژے کۅکرِ ہٕندِس جالس نِش بچاوُن، {تہٕ} تہٕ شرارتی وبا نِش۔ \n4. سُہ کرِ تۅہہِ پنہٕ نِس پکھہٕ سٍتـ̡ ؤلِتھ، تہٕ تٔمۍ سٕندِس پَکھہٕ تَل روزِ تۅہہِ سٍتـ̡ پَنٕنـ̡ پَکھہٕ سٍتـ̡ پٲٹھ \n5.\\tژیہ گژھ نہ راتس دہشت سٍتۍ خوف۔ {تہِ} تیرس {یُس} دۅہلہِ وُڈان چھُ؛ \n6.\\t{نَہ} وُپھ {یُس} چھُ انہِ گٹہِ منز پکان {نَہ} تَمہِ تباہی خٲطرٕ {یُس} دُپہرس ضایع سپدان چھُ۔ \n7. اکھ ساس گژھہِ تۅہہِ طرفہٕ تہٕ دچھنہِ اتھس پیٹھ داہ ساس پیوٚو۔ {مگر} یہ گژھہِ نہٕ توے نزدیک۔ \n8. صرف پنہٕ نِس أچھو سٍتـ̡ وُچھِو تہٕ وُچھِو بدکارن ہُند انعام۔ \n9. کیازِکہ ژے چُھہ خداوند یُس میٲنۍ پناہ گاہ چُھ، {حتیٰ کہ} چُھہ پنُن روزن وول بَنوومُت۔ \n10. تۅہہِ گژھہِ نہ کانہہ بُر، نہ گژھہِ تۅہہِ گَرِ نزدیک۔ \n11. تِکیازِ سُہ دِیہِ پَنٕنـ̡ فرشتن تێلہِ ہٕندِس سارِنٕے طریقس مَنٛز رژھرٕنـ̡ ۔ \n12.\\tتِم رٔٹِتھ تُہٕندِس اتھس منز، نتہٕ کُنہِ پٲٹھۍ۔ \n13.\\tژیہ پٔزۍ شیرس تہ شیرس پیٹھ قدم تراوُن: جوان شیر تہ ڈریگن ژیہ ژیہ کھۅرن تلہ لتہِ۔ {ایڈر: یا، آسپ}\n14.\\tکیازِ تٔمۍ چُھس میہ سٍتـ̡ محبت کورمُت، تێمہِ کِنۍ بہٕ کرٕ تس تھزرس پیٹھ، کیازِ تس چُھس میون ناو زانان۔ \n15.\\tسُہ کرِ میہ پکار، تہٕ بہٕ کرٕ تس جواب: بہٕ روزٕ تس سٍتـ̡ مصیبتَس مَنٛز۔ بہٕ کٔرٕ أمِس بچاوٕ تہٕ عزت کٔرِتھ۔ \n16.\\tزیچھِ وٲنسہِ سٍتـ̡ بہٕ أمِس تسلی دِوان تہٕ ہاوٕ پنٕنۍ نجات ۔ {زیٹھ...: ہیب۔ دۅہن ہُند زیچھر}","1. [زبور {یا} سبت کہ دۅہہٕ خٲطرٕ نغمہٕ۔] {یہِ چُھ اَکھ اصل {چیز} خداوند سُند شُکر ادا کرُن، تہٕ تُہندِ ناوٕچ حمد گٮ۪وُن، اے اعلیٰ ترین چیز: \n2. صبحس پنٕنۍ محبتہٕ تہٕ پرٮ۪تھ رٲژ پنٕنۍ وفاداری ظٲہر کرنہٕ خٲطرٕ، {پرٮ۪تھ...: ہیب۔ رٲژ منٛز}\n3.\\tدہن تارن ہندِس سازس پیٹھ، تہٕ زبورس پیٹھ؛ ہارپس پیٹھ اکھ سنجیدہ آواز۔ {ہارپ...: یا، ہارپس سٍتۍ سنجیدہ آواز} {اکھ سنجیدہ...: ہیب۔ ہِگیون}\n4. کیازِ، خداوند، چُھس پننہِ کامہِ سٍتـ̡ بہٕ خۅش کٔرِتھ: بہٕ کٔرٕ چانہِ اتھن ہٕنزِ کامہِ سٍتـ̡ کامیاب۔ \n5.\\tاے خداوند، چانۍ کٲم کوتاہ عظیم چھِ! {تہٕ} تُہند خیال چُھ سٮ۪ٹھاہ سرٛوٚن۔ \n6.\\tوحشی انسان چھہ نہ زانان۔ بیوقوف تہِ چھہ نہ یہ سمجھان۔ \n7.\\tییلہ بدکار گاسہٕ ہٕندۍ پٲٹھۍ، تہٕ ییلہ بدکارن ہٕندۍ سٲری کارکُن پھۅلٕن، {یہ} چُھ زِ تِم گژھن ہمیشہٕ خٲطرٕ تباہ کرنہٕ: \n8. مگر توہ، خداوند، {چُھہ} ہمیشہٕ خٲطرٕ تھد۔ \n9. تِکیازِ، اے خداوند، تُہند دُشمن گژھن ختم گٔژھن۔ بدکاری ہٕندِ سارِنٕے کارکُن گژھن منتشر کرنہٕ۔ \n10.\\tمگر میٲنۍ سینگ ژے کٔرِتھ کُنہِ کُنہِ سینگ ہٕندۍ پٲٹھۍ، بہٕ گژھہِ تازٕ تیٖلہٕ سٍتـ̡ مسح کرنہٕ۔ \n11.\\tمیانہِ اچھ تہِ وُچھن میانین دشمنن پیٹھ، {تہٕ} میانین کنن بوزِ {میانہِ خواہش} یُس میہ خلاف کھڑا سپدان چھُ۔ \n12.\\tنیک گژھہِ کھجور کُلِس ہٕندۍ پٲٹھۍ، سُہ گژھہِ لبنانس مَنٛز دیودار ہٕندۍ پٲٹھۍ۔ \n13. یُس خداوند سٕندِس گرس مَنٛز لاگنہٕ یِن تِم گژھن سانہِ خدایہ سٕندِس دربارس مَنٛز پھۄلٕنـ̡ ۔ \n14. تِم گژھن بُزرگس منز تہِ پھل دِنہٕ۔ تِم گژھن موٚٹۍ تہٕ پھۅلان۔ {پھۅلُن: ہیب۔ سبز}\n15.\\tیہِ ہاوُن زِ خداوند چُھہ سیدِ سید: {سُہ چُھ} میٲنۍ پتھر، تہٕ {أمِس مَنٛز چُھنہٕ کانہہ بدکاری}۔","1. خداوند چُھ بادشاہت کران، سُہ چُھ عظمت سٍتـ̡ لٔگِتھ لٔگِتھ۔ خداوند چُھ طاقتہٕ سٍتـ̡ لٔگِتھ لٔگِتھ، {یێمہِ} سٍتـ̡ چُھہ تٔمِس پانس سٍتـ̡ لٔگِتھ دِژمُت: دُنیا تہِ چُھہ قایم سپُدمُت، یُس نہٕ ہێکہٕ ہێکہِ ہُند پٲٹھـ̡ \n2. تُہند تخت {چُھ} پرانہِ پیٹھٕ قایم گومُت: توے {چُھ} ازل پیٹھ۔ {پرانہِ: ہیب۔ تَمہِ پَتہٕ}\n3. اے خداوند، سٔہلابَن ہٕنز آواز تُلِتھ تُلان۔ سٔہلاب چُھ پنٕنۍ لہرٕ تُلان۔ \n4. خداوند چُھ تھدِ آبہٕ کِس شورٕ کھۅتہٕ زیادٕ طاقتور، {ہاں، سمندرٕچ طاقتور لہرٕ کھۅتہٕ۔ \n5. تہنز گوٲہی چِھ واریاہ پکہٕ: پاکیزگی چُھ تُہند گرٕ بنان، اے خداوند، ہمیشہٕ خٲطرٕ۔ {ہمیشہٕ خٲطرٕ: ہیب۔ دۅہن ہٕندِس طوالتس تام}","1. اے خدایہ، یٔمِس سُند انتقام چُھ؛ اے خدایہ، یٔمِس سُند انتقام چُھ، پنُن پان ہٲوِو۔ {خدا...: ہیب۔ انتقامُک خدا} {ہاو...: ہیب۔ چمکُن}\n2. پَنُن پان تھوٚد تُل، اے زمینُک مُنصوٗب: مغرورَن دِیُک اَجر۔ \n3. خداوند، بدکار کٲتِس کالس روزِ بدکار، بدکار کٲتِس کالس روزِ فتح؟ \n4.\\t{﴾ تِم کُنہِ کالس کٔرِتھ {تہٕ} سخٕت کتھ کَرٕن؟ {تہٕ} سٲری بدکار چھِ پانس ناز کران؟ \n5. اے خداوند، تِم چھِ تُہٕندِس لُکن ٹُکرٕ ٹُکرٕ کٔرِتھ تہٕ تُہٕندِس وراثتس مُتٲثِر کٔرِتھ۔ \n6.\\tتِم چھِ بیواہ تہٕ اجنبی قتٕل کٔرِتھ تہٕ بے باپ قتل کٔرِتھ۔ \n7.\\tتوتہِ چھہِ ونان زِ خداوند گژھہِ نہ وچھان، یعقوب سُند خدا گژھہِ نہ وچھان۔ \n8.\\tسمجُن، اے لُکن مَنٛز وحشی: تہٕ بیوقوف، کٔر کٔرِو عقلمند؟ \n9.\\tیُس کَن ووتمُت چُھ، سُہ چُھہ نہٕ بوزُن؟ یُس أچھ بنوومُت، سُہ چُھہ نہٕ وُچھان؟ \n10.\\tیُس کُنہِ کافرس سزا دِیہِ، سُہ چُھہ نہٕ صحیح؟ یُس انسانس علم ہیچھناوان چُھ، سُہ گژھہِ نہٕ زانہٕ؟ \n11. خداوند چُھ انسان سٕندِس خیالس زانان، زِ تِم چِھ باطل ۔ \n12. سُہ شخص چُھہ بابرکت یُس ژے پاکیزہ کران چُھ، اے خداوند، تہٕ أمِس پنہٕ نِس شریعت سٍتـ̡ ہیچھناوُن۔ \n13.\\tیُتھ زِ تُہۍ دِیہِ أمِس مُصیبت کِس دۅہہٕ نِش آرام دِنہٕ، یوتام نہٕ بدکارن ہٕندِ خٲطرٕ کھۄڈ کھنہٕ ییہِ۔ \n14.\\tکیازِ خداوند کرِ نہٕ پَنٕنـ̡ پَنٕنـ̡ لُکہٕ ترٲوِتھ تہٕ نۂ سُہ پَنُن وَرث تراوُن۔ \n15.\\tمگر فیصلہ گژھہِ نیکی کُن واپس: تہٕ دِلس منز گژھن سارِنٕے سیدِ پٲٹھۍ۔ {پَتہٕ پَتہٕ...: ہیب۔ اَمہ پتہٕ آسہِ}\n16.\\tبدکارن خلاف کُس کرِ میانہِ خاطرہ کھڑا؟ {یا} کُس کرِ میانہِ خاطرہ بدکار کارن خلاف کھڑا؟ \n17.\\tیوٚت تام نہ خداوند میانہِ مددٕ آسہِ، میون روح اوس لگ بھگ خاموشی منز روزان۔ {تقریباً: یا، جلدی}\n18.\\tییلہ میہ ووٚن، میانہِ کھۅر رٔٹِتھ اے خداوند، چانہِ رحمت، رٔٹۍ میہ تھپھ۔ \n19.\\tمیانین خیالن ہٕندِس کثرتس منز چھُ چانۍ آرام میانہِ روحس خۅش کران۔ \n20.\\tکیا بدکاری ہٕندِس تختس سٍتـ̡ رٔلِتھ یُس شریعت سٍتـ̡ شرارت کران چُھہ؟ \n21. تِم چھِ پَنُن پان نیکوکارن ہٕندِس روحس خلاف جمع کران، تہٕ معصوم خونس مذمت کران۔ \n22. مگر خداوند چُھ میٲنۍ بچاو۔ تہٕ میون خدا چُھہ میانہِ پناہ گاہٕچ پتھر۔ \n23. تہٕ سُہ کرِ تِمن پیٹھ پنُن بدکار تہٕ تِمن ہٕنزِ بدکٲری سٍتـ̡ ژٹِتھ ژٹِتھ ۔ {آ}، خداوند سون خدا کرِ تِمن ژٹان۔","1. اے آو، أسۍ گٮ۪وو خدایہِ سٕندِ خٲطرٕ: أسۍ کرو پننہِ نجات ہٕندِس پتھرس پیٹھ خوشی ہُند شور۔ \n2. أسۍ یِو تٔمۍ سٕندِس حٲضِرِس برونہہ کُن شُکرگزاری کٔرِتھ، تہٕ زبورٕ سٍتـ̡ کٔرِو أمِس سٍتـ̡ خوشی ہُند شور۔ {یِو...: ہیب۔ تٔمۍ سُند بُتھ رُکٲوِو}\n3. خداوند چُھ اَکھ بٔڈ خدا، تہٕ سارِنٕے دیوتاہن ہٕندِ کھۅتہٕ بٔڈ بادشاہ۔ \n4.\\tتمۍ سندِس اتھس منز چھہِ زمینہِ ہنزِ سرنۍ جگہ: بالن ہنز طاقت تہِ چھیہ تسُند تہِ۔ {منز...: ہیب۔ کمۍ سٕندِس اتھس منز {طاقت...: یا، بالن ہند تھزر چھہ تسُند}\n5.\\tسمندرُک {چُھ} تہٕ تٔمۍ بنوو: تہٕ تٔمۍ سٕندِ اتھن بنیوو خشک {زمین}۔ {سمندر...: ہیب۔ کُس سمندر}\n6. اے آؤ، أسۍ پوٗزا کٔرِو تہٕ سجدٕ کٔرِو: أسۍ کرو پننِس خالق خداوند سٕندِس برونہہ کُن کُٹھہٕ کٔرِتھ۔ \n7. تکیازِ سُہ چُھ سُہ سُہ خدا۔ تہٕ أسۍ چِھہ تٔمۍ سٕندِ مرگہٕ ہٕندِ لُکھ تہٕ تٔمۍ سٕندِ اَتھٕکۍ کۅکر۔ از تام یێلہِ تٔمۍ سٕنز آواز بوزو، \n8.\\tپَنُن دِل کٔرِو نہٕ سخٕت، یِتھ کٔنۍ زَن اشتعال دِنہٕ آمُت، {تہٕ} یِتھٕ پٲٹھۍ{in} بیابانن مَنٛز فتنہ کِس دۅہہٕ: {اشتعال: حب۔ تنازعہٕ}\n9.\\tییلہ چانہِ مٲلیو میہ لالچ دِژ، میہ ثٲبت کٔر، تہٕ میون کٲم وُچھ۔ \n10.\\tژتٲجی ؤری اوسس میہ اتھ نسلس سٍتۍ غمگین تہ وونُن، یہ چھہ اکھ تِژھ قوم یُس پننِس دلس منز غلطی کران چھہِ، تہٕ تِم چھہِ نہ میانہِ وتہِ زانان۔ \n11.\\tبہٕ کُن بہٕ پننِس غضبَس مَنٛز قسم کھیوان زِ تِم گژھن نہٕ میٲنِس آرامس مَنٛز دٲخل گَژھن۔{یہ...: حب۔ اگر تِم میانہِ آرامس مَنٛز اژان چھِ}","1. اے خداوند سٕندِ خٲطرٕ گیو اکھ نوٚو گٮ۪وُن: سارِنٕے زمینہٕ سٍتـ̡ گیو خدایہِ سٕندِ خٲطرٕ۔ \n2. خداوند سٕندِ خٲطرٕ گٮ۪وُن، تٔمۍ سُند ناو کرو برکت۔ تٔمۍ سٕنز نجات دِیُن دۅہہٕ ہاونہٕ۔ \n3. کافرن مَنٛز کٔرِو تٔمۍ سٕندِس جلال ہُند اعلان، سارِنٕے لُکن مَنٛز تٔمۍ سٕندِ عجائبات ہُند اعلان۔ \n4. خداوند سُند {چُھ} عظیم، تہٕ واریاہ تعریف: سُہ چُھ سارِوٕے دیوتاہن کھوتہٕ زیادٕ خوفزدہ گژھُن۔ \n5.\\tقومن ہٕندِس سارِنٕے دیوتا چِھہ بُت، مگر خداوند بنوو آسمان۔ \n6.\\tعزت تہٕ عظمت چھِ تٔمِس برونہہ کُن: طاقت تہٕ خوبصورتی چھِ تٔمۍ سٕندِس مقدس مقامس مَنٛز۔ \n7. اے لُکن ہٕندِس رشتہٕ دارَو، دِیُو خداوند سٕندِس جلال تہٕ طاقت۔ \n8.\\tخداوند سُند جلال دِیُن {تٔمۍ سُند ناو}: اکھ نذرانہ أنِو، تہٕ تٔمۍ سٕندِس دربارس مَنٛز گژھُن۔ {کٔرِو...: ہیب۔ تٔمۍ سٕندِس ناوُک}\n9.\\tپاکیزگی ہٕندِس خوبصورتی مَنٛز کٔرِو خداوند سٕنز پوٗزا : أمِس برونہہ کُن خوف کٔرِو، سارِنٕے زمینہِ سٍتـ̡ {منز...: یا، شاندار مقدس مقامس منز}\n10. کُلِس مَنٛز وَنُن زِ خداوند چُھ بادشاہت کران: دُنیا تہِ گژھہِ قایم کرنہٕ یُن زِ یہِ گژھِ نہٕ منتقل کرنہٕ: سُہ کرِ لوکن ہُند انصاف پٲٹھۍ۔ \n11.\\tآسمانن گژھہِ خۅش تہ زمینہِ گژھہِ خۅش گژھن۔ سمندرس گژھہِ گُرُن تہ امیک پورُن۔ {پورُن...: یا، اتھ منز موجود سورُے چیز}\n12.\\tکھیت گژھہِ خۅش روزُن، تہٕ یێمہِ سٍتـ̡ یێلہِ سارِنٕے کُلۍ خۅش گٔژھنـ̡\n13. خداوند سٕندِ برونہہ کُن: کیازِ سُہ چُھ یِوان، یێلہِ سُہ چُھ زمینُک فیصلہ کرنہٕ خٲطرٕ یِوان، سُہ کرِ دُنیاہس سٍتـ̡ نیکی سٍتـ̡ تہٕ لوکن ہُند فیصلہ پنہٕ نِس سچٲیِس سٍتـ̡ کرنہٕ۔","1. خداوند چُھ بادشاہت کران؛ زمینہِ گژھہِ شاد سپدُن؛ جزیرن ہٕنز بٔڈ تعداد گژھہِ خوش گٔژھنـ̡ {تَمہِ سٍتـ̡ ۔ {کثیر...: ہیب۔ واریاہ ، یا، عظیم جزیرٕ}\n2.\\tاوٚبر تہٕ اندۍ پکھۍ چھِ: نیکی تہٕ فیصلہ {چھِ} تٔمۍ سٕندِس تختس ہٕنز بسان۔ {رہائش: یا، قیام}\n3.\\tأمِس برونہہ کُن چُھ نار نیران، تہٕ دُشمن دِوان دِنہٕ۔ \n4. تٔمۍ سٕنزِ بجلی کٔر دنیاہس روشن تہٕ لٔج تھرتھر۔ \n5. خداوند سٕندِس حضورس سٍتـ̡ گٔیہِ بالہٕ موم ہٕندۍ پٲٹھۍ۔ \n6. آسمانن چُھ تٔمۍ سٕندِ نیکی ہُند اعلان کران، تہٕ سارِوٕے لُکھ چھِ تٔمۍ سُند جلال وُچھان۔ \n7. تِم سارِنٕے گٔژھِو یِم بُتن ہٕنز خدمت کران چھِ، یِم بُتن ہٕندِس پٲٹھۍفخر کران چھِ: تٔمِس سٍتـ̡ کٔرِو سارِنٕے دیوتاہن ہٕنز پوجا کرنہٕ۔ \n8. صییون بوز، تہٕ گٔیہِ خۄش۔ تہٕ یہوداہ سٕنزِ کورِ گٔیہِ تُہندِ فیصلہٕ سٍتـ̡ خۅش۔ \n9. تۅہہِ خٲطرٕ، خداوند، سارِنٕے زمینہٕ پیٹھٕ تھزر: تہٕ چُھکھ سارِنٕے دیوتاہن پیٹھٕ تھزر۔ \n10. یُس خداوند سُند محبت کران چُھ، سُہ چُھ پننین مقدسن ہٕنزِ روحن رژھراوان ۔ سُہ چُھ تِمن بدکارن ہٕندِ اتھہٕ نِش نجات دِوان۔ \n11.\\tگاش چُھ نیکوکارن ہٕندِ خٲطرٕ وونہٕ آمُت، تہٕ دِلَس مَنٛز چُھ خوشی دِنہٕ آمٕژ۔ \n12. اے صالح، خداوند سٕندِس مَنٛز کٔرِو شاد ۔ تہٕ تٔمۍ سٕندِس پاکیزگی ہٕندِس یادس پیٹھ کٔرِو شُکر۔ {at...: یا، یادگارس کُن}","1. [اکھ زبور۔] اے خداوند سٕندِ خٲطرٕ گیو اکھ نوٚو گٮ۪وُن؛ تکیازِ تٔمۍ کٔر حیرت انگیز کامہٕ: تٔمۍ سٕندِ دٔچھُن اتھہٕ تہٕ تٔمۍ سٕنزِ پاک نٔرِ سٍتـ̡ دِژ تسٕنز فتح۔ \n2. خداوند چُھ پَنٕنـ̡ نجات ظٲہر کٔرمٕژ: تٔمۍ سٕنز پاکیزگی چھے کُلِس ہٕندِس نظرس منز ظٲہر کٔرمٕژ۔ {کھلہٕ پٲٹھۍ...: یا، ظٲہر کرنہٕ}\n3. أمِس چُھ پَنٕنہِ رحمتُک تہٕ اِسرٲیلِس سٍتـ̡ پَنٕنـ̡ سٍتـ̡ پۯاونہٕ آمُت پۯاوُن: زمینہٕ کِس سارِنٕے اند \n4.\\tسارِنٕے زمینہٕ سٍتـ̡ کٔرِو خدایہِ سٕندِ خٲطرٕ خوشی ہُند شور۔ \n5. گِیوو رب سٍتـ̡ ہارپ سٍتـ̡ ۔ ہارپ سٍتـ̡ تہٕ زبور سٕنزِ آوازٕ سٍتـ̡ گیو۔ \n6.\\tبُر تہٕ کارنیٹٕچ آوازٕ سٍتـ̡ کٔرِو خداوند بادشاہس برونہہ کُن خوشی ہُند شور۔ \n7.\\tسمندرس تہٕ اَمہ سٍتـ̡ سٍتـ̡ گٔژھِو۔ دُنیاہ، تہٕ یِم اَتھ مَنٛز روزان چھِ۔ {پورُن...: یا، سارِنٕے سٍتـ̡ چُھ}\n8. سٔہلاب گژھن ژرِ پوٚپ کٔرِتھ: پہاڑ گژھن اِکہٕ وٹہٕ خۅش\n9. خداوند سٕندِ برونہہ کُن؛ تِکیازِ سُہ چُھ زمینہِ ہُند انصاف کرنہٕ خٲطرٕ یِوان: نیکی سٍتـ̡ کرِ سُہ دُنیاہس تہٕ لوکن ہُند انصاف سٍتـ̡ فٲصلہٕ۔","1. خداوند چُھ بادشاہت کران؛ لُکن گژھہِ تھرتھر کرُن: سُہ چُھ کرُبِمس درمِیان بِہتھ۔ زمین گژھہِ ہُلاونہٕ۔ {ہُراونہٕ یُن: ہیب۔ ٹھہراونہٕ یُن}\n2. خداوند چُھہ صیونس مَنٛز عظیم۔ تہٕ سُہ چُھ سارِنٕے لُکن ہٕندِس سارِنٕے لُکن پیٹھ۔ \n3. تِم گژھن تُہٕندِس عظیم تہٕ خوفناک ناوٕچ تعریف۔ {کیازِ} چُھ یہِ {چُھ} مُقدس۔ \n4. بادشاہ سُند طاقت تہِ چُھ فیصلہٕ پسند کران۔ توے چُھہ انصاف قایم کران، تہٕ ژے چُھکھ یعقوبس منز انصاف تہٕ نیکی انجام دِوان۔ \n5. خداوند سٕندِس خدایہِ سٕنز تعظیٖم کٔرِو، تہٕ تٔمۍ سٕندِس قدمس پیٹھ کٔرِو پوٗز۔ {کیازِ} چُھ سُہ {چُھ} پاک۔ {سُہ چُھ...: یا چُھہ یہِ پاک}\n6. موسیٰ تہٕ ہارون پنہٕ نِس پادٕرَن مَنٛز، تہٕ سموئیل یُس تٔمۍ سُند ناو پکاران چھُ۔ تِمو کٔر خداوند سٕندِس سٍتـ̡ پُز، تہٕ تٔمۍ دِژ تِمن جواب۔ \n7.\\tتِمو کٔر تِمن سٍتـ̡ اوٚبرٕ ستونس مَنٛز کتھ کرنہٕ: تِمو کٔر تٔمۍ سٕنزِ گوٲہی تہٕ سُہ فرمان یُس تٔمۍ تِمن دِژمُت اوس۔ \n8.\\tژے دیت تِمن جواب، اے خداوند سانہِ خدایہ: ژے اوس اکھ خدا یُس تِمن مٲفی دِژ، یێلہِ تہِ تہندِ ایجاداتن ہُند انتقام ہیوٚتُن۔ \n9. خداوند سُند خدایہ کرُن تہٕ تٔمۍ سٕندِس مقدس بالس پیٹھ عبادت کٔرِو۔ یێمہِ سٍتـ̡ چُھہ خداوند سُند خدا {چُھ} پاک۔","1. [تعریفُک زبور۔] خداوند سٍتـ̡ کٔرِو خوشی ہُند شور۔ {تعریف: یا، شُکرگزار} {سارِنٕے...: ہیب۔ سارِنٕے زمینہٕ}\n2. خداوند سٕنز خدمت کٔرِو خوشی سٍتـ̡ : گیونہٕ سٍتـ̡ یێمہِ سٕندِس حٲضِرس برونہہ کُن یِو۔ \n3. ژیہ زانِو زِ خداوند چُھہ خدا چُھہ: {یہ} چُھ تٔمۍ {یُس} أسـ̡ بنوومُت، تہٕ أسـ̡ نہٕ أسـ̡ {أسـ̡ چُھہ تٔمۍ سٕندِس لُکھ تہٕ تٔمۍ سٕندِس چراگاہٕچ کۅکر۔ {تہٕ نہٕ...: یا، تہٕ أسـ̡ أسـ̡\n4.\\tشُکر ادا کٔرِتھ اژِو تٔمۍ سٕندِس دروازس منز، {تہٕ} تٔمۍ سٕندِس دربارس مَنٛز گژھِو تعریف۔ \n5. خداوند سٕندِ خٲطرٕ {چُھ} اصل؛ تٔمۍ سٕنز رحمت {چُھ} ہمیشہٕ؛ تہٕ تٔمۍ سٕنز سچائی {چُھ} سارنٕے نسلن تام قایم۔ {سارنٕے خٲطرٕ...: ہیب۔ نسل تہٕ نسلہٕ خٲطرٕ}","1. [داؤد سُند زبور۔] بہٕ گٮ۪وٕ رحمتُک تہٕ فیصلہٕ: اے خداوند، بہٕ گٮ۪وٕ ژے خٲطرٕ۔ \n2. بہٕ کَرٕ پنُن پان دانشمندانہ سٍتۍ کٲمل پٲٹھۍ۔ اے ژٕ کَر یِنہٕ میانہِ نِش؟ بہٕ پَکہٕ پننِس گرس اندر کامل دِلہٕ سٍتـ̡ پَکُن۔ \n3.\\tبہٕ تھاوٕ نہٕ کانہہ بدکار چیز پننین نظرن برونہہ کُن: بہٕ چُھس تِمن ہٕنزِ کامہِ سٍتۍ نفرت، یُس اَکہٕ طرفہٕ پھیران چھُ۔ {یہ} گژھِ نہٕ میہ سٍتـ̡ لٔٹِتھ۔ {بدکار...: حب۔ بِلیالُک چیز}\n4.\\tمیہ نِش گژھہِ اکھ بدکار دِل نیرُن: بہٕ گژھہِ نہ کانہہ بدکار {شخص}۔ \n5.\\tیُس یُس ہمساین ہٕندِس ہمساین بدنام کرِ، سُہ ژٔٹِتھ ژٔٹِتھ یُس تھدِ نظر تہٕ مغرور دِل آسہِ۔ \n6.\\tمیٲنۍ نظر گژھہِ زمینہٕ کین وفادارن پیٹھ، یُس میہ سٍتۍ روزُن: یُس کامل پٲٹھـ̡ پکان چُھ، سُہ کرِ میانہِ خدمت۔ {منز...: یا، وتہِ منز کامل}\n7. یُس دھوکہ دِوان چُھہ سُہ گژھِ نہٕ میٲنِس گرس منز روزُن: یُس اپُز ونان چُھ، سُہ گژھِ نہٕ میانہِ نظرِ منز روزُن۔ {گژھِ نہٕ روزُن: ہیب۔ گژھِ نہٕ قٲیم کرنہٕ}\n8. بہٕ کٔرٕ سُلی زمینہٕ کِس سارِنٕے بدکار تباہ ۔ یُتھ بہٕ کٔرٕ خداوند سٕندِ شہرٕ نِش سارِنٕے بدکار ژٔٹِتھ۔","1. [مُتٲثِر سٕنز دُعا، یێلہِ سُہ مغلوب سپدِ، تہٕ خداوند سٕندِس برونہہ کُن پنٕنۍ شکایت کٔرِتھ۔] اے خداوند، میٲنۍ دُعا بوز تہٕ میٲنۍ فریاد گژھہِ ژے نِش۔ {of: or, for}\n2.\\tییلہ بہٕ مصیبت آسہِ، میہ نِش کٔر نہ پنُن بُتھ ژوٗر۔ پَنُن کَن کٔرِو میہ کُن کُن: ییمہِ دۅہس {یێلہِ} بہٕ بلاوٕ دِیُس جلدی جواب دِیُن۔ \n3.\\tمیانہِ دۅہ چھہِ دوٚہہِ ہٕندۍ پٲٹھۍ، تہٕ میانہِ أڈجہ چھِ دٔسۍ زالنہٕ یوان۔ {یِتھک...: یا، (یِتھ کٔنۍ کینہہ پٔرِتھ) چھِ دھوکہٕ سٍتۍ زالنہٕ یِوان}\n4.\\tمیون دِل چُھس لٔگِتھ تہٕ گاسہٕ ہٕندۍ پٲٹھۍ مرزاونہٕ آمُت۔ یُتھ بہٕ چھُس پنُن روٹی کھیوٚن مٔشِد گٔژھان۔ \n5.\\tمیانہِ شۅنگہِ ہنزِ آوازِ سٍتۍ چھیہ میانہِ اڈجہ میٲنس مسلس سیتۍ ژٹان۔ {ژمہِ: یا، ماز}\n6. بہٕ چُھس بیابانن ہٕندِس پیلیکن ہٕندۍ پٲٹھۍ: بہٕ چُھس ریگستانُک راتہٕ مۄغل ہیوٗ آسان۔ \n7. بہٕ چُھس وُچھان، تہٕ چُھس مکانس پیٹھ کُنی چڑیا ہٕندۍ پٲٹھۍ۔ \n8.\\tمیٲنۍ دُشمن چھِ سارِوٕے دۅہس میہ ملامت کران۔ {تہٕ} یِم میہ خلاف پاگل چھِ، تِم چھِ میہ سٍتۍ حلف تلان۔ \n9.\\tکیازِ مے چُھس روٹی ہیوٗ سوٗر کھٮ۪ومُت، تہٕ پنُن شرابٕ رَلاونہٕ آمُت، \n10.\\tپننہِ شرارت تہٕ پننہِ شرارت کِنۍ: کیازِ ژے چُھکھ مے تھوٚد تہٕ دِژُکھ مےٚ۔ \n11.\\tمیانۍ دۅہ چھہِ ژھایہ ہیو یُس زوال پذیر چھہ۔ تہٕ میہ چھہ گاسہِ ہندۍ پاٹھۍ مرزاونہ آمت۔ \n12. مگر اے خداوند، تُہۍ روزِ ہمیشہٕ خٲطرٕ قایم۔ تہٕ تُہٕنز یاد تھاوٕنۍ سارِنٕے نسلن تام۔ \n13.\\tژے گژھہِ وۅتھُن، {تہٕ} صییونس پیٹھ رحم کرُن، تکیازِ تس سٍتـ̡ احسان کرنُک وق چُھہ آمُت۔ \n14. تِکیازِ تُہٕندِس خادمَس کٔرِو تٔمۍ سٕندِس کٔنِس سٍتـ̡ خۅش تہٕ یِمن ہٕنزِ گردِ ہٕندِس مٔنزِس سٍتـ̡ ر \n15.\\tیێلہِ گژھہِ کافر خداوند سٕندِ ناوٕ سٍتـ̡ تہٕ زمینہٕ کِس سارِنٕے بادشاہن تُہٕندِس جلال سٍتـ̡ خوف۔ \n16. یێلہِ خداوند صیون تعمیر کرِ، سُہ گژھہِ پننہِ جلال سٍتـ̡ ظٲہر۔ \n17.\\tسُہ کرِ بے سہارا سٕنزِ دعاہٕ ماننہٕ تہٕ تِہٕنزِ دعاہٕ سٍتـ̡ حقارت کرٕنـ̡ ۔ \n18.\\tیِہ گژھہِ یِنہٕ واجنہِ نسلہٕ خٲطرٕ لیکھنہٕ یُن: تہٕ یُس لُکھ پٲدٕ سپدِ، تِم گژھن خداوند سٕنز حمد کرنہٕ۔ \n19.\\tتِکیازِ تٔمۍ چُھ پننہِ مقدس جایہِ ہٕندِ تھزرٕ پیٹھٕ بۄن وُچھمُت۔ اسمانہٕ پیٹھٕ وُچھ خداوند زمین۔ \n20.\\tقٲدِ سٕندِ کرٛٮ۪کہٕ بوزنہٕ خٲطرٕ؛ یِم موتُک مُقرر کرنہٕ آمٕتۍ چھِ۔ {تِم...: ہیب۔ موتٕکۍ بچہٕ}\n21. صییونس مَنٛز خداوند سُند ناو تہٕ یروشلمس مَنٛز تٔمۍ سٕندِ تعریفُک اعلان کرُن۔ \n22. یێلہِ لُکھ یِکہٕ وَٹہٕ یِوان تہٕ بادشٲہی ہٕندِس سٍتـ̡ خداوند سٕنزِ خدمت کرنہٕ خٲطرٕ جمع سپدِ۔ \n23.\\tامۍ کٔر میانہِ دۅہ کمزور۔ تمۍ کٔر میانہِ دۅہ کم۔ {کمزور: ہیب۔ مصیبت}\n24. میہ ووٚن، اے خدایہ، میہ نِش نہٕ میانین دۅہن منز، چانۍ ؤری چھِ سارنٕے نسلن منز۔ \n25. پرٲنِس زمانس منز ٲس ژے زمینٕچ بُنیاد تھوومٕژ، تہٕ آسمانہٕ چُھ تہندِ اتھن ہٕنز کٲم۔ \n26.\\tتِم گژھن ختم گٔژھن، مگر تۅہہ روزِ برداش: آ، یِم سارِنٕے گژھن پوشاک ہٕندۍ پٲٹھۍ۔ یِتھٕ پٲٹھۍ، تِم بدلاوٕن: {برداش: ہیب۔ کھڑا روزُن}\n27.\\tمگر تۅہہِ چھُکھ یۅہے تہٕ چانہِ ؤرین ہُند کانہہ اند۔ \n28.\\tتُہٕندِس خادمَن ہٕندِ شُرِ روزن تہٕ تِہُند اولادٕ گژھہِ تۅہہِ برونہہ کُن قایم کرنہٕ۔","1. [{زبور} داؤد سُند زبور۔] اے میانہِ روح، تہٕ میٲنس اندر موجود سارِنٕے چیزس کٔر تٔمۍ سُند مقدس ناو۔ \n2. اے میانہِ روح، خداوند کرو برکت تہٕ تٔمۍ سٕندِ تمام فٲیدٕ مٔشِد گژھ نہٕ: \n3. یُس چُھہ تُہٕندِس سارِنٕے گُناہ معافی دِوان۔ یُس تُہٕنزِ سارِنٕے بیمارِ ہُند شفا دِوان چُھ؛ \n4. یُس تۅہہِ ہُند زُو تُہٕندِس تباہی نِش نجات دِوان چُھ؛ یُس چُھہ تۅہہِ محبتہٕ تہٕ نرم رحمتہٕ سٍتـ̡ تاج لاگان۔ \n5.\\tیُس چُھہ تُہٕندِس ٲسس رژھ \n6. خداوند چُھ سارِنٕے ظالمن ہٕندِ خٲطرٕ نیکی تہٕ فیصلہٕ دِوان۔ \n7. تٔمۍ کٔر موسیٰ سٕندِ خٲطرٕ پنٕنۍ وتہٕ تہٕ بنی اسرٲیلِس خٲطرٕ پنٕنۍ اعمال۔ \n8. خداوند چُھہ رحم دل تہٕ مہربان ، غصہٕ ہُند سُست تہٕ رحمتَس مَنٛز سٮ۪ٹھاہ زیادٕ۔ {کثرت...: عبرانی۔ رحمتَس مَنٛز عظیم}\n9.\\tسُہ روزِ نہٕ ہمیشہٕ طعنہٕ: تہٕ نہ روزِ سُہ ہمیشہٕ خٲطرٕ [پنُن غصہٕ}۔ \n10. تٔمۍ کٔر نہٕ سانہِ گۅنہٕ پتہٕ سٍتـ̡ \n11.\\tیِتھٕ پٲٹھـ̡ اسمانس زمینہٕ پیٹھٕ تھزر، تِتھے پٲٹھـ̡ چُھ تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ رحمتـ̡ بٔڈ یُس أمِس کھوژان چُھ۔ {یِتھ...: عبرانی۔ آسمانہٕ کِس تھزرس مطٲبق}\n12.\\tیوت تام مشرق مغرب پیٹھہ دور چُھ، یوت تام تم اسہِ نِش سانہِ خطا دور کٔرۍ۔ \n13.\\tیِتھٕ پٲٹھـ̡ مٲلِس پٲٹھـ̡ بچن ہُند رحم چُھہ کران، یێلہِ چُھہ خداوند تِمن ہُند خوف دِوان یُس أمِس سٍتـ̡ کھوژان چُھ۔ \n14.\\tکیازِ سُہ چُھ سانہِ فریم زانان۔ سُہ چُھ یاد تھاوان زِ أسۍ چھِ گرد۔ \n15.\\tانسانس چھہ تسند دۅہ گاسہ ہیو تہ کھہُک پوش تہ یتھے پاٹھۍ چھہ سہ پھۅلان۔ \n16.\\tتکیازِ واو چھہ اتھ پیٹھ نیران، تہ یہ چھہ ژلان۔ تہ امہ چہ جایہ گژھہِ نہ امہ پتہ کانہہ تہِ۔ {یہ چھہ ...: ہیب۔ یہ چھہ نہ}\n17. مگر خداوند سٕنز رحمت چِھ تِمن پیٹھ یُس أمِس خوفزدہ چُھ، تہٕ بچن ہٕندِس بچن خٲطرٕ چُھ تٔمۍ سٕنز نیکی ۔ \n18.\\tتِمن ہٕندِ خٲطرٕ یُس تٔمۍ سُند عہد پورٕ کرُن، تہٕ تِمن ہٕندِ خٲطرٕ یِم تٔمۍ سٕندِس حکمس یاد تھاوان چھِ۔ \n19. خداوند چُھ آسمانس مَنٛز پنُن تخت تیار کوٚرمُت۔ تہٕ تٔمۍ سٕنز بادشٲہی چھے سارِنٕے پٲٹھـ̡ حُکوٗمت کٔرِتھ۔ \n20. اے خداوند سٕندِس فرشتہٕ سٕندِس فرشتس سٍتـ̡ برکت دِیُن، یُس طاقتس مَنٛز سبقت حٲصل کران چُھ، یُس تٔمۍ سٕندِس کلامٕچ آواز بوزان چُھ۔ {یُس سٍتـ̡ چُھہ سٍتـ̡\n21. خداوند سٕندِس سارِنٕے لشکرس سٍتـ̡ برکت دِیُن؛ تٔمۍ سٕندِس خادمَس سٍتـ̡ یُس تٔمۍ سٕندِس خوشی سٍتـ̡ کٔرِو۔ \n22.\\tخداوند سٕندِس سارِنٕے کامہِ سٍتـ̡ کرُن تٔمۍ سٕندِس بادشاہس سٍتـ̡ برکت دِیُن، اے میانہِ روح۔","1. اے خداوند، اے میانہِ روح۔ اے خداوند میانہِ خدا، ژٕ چُھکھ واریاہ عظیم۔ تہٕ ژٕ چُھکھ عزت تہٕ عظمتُک پلو لٔگِتھ۔ \n2. یُس پانس گاشہٕ سٍتـ̡ پوشہٕ سٍتـ̡ پوشہٕ سٍتـ̡ ؤلِتھ چُھہ: یُس آسمانس پردٕ ہٕندۍ پٲٹھـ̡ پھٔہلِتھ چُھ: \n3. یُس پننِس کمرٕچ شعاعہٕ آبس مَنٛز تراوان چُھ: یُس اوٚبرن پنُن رتھ بناوان چُھ، یُس واو ہٕندِس پکھس پیٹھ پکان چُھ: \n4. یُس پننِس فرشتن روح بناوان چُھ؛ تٔمۍ سٕندِس وزیرن چُھ نار دِوان: \n5.\\t{یمۍ کٔرِتھ} زمینہِ ہنز بنیاد تھوو، {یُس} یہ گژھہِ نہ ہمیشہٕ خٲطرٕ ہٹاونہٕ یُن۔ {کُس...: حب۔ تمۍ چھیہ زمینہِ ہنز بنیاد پننین بنیادن پیٹھ تھٲومژ}\n6.\\tژے کٔر اتھ سرٛنِس سٍتـ̡ پوشہٕ سٍتـ̡ پوشہٕ: آب اوس پہاڑن پیٹھ۔ \n7.\\tتۅہہِ ہٕندِس ملامت سٍتـ̡ ژٔلِتھ \n8.\\tتِم چھِ بالہٕ کِنۍ کھسان۔ تِم چھِ وادی کِنۍ تتھ جایہِ تام وسان یُس ژے تِہندِ خٲطرٕ بُنیاد دِژمُت چھُ۔ {تِم چھِ ہیوٚر کھسان...: یا، پہاڑ کھسان چھِ، وادی چھِ وَسان}\n9.\\tژے چُھہ اکھ بندٕ مقرر کوٚرمُت زِ تِم گژھن نہٕ نیرِتھ۔ یُس نہٕ تِم دُبارٕ زمینہٕ ؤلِتھ پھیرِ۔ \n10.\\tسُہ چُھ چشمہٕ وادین مَنٛز سوزان، {یُس} بالن مَنٛز وسان چھُ۔ {سُہ: ہیب۔ کُس} {دور: ہیب۔ پَکُن}\n11.\\tتِم چِھ کھہہٕ کِس پرٮ۪تھ درندَس چِھہ دِوان: جنگلی گَرٕ چِھ پنٕنـ̡ پیاس بٔٹـ̡ دِوان۔ {بٔرِتھ: Heb. Break}\n12. تِمن ہٕندِ سٍتـ̡ آسُن اسمانٕکۍ جاناوارن پنُن روزن، {یُس} لٔرِن منز گٮ۪وان چُھ۔ {گیوُن: حب۔ اکھ آواز دِیُو}\n13.\\tسُہ چُھ پنہٕ نِس کمرہٕ منزٕ پہاڑن آب دِوان: زمین چھے تۅہہِ کامہِ ہٕندِس پھلس سٍتـ̡ مطمئن۔ \n14.\\tسُہ چُھ چارواین ہٕندِ خٲطرٕ گاسہٕ وۄپداوان، تہٕ اِنسانن ہٕنزِ خدمتہٕ خٲطرٕ کُلہٕ بوُٹ کٔرِتھ، یُتھ سُہ زمینہٕ منزٕ کھٮ۪ن کڈِتھ نیرِ۔ \n15. تہٕ شراب {یُس} انسان سُند دِل خۄش کران چُھ، {تہٕ} تیٖل چُھ {تٔمِس} بُتھ چمکاونہٕ خٲطرٕ، تہٕ روٹی {یُس} انسان سُند دِل مضبوٗط کران چُھ۔ {تیل...: ہیب۔ تٔمۍ سُند بُتھ تیٖلہٕ سٍتـ̡ چمکاونہٕ خٲطرٕ، یا تیلہٕ کھۅتہٕ زیادٕ}\n16. خداوند سٕندِ کُلۍ چِھ بٔرِتھ {رَس}؛ لبنانٕکۍ دیودار، یُس تٔمۍ لگٲومُت چُھ؛ \n17.\\tجاناوار کتہِ چھہِ پنُن گرہ بناوان: {یتھے پاٹھۍ} چھہ سٹارک، فر کُلۍ چھہِ تمۍ سندِ مکانہ۔ \n18.\\tتھدِ بالہٕ چھِ جنگلی ژھاوٮ۪ن ہٕندِ خٲطرٕ پناہ گاہ۔ {تہٕ}کُنٮ۪ن ہٕندِ خٲطرٕ کٔنہِ۔ \n19.\\tتٔمۍ کٔر زون موسمن خٲطرٕ مقرر: آفتاب چُھ پتاہ زِ تٔمۍ سُند لوسُن چُھ۔ \n20.\\tژے چھُکھ انہِ گوٚٹ بناوان، تہٕ یہ چھُ رٲژ یَتھ مَنٛز جنگلٕکۍ سٲری درندٕ چھِ ژٔلان۔ {درندٕ...: ہیب۔ تِمن ہٕندِس درندٕ چھِ جنگلَس مَنٛز لَتہٕ لَتان}\n21. جوان شیر چھِ پننِس شکارس پَتہٕ گرٛٮ۪وان تہٕ خدایہِ نِش پنُن ماز ژھاران۔ \n22.\\tآفتاب چُھ طلوع سپدان، تِم چھِ پانس جمع کٔرِتھ پننین گۅپھن منز تراوان۔ \n23.\\tانسان چُھ شامس تام پننہِ کامہِ تہٕ محنتس کُن نیران۔ \n24. اے خداوند، تُہٕندِ کامہِ کوتاہ گٔیہِ! عقلہٕ سٍتـ̡ چُھہ تِم سارِنٕے بَنوومٕتۍ: زمین چھے تُہٕندِس دولتَس سٍتـ̡ بٔرِتھ۔ \n25.\\t{یتھے پاٹھۍ چھہ یہ عظیم تہ وسیع سمندر، یتھ منز {چھہِ} بے شمار چیز چھہِ، لۅکٹۍ تہ بٔڈ درندہ۔ \n26. جہازٕ چِھ گَژھان: {اَتہِ} چُھ سُہ لیویتھن، {یُس} چُھ تَتھ منز گِندنہٕ خٲطرٕ بنوومُت۔ {بَننہٕ آمُت: ہیب۔ بَننہٕ آمُت}\n27. یِم سارِنٕے چُھہ تۅہہِ ہُند انتظار کَران۔ یُتھ زن تِمن ہُند ماز مُقرر وقتس پیٹھ دِتھ۔ \n28.\\tژے دِوان تِم چھِ جمع کٔرِتھ: ژے چھکھ پنُن اتھہٕ کھولان، تِم چھِ نیکی سٍتۍ بٔرِتھ۔ \n29. ژے چھکھ پنُن بُتھ ژوٗرِ تھاوان، تِم چھِ پریشان گٔژھان: ژے چھکھ تِہُند دم کڈان، تِم چھِ مران تہٕ واپس پننہِ گردِ کُن واپس۔ \n30. توے چُھکھ پنُن روح سوزان، تِم چھِ تخلیق کرنہٕ آمٕتۍ، تہٕ ژے چُھکھ زمینہِ ہُند بُتھ تازٕ کران۔ \n31. خداوند سُند جلال روزِ ہمیشہٕ خٲطرٕ: خداوند کرِ پننین کامہِ سٍتـ̡ شاد۔ {برداش: ہیب۔ بے}\n32. سُہ چُھ زمینس وُچھان، تہٕ سُہ چُھ تھرتھران تہٕ سُہ چُھ بالن اَتھٕ لاگان تہٕ تِم چِھ دھواں دِوان۔ \n33. یوتام بہٕ زندٕ روزان چُھس بہٕ خداوند سٕندِ خٲطرٕ گٮ۪وُن: بہٕ گٮ۪وٕ پننِس خدایہِ سٕندِ تعریفس سٍتـ̡ یێلہِ بہٕ پنُن وجود آسہِ۔ \n34.\\tمیٲنۍ مراقبہٕ گژھہِ موٚدُر: بہٕ روزٕ خداوند سٕندِس سٍتـ̡ خوش۔ \n35. گۅنہگار گژھن زمینہِ منزٕ ختم کرنہٕ یُن، تہٕ بدکار گژھن نہٕ وۅں سٍتـ̡ دِنہٕ۔ اے میانہِ روح، خداوند سٕنز برکت۔ خداوند سٕنز حمد کرٕنۍ۔","1. خداوند سُند شُکر کٔرِو۔ تٔمۍ سُند ناو پکار کرُن: تٔمۍ سٕندِ اعمال کٔرِو لُکن مَنٛز ظٲہر۔ \n2. أمِس گٮ۪وُن، أمِس گٮ۪وُن زبور: تٔمۍ سٕندِس سارِنٕے عجیٖب کامہِ ہٕنز کتھ کٔرِو۔ \n3. تٔمۍ سٕندِس مقدس ناوس مَنٛز جلال کرو: خداوند سٕندِس سٍتـ̡ یێلہِ سٍتـ̡ تِمن ہُند دِل گژھہِ شاد سپدُن۔ \n4. خداوند سٕنز تہٕ تٔمۍ سٕنز طاقت ژھانڈِو: تٔمۍ سُند بُتھ ژھٲرِو۔ \n5. تٔمۍ سٕندِ حیرت انگیز کامہِ یاد تھاوُن یُس تٔمۍ سٕندِ کٔرمٕژ چھِ؛ تٔمۍ سٕندِ عجائب تہٕ تٔمۍ سٕندِ ٲسٕکۍ فیصلہٕ؛ \n6. اے ابراہیم سٕندِ اولاد، یعقوب سٕندِ ژٲرِمٕژ اولاد ۔ \n7. سُہ چُھ خداوند سُہ خدا: تٔمۍ سٕندِ فٲصلہٕ چُھ سارِنٕے زمینس مَنٛز۔ \n8.\\tأمِس چُھ پَنُن عہد ہمیشہٕ خٲطرٕ یاد تھاوُن، سُہ لفظ {یُس} یُس تٔمۍ ساس نسلن ہُند حُکُم دِیُت۔ \n9. کُس {معاہد} اوس تٔمۍ ابراہیم سٍتـ̡ تہٕ اسحاق سٍتـ̡ حلف کورمُت۔ \n10. تہٕ یعقوبس سٍتـ̡ کٔرٕن شریعت خٲطرٕ، {تہٕ} اسرٲیلِس سٍتـ̡ اَکہِ ابدی عہد خٲطرٕ: \n11.\\tیہ ونِتھ زِ بہٕ دِیہ ژے کنعانٕچ زمین، چانہِ وراثتُک حصہٕ: {لوٹ: ہیب۔ رَس}\n12.\\tییلہ تِم {مگر} تعدادس منز کینہہ نفر ٲسۍ۔ آ، واریاہ کم، تہٕ اَتھ منز ٲسۍ اجنبی۔ \n13. ییلہ تم اکہ قومہ پیٹھہ بییس قومس منز، اکہ سلطنتہ پیٹھہ بییس قومس تام گٔیہ۔ \n14. تٔمۍ دِژ نہٕ کٲنسہ تہِ نفرس تِمن غلط کرنہٕ خٲطرٕ: آ، تٔمۍ کٔر بادشاہن تہندِ خٲطرٕ ملعت۔ \n15. {ونان}، میانہِ مسح کرنہٕ آمٕژ تہٕ میانین پیغمبرن کٔرِو نہٕ کانہہ نقصان ۔ \n16.\\tامہِ علاوٕ دِژ تٔمۍ زمینس پیٹھ قحطُک مُطالبہٕ: تٔمۍ کٔر سارِنٕے روٹی ہُند لٔٹ۔ \n17.\\tتِمن برونہہ کُن سوزُن اکھ شخٕص یوسف، {یُس} أکِس نوکر سٕندِ خٲطرٕ کٕننہٕ آمُت۔ \n18.\\tیمۍ سٕندِس کھورِ ہٕندِس کھورِ زنجیر سٍتـ̡ دِژمُت: سُہ آو ششتٕرَس مَنٛز دِنہٕ: {سُہ...: حب۔ تٔمۍ سُند روح آو ششتٕرَس مَنٛز}\n19. یوتام تٔمۍ سُند کلام آو تہٕ خداوند سٕندِ کلامَن کٔر أمِس آزمٲیش۔ \n20. بادشاہن سوٗز تہٕ یلہٕ ترٛٲوُن۔ حتیٰ کہ عوامُک حکمران، تہٕ دِژن سُہ آزاد۔ \n21.\\tتٔمۍ بنوو سُہ پنہٕ نِس گرُک مٲلک، تہٕ پنہٕ نِس سارِنٕے چیزُک حُکُمران: {مادہ: حبری۔ قبضہٕ}\n22.\\tپننین شہزادن پننہِ مرضی پیٹھ پابند کرُن۔ تہٕ پننین سینیٹرن ہیچھناوٕنۍ حکمت۔ \n23.\\tاسرٲیل تہِ آو مصرس مَنٛز۔ تہٕ یعقوب گۆو ہام کِس سرزمینس مَنٛز روزنہٕ۔ \n24. تہٕ تٔمۍ کٔر پننین لوکن ہُند سٮ۪ٹھاہ اضافہٕ۔ تہٕ بنٲیِن تِم پننین دُشمنن کھوتہٕ زیادٕ مضبوط۔ \n25.\\tتٔمۍ پھیُر تِہُند دِل پننین لُکن سٍتـ̡ نفرت، پننین خدمتگارن سٍتـ̡ \n26.\\tتٔمۍ سوٗز موسیٰ پنُن خادم۔ {تہٕ} ہارون یُس تٔمۍ ژٲرمُت اوس۔ \n27.\\tتِمو ہٲو تِمن مَنٛز تٔمۍ سٕندِس نشانہٕ تہٕ ہام کِس ملکس مَنٛز عجائب۔ {تٔمِس...: ہیب۔ تٔمۍ سٕندِس نشانن ہٕندِس کلام}\n28.\\tتٔمۍ سوٗز انہِ گوٚٹ، تہٕ کوٚرُن سُہ انہِ گوٚٹ۔ تہٕ تِمو کٔر نہٕ أمۍ سٕندِس کلامَس خلاف بغاوت۔ \n29.\\tتِمن ہُند آبُک خوٗن، تہٕ مٲرِن تِہٕندِس گاڈَس مٲرِتھ۔ \n30.\\tتِہٕندِس سرزمینس سٍتـ̡ دِژ نِلہٕ کٔرِتھ تہندِس بادشاہن ہٕندِس کمرس مَنٛز۔ \n31.\\tتٔمۍ کٔر کتھ تہٕ تِمن سارِنٕے ساحلن منز آیہ مختلف قسمہ چہ مکھۍ، {تہٕ} جوُن۔ \n32.\\tتِمن دِژ تِمن ہٕندِس زمینس مَنٛز نار دِنہٕ خٲطرٕ۔ {تِم...: ہیب۔ تِہُند روٗد وُچھُن}\n33.\\tتِمن ہٕندٮ۪ن بیلن تہٕ انجیر کُلٮ۪ن تہِ مار۔ تہٕ تِمن ہٕندِس ساحلن ہٕندِس کُلِس لٔٹِتھ دِژٕ۔ \n34.\\tتٔمۍ کٔر کتھ تہٕ ٹِڈی دِژ تہٕ ٹِڈی دِژٕ، تہٕ سُہ گٔیہِ بے تعداد، \n35.\\tتہٕ کھیوٚکھ پننہِ زمینہِ ہٕندِ سارِنٕے جُڑی بوٹی تہٕ کھیوٚکھ تِہٕنزِ زمینہِ ہُند پھل۔ \n36.\\tتٔمۍ دِژ تِہٕندِس سرزمینس مَنٛز سارِنٕے گۅڈنِچہِ زُود تہِ، یُس تِہٕندِس سارِنٕے طاقتُک سردار۔ \n37.\\tتِمو کٔر تِم رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ تہٕ تِمن ہٕندِس قبیلس مَنٛز اوس نہٕ کانٛہہ تہِ کمزور شخص۔ \n38.\\tمصر گۆو خۅش ییلہ تم نیران ٲسۍ، تکیازِ تمن ہند خوف اوس تمن پیٹھ۔ \n39.\\tتٔمۍ پھٔہلٲوِو پوشہٕ خٲطرٕ اوٚبر۔ تہٕ رٲژ گاش دِنہٕ خٲطرٕ نار۔ \n40.\\tلُکن پرژھ، تہٕ تٔمۍ أنۍ بٹیر، تہٕ تِمن کٔرٕن جنتٕچ روٹی سٍتـ̡ تسلی دِنہٕ۔ \n41.\\tتٔمۍ کٔر کٔنہِ کُ \n42.\\tتکیازِ تس اوس پنُن مقدس وعدہ یاد، تہٕ ابراہیم اوس پنُن خادم یاد۔ \n43.\\tتہٕ تٔمۍ کٔر پَنٕنـ̡ لُکھ خوشی سٍتـ̡ برونہہ کُنـ̡ {تہٕ پَنٕنـ̡ چُھہ خوشی سٍتـ̡ پۯاوُن: {خوشی: ہیب۔ گیون}\n44.\\tتہٕ دِتُکھ تِمن کافرن ہٕنزِ زمینہٕ، تہٕ تِمن میلہِ لوکن ہٕنز محنت وراثتس منز۔ \n45.\\tیُتھ تِم تٔمۍ سٕندِس قونوٗنن ہٕنز پاسداری کٔرِتھ، تہٕ تٔمۍ سٕندِس قونوٗنس پیٹھ عمل کٔرِتھ۔ خداوند سٕندِ حمد کٔرِو۔ {تعریف...: ہیب۔ ہلیلوجا}","1. خداوند سُند حمد کرُن۔ اے خداوند سُند شُکر ادا کرُن؛ کیازِ {سُہ چُھ} اصل: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ {ہمیشہٕ برداش}۔ {تعریف...: حب۔ ہلیلوجا}\n2. خداوند سٕنزِ زبردست کٲم کُس ہیکہِ کٔرِتھ؟ {کُس} ہیکہِ تٔمۍ سٕندِ سارِنٕے تعریفن ہٲوِتھ؟ \n3. بابرکت چِھہ تِم یُس فیصلہ کران چُھ، {تہٕ} یُس پریتھ ساتہٕ نیکی کران چُھ۔ \n4. اے خداوند، میہ یاد تھاوُن تتھ عنایتس سٍتـ̡ یُس ژے پننین لوکن ہٕندِس سٍتـ̡ دِوان چُھہ: اے پَنٕنـ̡ نجات سٍتـ̡ کٔرِو مے سٍتـ̡ \n5. یُتھ بہٕ چُھس چانہِ ژٲرِمٕژ ہٕنز خیر وُچھان، یُتھ بہٕ ہێکہٕ چانہِ قومہٕ چہِ خوشی مَنٛز شاد گژھُن، یُتھ بہٕ ہێکہٕ چانہِ وراثتس سٍتـ̡ جلال حٲصل کٔرِتھ۔ \n6. اسہِ چھُ پننین مٲلن سٍتـ̡ گۅنہہ کورمُت، اسہِ چھُ بدکار کورمُت۔ \n7.\\tسانٮ۪و مٲلو سمجِتھ نہٕ مصرس مَنٛز تُہند عجائب ۔ تِمو کٔر نہٕ تُہٕندِس رحمتَن ہٕنز کثرت یاد۔ مگر سمندرس مَنٛز تہٕ سمندرس مَنٛز تہِ کٔرٕکھ اِشارٕ۔ \n8.\\tبہر حال بچٲو تِم پننہِ ناوٕ خٲطرٕ، تاکہ سُہ کرِ پنُن طاقتور طاقت ظٲہر کرنہٕ۔ \n9.\\tتٔمۍ کٔر بحرِ احمر تہِ ملامت تہٕ سُہ گوٚو خشک تہٕ تِمو کٔر تِمن سٍتـ̡ بیابانن مَنٛز۔ \n10. تہٕ تٔمۍ بچٲو تِم تٔمِس سٕندِ اتھہٕ نِش یُس تِمن سۭتۍ نفرت اوس کٔرِتھ، تہٕ دُشمن ہٕندِ اتھہٕ نِش نجات دِژٕنۍ۔ \n11.\\tتہٕ آبن کور پننین دشمنن ہٕندِس دُشمن سٍتـ̡ تہٕ تمن منز اوس نہٕ کانہہ تہِ باقی۔ \n12.\\tتێلہِ گۆو تٔمۍ سٕندِس کلامس پیٹھ یقین ۔ تِمو گیوٚو تٔمۍ سٕندِ تعریف۔ \n13.\\tتِمو گٔیہِ تٔمۍ سٕندِ کامہِ ہٕندِس کامہِ مٔشِد۔ تِمو کٔر نہٕ تٔمۍ سٕندِس مشورُک انتظار: {تِمو جلدٕے...: ہیب۔ تِمو کٔر جلدی تہٕ تِمو گٔیہِ مٔشِد}\n14.\\tمگر بیابانس منز کٔرٕن سٮ۪ٹھاہ لالچ تہٕ ریگستانس مَنٛز کٔرٕن خدایہ سٍتـ̡ لالچ۔ {ہوس...: ہیب۔ ہوس کٔرِتھ ہوس}\n15. تہٕ تٔمۍ دِژ تِمن ہٕنز درخواست۔ مگر تِمن ہٕندِس روحس مَنٛز دِژٕ۔ \n16.\\tتِمو کٔر خٲمس مَنٛز موسیٰ سٕندِس سٍتـ̡ حسد، {تہٕ} خداوند سُند سنت ہارون سٍتـ̡ حسد۔ \n17.\\tزمینہِ کھٲلِتھ تہٕ نِگِتھ دَتھن، تہٕ کوٚرُن ابیرام سٕندِس صحبتس ؤلِتھ۔ \n18.\\tتہٕ تِمن ہٕندِس صحبتس منز آو نار دِنہٕ۔ دِژ بدکارن زٲلِتھ۔ \n19.\\tتِمو بَنوو حوربس مَنٛز اکھ بَچھرٕ تہٕ کٔرٕکھ پگلہٕ بُتھِ ہٕنز پوجا ۔ \n20.\\tیتھہ پاٹھۍ بدلٲو تمو پنُن شان گاسہ کھٮ۪وان أکِس بیلس ہٕندِس مثالس منز۔ \n21.\\tتِمو چُھ خدایہ پنُن نجات دِنہٕ وول مٔشِد، یٔمۍ مصرس مَنٛز بٔڈ کٲم کٔرمٕژ ٲس۔ \n22.\\tحیرت انگیز کٲم چھے ہام کِس سرزمینس منز، {تہٕ} بحر احمر کِس بٔٹھِس سٍتـ̡ خوفناک چیز۔ \n23. تَمہِ کِنۍ ووٚن تِم زِ سُہ کرِ تِم تباہ کٔرِتھ، یێلہِ نہٕ تٔمۍ سُند ژٲرِمُت موسیٰ أمِس برونہہ کُن کھڑا آسہِ، یُس نہٕ تِمن ہُند غصہٕ ژٹِتھ دِیہِ۔ \n24.\\tآ، تِمو کٔر خۅش زمینس حقارت، تِمو کٔر نہٕ تٔمۍ سٕندِس کلامَس پیٹھ یقین کٔرِتھ: {خوشگوار...: ہیب۔ خواہشُک سرزمین}\n25.\\tمگر تِمن ہٕندِس خیمَس مَنٛز گُرگو، {تہٕ} بوزُکھ نہٕ خداوند سٕنز آواز۔ \n26.\\tتێلہِ تُلُن تِمن خلاف اتھہٕ، بیابانن مَنٛز تُلنہٕ خٲطرٕ: {تُلُن: حب۔ تِم پَسنہٕ خٲطرٕ}\n27.\\tقومن مَنٛز تہِ تِہُند بُول تہٕ زمینن مَنٛز پھِراونہٕ خٲطرٕ۔ {تختہٕ والنہٕ خٲطرٕ: حب۔ تِمن ہُند زوال دِنہٕ خٲطرٕ}\n28.\\tتِمو رٔلِتھ تہِ رٔلِتھ بَلپیورس سٍتـ̡ تہٕ کھیوٚکھ مُردن ہٕنز قربانی ۔ \n29.\\tیتھہ پاٹھۍ کٔر تمو پننین ایجادن پیٹھ شرارت تہ تمن پیٹھ پھیُر وُپھ۔ \n30.\\tتێلہِ ووٚتھ فینہاس، تہٕ دِتُن فیصلہٕ: تہٕ یێلہِ آو طاعون رُکاونہٕ۔ \n31.\\tتہٕ سُہ اوس أمِس سٍتـ̡ سارنٕے نسلن ہٕندِ خٲطرٕ نیکی ہٕندِ خٲطرٕ شمار کرنہٕ آمُت۔ \n32.\\tتِمو کٔر کشمکش کِس آبس سٍتـ̡ تہِ شرارت، یێلہِ سُہ گۆو موسیٰ سٕندِس سٍتـ̡ تہندِ خٲطرٕ بیمار۔ \n33.\\tکیازِ تِمو کٔر تٔمۍ سٕندِس روحس اِشارٕ دِنہٕ، یُتھ زن سُہ چپنہٕ نِس وُٹھہٕ سٍتـ̡ کتھ کٔرِتھ۔ \n34. تِمو کٔر نہٕ تِم قومن تباہ یِمن مُتلق خداوند تِمن حُکُم دِیُت: \n35.\\tمگر گٔیہِ کافرن سٍتـ̡ رٔلِتھ تہٕ تِہٕنزِ کٲم ہیچھمٕژ۔ \n36.\\tتہٕ تِمو کٔر پننین بتن ہٕنز خدمت: یِم تِمن ہٕندِ خٲطرٕ اکھ جال ٲسۍ۔ \n37. آ، تِمو کٔر پنٕنۍ نیچوۍ تہٕ کورِ شیطانن خٲطرٕ قربان، \n38.\\tتہٕ کٔرٕن معصوم خون، حتیٰ کہ پننین نیچوین تہٕ کورین ہُند خون، یِم تمو کنعان کین بتن خٲطرٕ قربان کٔرۍ، تہٕ زمین گٔیہٕ خونس سٍتـ̡ آلودہ۔ \n39.\\tیِتھے پٲٹھۍ گٔیہ تِمو پننیو کامہِ سٍتـ̡ ناپاک تہٕ گٔیہِ پنٕنـ̡ ایجاداتن سٍتـ̡ بدکار ۔ \n40. تێمہِ کِنۍ گۆو خداوند سُند قہر پننِس لوکَس سٍتـ̡ دِنہٕ، یُتھ زن سُہ پننِس وراثتس سٍتـ̡ نفرت کٔرِتھ۔ \n41.\\tتہٕ تٔمۍ دِژ تِم کافرن ہٕندِس اتھس منٛز۔ تہٕ یِمن سٍتـ̡ نفرت کٔرِتھ کٔرِکھ تِمن پیٹھ حُکوٗمت۔ \n42.\\tتِہندِ دُشمن تہِ کٔر تِمن پیٹھ ظُلم تہٕ تِم آیہ تِمن ہٕندِس اتھس تل غلام بناونہٕ۔ \n43.\\tواریاہہِ لٹہِ کٔر تِم بچاونہٕ۔ مگر تِمو کٔر پننیو مشورو سٍتـ̡ اِشارٕ دِنہٕ، تہٕ گٔیہٕ تِمن ہٕندِس بدکارس کُن نیران۔ {اننہٕ...: یا، غریب، یا کمزور}\n44.\\tبہر حال اوس تِمن ہٕنزِ مصیبت وچھان، ییلہ تٔمۍ تِہٕنز فریاد بوز: \n45. تہٕ تٔمۍ کٔر تِہندِ خٲطرٕ پنُن عہد یاد، تہٕ کٔرٕن پنٕنۍ رحمتَن ہٕندِ بہتٔری مُطٲبق توبہٕ۔ \n46.\\tتِمن سارِنٕے سٍتـ̡ یِمن ہٕندِس سٍتـ̡ رحم کھسنہٕ یِنہٕ وٲلۍ۔ \n47. اے خداوند سٲنِس خدایہ، اسہِ بچاو، تہٕ اسہِ کٔر کافرن مَنٛز جمع کرنہٕ، تہٕ پننہِ مقدس ناوُک شُکر ادا کرنہٕ خٲطرٕ، {تہٕ} پننہِ تعریفس مَنٛز فتح حٲصل کرنہٕ خٲطرٕ۔ \n48.\\tاسرٲیلُک خداوند خدا آسُن ازل پٲٹھـ̡ ابدی پٲٹھـ̡ بابرکت تہٕ سارِنٕے لُکھ وَنُن آمین۔ خداوند سٕنز حمد کرٕنـ̡ {تعریف...: عبرانی۔ ہلیلویا}","1. اے خداوند سُند شُکر کٔرِو، کیازِ {سُہ} چُھہ اصل: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ {چُھ} ہمیشہٕ برداش۔ \n2. خداوند سٕندِ نجات دِنہٕ آمُت وَنُن یُس دُشمن سٕندِ اتھہٕ نِش نجات دِژمُت چُھ، \n3.\\tتہٕ کٔرِکھ تِم زمینہٕ منز، مشرق تہٕ مغرب پیٹھ، شمالہٕ پیٹھٕ تہٕ جنوبہٕ پیٹھٕ جمع کٔرِتھ۔ {جنوب: ہیب۔ سمندر}\n4.\\tتِم رودۍ بیابانن منز کُنہِ وتہِ نژان۔ تِمن لوٚب نہٕ روزنہٕ خٲطرٕ کانہہ شہر۔ \n5. فاقہٕ تہٕ ترش، تِہُند روح گوٚو تِمن منز بے ہوش۔ \n6. پَتہٕ تِمو کٔر تِمن مُصیبتَن مَنٛز خداوند سٕندِس مُصیبتَس مَنٛز دِنہٕ، {تہٕ} تِمو کٔرٕن تِمن مُصیبت نِش نجات دِنہٕ۔ \n7. تہٕ تٔمۍ کٔر تِمن صحیح وتہِ کُن یُتھ زن تِم بستی ہٕندِس شہرس کُن گٔژھِتھ۔ \n8. اے یێلہِ {انسان} کرِ خداوند سٕنزِ نیکی خٲطرٕ، تہٕ {اِنسانن ہٕندِس شُرین ہٕندِس عٔلمن ہٕندِس کامہِ خٲطرٕ﴾ تعریف! \n9. تکیازِ سُہ چُھ حسرت وٲلِس روحس پوٗرٕ کران، تہٕ فاقہٕ وٲلِس روحس نیکی سٍتۍ بٔرِتھ۔ \n10.\\tیُس انہِ گٹہِ منز تہٕ موت کِس ژھایہ منز بِہِتھ، مصیبت تہٕ ششتٕرَس مَنٛز بِہِتھ چھُ؛ \n11.\\tکیازِ تِمو کٔر خدایہ سٕندِس کلامس خلاف بغاوت تہٕ کٔرٕکھ خدایہ سٕندِس مشورس سٍتـ̡ حقارت کرنہٕ: \n12.\\tتێلہِ دِژ تِہُند دِل محنتہٕ سٍتـ̡ ۔ تِم پٔسۍ، تہٕ {اَم} اوس نہٕ کانہہ تہِ مدد۔ \n13.\\tپَتہٕ کٔر تِمو پننِس مصیبتَس مَنٛز خداوند سٕندِس نِش فریاد تہٕ تٔمۍ بچٲوٕن تِمن ہٕنزِ مصیبت نِش نِش۔ \n14.\\tتٔمۍ کٔر تِم انہِ گٹہِ تہٕ موتٕچ ژھایہِ منزٕ نیبر تہٕ تِمن ہٕندِس بندس پھٔٹِتھ پھٔٹِتھ۔ \n15.\\tاے یێلہِ {انسان} کرِ خداوند سٕنزِ نیکی خٲطرٕ، تہٕ {اِنسانن ہٕندِس بچن ہٕندِ خٲطرٕ تٔمۍ سٕنزِ حیرت انگیز کامہِ خٲطرٕ!» \n16.\\tکیازِ تٔمۍ پھُٹرٲوۍ پیتلٕکۍ دروازٕ، تہٕ ژٔٹِتھ ژٔٹِتھ ششتٕرٕچ سلاخ۔ \n17.\\tبیوقوف چھِ پننہِ زیادتی کِنۍ تہٕ بدکاریو کِنۍ مُتٲثِر سپدان۔ \n18.\\tتِہُند روح چُھ پرٮ۪تھ قٕسمٕک مازس نفرت۔ تہٕ تِم چھِ موتٕکِس دروازس نزدیک واتان۔ \n19.\\tپَتہٕ چِھ تِم پننِس مصیبتَس مَنٛز خداوند سٕندِس نِش فریاد کران، {تہٕ} سُہ چُھ تِمن ہٕنزِ مصیبت نِش بچاوان۔ \n20. تٔمۍ سُند کلام سوزُن، تہٕ تِمن شفا دِژُن تہٕ تِمن ہٕنزِ تباہی نِش نجات دِژٕنۍ۔ \n21. اے یێلہِ {انسان} کرِ خداوند سٕنزِ نیکی خٲطرٕ، تہٕ {اِنسانن ہٕندِس بچن ہٕندِ خٲطرٕ﴾ تٔمۍ سٕندِ حیرت انگیز کامہِ خٲطرٕ! \n22. تہٕ تِم گژھن شُکرگزاری ہٕنزِ قربانی دِن، تہٕ تٔمۍ سٕندِ کامہِ ہُند اعلان کرُن خوشی سان ۔ {خوشی: حب۔ گیون}\n23.\\tتِم یِم جہازن منز سمندرس منز وسان چھِ، یِم بٔڈِس آبس منز کاربار کران چھِ۔ \n24. یِم چھِ خداوند سٕنزِ کامہِ تہٕ تٔمۍ سٕندِس عجائب سٍتـ̡ وُچھان۔ \n25.\\tتکیازِ سُہ چُھ حُکُم دِوان، تہٕ طوفانی واو تُلناوان چُھ، یُس اَمہِ ہٕنزِ لہرٕ تُلِتھ چُھ۔ {تھوٚد کٔرِتھ: ہیب۔ کھڑا گژھُن}\n26.\\tتِم چھِ آسمانس تام کھسان، تِم چھِ دُبارٕ سرٛنٮ۪رَس کُن وَسان: تِہُند روح چُھ مصیبت کِنہِ پٮ۪وان۔ \n27.\\tتِم چھِ شرابس ہٕندۍ پٲٹھۍ، تہٕ شرابہٕ سٕندۍ پٲٹھۍ، تہٕ چھِ پننہ عقلہٕ ہٕندِس اندس پیٹھ۔ {چھِ...: حب۔ تِہٕنز سورے عقل چھِ نِنہٕ آمٕژ}\n28. پَتہٕ چِھ تِم پننِس مصیبتَس مَنٛز خداوند سٕندِس نِش فریاد کران، تہٕ سُہ چُھ تِمن مُصیبتَو نِش نیران۔ \n29.\\tسُہ چُھ طوٗفان سُکُن بناوان، یُتھ زن اَمہِ ہٕنزِ لہرٕ رُکاونہٕ یِوان۔ \n30. تیلہِ چھِ تِم خۄش گژھان تِکیازِ تِم چھِ ژھۄپہٕ کَران۔ یێلہِ چُھ سُہ تِمن ہٕندِس پسندیدٕ پناہ گاہَس تام انان۔ \n31.\\tکاش {انسان} کرِ خداوند سٕنزِ نیکی خٲطرٕ، تہٕ {اِنسانن ہٕندِس بچن ہٕندِ خٲطرٕ﴾ تٔمۍ سٕندِ حیرت انگیز کامہِ خٲطرٕ! \n32.\\tتِم کرٕن أمِس لُکن ہٕنزِ جمٲژ مَنٛز تہٕ بزرگن ہٕنزِ مجلسس مَنٛز تہِ تٔمِس تعریف۔ \n33.\\tسُہ چُھ دریاوَن بیابانَس مَنٛز بدلاوان، تہٕ آبہٕ چشمہٕ خۄشٕک زمینہٕ بناوان چھُ۔ \n34.\\tاکھ پھلدار زمین، یُس اَتھ منز روزان چھُ، تِمن ہٕنزِ بدکٲری خٲطرٕ۔ {بانجھ: ہیب۔ نمکین}\n35. سُہ چُھ بیابانس کھڑا آبس مَنٛز بدلاوان، تہٕ خشک زمینہٕ چُھ آبہٕ چشمہٕ بناوان۔ \n36.\\tتہٕ اَتہِ چُھ سُہ فاقہٕ مَنٛز روزُن، یُتھ تِم روزن خٲطرٕ اکھ شہر تیار کٔرِتھ۔ \n37.\\tتہٕ کھیت ووُن، تہٕ انگور کُلِتھ کٔرِو یِمو سٍتـ̡ ہُریرُک پھل میلہِ۔ \n38.\\tسُہ چُھ تِمن تہِ برکت دِوان، یُتھ زن تِمن ہٕندِس بٔڈِس سٍتـ̡ بٔڈِتھ گٔیہِ۔ تہٕ دِیہِ نہٕ تِمن ہٕندِس چارواین ہٕندِس سٍتـ̡ کم کرنہٕ۔ \n39.\\tبییہِ چھِ تِم ظلم، مصیبت تہٕ غم سٍتۍ کم کرنہٕ آمٕتۍ۔ \n40.\\tسُہ چھُ شہزادن حقارت کٔرِتھ، تہٕ تِمن بیابانن مَنٛز پھیران دِوان، {یتہِ نہٕ کانہہ وتھ آسہِ}۔ {بیابان: یا، خٲلی جاے}\n41.\\tتوتہِ چھُ سُہ غریبَن مُصیبت نِش تھزرس پیٹھ بٔنِتھ، تہٕ چھُ أمِس خاندانن ہٕندِس پٲٹھۍ۔ {منز: یا، پتہٕ}\n42.\\tنیک وُچھن تہٕ خۅش گژھن: تہٕ سارِوٕے بدکاری گژھہِ تٔمۍ سٕندِس ٲسس بند کرنہٕ۔ \n43.\\tیُس تہِ عقلمند آسہِ، تہٕ یِمن چیزن پیٹھ عمل کرِ، تِم تہِ گژھِ خداوند سٕنزِ محبتہٕ سٍتـ̡ سمجُن۔","1. [اکھ بٲتھ {یا} داؤد سُند زبور۔] اے خدایہ، میون دِل چُھ ٹھیٖک۔ بہٕ گٮ۪وٕ تہٕ تعریف، پننہِ عظمتس سٍتـ̡ تہِ۔ \n2. بیدار، زبور تہٕ ہارپ: بہٕ چُھس سُلی بیدار۔ \n3. اے خداوند، لُکن مَنٛز کَرٕ بہٕ تُہٕندِ تعریف۔ \n4. تُہٕنزِ رحمتہٕ سٍتـ̡ چُھہ آسمانس پیٹھـ̡ بٔڈ تہٕ تُہُند پۯاوُن چُھہ اوٚبرن تام وٲتِتھ۔ {اوبر: یا، آسمان}\n5. اے خدایہ، آسمانس پیٹھ، تہٕ سارِنٕے زمینہٕ پیٹھٕ تہٕ تُہٕندِس جلال سٍتـ̡ آسُن۔ \n6.\\tیُتھ چُھہ پنُن محبوب نجات دِنہٕ یُن: پنُن دچھُن اتھہٕ سٍتـ̡ بچٲوِتھ تہٕ دِیُن مےٚ جواب۔ \n7. خداین چُھ پننِس پاکیزگی منز کتھ کٔرمٕژ۔ بہٕ کٔرٕ شاد تہٕ بہٕ کٔرٕ شیکیمس تقسیٖم تہٕ وادی سُکوتھ کٔرِتھ۔ \n8. گلعاد {چُھ} میٲنۍ منسیٰ {چُھ} میون ؛ افرائیم تہِ {چُھ} میانہِ کلہٕ سٕنز طاقت؛ یہوداہ {چُھ} میون قانون دِنہٕ وول ؛ \n9. موآب چُھہ میٲنۍ واش پاٹ؛ ادومس پیٹھ کٔرٕ بہٕ پنُن جوت؛ فلسطینس پیٹھ بہٕ کٔرٕ فتح۔ \n10. کُس کرِ میہ مضبوٗط شہرس مَنٛز؟ کُس کرِ میہ ایڈومَس مَنٛز؟ \n11. اے خدایہ، {توہ} کٔمۍ کٔر اسہِ کٔرِتھ؟ تہٕ اے خدایہ، کیا ژٕ گژھ نہٕ سانین فوجن سٍتـ̡ نیرُن؟ \n12.\\tمصیبت نِش دِیو اسہِ مدد: بیکار {چُھ} انسان سٕنز مدد۔ \n13. خدایہ سٕندِ سٍتـ̡ کرو أسـ̡ بہادری سٍتـ̡ کٔرِتھ: کیازِ سُہ چُھہ سانین دُشمن ہُند دُشمن پٲٹھـ̡ پٲٹھـ̡ دِنہٕ۔","1. [اہم موسیقارس سٍتۍ، داؤد سُند زبور۔] اے میانہِ تعریفُک خدایہ، پَنُن رٔٹِو نہٕ پَنُن سکون۔ \n2.\\tبدکارن ہٕندِس ٲسس تہٕ دھوکہ دِنہٕ والٮ۪ن ہٕندِس ٲسس چھُ میانہِ خلاف کتھ کٔرمٕژ۔ {دھوکہٕ دِنہٕ والٮ۪ن ہٕندِس: ہیب۔ دھوکہٕ دِنہٕ سٍتۍ} {کھُلنہٕ آمٕتۍ: ہیب۔ چُھکھ پان کھولنہٕ آمُت}\n3.\\tتِمو کٔر میہ نفرتٕکۍ لفظو سٍتۍ تہِ۔ تہٕ لوٚگ میہ خلاف کُنہِ وجہہ ورٲے لڑان۔ \n4.\\tمیانہِ عشقہ خاطرہ چھہِ تم میانہِ مخالف: مگر بہٕ چھُس پانس دُعا کران۔ \n5. تہٕ تمو دیت میہ نیکی خٲطرٕ بدی تہٕ میانہِ محبتہٕ خٲطرٕ نفرتُک انعام۔ \n6.\\tتس پیٹھ تھوو اکھ بدکار انسان: تہٕ شیطان تھاوُن پننِس دچھنہِ اتھس پیٹھ۔ {شیطان: یا، اکھ مخالف}\n7. یێلہِ یێلہِ أمِس سزا ییہِ دِنہٕ، تہٕ تٔمِس دُعا گژھہِ گۅناہ بنہِ۔ {مذمت گژھہِ: حب۔ نیرِو مجرم یا بدکار}\n8.\\tتٔمۍ سٕندِ دۅہ گژھہِ کم آسُن۔ {تہٕ} بییِس سُند عہدٕ رٔٹُن۔ {دفتر: یا، چارج}\n9.\\tتٔمۍ سٕندِس شُرِ گژھہِ بے مول تہٕ زنانہٕ گژھہِ بیواہ۔ \n10.\\tتٔمۍ سٕندِس شُرِ گژھن لگاتار آوارہ وارٕ روزُن، تہٕ منگُن: تِم گژھن تِمن ہٕندِس ویران مقامو منزٕ تہِ ژھانڈنہٕ۔ \n11.\\tبھٲتِس سٍتـ̡ رٔٹِتھ یُس أمِس نِش آسہِ۔ تہٕ اَمہِ سٍتـ̡ گٔژھِن تٔمِس سٍتـ̡ محنت برباد کَرٕنـ̡ ۔ \n12.\\tأمِس سٍتـ̡ گژھہِ نہٕ کانہہ رحم کرُن، تہٕ نہ گژھہِ کانہہ تہِ یُس أمِس مٲلِس شُرٮ۪ن سٍتـ̡ احسان کرُن۔ \n13.\\tتٔمۍ سٕندِس اولادس گژھہِ ژٹنہٕ یُن۔ {تہٕ}یِنہٕ وٲلِس نسلس مَنٛز گژھہِ تِہُند ناو مٹاونہٕ یُن۔ \n14. تٔمۍ سٕندِس مٲلِس سٕنز بدکاری گژھہِ خداوند سٕندِ سٍتـ̡ یاد تھاونہٕ۔ تہٕ ماجہِ ہُند گۅناہ گژھہِ نہٕ ختم کرنہٕ۔ \n15.\\tتِم گژھن خداوند سٕندِ برونہہ کُن روزُن، یُتھ سُہ کرِ تِمن ہُند یاداشت زمینہٕ نِش ژٹِتھ۔ \n16.\\tکیازِ تس اوس نہٕ رحم کرُن یاد بلکہ اوسُن غریبن تہٕ محتاجن ستاونہٕ یُن، یُتھ سُہ دِل پھُٹمُت تہِ مارِ۔ \n17.\\tیِتھہ پٲٹھـ̡ أمِس بد دعا کرُن خۅش اوس، تِتھے پٲٹھـ̡ گژھہِ أمِس نِش دوٗر آسُن۔ \n18.\\tیِتھے پٲٹھـ̡ تٔمۍ سٕندِس پَلَس سٍتـ̡ بد دعا کٔرِتھ، تِتھے پٲٹھـ̡ یێلہِ پٲٹھـ̡ آبہٕ سٍتـ̡ تہٕ تٔمِس أڈجن مَنٛز تیٖل پٲٹھۍ۔ {تٔمۍ سٕندِس أنٛدرمن مَنٛز: حب۔ أمِس اندر}\n19.\\tیہ گژھہِ أمِس سٍتـ̡ پوشاک یُس أمِس ؤلِتھ آسہِ، تہٕ یێمہِ سٍتـ̡ سُہ لگاتار لٲگِتھ آسہِ۔ \n20.\\tیہ گژھہِ خدایہ سٕندِ طرفہٕ میانین مُخٲلفن ہُند انعام، تہٕ تِمن ہُند یِم میانہِ روحس خلاف بد کتھ کران چھِ۔ \n21. مگر اے خدایہ، پننہِ ناوٕ خٲطرٕ کٔرِو میانہِ خٲطرٕ، کیازِ تُہٕنٛز رحمت چھِ اصل، تہٕ کٔرٕکھ مےٚ بچاو۔ \n22.\\tکیازِ بہٕ چُھس غریب، تہٕ میہ دِل چُھس پانس اندر زخم۔ \n23.\\tبہٕ چھُس ژھایہِ ہٕندۍ پٲٹھۍ، ییلہ یہ زوال پذیر چھُ، بہٕ چھُس ٹِڈی ہٕندۍ پٲٹھۍ ہیوٚر بوٚن ٹاس دِوان۔ \n24. روزٕ سٍتـ̡ چُھہ میٲنۍ کۅٹھہٕ کمزور۔ تہٕ میون ماز چُھہ موٚٹُر گٔژھان۔ \n25.\\tبہٕ بنیوو تِمن ہُند ملامت تہِ: {ییلہ} تِمو میہ کُن نظر دِوان تِمو کلہٕ ہلاوان۔ \n26. اے خداوند، میانہِ خدایہ کٔر میہ مدد: اے پننہِ رحمتہٕ مطٲبق کٔر میہ بچاو: \n27.\\tیُتھ تِمن گژھہِ پتاہ زِ یہِ چُھہ تُہند اتھہٕ۔ {یہ} خداوند، ژے چُھ یہِ کورمُت۔ \n28.\\tتِم گژھن بد دعا کرُن، مگر دُعا کرُن: ییلہ تم وۅتھان گژھن شرمندہ گژھن۔ مگر تُہند خادم گژھہِ خۅش گژھُن۔ \n29.\\tمیانین مُخٲلفن گژھن شرم کٔرِتھ پوشہٕ دِنہٕ، تہٕ تِم گژھن پنُن پان پوشہٕ سٍتـ̡ پوشہٕ سٍتـ� \n30. بہٕ کَرٕ پننہِ ٲسِس سٍتـ̡ خداوند سٕنز تعریف۔ آ، بہٕ کٔرٕ تٔمِس تعریف۔ \n31.\\tکیازِ سُہ گژھہِ غریبن ہٕندِس دچھنہِ اتھس پیٹھ کھڑا روزُن، تِمن نِش بچاونہٕ خٲطرٕ یُس تٔمۍ سٕندِس روحس مذمت کران چھِ۔ {تِم...: ہیب۔ قاضی}","1. [داؤد سُند زبور۔] خداوند ووٚن میٲنس آغس زِ بہٕ بِہتھ میانہِ دچھنہِ اتھس پیٹھ، یوتام نہٕ بہٕ چانہِ دُشمن پنُن کھۅر بٔنِتھ۔ \n2. خداوند سوزِ پننہِ طاقتٕچ لٔر صہیون منزٕ نیبر: پَنٕنِس دُشمنن مَنٛز کٔرِو حُکوٗمت۔ \n3. تُہٕندِس قوبَس مَنٛز، صُبحہٕ کِس کوکھ پیٹھٕ پاکیزگی ہٕنزِ خوبصورتی مَنٛز، ژے چُھہ پننہِ جوانی ہٕندِس شبنم سٍتـ̡ رضامند۔ {سٍتـ̡...: یا، صُبحہٕ کِس رحم کھۅتہٕ زیادٕ: توے آسہٕ وغیرہ}\n4. خداوند چُھہ قسم کھوٚتمُت، تہٕ توبہ کرِ نہٕ، تہٕ چُھہ نہٕ توبہٕ کٔرِتھ، تہٕ چُھکھ نہٕ ملکیسیدک سٕندِ حُکمس پٲٹھـ̡ ہمیشہٕ خٲطرٕ پادٕر۔ \n5. خداوند چُھہ تُہندِ دچھنہِ اتھس پیٹھ بادشاہن ہٕندِس قہر سٍتـ̡ حملہٕ کرُن۔ \n6. سُہ کرِ کافرن مَنٛز فٲصلہٕ، سُہ کرِ مُردٕ لاشہٕ سٍتـ̡ بٔرِتھ۔ سُہ کرِ واریاہن ملکن مَنٛز کلہٕ زخم۔ {واریاہ : یا، عظیم}\n7.\\tسُہ چُھہ وتہِ کلہٕ تُلُن۔","1. خداوند سٕندِ حمد کٔرِو۔ بہٕ کَرٕ خداوند سٕنز حمد پوٗرٕ دِلہٕ سٍتـ̡\n2. خداوند سٕنز کٲم چھے عظیم، یِمن سارِنٕے سٍتـ̡ یِمن سٍتـ̡ خوشی حٲصل سپدان چِھ۔ \n3. تٔمۍ سٕنز کٲم چھے عزت دار تہٕ شاندار: تہٕ تٔمۍ سٕنز نیکی چھے ہمیشہٕ قایم روزان۔ \n4. تٔمۍ کٔر پنٕنۍ حیرت انگیز کٲم یاد تھاونہٕ خٲطرٕ: خداوند چُھہ مہربان تہٕ رحم دِل سٍتـ̡ بٔرِتھ۔ \n5.\\tتِمن دِیُت تِمن ماز یُس أمِس کھوژان چُھ، سُہ روزِ ہمیشہٕ پنہٕ نِس معاہدُک خیال تھاوُن۔ {ماز: ہیب۔ شکار}\n6.\\tتٔمۍ ہٲو پننین لوکن ہٕنزِ کامہِ ہُند طاقت، یُتھ سُہ دِیہِ تِمن کافرن ہُند وراثت۔ \n7. تٔمۍ سٕندِ اَتھن ہٕنزِ کٲم چھِ صداقت تہٕ فیصلہٕ۔ تٔمۍ سٕندِ سارِنٕے حُکُم چھِ پَکہٕ پٲٹھۍ۔ \n8. تِم چِھ ہمیشہٕ ہمیشہ خٲطرٕ مضبوط، {تہٕ چِھ} سچٲئی تہٕ سچائی سٍتـ̡ کرنہٕ آمٕتۍ۔ {کھڑا...: ہیب۔ چُھ قٲئم کرنہٕ آمُت}\n9. تٔمۍ سُہ سوٗز پننِس لُکن خٲطرٕ نجات تہٕ تٔمۍ چُھ ہمیشہٕ خٲطرٕ پنُن عہد کرنُک حُکُم کورمُت: مقدس تہٕ محترم {چُھ} تٔمۍ سُند ناو۔ \n10.\\tخداوند سُند خوف {چُھ} حکمتُک آغاز: اصل فہم چُھ تِم سارِنٕے سٍتـ̡ یِم {تٔمۍ سٕندِس حکمن} کران چِھہ: تٔمۍ سٕندِ حمد چُھ ہمیشہٕ قایم روزان۔ {اَکھ اصل...: یا، رٔژ کامیابی} {تٔمۍ سٕندِس حُکمَن: ہیب۔ تِم}","1. خداوند سٕندِ حمد کٔرِو۔ سُہ انسان {یُس} خداوند سُند خوف چُھ، {یُس} چُھ تٔمۍ سٕندِس حکمس سٍتـ̡ واریاہ خۅش سپدان۔ {تعریف...: عبرانی۔ ہلیلوجا}\n2. تٔمۍ سُند اولادٕ آسہِ زمینس پیٹھ طاقتور تہٕ نیک سٕنز نسل گژھہِ بابرکت سپدٕنۍ۔ \n3. تٔمۍ سٕندِس گَرَس مَنٛز روزِ دولت تہٕ دولت، تہٕ تٔمۍ سٕنز نیکی روزِ ہمیشہٕ قایم۔ \n4.\\tسیدِ سٍتـ̡ چُھہ گاش پٲدٕ سپدان: {سُہ} مہربان تہٕ رحم دِل تہٕ نیک چُھ۔ \n5.\\tاکھ اصل انسان چھُ احسان تہٕ دِوان: سُہ کرِ پنٕنـ̡ معاملہٕ صوابدید سٍتـ̡ رہنُمٲیی کٔرِتھ۔ {صوابدید: Heb. فیصلہٕ}\n6. یٔقیٖنی طور گژھِ نہٕ سُہ ہمیشہٕ خٲطرٕ منتقل کرنہٕ یُن: نیک روزِ ہمیشہٕ یاد پٲٹھۍ۔ \n7. سُہ گژھِ نہٕ بد بشارت نِش خوفزدہ گژھُن: تٔمۍ سُند دِل چُھہ رُکاونہٕ آمُت، خداوند سٍتـ̡ بھروسہ کٔرِتھ۔ \n8.\\tتٔمۍ سُند دِل {چُھ} قایم گومُت، سُہ گژھِ نہٕ کھوژُن، یوٚت تام نہٕ سُہ پننین دُشمنن پیٹھ وُچھِ۔ \n9. سُہ چُھ منتشر گومُت، تٔمۍ چُھ غریبن دِژمُت۔ تٔمۍ سٕنز نیکی چِھ ہمیشہٕ خٲطرٕ برقرار روزان؛ تٔمۍ سُند سینگ گژھہِ عزتہٕ سٍتـ̡ تھزراونہٕ۔ \n10.\\tبدکار گژھہِ وُچھِتھ غم۔ سُہ گژھہِ دند دِتھ تہٕ گٔژھِتھ گٔژھِتھ تہٕ بدکار سٕنز خواہش گژھہِ ختم۔","1. خداوند سٕندِ حمد کٔرِو۔ اے خداوند سٕندِس خادمَو سٕندِس سٍتـ̡ کٔرِو تعریف۔ {تعریف...: ہیب۔ ہلیلویا}\n2. یێمہِ وقتہٕ پیٹھٕ تہٕ ہمیشہٕ خٲطرٕ گژھہِ خداوند سُند ناو بابرکت آسُن۔ \n3. آفتاب کھسنہٕ پیٛٹھٕ لوسنہٕ تام، خداوند سُند ناو {چُھ} تعریف کرنہٕ یُن۔ \n4. خداوند چُھہ سارِنٕے قومن پیٹھٕ تھزر، تہٕ تٔمۍ سُند جلال چُھ آسمانس پیٹھ۔ \n5. یُس {چُھ} خداوند سٲنِس خداہس ہیوٗ چُھ، یُس تھزرس پیٹھ روزان چُھ، {روزان چُھ...: ہیب۔ پنُن پان چُھ بَساونہٕ خٲطرٕ بلند}\n6. یُس آسمانس تہٕ زمینس مَنٛز موجود چیزن وُچھنہٕ خٲطرٕ عاجز چُھ! \n7.\\tسُہ چُھ غریبَن مٔنزۍ تُلِتھ تُلان۔ \n8. تاکہ سُہ کرِ شہزادن سٍتۍ، حتیٰ کہ پننین لوکن ہٕندِس شہزادن سٍتـ̡ تہِ۔ \n9.\\tسُہ چُھ بانجھ زنانہِ ہُند گرٕ رژھراوُن، {تہٕ شُرٮ۪ن ہٕنز خۅش موج بَناوُن}۔ خداوند سُند حمد کرُن۔ {رژھراونہٕ خٲطرٕ...: ہیب۔ أکِس گَرَس مَنٛز روزنہٕ خٲطرٕ}","1.\\tییلہ اسرٲیل مصر منزہ نیبر نیرِ، یعقوب سُند گرٕ گۆو عجیب زبانہِ ہندِ لُکہٕ سٍتـ̡ ۔ \n2. یہوداہ اوس تٔمۍ سُند مقدس مقام، {تہٕ} اسرائیل اوس تٔمۍ سُند سلطنت۔ \n3. سمندرَن وُچھ تہٕ ژوٚل: اردن آو واپس ژلنہٕ۔ \n4.\\tپہاڑ گٔیہِ کۅکرِ ہٕندۍ پٲٹھۍ، {تہٕ} لۄکٹۍ بالہٕ کٔرِتھ کۅکرِ ہٕندۍ پٲٹھۍ۔ \n5.\\tژیہ کیا گٔیہ، اے سمندر، ژے ژٔلِتھ ژٔلِتھ؟ ژے اردن، {یُس} ژیہ ژیہ ژٔلِتھ ژٔلِتھ؟ \n6.\\tاے پہاڑ، {یُس} تم چھہِ کۅکرِ ہٕندۍ پٲٹھۍ؛ {تہ} تم لۅکٹۍ بال، کۅکرِ ہٕندۍ پٲٹھۍ؟ \n7. اے خداوند سٕندِس حضورس منز، یعقوب سٕندِس خدایہ سٕندِس حضورس سٍتـ̡ تھر تھرٲوِو۔ \n8.\\tیمۍ کٔر یہ کٔنہِ کھڑا آبس منز، یہ چمک آبک چشمہ بنوو۔","1. اے خداوند، اسہِ خٲطرٕ نہٕ اسہِ خٲطرٕ، بلکہ پننہِ رحمتہٕ خٲطرٕ تہٕ پننہِ حقیقتہٕ خٲطرٕ دِیُن پننہِ ناوٕ سٍتـ̡ جلال دِیُن۔ \n2. کافر کیازِ چُھ ونان، کتہِ چُھہ تہند خدا؟ \n3. مگر سون خدا چُھ آسمانس مَنٛز: تٔمۍ کٔر یُس یُس مرضی چُھ کٔرمُت۔ \n4. تِہٕندِ بُت چھِ رۄپہٕ تہٕ سۄنہٕ، یِم چھِ مردن ہٕندِ اتھن ہٕنز کٲم۔ \n5.\\tتِمن چُھ ٲس، مگر تِم چِھ نہٕ کتھ کران: اچھ چِھ، مگر تِم چِھ نہٕ وُچھان: \n6.\\tتِمن چھِ کَن، مگر تِم چھِنہٕ بوزان: نَس چھِ، مگر تِمن چھِنہٕ بوزان: \n7. تِمن چِھ اتھہٕ آسان، مگر تِم چِھ نہٕ تھپھ کٔرِتھ: کھۄر چِھ، مگر تِم چِھ نہٕ پَکان: نَہ چِھ تِمن ہٕندِس حلقہٕ سٍتـ̡ کتھ کران۔ \n8. یِم یِم بناوان چھِ تِمن ہِش آسان۔ یِتھے پٲٹھۍ چھُ پرٮ۪تھ کانٛہہ یُس تِمن پیٹھ بھروسہٕ کران چھُ۔ \n9.\\tاے اسرائیل، خداوند سٍتـ̡ بھروسہ کرُن: سُہ چُھہ تِہُند مدد تہٕ تِہُند ڈھال۔ \n10. اے ہارون سٕندِس گرس پیٹھ بھروسہ کرُن: سُہ چُھ تِہُند مدد تہٕ تِہُند ڈھال۔ \n11.\\tیُس خداوند سٍتـ̡ کھوژان چُھ، تۯێو خداوند سٍتـ̡ بھروسہ کرُن: سُہ چُھہ تِہُند مدد تہٕ تِہُند سہارٕ۔ \n12. خداوند چُھ اسہِ ہُند خیال تھاوان: سُہ کرِ اسہِ سٍتـ̡ برکت؛ سُہ کرِ اسرٲیلِس گرس برکت؛ سُہ کرِ ہارون سٕندِس گرس برکت۔ \n13. سُہ کرِ تِمن برکت یُس خداوند سٍتـ̡ کھوژان چُھ، {لۄکٕٹـ̡ تہٕ بٔڈـ̡ دۄشوٕے۔ {تہٕ: حب۔ سٍت}\n14. خداوند کرِ تۅہہِ تہٕ تُہٕندِس شُرِس زیادٕ کھۅتہٕ زیادٕ ہُریر۔ \n15. تُہۍ چھِو خداوند سٕندِ سٕندِ سٍتـ̡ بابرکت یُس اسمانس تہٕ زمینہٕ بنوو۔ \n16.\\tآسمان، {حتیٰ کہ} آسمان، {چُھ} خداوند سُند، مگر زمینہٕ چُھ تٔمۍ انسانن ہٕندِس اولادس دِژمُت۔ \n17. مُردٕ چُھہ نہٕ خداوند سٕنز تعریف کران، تہٕ نہ چُھہ کانہہ تہِ یُس ژھۄپہٕ گژھان چُھ۔ \n18. مگر أسۍ کٔرِو امہِ وقتہٕ پیٹھٕ تہٕ ہمیشہٕ خٲطرٕ خداوند سٕنز برکت دِوان۔ خداوند سُند حمد کرُن۔","1. بہٕ چُھس خداوند سُند محبت کران، تکیازِ تٔمۍ چُھ میٲنۍ آواز تہٕ میٲنۍ دُعا بوزمٕژ۔ \n2.\\tکیازِ تمۍ چھہ میہ کُن روٚٹمُت، لہذا کٔرٕ بہٕ یوت تام بہٕ زندٕ روزان چھُس تٔمِس بُلان۔ {یوت تام ...: ہیب۔ میانین دۅہن منز}\n3.\\tموتُک غم گۆو میہ اندۍ پکھۍ، تہٕ جہنمٕچ دَگ ٲس میہ تھپھ کٔرِتھ: مے لٔب مصیبت تہٕ غم۔ {گاٹ...: ہیب۔ لٔبِتھ مے}\n4. اَمہِ پَتہٕ کٔر میہ خداوند سٕندِ ناوٕ سٍتـ̡ بُلاونہٕ۔ اے خداوند، بہٕ چُھس ژے سٍتـ̡ پنُن روح نجات دِوان۔ \n5. مہربان چُھہ خداوند تہٕ صالح۔ آ، سون خدا چُھہ رحم فرما۔ \n6. خداوند چُھ سادٕ رژھراوان: بہٕ آو کم کرنہٕ، تہٕ تٔمۍ کٔر مےٚ مدد۔ \n7. اے میانہِ روح، پنہٕ نِس آرام کُن واپس۔ تِکیازِ خداوند چُھ ژے سٍتـ̡ فیاضی سٍتـ̡ سٍتـ� \n8. تکیازِ ژے بچٲو میون روح موتہٕ نِش، میٲنۍ أچھ اوٚش نِش تہٕ میٲنۍ کھۅر پینہٕ نِش۔ \n9. بہٕ چُھس زندٕ سٕندِس سرزمینس مَنٛز خداوند سٕندِ برونہہ کُن پَکُن۔ \n10.\\tمیہ کٔر یقین تہ میہ کٔر کتھ کرنہ: میہ گۆو سیٹھا مصیبت: \n11.\\tمیہ ووٚن جلدی منز سارِنٕے انسان اپُز۔ \n12. بہٕ کیا کرٕ خداوند سٕندِ خٲطرٕ تٔمۍ سٕندِس تمام فٲیدٕ دِنہٕ؟ \n13. بہٕ رٔٹِتھ نجات ہُند پیالہ تہٕ خداوند سُند ناو پکار۔ \n14. بہٕ کَرٕ وۅنۍ رب سٕندِس سارِنٕے لُکن ہٕنزِ موجودگی مَنٛز پنُن عہد ۔ \n15. خداوند سٕندِس نظرس مَنٛز چُھہ تٔمۍ سٕندِس مُقدسن ہُند مرُن۔ \n16. اے خداوند، پٔزۍ پٲٹھـ̡ چُھس بہٕ چُھس تُہند خادم۔ بہٕ چُھس تُہُند خادم، تہٕ چُھس چانہِ خادمُک نیٚچُو: ژے چُھہ میٲنۍ بندہ یلہٕ کٔرِتھ۔ \n17. بہٕ کَرٕ ژے شُکرگزاری ہٕنز قربانی تہٕ خداوند سُند ناو منگان۔ \n18. بہٕ کَرٕ خداوند سٕندِس سارِنٕے لُکن ہٕندِس حٲضِرِ سٍتـ̡ پنُن عہد \n19.\\tخداوند سٕندِس گرٕ کِس دربارس مَنٛز، اے یروشلم۔ خداوند سٕندِس حمد کٔرِو۔","1. اے خداوند سُند حمد کرُن، اے سارِنٕے قومن ہٕندِس تعریف۔ \n2. تٔمۍ سٕنز رحم دِل چھے اسہِ سٍتـ̡ واریاہ زیادٕ: تہٕ خداوند سٕنز سچائی چھے ہمیشہٕ خٲطرٕ قایم روزان۔ خداوند سٕنز حمد کرٕنـ̡ ۔","1. اے خداوند سُند شُکر ادا کرُن؛ کیازِ {سُہ} چُھہ اصل: کیازِ تٔمۍ سٕنز رحمت چھے ہمیشہٕ برقرار۔ \n2. اسرٲیلِس وُنہِ وَنُن زِ تٔمۍ سٕنز رحمت روزِ ہمیشہٕ قایم۔ \n3.\\tہارون سُند گرٕ وَنُن زِ تٔمۍ سٕنز رحمت روزِ ہمیشہٕ خٲطرٕ۔ \n4.\\tیِم یِم خداوند سٕندِ خوفہٕ سٍتـ̡ وَنُن چُھہ وَنُن زِ تٔمۍ سٕنز رحمت روزِ ہمیشہٕ خٲطرٕ۔ \n5.\\tمیہ دِژ مصیبت منز خداوند سٕندِس مُشکِلَس مَنٛز، خداوند دِژ میہ جواب، {تہٕ تھووُن میہ أکِس بٔڈِس جایہِ}۔ {مصیبت منز: حب۔ مصیبت منز}\n6. خداوند {چُھ} میانہِ طرفہٕ؛ بہٕ چُھس نہٕ خوف: انسان کیا ہیکہِ میانہِ خٲطرٕ کٔرِتھ؟ {on...: ہیب۔ میانہِ خٲطرٕ}\n7. خداوند چُھ تِمن سٍتـ̡ میٲنۍ حصہٕ نِوان یُس میانہِ مدد کران چُھ، تێمہِ مۄکھٕ چُھس بہٕ تِمن سٍتـ̡ وُچھان یِم میہ سٍتـ̡ نفرت کران چِھہِ۔ \n8.\\tانسانس پیٹھ بھروسہٕ کرنہٕ کھوتہٕ چُھ خداوند سُند بھروسہٕ کرُن بہتر۔ \n9. شہزادن پیٹھ بھروسہٕ کرنہٕ کھوتہٕ چُھ رب سُند بھروسہٕ کرُن بہتر۔ \n10.\\tسارِنٕے قومن کٔر میہ اندۍ پکھۍ: مگر خداوند سٕندِ ناوٕ سٍتـ̡ بہٕ کٔرٕ تِم تباہ کرنہٕ۔ {تباہ کٔرِو...: ہیب۔ تِم ژٔٹِتھ ژٔٹِو}\n11.\\tتِمو کٔر میہ اندۍ پکھۍ۔ آ، تِمو کٔر میہ اندۍ پکھۍ، مگر خداوند سٕندِ ناوٕ سٍتـ̡ بہٕ کرٕ تِم برباد۔ \n12.\\tتِمو کٔر میہ ماچھ ہٕندۍ پٲٹھۍ۔ تِم چھِ کانٹَن ہٕندِس نارس سٍتـ̡ ژھینہٕ آمٕتۍ: کیازِ خداوند سٕندِ ناوٕ سٍتـ̡ بہٕ کٔرٕ تِم تباہ کرنہٕ۔ {تباہ کٔرِو: حب۔ ژٔٹِتھ کٔرِو}\n13. ژے چُھہ میہ دِژمُت یُتھ بہٕ پیوٚو بہٕ پیوٚو، مگر خداوند کٔر میہ مدد۔ \n14. خداوند چُھ میٲنۍ طاقت تہٕ گیون، تہٕ چُھ میٲنۍ نجات بنیومُت۔ \n15. خوشی تہٕ نجات ہٕنز آواز چِھہ نیکوکارن ہٕندِس خیمہ خانس مَنٛز: خداوند سُند دچھُن اتھہٕ چُھ بہادری سان کران۔ \n16. خداوند سُند دچھُن اَتھٕ چُھ تھزر: خداوند سُند دٔچھُن اَتھٕ چُھ بہادری سان کران۔ \n17. بہٕ چُھس نہٕ مَرُن، بٔلکہِ زِندٕ روزٕ تہٕ خداوند سٕندِ کامہِ ہُند اعلان کرُن۔ \n18.\\tخداوند چُھس میہ دِژمُت، مگر تٔمۍ دِژ نہٕ مے موتس خٲطرٕ۔ \n19. میانہِ خٲطرٕ کھولہٕ نیکی ہٕندِ دروازٕ: بہٕ گژھٕ تِمن مَنٛز اژُن، {تہٕ} بہٕ کَرٕ خداوند سٕنز تعریف: \n20. خداوند سُند یہ دروازہ، یتھ مَنٛز نیک اژُن گژھِ۔ \n21. بہٕ کٔرٕ تۅہہِ ہٕنز تعریف: کیازِ ژے چُھہ مے بوزمُت، تہٕ چُھس میٲنۍ نجات بنیومُت۔ \n22.\\tسُہ کُن {یُس} معمارو انکار کٔر، سُہ چُھ کونُک کُن {کٔن} بنان۔ \n23. یہِ چُھ خداوند سٕنز کٲم۔ یہِ چُھ سانہِ نظرن منز حیرت انگیز۔ {خداوند سٕندِ...: ہیب۔ خداوند سٕندِ طرفہٕ}\n24. یہِ چُھ سُہ دۅہ {یُس}یُس خداوند چُھ بنوومُت۔ أسۍ کرو اتھ پیٹھ شاد تہٕ خۄش۔ \n25.\\tوۅنۍ بچٲوِتھ بہٕ ژے گُزٲرِتھ اے خداوند: اے خداوند، بہٕ چھُس ژے گُزٲرِتھ، وۅنۍ سوز خوشحالی۔ \n26. یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چُھ، سُہ چُھہ تُہٕندِس گَرٕ سٍتـ̡ برکت دِژمٕژ۔ \n27. خدا چُھہ خدا، یُس اسہِ گاش ہٲومُت چُھ: قربانی رَزِ سٍتـ̡ رَزِ سٍتـ̡ گٔنڈِو، {حتیٰ کہ} قربان گاہ ہٕندِس سینگس سٍتـ̡ ۔ \n28. ژٕ چُھکھ میٲنۍ خدا، تہٕ بہٕ کٔرٕ تُہٕندِ تعریف: {تہٕ چُھہ} میٲنۍ خدا، بہٕ کَرٕ ژے بلند۔ \n29. اے خداوند سُند شُکر ادا کرُن؛ تکیازِ {سُہ} چُھہ اصل: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزُن ہمیشہٕ خٲطرٕ۔","1. علیف۔ بابرکت {چھِ} وتہِ منز ناپاک ، یُس خداوند سٕندِس شریعتس مَنٛز پکان چُھ۔ {غیر ناپاک: یا، کامل، یا، مخلص}\n2. تِم چھِ تِم یِم تٔمۍ سٕنزِ گوٲہی تھاوان چھِ، {تہٕ یِم} چھِ أمِس پوٗرٕ دِلہٕ سٍتـ̡ ژھاران۔ \n3. تِم تہِ چھِنہٕ کانہہ بدکاری کران: تِم چھِ تٔمۍ سٕنزِ وتہِ پٲٹھۍ۔ \n4. ژے چُھ حُکُم دِژمُت زِ پَنٕنـ̡ پَنٕنـ̡ ہُند حکم تھاوُن۔ \n5. اے کاش میٲنۍ وتہٕ آسہٕ تُہند قانون برقرار تھاونُک ہدایت دِنہٕ آمُت! \n6. تیلہِ گژھہِ نہ میہ شرم ییلہ میہ چانہِ سارِنٕے حکمن ہُند احترام آسہِ۔ \n7.\\tبہٕ کٔرٕ تۅہہِ سٍتـ̡ سٍتـ�\n8.\\tبہٕ کٔرٕ چانہِ قونوُن: اے میہ کٔرِو نہٕ پوٗرٕ پٲٹھۍ۔ \n9.\\tبیتھ۔ کمہِ سٍتـ̡ کرِ جوان پنٕنۍ وتھ صاف کٔرِتھ؟ تێلہِ کٔرِتھ چُھہ پننہِ کلامٕہ مُطٲبق ہوشیار کٔرِتھ۔ \n10. میہ کٔر پورٕ دِلہٕ سٍتـ̡ ژے ژھانڈنہٕ: اے بہٕ گژھ نہٕ چانہِ حکمن نِش بھٹکُن۔ \n11.\\tچانہِ کلامُک کتھ چُھس میہ پننِس دِلس منز ژوٗرِ تھوومُت، یُتھ بہٕ کرٕ نہٕ ژے خلاف گۅناہ کرنہٕ۔ \n12. بابرکت {آرٹ} اے خداوند: مے ہیچھناوو پنٕنۍ قوانین۔ \n13.\\tمیہ کٔر پننہِ چپنہِ سٍتۍ چانہِ ہندِ سارِنٕے فیصلن ہُند اعلان۔ \n14. بہٕ چُھس چانہِ گوٲہی ہٕندِس وتہِ سٍتـ̡ خوش گومُت، یێلہٕ سٍتـ̡ سارِنٕے دولتس مَنٛز۔ \n15. بہٕ کَرٕ چانہِ ہٕندِس حکمس مَنٛز مراقبہٕ، تہٕ کَرٕ تہندٮ۪ن طریقن ہُند احترام۔ \n16. بہٕ کَرٕ چانہِ قونوٗنَس سٍتـ̡ خۄش: بہٕ کَرٕ نہٕ تُہند کلام مٔشِد۔ \n17. گِمل۔ پننِس خادمس سٍتـ̡ کرو فیاضی سٍتـ̡ تہٕ بہٕ روزٕ تہٕ چانہِ کلامٕچ کٲم کرٕنـ̡ ۔ \n18.\\tمیٲنۍ أچھ کھول، یُتھ بہٕ ہێکہٕ چانہِ شریعت منزٕ حیرت انگیز چیز وُچھِتھ۔ {کھولو: حب۔ ظٲہر کٔرِو}\n19. بہٕ چُھس زمینس مَنٛز اَکھ اَکھ اَجنبی: پَنُن حُکُم مہ کٔرِو نہٕ میہ نِش۔ \n20. میون روح چُھ تُہندِ فٲصلن ہٕندِس حسرتس سٍتـ̡ پھٹان۔ \n21.\\tژے کٔر تِمن مغرورن ملامت کٔرِتھ یِم تہندِس حکمس منز غلطی کران چھِ۔ \n22. میہ نِش کٔرِو ملامت تہٕ حقارت ہٹاو۔ تکیازِ مے چھے تہنز گوٲہی برقرار تھٲومٕژ۔ \n23.\\tشہزادن تہِ بِہتھ {تہٕ} میانہِ خلاف کتھ کٔرِتھ: {مگر} چانہِ خادمَن کٔر چانہِ قونونن مَنٛز مراقبہٕ۔ \n24.\\tتہنز گواہی تہِ چھیہ میٲنۍ خوشی تہٕ میانہِ مشیر۔ {میٲنۍ مشیر: ہیب۔ میانہِ مشورٕکۍ مرد}\n25. دالتھ۔ میون روح چُھس گردِ ژٔٹِتھ ژٔل \n26. مے چُھہ پنٕنـ̡ وتہٕ اعلان کورمُت، تہٕ ژے بوزو: مے ہیچھناوو پنٕنۍ قوانین۔ \n27.\\tمیہ کرو چانہِ حکمن ہنز وتھ سمجھن: یتھے پاٹھۍ کرٕ بہٕ چانہِ حیرت انگیز کامہِ ہنز کتھ کرنہ۔ \n28.\\tمیون روح چُھہ گۅب سٍتـ̡ پۯاوُن: ژے کٔر میہ پننہِ کلامٕ مطٲبق مضبوط۔ {پگھلُن: حب۔ ڈراپتھ}\n29.\\tمیانہِ نِش ہٹاوُن اپُزُک طریقہٕ: تہٕ دِیُن پنُن قانون رحمتہٕ سٍتـ̡ دِنہٕ۔ \n30. میہ چُھ سچٲئی ہٕنز وتھ ژٲرمٕژ: تُہند فٲصلہٕ چُھہ میہ برونہہ کُن تھاونہٕ آمُت۔ \n31. بہٕ چُھس چانہِ گوٲہی پیٹھ ڈٔٹِتھ روزمُت: اے خداوند، مے کٔر نہٕ شرمسار کرنہٕ۔ \n32. بہٕ چُھس چانہِ حُکمن ہٕنزِ وتہِ پٲٹھۍ، یێلہِ ژے میون دِل بٔڑاو۔ \n33. سُہ ۔ اے خداوند، پنہٕ نِس قونونن ہٕنز وتھ ہیچھناوٕنۍ۔ تہٕ بہٕ تھاوٕ یہِ ٲخرس تام۔ \n34.\\tمیہ دِژ سمجھ تہٕ بہٕ کرٕ چانۍ شریعت برقرار تھاون۔ آ، بہٕ کٔرٕ اتھ پورٕ دلہٕ سٍتـ̡ پاس۔ \n35. بہٕ بناو میہ پننین حکمن ہٕنزِ وتہِ پٲٹھۍ۔ تکیازِ بہٕ چُھس اَتھ مَنٛز خۄش۔ \n36. میون دِل کٔرِو پننہِ گوٲہی کُن، نہ کہ لالچس کُن۔ \n37.\\tمیانہِ اچھ پھیُر باطلس نِش۔ {تہٕ} ژے کٔر میہ پننہِ وتہِ منز جلدی۔ {پھیر...: ہیب۔ گزرُن}\n38.\\tپَنُن کلام کٔرِو پننِس خادمس تام، یُس تُہٕندِس خوفس سٍتـ̡ وقف چُھ۔ \n39.\\tمیون ملامت پھیُر یُس بہٕ کھوژان چھُس، تکیازِ چانۍ فٲصلہٕ چھِ اصل۔ \n40. وچھ بہٕ چُھس چانہِ حکمن ہُند انتظار کورمُت: پنہٕ نِس نیکی سٍتـ̡ کٔرِو مے زندٕ۔ \n41. واو۔ اے خداوند، چانۍ نجات تہِ گژھہِ میانہِ نِش، چانہِ کلامٕ مُطٲبق تہِ واتہِ۔ \n42. یُس میہ ملامت کرِ، تِتھۍ سٍتـ̡ جواب دِنہٕ یُس میہ ملامت کرِ، تکیازِ بہٕ چُھس چانہِ کلامس پیٹھ بھروسہ کرُن۔ {توتہ...: یا، یُس میہ کُنہِ چیزس منز ملامت کرِ}\n43.\\tتہٕ کٔرِو نہٕ میانہِ چُھہ سٍتـ̡ حقیقتُک کلام پوٗرٕ پٲٹھـ̡ نیران۔ تکیازِ بہٕ چُھس تہندِس فٲصلس مَنٛز وۅمید کٔرمٕژ۔ \n44. یِتھٕ کٔنۍ بہٕ چُھس چانہِ شریعت ہمیشہٕ خٲطرٕ برقرار تھاوُن۔ \n45.\\tتہٕ بہٕ چُھس آزادیَس سٍتـ̡ پَکُن: کیازِ بہٕ چُھس تُہٕندِس احکام ژھاران۔ {آزادی﴾ اَتھ مَنٛز\n46. بہٕ کَرٕ بادشاہن برونہہ کنہِ تہِ چانہِ گوٲہی ہٕنز کتھ تہٕ بہٕ گژھٕ نہٕ شرمندٕ۔ \n47. تہٕ بہٕ کَرٕ پنُن پان چانہِ حُکمن سٍتـ̡ خۅش کرنہٕ، یُس مےٚ پسند چُھ۔ \n48. بہٕ تُلِتھ تہِ تُلِتھ چانہِ حُکمن تام، یُس میہ محبت چُھس کوٚرمُت۔ تہٕ بہٕ کَرٕ چانہِ قونونن مَنٛز مراقبہٕ۔ \n49.\\tزین۔ پننِس خادمس سٍتۍ کتھ یاد تھاوٕنۍ، یتھ پیٹھ ژے مے وۅمید کٔرمٕژ۔ \n50. یہِ چُھہ میانِس مصیبتَس مَنٛز میٲنۍ آرام دِژمُت، تِکیازِ تُہٕندِس کلامَس سٍتـ̡ چُھہ میہ زندٕ کورمُت۔ \n51.\\tمغرورَن چُھس میہ سٮ۪ٹھاہ طنز کٔرِتھ: {توتہِ} کیا میہ چُھنہٕ چانہِ شریعت نشہِ انکار کورمُت۔ \n52.\\tاے خداوند، میہ چھہ پرانہِ زمانہ چانہِ فیصلہٕ یاد۔ تہٕ کورُن پانس تسلی دِوان۔ \n53.\\tبدکار سٍتـ̡ یُس تُہند شریعت تراوان چُھ، میہ سٍتـ̡ وحشت گٔیہِ۔ \n54.\\tتُہٕندِس مجسمہٕ چھِ میانہِ زیارت کِس گرس مَنٛز میٲنۍ بٲتھ رودمٕتۍ۔ \n55. اے خداوند، رٲژ چُھہ تُہند ناو یاد، تہٕ چُھس چانہِ شریعت برقرار تھاومُت۔ \n56.\\tیہ اوس میہ تکیازِ میہ ٲس چانۍ اصول پور۔ \n57. چیتھ۔ {تُہۍ چُھہ} میٲنۍ حصہٕ، اے خداوند: مے چُھس ووٚنمُت زِ بہٕ کرٕ چانہِ کلام۔ \n58.\\tمیہ کٔر چانہِ سٍتـ̡ پورٕ دِلہٕ سٍتـ̡ رحمت: چانہِ کلامَس مُطٲبق کٔرِو میانہِ سٍتـ̡ رحم۔ {احسان: حب۔ بُتھ}\n59.\\tمیہ سونچُن پننین وتن پیٹھ تہٕ پھیُر پنٕنۍ قدم۔ \n60.\\tمیہ کٔر جلدی تہٕ تُہند حُکُم پورٕ کرنس منز کٔر نہٕ ژیر ۔ \n61.\\tبدکارن ہٕندِس جمٲژ چھُ میہ لُٹمُت: {مگر} بہٕ چُھس نہٕ تُہند قانون مٔشِد گومُت۔ {بینڈ: یا، کمپنی}\n62. نصف رٲژ چُھس بہٕ تہندِ نیک فیصلن سٍتـ̡ تُہند شُکر ادا کرنہٕ خٲطرٕ وۅتھان۔ \n63. بہٕ چُھس تِمن سارِنٕے ہُند سٲتھی یُس تۅہہِ کھوژان چُھ، تہٕ تِمن ہُند یِم تُہٕندِس حکمس پیٹھ عمل کران چھِ۔ \n64. اے خداوند، زمین چُھہ چانہِ رحمتہٕ سٍتـ̡ بٔرِتھ: مے ہیچھناوٕنـ̡ پنٕنۍ قوانین۔ \n65. ٹیتھ۔ اے خداوند، توے چُھہ پننِس خادمس سٍتـ̡ رٔژ سٍتـ̡ سٍتـ� \n66.\\tمیہ ہیچھناوُن اصل فیصلہ تہٕ علم: کیازِ میہ چُھہ چانہِ حکمن پیٹھ یقین کورمُت۔ \n67.\\tمیہ دِنہٕ برونہہ گوس بہٕ گمراہ گومُت، مگر وۅنۍ چُھس میہ چانہِ کلام۔ \n68.\\tژے چُھہ نیک تہٕ نیکی کران۔ میہ ہیچھناوُن پنُن قوانین۔ \n69.\\tمغرورو چھہ میہ خلاف اپُز بناومُت: {مگر} بہٕ تھاوٕ چانۍ اصول پورٕ دِلہٕ سٍتۍ۔ \n70.\\tتِہُند دِل چُھہ چُھس موٚٹُک ہیوٗ موٚٹ۔ {مگر} بہٕ چُھس چانہِ شریعت سٍتـ̡ خۅش سپدان۔ \n71. {یہِ} چُھس میانہِ خٲطرٕ اصل زِ بہٕ چُھس مُتٲثِر گومُت۔ یُتھ بہٕ ہێکہٕ تُہند قونوٗن ہیٚچھِتھ۔ \n72.\\tچانہِ ٲسُک قانون چھُ میانہِ خٲطرٕ ساسہٕ بٔدۍ سۄنہٕ تہٕ رۄپہٕ کھۅتہٕ بہتر۔ \n73.\\tیہود ۔ چانہِ اتھو چُھہ میہ بنوومُت تہٕ بنووُن: مے دِژ سمجھ، یُتھ بہٕ ہێکہٕ چانۍ حُکُم ہیچھِتھ۔ \n74. یِم تۅہہِ کھوژان چھِ، تِم گژھن میہ وُچھِتھ خۄش۔ تکیازِ میہ چھیہ چانہِ کلامس منز وۅمید کٔرمٕژ۔ \n75. اے خداوند، بہٕ چُھس پتاہ زِ تُہند فیصلہٕ چُھ صحیح، تہٕ {یہ} چُھہ ژے وفاداری سٍتـ̡ مے مُتٲثِر کٔرمٕژ۔ {صحیح: حب۔ نیکی}\n76. بہٕ چُھس ژے دُعا کران زِ چانۍ رحم دِل گژھہِ میانہِ آرام دِنہٕ خٲطرٕ، چانہِ خادمس سٍتـ̡ کتھ مُطٲبق۔ {for...: Heb. میہ تسلی دِنہٕ خٲطرٕ}\n77.\\tچانۍ نرم رحمتہٕ گژھہِ میہ نِش، یُتھ بہٕ زندٕ روزُن، تکیازِ چانۍ شریعت چھیہ میٲنۍ خوشی۔ \n78.\\tمغرور گژھہِ شرمندہ گژھُن۔ تکیازِ تِمو کٔر میہ سٍتـ̡ کُنہِ وجہہ ورٲے غلط سلوک کرنہٕ: {مگر} بہٕ کٔرٕ چانہِ حکمن مَنٛز مراقبہٕ۔ \n79. یِم تۅہہِ سٍتـ̡ کھوژان چِھہ، تہٕ یِمن تێہٕنزِ گوٲہی زانان آسہِ۔ \n80.\\tمیون دِل گژھہِ چانہِ قونونن مَنٛز پٲٹھۍ۔ یُتھ زِ بہٕ گژھہِ نہٕ شرمندٕ۔ \n81. کیف۔ میون روح چُھ چانہِ نجات خٲطرٕ بے ہوش گژھان: {مگر} بہٕ چُھس چانہِ کلامس مَنٛز وۅمید کران۔ \n82.\\tمیانہِ اچھ چھیہ چانہِ کلامس سٍتـ̡ یہ ونان زِ ژٕ کر کٔرِکھ میہ تسلی دِنہٕ؟ \n83.\\tکیازِ بہٕ چُھس دھوکہٕ منز بوتلہٕ ہیوٗ بنیومُت۔ {توتہِ} بہٕ چُھس نہٕ تُہند قانون مٔشِد گٔژھان۔ \n84.\\tچانہِ نوکرِ سٕندِ کٲتِہ دۅہہ؟ یِمن سٍتـ̡ کٔرِو تِمن سٍتـ̡ یِمن سٍتـ̡ دِنہٕ آمُت؟ \n85.\\tمغرورو کٔر میانہِ خٲطرٕ کھۄدٕ کھننہٕ، یِم نہٕ تُہندِ قانونس پَتہٕ چھِ۔ \n86. چانہِ سارِنٕے حُکُم چھِ وفادار: تِم چھِ مےٚ غلط سٍتـ̡ ستاونہٕ یِوان۔ ژٕ کٔرِو میانہِ مدد۔ {وفادار: عبرانی۔ وفاداری}\n87.\\tتِمو اوس میہ زمینہِ پیٹھ لگ بھگ کھیوٚومُت۔ مگر بہٕ کٔر نہٕ چانہِ حکمہٕ ترک۔ \n88.\\tپننہِ محبتہٕ پتہٕ کٔر مے زندٕ۔ یِتھٕ پٲٹھۍ تھاوٕ بہٕ چانہِ ٲسٕچ گوٲہی ۔ \n89. لامید۔ اے خداوند، تُہند کلام چُھ ہمیشہٕ خٲطرٕ آسمانس مَنٛز قایم گومُت۔ \n90.\\tتُہٕنز وفاداری چھے سارنٕے نسلن تام: ژے چھے زمینہٕ قایم کٔرمٕژ، تہٕ سُہ چُھ روزان۔ {to...: Heb. نسل تہٕ نسلہٕ خٲطرٕ} {Abideth: Heb. Standed}\n91.\\tتِم چِھہ چُھہ تُہندِ احکام مُطٲبق چُھہ یِمن ہٕندِس سارِنٕے خادمَن ہٕندِ خٲطرٕ۔ \n92. یوٚت تام نہ چانۍ شریعت میانہِ خوشی آسہِ، تیلہِ گژھہِ میہ پننہِ عذابس منز ختم سپدُن۔ \n93.\\tبہٕ چھُس نہٕ تُہٕندِ حکمہٕ زانہہ مٔشِد: تِکیازِ تِمو سٍتـ̡ چُھہ ژے مے زندٕ کٔرمٕژ۔ \n94. بہٕ چُھس تُہٕندِس حکمس سٍتـ̡ بچاوُن۔ کیازِ مے چُھس تُہٕندِس حکمس سٍتـ̡ منگمُت۔ \n95.\\tبدکارو چُھس میہ تباہ کرنُک انتظار کرُن: {مگر} بہٕ کرٕ چانہِ شہادتن پیٹھ غور۔ \n96.\\tمیہ وچھ سارِنٕے کمالُک خاتمہٕ: {مگر} تُہند حکم {چُھ} زیادٕ وسیع ۔ \n97. میم۔ اے میہ کوتاہ محبت چُھس چانہِ قانون! یہ چُھ سٲرۍسٕے دۅہس میون مراقبہٕ۔ \n98.\\tژے چُھہ پننیو حکمو سٍتـ̡ میہ میانین دُشمنن کھۅتہٕ زیادٕ عقلمند بنوومُت: تکیازِ تِم چِھہ ہمیشہ میانہِ سٍتـ̡ آسان۔ {تِم...: ہیب۔ یہ چُھ ہمیشہ میانہِ سٍتـ̡ روزان}\n99.\\tمیہ چھہ پننین سارِنٕے استادن کھۅتہٕ زیادٕ سمجھ: چانہِ شہادتن ہٕندِ خٲطرٕ چُھہ میٲنۍ مراقبہٕ۔ \n100. بہٕ چُھس پرانین کھوتہٕ زیادٕ سمجھان، تکیازِ بہٕ چُھس تہند اصول تھاوان۔ \n101.\\tمیہ چُھس پرٮ۪تھ بد وتہِ نِش پَنٕنـ̡ پۯاونہٕ آمُت، یُتھ بہٕ چُھس چانہِ کَتھ پٲٹھـ̡ \n102.\\tبہٕ چُھس نہٕ چانہِ فیصلہٕ نِش دور گومُت: کیازِ ژے چھے مے ہیچھناومٕژ۔ \n103.\\tچانۍ کتھ کوتاہ میٹھۍ چھیہ میانہِ ذوقہ! {آ، موٚدُر} میانہِ ٲسس پیٹھ! {چکھ: ہیب۔ تالہ}\n104. چانہِ حکمو سٍتۍ چُھس بہٕ سمجھ حٲصل سپدان: لہذا چُھس بہٕ پریتھ غلط طریقہٕ سٍتۍ نفرت۔ \n105.\\tراہب۔ تُہند کلام {چُھ} میانین قدمن خٲطرٕ اکھ چراغ تہٕ میانہِ وتہِ خٲطرٕ گاش۔ {چراغ: یا، شمع}\n106. میہ چھہ قسم، تہٕ بہٕ کرٕ یہ پورٕ زِ بہٕ کرٕ چانۍ نیک فیصلہٕ۔ \n107. بہٕ چُھس واریاہ مُصیبت گومُت: اے خداوند، پننہِ کلامٕ مُطٲبق کٔر مے زندٕ۔ \n108.\\tاے خداوند، میانہِ پننہِ مرضی ہٕنزِ آزادانہ پیشکش قبوٗل کٔرِتھ تہٕ مے ہیچھناوُن پنُن فیصلہٕ۔ \n109.\\tمیون روح چُھہ مُسلسل میٲنس اتھس منز، توتہِ چُھس نہٕ بہٕ تُہند شریعت مٔشِد گٔژھان۔ \n110. بدکارو چُھ میانہِ خٲطرٕ اکھ جال ترٛٲومُت، توتہِ چُھس نہٕ بہٕ چُھس نہٕ چانہِ حکمَن مَنٛز غلطی کٔرمٕژ۔ \n111.\\tچانہِ گوٲہی چھیہ میہ ہمیشہ خٲطرٕ وراثت رٔٹمٕژ: تکیازِ تِم چھِ میانہِ دِلٕچ خوشی ہٕندِس طورس پیٹھ۔ \n112. میہ چُھس پنُن دِل چُھہ تُہند قونوُن ہمیشہٕ انجام دِنہٕ خٲطرٕ، {حتیٰ کہِ ٲخرس تام}۔ {انجام دِنہٕ خٲطرٕ: حب۔ کرُن}\n113. سمیچ۔ بہٕ چُھس {فضول} خیالن سۭتۍ نفرت: مگر تُہند قانون چُھس بہٕ محبت۔ \n114.\\tژے چھکھ میٲنۍ پوشہِ تہٕ میٲنۍ ڈھال: بہٕ چھُس چانہِ کلامس منز وۅمید کران۔ \n115. اے بدکارو، میہ نِش گژھ نیرُن، تکیازِ بہٕ کرٕ پننِس خدایہ سٕندِ حکمس پورٕ۔ \n116. پننہِ کلامٕ مطٲبق تھاو میہ رژھرتھ، یُتھ بہٕ زندٕ روزُن، تہٕ بہٕ گژھ نہٕ پننہِ وۅمید پیٹھ شرمندہ۔ \n117. ژٕ تھپھ کٔرِتھ تہٕ بہٕ روزٕ محفوٗظ: تہٕ بہٕ روزٕ چانہِ قونونن ہُند لگاتار احترام۔ \n118.\\tژے کٔر تِمن سارِنٕے سٍتـ̡ یِم پنہٕ نِس قونونس سٍتـ̡ غلطی کران چھِ، تِکیازِ تِہُند دھوکہٕ چُھہ اپُز۔ \n119.\\tژے کٔر زمینہِ ہٕندِس سارِنٕے بدکارن ہٕندِس سٍتـ̡ ژٔٹِھتھ {یِتھٕ پٲٹھۍ} دٔرِتھ: تێلہِ چُھس بہٕ چُھس چانہِ شہادتن سٍتـ̡ محبت۔ {puttest...: Heb. بند کرنُک سبب}\n120. میون ماز چُھہ ژے سٕندِ خوفہٕ سٍتـ̡ تھرتھران۔ تہٕ بہٕ چُھس چانہِ فٲصلن سٍتـ̡ کھوژان۔ \n121. عین۔ میہ چھہ فیصلہ تہ انصاف کورمُت: میہ تراوو نہ میانین ظالمن پیٹھ۔ \n122. پننِس خادمَس خٲطرٕ بٔنِو نیکی خٲطرٕ ضمانت: مغرور گژھِ نہٕ مےٚ ظُلم کَرُن۔ \n123. میٲنۍ أچھ چِھہ چانہِ نجات خٲطرٕ تہٕ چانہِ نیکی ہٕندِس کلامَس خٲطرٕ ناکام گٔمٕژ۔ \n124. پَنٕنِس خادمَس سٍتـ̡ کٔرِو پَنٕنـ̡ رحمتہٕ مُطٲبِق، تہٕ پَنٕنـ̡ پَنٕنـ̡ قونوٗنـ̡ ہیچھناوٕنـ̡ ۔ \n125.\\tبہٕ چُھس تُہند خادم۔ مے دِژ سمجھ، یُتھ بہٕ ہێکہٕ چانۍ گواہی زانہٕ۔ \n126. {یہ} چُھہ تُہٕندِ خٲطرٕ وقٕت، خداوند، کٲم کرنُک وقٕت: {کیازِ} تِمو چُھ تُہند شریعت کالعدم کورمُت۔ \n127. تێمہِ کِنۍ چُھس بہٕ چُھس چانہِ حُکمن سۄنہٕ سٍتـ̡ زیادٕ پسند۔ آ، سٍتـ̡ \n128.\\tتێلہِ چُھس بہٕ سارِنٕے {تُہٕندِ} اصولن {متعلق} سارِنٕے {چیزن متعلق} احترام کران {تہٕ} بہٕ چُھس پریتھ غلط طریقس سٍتۍ نفرت۔ \n129.\\tPE. تۅہہِ شہادت چھیہ حیرت انگیز: لہذا چھہ میون روح تمن رژھران۔ \n130.\\tچانہِ کلامُک دروازٕ چھُ گاش دِوان۔ یہِ چھُ سادٕ سٍتـ̡ سمجھ دِوان۔ \n131.\\tمیہ کٔر بوش تہٕ ہانپھ کٔرِتھ، تکیازِ بہٕ اوسُس چانہِ حُکمن ہُند طمع کران۔ \n132.\\tمیہ پیٹھ نظر تھاوُن، تہٕ میانہِ سٍتـ̡ رحم کرُن، یِتھٕ پٲٹھـ̡ تہٕ تُہٕندِس ناوس سٍتـ̡ محبت کرن والٮ۪ن سٍتـ̡ کرُن۔ {یِتھٕ پٲٹھـ̡ تُہہ...: Heb. تِمن سٍتـ̡ رسم مُطٲبق، بیترِ}\n133. پننہِ کلامَس مَنٛز کٔرِو میانہِ قدمن ہُند حُکُم: تہٕ کُنہِ تہِ بدکاری گژھہِ نہٕ میانہِ پیٹھ غلبہٕ۔ \n134.\\tبہٕ کٔرِو میہ انسانہ سٕندِ ظلمہٕ نِش بچاوُن: یِتھے پٲٹھۍ کٔرٕ بہٕ چانہِ حکمہٕ پورٕ۔ \n135.\\tپَنُن بُتھ بناو پننِس خادمَس سٍتـ̡ چمکاونہٕ۔ تہٕ مے ہیچھناوُن پنٕنۍ قوانین۔ \n136.\\tآبکۍ دریاو چھہِ میانین اچھن پیٹھ وسان، تکیازِ تم چھہِ نہ چانۍ شریعت تھاوان۔ \n137.\\tتزیدی۔ اے خداوند، تہٕ چُھکھ پنُن فیصلہٕ۔ \n138.\\tتہنز شہادت {یُس} چُھہ حُکُم دِژمُت {چُھہ نیک تہٕ سٮ۪ٹھاہ وفادار۔ {راستباز: عبری۔ نیکی } {وفادار: عبرانی۔ وفاداری}\n139.\\tمیانہِ جوشس چھہ میہ کھیوٚومُت، تکیازِ میانین دشمنن چھیہ چانۍ کتھ مٔشِد گٔمژ۔ {کٔرِتھ...: ہیب۔ ژٔٹِتھ ژٔٹِتھ کٔرِتھ}\n140.\\tتُہند کلام {چُھ} سٮ۪ٹھاہ پاک: تێلہِ چُھہ تُہند خادم اتھ سٍتـ̡ محبت کران۔ {خالص: ہیب۔ کوشش کٔرِتھ، یا نَفِر}\n141.\\tبہٕ چھُس {چھُس} لۄکُٹ تہٕ حقارت: {توتہِ} بہٕ چھُس نہٕ تُہند اصول مٔشِد گٔژھان۔ \n142.\\tتُہٕنز نیکی چھے اکھ ابدی نیکی تہٕ تُہند شریعت چُھ سچ۔ \n143.\\tمصیبت تہٕ غم چھُ میہ رٔٹمُت: {توتہِ} چُھہ چانہِ حُکُم {چھِ} میٲنۍ خۅش۔ {نِنہٕ...: ہیب۔ لٔبِتھ مے لٔبِتھ}\n144. چانہِ شہادتن ہٕنز نیکی چھے ابدی روزان: مے دِژ سمجھ، تہٕ بہٕ روزٕ زندٕ۔ \n145. کوف۔ میہ وۆن پورٕ دِلہٕ سٍتـ̡ دِلہٕ۔ اے خداوند، بہٕ کٔرٕ چانہِ قونونن ہٕندِس حکمس رژھرٕ۔ \n146.\\tمیہ کٔر ژے کُن فریاد میہ بچاو تہٕ بہٕ تھاوٕ چانۍ گوٲہی۔ {تہٕ بہ...: یا، بہٕ تھاوُن}\n147.\\tمیہ رُکٲوُن صُبحُک پھُلُن، تہٕ وَنُن: بہٕ اوسُس چانہِ کلامَس مَنٛز وۅمید کٔرمٕژ۔ \n148.\\tمیانہِ أچھ چھیہ {رٲژ ہٕندِس پَچھرِس} رُکٲوِتھ، یُتھ بہٕ چانہِ کلامَس مَنٛز مراقبہٕ کٔرِتھ۔ \n149.\\tپننہِ محبتہٕ مطٲبق بوز میٲنۍ آواز: اے خداوند، پننہِ فٲصلہٕ مُطٲبق کٔر مے زندٕ۔ \n150.\\tتِم چھِ شرارت پَتہٕ یِنہٕ وٲلِس نزدیک: تِم چھِ تُہٕندِس قانونس نِش دور۔ \n151.\\tاے خداوند، تُہٕندِ سارِنٕے حُکُم چھِ صحیح۔ \n152.\\tچانہِ گوٲہی مُتلِق چُھس میہ پرانہِ پٲٹھـ̡ پتاہ زِ ژے چھے تِمن ہٕنز بُنیاد ہمیشہٕ خٲطرٕ تھٲومٕژ۔ \n153. ریش۔ میانہِ مصیبت سمجھ تہٕ نجات دِیُن، کیازِ بہٕ چُھس نہٕ تُہند شریعت مٔشِد گٔژھان۔ \n154.\\tمیانہِ کامہِ ہٕنز درخواست کٔرِو تہٕ نجات دِیُن: پننہِ کلامٕ مُطٲبق کٔرِو مے زندٕ۔ \n155. نجات {چُھ} بدکارن نِش دور: کیازِ تِم چِھ نہٕ تُہند قونوُن ژھاران۔ \n156. اے خداوند، چانہِ نرم رحمت، اے خداوند: پنٕنۍ فٲصلہٕ مُطٲبق کٔر مے زندٕ۔ {عظیم: یا، واریاہ زیادٕ}\n157.\\tواریاہ چھہِ میانۍ ظلم کرن وٲل تہٕ میٲنۍ دُشمن۔ {توتہِ} بہٕ چُھس نہٕ چانہِ گوٲہی نِش انکار کران۔ \n158.\\tمیہ وُچھ نافرمان تہٕ گۆو غم۔ تکیازِ تِمو کٔر نہٕ تُہند کلام۔ \n159.\\tغور کرو بہٕ کِتھہ پٲٹھـ̡ چُھس چانہِ حکمن سٍتـ̡ محبت کران: اے خداوند، پننہِ محبتہٕ مطٲبق کٔر میہ زندٕ۔ \n160. تُہند کلام {چُھ} پوٚز {ابتداہس پیٹھ} تہٕ چُھہ تُہند پرٮ۪تھ کانہہ نیک فیصلہٕ {ہمیشہٕ خٲطرٕ} برقرار روزُن۔ {تُہند کلام...: حب۔ تُہند کلامُک آغاز چُھ صحیح}\n161. شِن۔ شہزادو کٔر مے کُنہِ وجہہ ورٲے ستاونہٕ: مگر میون دِل چُھ چانہِ کلامَس سٍتۍ خوفزدہ گٔژھان۔ \n162. بہٕ چُھس چانہِ کلامَس پیٹھ خوش گژھان، یُس واریاہ غنیمت میلان چھُ۔ \n163.\\tبہٕ چُھس اپُز سٍتـ̡ نفرت تہٕ نفرت: {مگر} چُھس چانہِ شریعت سٍتـ̡ محبت۔ \n164. بہٕ چُھس دۅہس منز سَتھ لٹہِ چانہِ نیک فیصلن ہٕندِ وجہ سٍتـ̡ تعریف کران۔ \n165.\\tتُہٕندِس شریعس سٍتـ̡ چُھہ تُہٕندِس شریعس سٍتـ̡ س�\n166. خداوند، بہٕ چُھس چانہِ نجات ہٕنز وۅمید کٔرمٕژ، تہٕ چُھس تُہند حکم پورٕ کورمُت۔ \n167. میانہِ روحن چھیہ چانۍ گواہی رژھرٲومژ۔ تہٕ بہٕ چُھس تِمن سٮ۪ٹھاہ محبت۔ \n168.\\tمیہ چھیہ چانۍ اصول تہٕ تہنز شہادت رژھرٲومٕژ، تکیازِ میانہِ سارِنٕے وتہٕ چِھہ ژے برونہہ کُن۔ \n169.\\tتاو۔ اے خداوند، میٲنۍ فریاد گژھہِ پانس برونہہ کُن یِن، اے خداوند، میہ دِژ پننہِ کلامٕ مطٲبق سمجھ۔ \n170. میٲنۍ دُعا گژھہِ پانس برونہہ کُن یِن: پننہِ کلامٕ مُطٲبق کٔرِو مے نجات دِنہٕ۔ \n171.\\tمیٲنۍ وٹھ کٔرِن تعریف، ییلہ ژے مے پنٕنۍ قانون ہیچھناو۔ \n172. میٲنۍ زبان کرِ چانہِ کلامٕچ کتھ کرنہٕ: تِکیازِ چانہِ سارِنٕے حُکُم چھِ نیکی ۔ \n173.\\tپنُن اَتھٕ کٔرِو میانہِ مدد۔ تِکیازِ مے چُھہ چانہِ ہُند احکام ژٲرمُت۔ \n174. اے خداوند، بہٕ چُھس چانہِ نجات ہٕندِ خٲطرٕ آرزو کٔرمٕژ۔ تہٕ تُہند شریعت چُھہ میٲنۍ خوشی ۔ \n175.\\tمیانہِ روح زندٕ روزُن، تہٕ سُہ کرِ چانہِ تعریف۔ تہٕ چانہِ فٲصلہٕ کٔرِن میانہِ مدد۔ \n176. بہٕ چُھس رٲوِتھ کٔرِتھ گٔژھمُت۔ پنُن خادم ژھانڈُن؛ تکیازِ بہٕ چُھس نہٕ تُہند حکم مٔشِد گٔژھان۔","1. [ڈگرین ہُند نغمہٕ۔] مُشکِلَس مَنٛز کٔر میہ خداہس نِش فریاد تہٕ تٔمۍ بوز مےٚ۔ \n2. اے خداوند، میانہِ روح کٔر اپُز چپنہٕ نِش، {تہٕ} دھوکہ دِنہٕ واجنہِ زبانہِ نِش۔ \n3.\\tژے کیا دِیہِ؟ یا کیا گژھہِ ژے دِنہٕ، غلط زبانہِ؟ {کیا دِیہِ...: یا، دھوکہ دِنہٕ واجنہِ زبان کیا دِیہِ ژےٚ؟ یا اَمہ سٍتـ̡ کیا فٲیدٕ دِیہِ؟} {done: Heb. اضٲفہٕ}\n4.\\tطاقتور سٕندِ تیز تیر، جونیپرٕکۍ ژیلہٕ سٍتۍ۔ {تیز...: یا، یہ چھُ طاقتور انسان سٕندِ تیز تیرن ہٕندۍ پٲٹھۍ، جونیپرٕکۍ ژیلہٕ سٍتۍ}\n5.\\tافسوس چھُس میہ میسیکس منز روزان، {یہ} بہٕ چھُس کیدار کین خیمن منز روزان! \n6. میون روح چُھ واریاہ کالہٕ سٍتـ̡ تس سٍتـ̡ روزان یُس امن سٍتـ̡ نفرت کران چُھ۔ \n7.\\tبہٕ چُھس امن خٲطرٕ: مگر ییلہ بہٕ کتھ کران چھُس، تِم چھِ جنگہٕ خٲطرٕ۔ {امن خٲطرٕ: یا، امن خٲطرٕ}","1. [ڈگرین ہُند نغمہٕ۔] بہٕ تُلِتھ پنٕنۍ أچھ بالن کُن، ییتہِ پیٹھہ میون مدد میلہِ۔ {بہٕ کرِ...: یا بہٕ تُلِتھ پنٕنۍ أچھ بالن کُن؟ کتہِ گژھہِ میون مدد؟}\n2. میٲنۍ مدد چُھ خداوند سٕندِ طرفہٕ یُس اسمانس تہٕ زمینہٕ بنوو۔ \n3.\\tسُہ دِیہِ نہٕ تُہٕندِس کھورِ ہٕندِس کھورِ ہٕندِس سٍتـ̡ یُس نہٕ تُہٕندِس کھورِ سٍتـ̡ دِیہِ سُہ چُھہ نہٕ شوٚنگِتھ۔ \n4.\\tیُس اسرٲیلِس رٲچھ کٔرِتھ آسہِ سُہ گژھہِ نہٕ شوٚنگتھ تہٕ نِندٕرِ۔ \n5. خداوند چُھہ تُہُند رٲچھ کَرُن: خداوند چُھہ تُہٕندِس دٔچھنِس اتھس پیٹھ تُہُند سایہٕ۔ \n6.\\tآفتاب گژھہِ نہ دۅہس تہ نہ راتس زونہِ۔ \n7. خداوند کرِ تۅہہِ سارِنٕے بدی نِش بچاوُن: سُہ کرِ تُہند روح رژھراوُن۔ \n8. خداوند کرِ تۅہہِ نیرُن تہٕ یِنہٕ سٍتـ̡ تہٕ ہمیشہٕ خٲطرٕ۔","1. [داؤد سٕندِس درجن ہُند نغمہٕ۔] بہٕ گۆو خۅش ییلہ تِمو مےٚ ووٚن، أسۍ گژھو خداوند سٕندِس گرس مَنٛز۔ \n2. اے یروشلم، سانۍ قدم گژھن چانہِ دروازس اندر کھڑا۔ \n3. یروشلم چُھ أکِس شہرس پٲٹھـ̡ تعمیر کرنہٕ آمُت یُس یکوٹہٕ چُھ: \n4. ییتہِ قبیلہٕ کُنہِ تام واتان چِھ، خداوند سٕندِ قبیلہٕ چِھ اسرٲیلِچ گوٲہی دِنہٕ خٲطرٕ، خداوند سٕندِ ناوُک شُکر ادا کرنہٕ خٲطرٕ۔ \n5.\\tتِکیازِ یێلہِ چُھہ داؤد سٕندِس گرس سٕندِس تختس سٍتـ̡ مقرر کرنہٕ آمُت۔ {are...: Heb. بِہُن}\n6. یروشلم کِس امن خٲطرٕ کٔرِو دُعا: تِم گژھن تۅہہِ سٍتـ̡ محبت کرن وٲلِس سٍتـ̡ ترقی۔ \n7. چانہِ دیوارن مَنٛز آسُن امن، تہٕ پنہٕ نِس محلس مَنٛز آسُن خۄشحالی۔ \n8.\\tمیانین باین تہٕ سٲتھین ہٕندِ خاطرٕ وَنُن بہٕ وَنُن، ژے اندر امن آسُن۔ \n9. خداوند سٕندِ گرٕ سٍتـ̡ بہٕ چُھس چانہِ بھلائی ژھاران۔","1. [ڈگرین ہُند نغمہٕ۔] اے آسمانس منز روزن وٲلس تہٕ ژے کُن تُلِتھ پنٕنۍ أچھ تُلان۔ \n2. وُچھِو، یِتھٕ پٲٹھـ̡ خادمَن ہٕنزِ أچھ پننِس مالہٕ سٕندِس اتھس کُن وُچھان، {تہٕ} پٲٹھـ̡ أکِس کُنہِ کُنہِ ہٕنزِ أچھ پۯاوٕنـ̡ سٍتـ̡ پۯاوٕنـ̡ یێلہِ چُھہ سانہِ أچھ سٲنـ̡ خدایہِ سٕندِس خداہس سٍتـ̡ پى۪ٹھ \n3. اے خداوند، اسہِ پیٹھ رحم کرو اسہِ پیٹھ، کیازِ أسۍ چھہِ بے حسی سٍتـ̡ بٔرِتھ۔ \n4.\\tسانہِ روح چھہ تمن لوکن ہنز حقارت سٍتۍ بٔرِتھ یُس آرام سان آسان چھُ، {تہٕ} مغرورن ہٕنزِ حقارت سٍتـ̡ بٔرِتھ۔","1. [داؤد سُند نغمہٕ۔] یێلہِ نہٕ یہِ خداوند یُس سانہِ طرفہٕ اوس، وُنہِ ہیکہِ اسرٲیلِہ وَنُن؛ \n2. اگر نہٕ یہِ خداوند آسہِ ہا یُس سانہِ طرفہٕ اوس، یێلہِ انسان اسہِ خلاف کھڑا گٔیہِ: \n3. تمہ پتہ اوس تِمو اسہِ جلدی نِلِتھ، ییلہ تِہُند غصہٕ اسہِ سٍتـ̡ دِنہٕ آو: \n4.\\tامہ پتہ اوس آبن اسہِ مغلوب گومت، نالہٕ اوس سانہِ روحس پیٹھ ژٔلتھ: \n5.\\tامہ پتہ اوس فخرُک آب سانہِ روحس پیٹھ۔ \n6. خداوند سُند بابرکت چُھ، یٔمۍ نہٕ اسہِ تہندِ دندن ہُند شکار دِیُت نہٕ۔ \n7.\\tسانہِ روح چھہ جاناوارن ہندِ جالہ منزہ نیبر نیران: جال چھہ پھُٹمُت، تہٕ أسۍ چھہِ ژلان۔ \n8. سون مدد چُھہ خداوند سٕندِ ناوٕ سٍتـ̡ یُس اسمانس تہٕ زمینہٕ بنوو۔","1. [ڈگرین ہُند نغمہٕ۔] یِم خداوند سٍتـ̡ بھروسہٕ چُھہ {یُس نہٕ ہٹٲوِتھ} ہُند پٲٹھـ̡ روزُن، {مگر} روزِ ہمیشہٕ خٲطرٕ۔ \n2. یِتھٕ پٲٹھـ̡ پہاڑ یروشلمس اندۍ پٔکھۍ چِھہ، تِتھے پٲٹھـ̡ چُھ خداوند پنہٕ نـ̡ پۯاوُن پۯاوُن۔ \n3. بدکارن ہٕنز لٔر گژھِ نہٕ نیکوکارن ہٕندِس سٍتـ̡ رٔٹِتھ ۔ یێلہِ گژھِ صٔحیحی پَنٕنـ̡ پَنُن اَتھٕ بُنیادٕ کُن دِنہٕ۔ {بدکار﴾ بدکار}\n4. اے خداوند، نیک کرُن، تہٕ تِمن سٍتـ̡ یِمن ہٕندِس دِلس مَنٛز سیدٕ آسن۔ \n5.\\tیێلہِ یُس پنہٕ نِس کُنہِ وتہِ کُن پھیرِ، خداوند کرِ تِمن بدکار کارن سٍتـ̡ برونہہ کُن: {مگر} اسرٲیلـ̡ سٍتـ̡ گژھہِ سلام۔","1. [ڈگرین ہُند نغمہٕ۔] ییلہ خداوند دُبارٕ صییونُک قید پھیُر، أسۍ ٲسۍ تِمن ہٕندۍ پٲٹھۍ، یُس خواب۔ {پھیرِ...: ہیب۔ واپس}\n2. اَمہِ پَتہٕ گٔیہِ سانہِ چُھس اَسنہٕ سٍتـ̡ بٔرِتھ تہٕ سانہِ زبان گیونہٕ سٍتـ̡ بٔرِتھ بٔرِتھ: تَمہِ پَتہٕ وَنُن تِمو کافرن مَنٛز، خداوند چُھ تِمن خٲطرٕ بٔڈ کٲم کٔرمٕژ۔ {ہَس...: عبرانی۔ تِمن سٍتـ̡ چُھہ بٔڈِتھ کٔرِمُت}\n3. خداوند چُھ سانہِ خٲطرٕ بٔڈ کٲم کٔرمٕژ۔ {یێمہِ سٍتـ̡ أسـ̡ أسـ̡ خوشی چِھہ ۔ \n4. اے خداوند، پنُن قید دُبارٕ پھیُرُن، یِتھٕ پٲٹھۍ، جنوبس مَنٛز نالہٕ۔ \n5.\\tیُس اوٚش واش کران چھہِ تم گژھن خوشی منز لُٹان۔ {خوشی: یا، گیون}\n6. یُس نیران تہٕ روُن، قیمتی بیٲلۍ ہٮ۪تھ، سُہ گژھہِ بلاشبہ خوشی ہیتھ دُبارٕ یِنہٕ، پنٕنۍ گلہٕ {پانس سٍت} أنِتھ۔ {قیمتی...: یا، بیٲلۍ ٹوٗکر}","1. [سلیمان سندِ خٲطرٕ ڈگرین ہُند نغمہٕ۔] یوتام رب سُند گرٕ تعمیر کرُن، تِم چِھ بیکار محنت کران یُس یہٕ تعمیر کران چُھ: یوتام رب شہر رچھِ، چوکیدار چُھ بیکار بیکار بیدار کران۔ {for...: یا، سلیمان} {یہ...: ہیب۔ یُس اتھ منز تعمیر کرن وٲل چِھ}\n2.\\tیہ چھہ بیکار زِ ژیہ سُلہِ وۅتھُن، ژیر تام وۅتھان تہ غمن ہنز روٹی کھیوٚن: {تکیازِ} تہِ چھہ سہ پننہِ محبوبہ نندر دوان۔ \n3. یێلہِ چُھہ بچہٕ خداوند سُند میراث: {تہٕ} رحمُک پھل {چُھ} تٔمۍ سُند انعام۔ \n4. یِتھٕ پٲٹھۍ چھِ تیر أکِس طاقتور انسان سٕندِس اتھس منز۔ یِتھے پٲٹھۍ چھِ نوجوانَن ہٕندِ شُرۍ۔ \n5. خوش باش {چُھ} سُہ انسان یُس تِمو سٍتـ̡ بٔرِتھ چُھہ: تِم گژھن نہٕ شرم کَرُن، مگر تِم گژھن دروازس منز دُشمن سٍتـ̡ کتھ کرنہٕ۔ {تٔمِس...: Heb. تِمو سٍتـ̡ بٔرِتھ بٔرِتھ} {کَتھ...: یا، زیر کٔرِو، یا تباہ کٔرِو}","1. [ڈگرین ہُند نغمہٕ۔] بابرکت چُھہ پریتھ کانہہ یُس خداوند سُند خوف چُھ؛ یُس پننہِ وتہِ پٲٹھـ̡ پکان چُھ۔ \n2.\\tتکیازِ ژے گژھہِ پننہِ اتھن ہنز محنت کھٮ۪وان: خوش روزُن تہٕ یہ گژھہِ ژے سٍتـ̡ رژھ۔ \n3.\\tتہنز زنانہِ آسہِ تۅہہِ کُلِس اندۍ پکھۍ زیتون کُلۍ۔ \n4. وُچھِو یِتھٕ پٲٹھـ̡ خداوند سٕندِس سٍتـ̡ خوفزدہ سپدِ۔ \n5. خداوند کرِ ژے صییون منزٕ برکت: تہٕ ژے گژھہِ پننہِ زندگی ہٕندِس سارِنٕے دۅہن یروشلمٕچ خیر وُچھان۔ \n6. آ، توے وُچھِو پننین بچن ہٕندِس شُرۍ، {تہٕ} اسرٲیلِس سٍتـ̡ سلام۔","1.\\t[ڈگرین ہُند نغمہٕ۔] واریاہ لٹہِ چھہ میہ جوانی پیٹھے مُتٲثر کورمُت، اسرٲیلِس ونہِ ونان: {واریاہ ...: یا، واریاہ زیادہ}\n2.\\tواریاہ لٹہِ چھُ یِمو میانہِ جوانی پیٹھے مُتٲثِر کٔرمٕتۍ، توتہِ چُھنہٕ تِمو میانہِ خٕلاف۔ {واریاہ ...: یا، زیادٕ}\n3.\\tپلوو کٔر میٲنس کمرس پیٹھ ہل دِتھ: تِمو کٔر زیٹھۍ کھال۔ \n4. خداوند چُھہ نیک چُھہ: یێمہِ سٍتـ̡ چُھہ بدکارن ہٕنزِ رزِ ژٔٹِتھ ژٔٹِمٕژ۔ \n5. تِم سارِنٕے گٔژھِن پریشان تہٕ واپس پھیرُن یُس صیونس سٍتـ̡ نفرت۔ \n6.\\tتِم گژھن گاسہٕ ہٕندۍ پٲٹھۍ، یُس امہِ برونہہ کُن کھسنہٕ وُچھان چھُ: \n7. یَتھ سٍتـ̡ ژٹنہٕ وول چُھہ نہٕ پَنُن اَتھٕ بٔرِتھ بٔرِتھ۔ نَہ چُھہ یُس پَنُن سینہ بٔرِتھ چُھہ سُہ بٔرِتھ۔ \n8.\\tیِم تہِ چِھہ ونان زِ خداوند سٕنز برکت تہٕ أسۍ چھِ خداوند سٕندِ ناوٕ سٍتـ̡ برکت دِوان۔","1. [ڈگرین ہُند نغمہٕ۔] اے خداوند، میہ ووت ژے سٍتـ̡ کُنہِ کُنہِ سٍتـ̡ وۆنـ̡ ۔ \n2. خداوند، میٲنۍ آواز بوزو: پَنٕنۍ کَن گژھن میانہِ دُعا ہٕنزِ آوازِ سٍتـ̡ توجہ دِنہٕ۔ \n3. اے خداوند، یێلہِ ژے گُناہ کُس کرُن، اے خداوند، کُس گژھہِ کھڑا روزُن؟ \n4. مگر ژے سٍتـ̡ چُھہ معافی، یُتھ ژیہ خوفہٕ گژھہِ۔ \n5. بہٕ چُھس خداوند سُند انتظار کران، میون روح چُھ انتظار کران، تہٕ تٔمۍ سٕندِس کلامس منز چُھس بہٕ وۅمید کران۔ \n6. میون روح چُھ صُبحَس وُچھان تِمو کھۅتہٕ زیادٕ خداوند سُند انتظار کران: {بہٕ چُھس ونان، تِمو کھۅتہٕ زیادٕ یِم صُبحَس وُچھان چھِ}۔ {بہٕ چُھس ونان...: یا، یُس وُچھان چُھ}\n7. اسرٲیلِس گژھہِ خداوند سٕندِس سٍتـ̡ وۅمید کٔرِتھ: یێلہِ خداوند سٍتـ̡ چُھہ رحمت، تہٕ أمِس سٍتـ̡ چُھہ واریاہ نجات دِنہٕ۔ \n8. تہٕ سُہ کرِ اسرٲیلِس پنہٕ نِس تمام بدکاریو نِش نجات دِنہٕ۔","1. [داؤد سٕندِ درجن ہُند نغمہٕ۔] خداوند، میون دِل چُھنہٕ مغرور تہٕ نہ چُھس میٲنۍ أچھ تھزر: نہ چُھس بہٕ بٔڈۍ معاملن مَنٛز ورزش کران، یا میانہِ خٲطرٕ واریاہ تھدِ چیزن مَنٛز۔ {ورزش...: ہیب۔ واک} {تھزر: ہیب۔ حیرت انگیز}\n2.\\tپزۍ پاٹھۍ چھہ میہ پانس سٍتۍ سلوک تہ ژھۅپہ کورمُت، یُس پننہِ ماجہ نشہِ دوٚپ دِتھ چھُ، میون روح {چھُ} تہِ چھُ۔ {میہ چھُ: ہیب۔ میون روح}\n3.\\tاسرٲیلِس گژھہِ از برونہہ تہٕ ہمیشہٕ خٲطرٕ خداوند سٕنز وۅمید کرٕنۍ۔ {از پتہٕ: ہیب۔ وُن}","1. ڈگرین ہُند نغمہٕ۔ خداوند، داؤد یاد تھاوُن، {تہٕ} تٔمۍ سٕنزِ تمام مصیبت: \n2. کِتھہ پٲٹھـ̡ چُھ سُہ خداوند سٍتـ̡ قسم، {تہٕ} یعقوب سٕندِس طاقتور {خدایہ} سٍتـ̡ عہد کورمُت۔ \n3. یقینا بہٕ واتہٕ نہٕ پننِس گرٕ کِس خیمہ خانس مَنٛز، تہٕ نہ گژھٕ پننِس بسترس مَنٛز۔ \n4.\\tمیہ دِیہ نہ پننین اچھن نندر تہ نندر دِتھ پننین اچھن ٹٲرۍ، \n5.\\tیوتام نہ میہ خداوند سٕندِ خٲطرٕ کانہہ جاے میلہِ، یعقوب سٕندِ طاقتور {خدایہ} سٕندِ خٲطرٕ اکھ بستی۔ {اکھ بستی: عبرانی۔ بستی}\n6.\\tاسہِ بوز یہ افراتس منز: اسہِ لوٚب یہ لٔکرِ ہٕندِس کھہس منز۔ \n7. أسۍ گژھو تٔمۍ سٕندِس خیمہ خانس مَنٛز: أسۍ کرو تٔمۍ سٕندِس قدمن پیٹھ پوٗزا کرنہٕ۔ \n8. اے خداوند، وۅتھٕ پنہٕ نِس آرامس مَنٛز۔ تہٕ تُہٕندِس طاقتُک صندوق۔ \n9. پَنٕنـ̡ پادٕرۍ گژھن نیکی سٍتـ̡ لٔگِتھ۔ تہٕ پۯاوٕنـ̡ ۔ \n10. پننِس خادم داؤد سٕندِ خٲطرٕ گژھ نہٕ پنہٕ نِس مسح کرنہٕ آمُت سُند بُتھ پھیرِ۔ \n11. خداوند چُھ داؤدس سٍتـ̡ سچُھہ حلف دِژمُت۔ سُہ چُھہ نہٕ اَمہ نِش پھیرِ۔ تێنہِ جسمہٕ کِس پھلہٕ سٍتـ̡ بہٕ چُھس تێنہِ تختس پیٹھ بٔنـ̡ ۔ {جسم: عبرانی۔ یٔڈِ}\n12. یێلہِ تُہٕندِ شُرِ میٲنۍ عہد تہٕ میٲنۍ گوٲہی یُس بہٕ تِمن ہیچھناوُن، تِہٕندِ شُرِ تہِ بِہِتھ ہمیشہٕ خٲطرٕ تُہٕندِس تختس پیٹھ۔ \n13. کیازِ خداوند چُھ صیون ژارنہٕ آمُت۔ تٔمۍ چُھ پننہِ بستی خٲطرٕ یژھان۔ \n14. یہ {چُھ} میٲنۍ ہمیشہٕ خٲطرٕ آرام: یتہِ روزٕ بہٕ روزُن؛ کیازِ مے چُھس یہِ یژھان کوٚرمُت۔ \n15.\\tبہٕ کٔرٕ تٔمۍ سٕندِس رزق سٍتۍ سٮ۪ٹھاہ برکت تہٕ بہٕ کٔرٕ تٔمۍ سٕندِس غریبس روٹی سٍتۍ تسٕندِس غریبس پوٗرٕ کرنہٕ۔ {وافر پٲٹھۍ: یا، یقینا}\n16.\\tبہٕ کرٕ تٔمۍ سٕندِس پادٕرین نجات دِنہٕ خٲطرٕ تہٕ تٔمۍ سٕندِس پادٕرَن ہٕندِس پٲٹھـ̡ بَڑِ پٲٹھـ̡ کرٛٮ۪کہٕ دِنہٕ۔ \n17. اَتہِ کَرٕ بہٕ داوُد سُند سینگ بَنُن: مے چُھس پننہِ خٲطرٕ اکھ شمع مقرر کورمُت۔ {چراغ: یا، شَمَبتی}\n18.\\tتٔمۍ سٕندِس دُشمن سٍتـ̡ پوشہٕ بہٕ لَگُن، مگر پانس سٍتـ̡ گژھہِ تٔمۍ سُند تاج۔","1. [داؤد سُند نغمہٕ۔] وُچھِو، کوتاہ اصل تہٕ خۅش چُھہ بٲے یکوٹہ رٔلِتھ روزُن! {یکوٹے...: حب۔ یکوٹہ تہِ}\n2. {یہ} چُھہ کلس پیٹھ قیمتی مرہم ہیو یُس داڑھس پیٹھ وسان اوس، {حتیٰ کہ} ہارون سٕنز داڑھ: یُس تٔمۍ سٕندِس پلون ہٕندِس دارس تام وسان اوس۔ \n3. ہرمون سٕندِ شبنم سٕندۍ پٲٹھۍ، {تہٕ شبنم} یُس صیہون کِس پہاڑن پیٹھ وسان چُھ، تکیازِ تتہِ دِژ خداوند سُند حُکُم، {حتیٰ کہ} ہمیشہٕ خٲطرٕ زندگی۔","1. [ڈگرین ہُند نغمہٕ۔] وُچھو، خداوند سٕندِس سارِنٕے خادم، یُس رٲژ خداوند سٕندِس گرس مَنٛز کھڑا چھُ۔ \n2. پَنٕنۍ اَتھٕ تُلِو مُقدس مَنٛز، تہٕ خداوند سٕنز برکت کٔرِو۔ {مقدس مقام: یا، پاکیزگی}\n3. خداوند یُس اسمانس تہٕ زمینہٕ بنوو، سُہ چُھ ژے صیون نِش برکت دِوان۔","1. خداوند سٕندِس سٍتـ̡ حمد کٔرِو۔ خداوند سٕندِس ناوٕچ حمد کٔرِو۔ اے خداوند سٕندِس خادمَس سٍتـ̡ حمد کٔرِو۔ \n2. یُس خداوند سٕندِس گرس مَنٛز کھڑا چُھ، سانہِ خدایہ سٕندِس گرس مَنٛز، \n3. خداوند سٕنز حمد کٔرِو؛ خداوند سٕندِ خٲطرٕ {چُھ} اصل: تٔمۍ سٕندِس ناوٕچ حمد گٮ۪وُن؛ کیازِ {یہِ} چُھ خۄشگوار ۔ \n4. کیازِکہ خداوند چُھ یعقوب پانس خٲطرٕ ژٲرمُت، {تہٕ} اسرائیلُک خاص خزانہٕ خٲطرٕ۔ \n5. کیازِ بہٕ چُھس پتاہ زِ خداوند {چُھ} عظیم تہٕ {یہ} چُھ سون رب {چُھ} سارِنٕے دیوتاہن پیٹھ۔ \n6. یُس تہِ خداوند خۅش کٔر، سُہ کٔر آسمانس منز، زمینس منز، سمندرن مَنٛز تہٕ سارنٕے سرٛنِس مقامس مَنٛز۔ \n7. سُہ چُھ زمینہٕ کِس اندس پیٹھٕ بخارات کھسان۔ سُہ چُھ روٗدٕ خٲطرٕ بجلی بناوان۔ سُہ چُھ پنٕنِس خزانہٕ منزٕ واو کڈان۔ \n8.\\tیمۍ مصر کِس گۅڈنِس زامتس انسانس تہٕ درندٕ سٕندِس زامتس مار۔ {دۅنوے...: عبرانی۔ انسان پیٹھہ درندس تام}\n9.\\t{یٔمۍ سُو} ژے منز، اے مصر، فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن پیٹھ، تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن سٍتـ̡ \n10. یِمو بٔڈۍ قومن ہُند مارٕ دِیُت، تہٕ طاقتور بادشاہن مارُن۔ \n11.\\tامورین ہُند بادشاہ سِحون تہٕ بشانُک بادشاہ اوگ تہٕ کنعانٕچ سارِنٕے سلطنتہٕ: \n12.\\tتہٕ دِژن پنٕنۍ زمین، اکھ وراثت، اکھ وراثت، یُس اسرٲیلِس پنہٕ نِس لوکَن ہُند میراث۔ \n13.\\tتُہند ناو اے خداوند، {ہمیشہ روزُن} {تہٕ} تُہند یادگار، اے خداوند، سارِنٕے نسلن منز۔ {پورٕ پٲٹھۍ...: ہیب۔ نسل تہٕ نسل}\n14.\\tکیازِ خداوند کرِ پننین لوکن ہُند فیصلہ تہٕ سُہ کرِ پننین خدمتگارن متعلق توبہٕ۔ \n15.\\tکافرن ہٕندِ بُت چھِ رۄپہٕ تہٕ سۄن، یُس انسانن ہٕندِ اتھن ہٕنز کٲم چھِ۔ \n16.\\tتِمن چُھ ٲس، مگر تِم چِھ نہٕ بولان۔ تِمن چِھ أچھ آسان، مگر تِم چِھ نہٕ وُچھان۔ \n17.\\tتِمن چِھ کَن، مگر تِم چِھ نہٕ بوزان۔ تہندِس ٲسس منز چُھ نہٕ {کُنہِ} شاہ۔ \n18. یِم تِمن بناوان چھِ تِمن ہِوۍ آسان: یِمن پیٹھ بھروسہٕ کرن وول چھُ پرٮ۪تھ کانہہ تہِ۔ \n19. اے اسرائیلُک گرٕ خداوند سُند برکت کرُن: اے ہارون سٕندِس گھرس سٍتـ̡ کٔرِو خداوند سٕنز برکت: \n20. اے لیوی ہٕندِس گھرس سٍتـ̡ خداوند سٕندِس سٍتـ̡ برکت دِیُو۔ \n21. یُس یروشلمَس مَنٛز روزان چُھ، صییہون سٍتـ̡ خداوند سُند بابرکت آسُن۔ خداوند سٕندِ حمد کٔرِو۔","1. اے خداوند سُند شُکر ادا کرُن؛ تکیازِ {سُہ} چُھہ اصل: تٔمۍ سٕنزِ رحمتُک {ہمیشہٕ برداش}۔ \n2. اے خدایہ سُند شُکر کرُن: تٔمۍ سٕنزِ رحمتُک {ہمیشہٕ برداش}۔ \n3. اے خداوند سُند شُکر ادا کرُن: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزُن ہمیشہٕ خٲطرٕ۔ \n4. یُس تنہا عظیم عجائب کران چُھ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ۔ \n5.\\tتٔمِس سٍتـ̡ یُس حکمت سٍتـ̡ آسمانہٕ بنوومُت: تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ چُھہ ہمیشہٕ قایم روزُن۔ \n6.\\tتٔمِس سٍتـ̡ یُس آبس پیٹھـ̡ زمینہِ پھٔہلٲوِتھ چُھہ: تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ روزِ ہمیشہٕ خٲطرٕ۔ \n7. یُس عظیم گاش بنوومُت چُھ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ چُھ ہمیشہٕ خٲطرٕ: \n8.\\tآفتاب دۅہلہِ حکمرٲنی کرُن: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ:{حکمرٲنی کرُن...: ہیب۔ دۅہہٕ حُکُمن ہٕندِ خٲطرٕ}\n9.\\tزوٗن تہٕ تارکھ رٲژ ہٕندِ خٲطرٕ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ۔ \n10.\\tتٔمِس سٍتـ̡ یُس مصرس پننِس گۅڈنِکِس زامتس مَنٛز دِژمُت: تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ چُھہ ہمیشہٕ خٲطرٕ: \n11.\\tتہٕ کٔرِن تِمن منزٕ اِسرٲیلِس نیبر، تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ ہمیشہٕ خٲطرٕ: \n12. مضبوٗط اَتھٕ سٍتـ̡ تہٕ نٔرِ ہٕندِس رحمتہٕ سٍتـ̡ ہمیشہٕ سٍتـ̡ برداش۔ \n13.\\tتٔمِس سٍتـ̡ یُس بحرِ احمر حصن مَنٛز تقسیم کٔرِتھ: تٔمۍ سٕنزِ رحمتُک {ہمیشہٕ روزُن}۔ \n14.\\tتہٕ بنووُن اِسرٲیلِس اَتھ مَنٛز نیرُن: تٔمۍ سٕنزِ رحمتَس مۅکھٕ روزِ ہمیشہٕ خٲطرٕ: \n15.\\tمگر فرعون تہٕ تٔمۍ سٕندِس لشکرس سٍتـ̡ ہمیشہٕ سٍتـ̡ دِنہٕ آمُتـ̡ {الٹنہٕ:حب﴾۔ ہُراونہٕ آمُت}\n16.\\tتٔمِس سٍتـ̡ یُس پننین لوکن بیابانن مَنٛز نِوان چُھ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ۔ \n17.\\tتٔمِس سٍتـ̡ یُس بٔڈۍ بادشاہن ہٕندِس رحمتس سٍتـ̡ دِژمُت: \n18.\\tتہٕ مٲرِن مشہور بادشاہ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ {برداش} ہمیشہٕ خٲطرٕ: \n19. امورین ہُند بادشاہ سِحون: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزُن ہمیشہٕ خٲطرٕ: \n20. تہٕ اوگ بشنُک بادشاہ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزُن ہمیشہٕ: \n21.\\tتہٕ دِژُن پنٕنۍ زمین میراثہٕ خٲطرٕ: تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ: \n22.\\t{حتیٰ کہ} اسرٲیلِس سٍتـ̡ میراث، یێمہِ سٕندِ رحمتُک {ہمیشہٕ روزِ} \n23.\\tیُس اسہِ پۯاوُن سانہِ پٔنِس مقامس مَنٛز یاد پٲٹھۍ: تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ چُھہ ہمیشہٕ سٍتـ̡ دِنہٕ آمُت: \n24. تہٕ کٔرٕن اسہِ دُشمنن نِش نجات دِنہٕ: تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ روزِ ہمیشہٕ خٲطرٕ۔ \n25. یُس سارِنٕے مازس کھٮ۪ن دِوان چُھ، تٔمۍ سٕنزِ رحمتہٕ سٍتـ̡ چُھہ ہمیشہٕ دِوان۔ \n26. اے آسمانہٕ کِس خدایہِ سُند شُکر کٔرِو: تٔمۍ سٕنزِ رحمتُک {ہمیشہٕ برداش}۔","1. بابل کِس دریاوَس نِش بِہتھ أسۍ ووٚتھ، آ، أسۍ روُن، ییلہ أسۍ صیون یاد پیوٚو۔ \n2.\\tاسہِ لوٚگ پنٕنۍ ہارپ اَتھ منز وِلوَس پیٹھ۔ \n3.\\tتِکیازِ تِمو یِمو اسہِ اسہِ قٲد کٔرِتھ نِنہٕ آمٕتۍ تِمو ٲسۍ اسہِ نِش اکھ گیونُک ضرورت۔ تہٕ یِمو اسہِ ضایع کٔرِتھ {یِمو اسہِ نِش ضٲبطہٕ کٔرِتھ}، {ونن}، اسہِ گیوُن صیہون کین بٲتن منز {اکھ}۔ {اکھ گیون: ہیب۔ اَکہِ بٲتٕکۍ کلام} {ضایع...: ہیب۔ اسہِ لٔٹِتھ دِنہٕ آمُت}\n4.\\tاسہِ کِتھہ پاٹھۍ گیوو خدایہ سُند بٲتھ عجیب زمینس منز؟ {عجیب...: ہیب۔ اَکھ اجنبی سُند سرزمین؟}\n5. اے یروشلم، یێلہِ بہٕ ژٕ مٔشِد گٔژھِتھ یێلہِ میانہِ دٔچھُن اَتھٕ مٔشِد گٔژھِتھ {تٔمۍ سٕنز چالاکی}۔ \n6.\\tاگر نہ میہ ژیہ یاد آسہِ، میانہِ زبان گژھہِ پننہِ ٲسس پیٹھ تھپھ کٔرتھ۔ اگر نہ میہ یروشلمس پننہِ خوشی کھوتہ زیادہ ترجیح دِتھ۔ {میون سردار...: ہیب۔ میانہِ خوشی ہند سر}\n7. اے خداوند، یروشلم کِس دۅہس مَنٛز ادوم کِس اولادَس یاد تھاوُن۔ یُس ووٚن، رَس {یہ}، رَس {یہِ، حتیٰ کہِ} اَمہ کِس بنیادس تام۔ {رَسُن: حب۔ نٮ۪بر کٔرِو}\n8.\\tاے بابل سٕنزِ کورِ، یُس تباہ گژھُن آسہِ۔ خوش گژھُن، یُس ژے اسہِ خدمت کٔرِتھ بدلہٕ دِیہِ۔ {برباد سپُدُن} {انعام...: ہیب۔ تُہند بدلہٕ دِیُن یُس ژے اسہِ سٍتـ̡ کورمُت چُھ}\n9. خوش باش {کیا سُہ آسہِ}، یُس تُہند لۄکٹۍ بچہٕ کنن پیٹھ رٔٹِتھ تہٕ ٹاس دِوان۔ {کٔنۍ: ہیب۔ کٔنہِ}","1. [{داؤد سُند زبور}] بہٕ کَرٕ پوٗرٕ دِلہٕ سٍتـ̡ تۅہہِ ہٕنز تعریف: دیوتاہن برونہہ کُن گٮ۪وٕ بہٕ ژےٚ تعریف۔ \n2. بہٕ کٔرٕ چانہِ مقدس مندرس کُن عبادت تہٕ چانہِ محبتہٕ خٲطرٕ تہٕ پننہِ حقیقتہٕ خٲطرٕ تہٕ چانہِ سٍتـ̡ ناوٕچ تعریف، تکیازِ ژے چُھہ پنُن کلام سارِوٕے ناوس پیٹھٕ بڑٲومُت۔ \n3. ییمہ دۅہہ میہ روو ژے جواب دِژ، {تہٕ} کٔرٕن میٲنس روحس منز طاقت دِتھ مضبوط۔ \n4. اے خداوند، یێلہِ تُہٕندِس ٲسِس سٍتـ̡ تُہٕندِس کَلامس سٍتـ̡ تُہٕندِس سٍتـ̡ تُہٕندِس سٍت \n5. آ، تِم گٮ۪وَن خداوند سٕنزِ وتہِ مَنٛز: یێلہِ چُھہ خداوند سُند جلال بٔڈِ۔ \n6.\\tیێلہِ چُھہ خداوند تھدِ پٲٹھۍ، توتہِ چُھہ سُہ کمتر لوکن ہُند احترام کران، مگر سُہ چُھہ دوٗر پٲٹھـ̡ زانان۔ \n7. یێلہِ بہٕ مُصیبتس منز پکان چُھس، تہٕ ژے کٔرِکھ میہ زندٕ: تہٕ ژٕ کٔرِکھ میانین دُشمنن ہٕندِس قہر نِش پنُن اتھہٕ تہٕ تُہند دٔچھُن اتھٕ بچاو۔ \n8. خداوند کرِ مُکمل {یُس میہ سٍتـ̡ وابستہٕ چُھہ} چُھہ تُہند رحمت، اے خداوند، {ہمیشہٕ خٲطرٕ برداش} روزُن: پنہٕ نـ̡ پننین اتھن ہٕنزِ کامہِ تراوُن نہٕ۔","1. [اہم موسیقارس تام، داؤد سُند زبور۔] اے خداوند، ژے کٔر میہ ژھانڈمُت، تہٕ زان {مے}۔ \n2.\\tژے چھکھ میون زوال تہٕ میانہِ بغاوت زانان، ژے چھکھ میون خیال دور تام سمجھان۔ \n3.\\tژے چھکھ میانہِ وتہِ تہ میانہِ وتہِ سٍتۍ وابستہ، تہٕ میانین سارنٕے وتن سٍتۍ وٲقف۔ {کمپاسیسٹ: یا، وِنوویسٹ}\n4.\\tمیانہِ زبانہِ منز چھہ نہ کانہہ لفظ، {مگر}، اے خداوند، ژے چھکھ یہ پورہ پاٹھۍ زانان۔ \n5.\\tژے کٔر میہ پتھ کُن تہٕ برونٹھ کُن تہٕ تھووُن میہ پیٹھ اتھہٕ۔ \n6. {یُتھ} علم {چُھ} میانہِ خٲطرٕ واریاہ حیرت انگیز۔ یہ چھُ تھوٚد، بہٕ ہیوٚک نہٕ اتھ تام {حٲصل} کٔرِتھ۔ \n7. بہٕ کوٚت گژھٕ چانہِ روحہٕ نِش نیرُن؟ یا کوٚت ژلہٕ بہٕ چانہِ نِش ژلہٕ؟ \n8.\\tاگر بہٕ جنتس منز کھسُن، تہٕ تُہۍ چھِو تتہِ: اگر بہٕ جہنمس مَنٛز پنُن بسترٕ بناوان چھُس، وُچھ، تُہۍ چھِو تتہِ}۔ \n9. {اگر} بہٕ صبحٕکۍ پَکھ رٔٹِتھ، {تہٕ} سمندرٕ کِس اندِس حصس منز روزان چھُس۔ \n10. تتہِ تہِ گژھہِ چانۍ اتھہ میہ رٔٹتھ تہ چانۍ دچھُن اتھہ رٔٹتھ تہِ۔ \n11.\\tاگر بہٕ وَنُن، یێلہِ گٔیہِ انہِ گٹہِ میہ ؤلِتھ۔ رٲژ تہِ آسہِ میہ اندۍ پکھۍ گاش۔ \n12.\\tآ، انہِ گٹہِ چھہ نہ ژے نِش پوشید۔ مگر رٲژ چھیہ دۅہہکۍ پاٹھۍ چمکان: انہِ گٹہِ تہ گاش چھہِ دۅشوے ہِوۍ۔ {پوشید...: ہیب۔ انہِ گٹہِ تہِ چھہ نہ} {انہِ گوٚٹ تہِ...: ہیب۔ یتھے پاٹھۍ چھہ انہِ گوٚٹ تہِ، گاش تہِ چھہ تہِ}\n13.\\tکیازِ ژے چھُکھ میانہِ ماجہ ہٕندِس رحمس منز میہ ؤلِتھ۔ \n14.\\tبہٕ کٔرٕ تۅہہِ ہٕندِس تعریف۔ تکیازِ بہٕ چُھس خوفہٕ سٍتـ̡ {تہٕ} حیرت انگیز بنیومُت: حیرت انگیز {چُھ} تُہند کامہٕ؛ تہٕ {یہ} میون روح چُھ صحیح پٲٹھـ̡ زانان۔ {صحیح...: ہیب۔ واریاہ زیادٕ}\n15.\\tمیون مادہ اوس نہٕ ژے نِش پوشید، ییلہ بہٕ ژیہ پوشیدٕ پٲٹھۍ، {تہٕ} زمینہٕ کِس بٔنِمِس حصس مَنٛز عجیب پٲٹھۍ بناونہٕ آمُت۔ {مادہ: یا، طاقت، یا، جسم}\n16.\\tچانہِ اچھن وُچھ میون مادہ مگر نامکمل اوس۔ تہٕ تُہنزِ کتابہِ منز ٲسۍ سٲری {میانین ارکان} لیکھنہٕ آمٕتۍ، {یُس} اوس تِمن منز {یُس وُنیُک} اوس نہٕ کانہہ تہِ۔ {سٲری ...: ہیب۔ سارِنٕے ﴾ {کُس...: یا، کمہِ دۅہہٕ گژھن یِم بناوٕن}\n17. اے خدایہ، چانہِ خیال کوتاہ قیمتی چھُ! یِمن ہُند مجموعہ کوتاہ بوٚڈ چھُ! \n18.\\t{اگر} میہ گٔنزراوُن، تِم چھِ سیکہِ کھۅتہٕ زیادٕ تعداد: ییلہ بہٕ بیدار سپدان چھُس، بہٕ چھُس توتہِ ژے سٍتـ̡ آسان۔ \n19.\\tاے خدایہ، یێلہِ کٔرِو میہ نِش نیرُن، اے خونریز۔ \n20.\\tتِکیازِ تِم چھِ تۅہہِ خلاف بدکار کتھ کران، {تہٕ} تُہند دُشمن چھُ {تُہُند ناو} بیکار رٹان۔ \n21. اے خداوند، کیا بہٕ چُھس نہٕ تِمن سٍتـ̡ نفرت؟ تہٕ کیا بہٕ چُھس نہٕ تِمن سٍتـ̡ غمگسار یِم تۅہہِ خلاف کھڑا سپدان چِھ؟ \n22.\\tبہٕ چُھس تِمن سٍتـ̡ نفرت: بہٕ چُھس تِمن پنُن دُشمن مانان۔ \n23.\\tاے خدایہ، میہ ژھانڈ تہٕ میانہِ دِل زان: کوشش کرُن، تہٕ میانہِ خیالن زان: \n24.\\tتہٕ وُچھ زِ میہ منز ما آسہ کانہہ بدکار وتھ، تہٕ مے کٔرِو ابدی وتہِ کُن۔ {بدکار...: حب۔ دگ ہُند وتھ، یا غم}","1. [اہم موسیقارس سٍتـ̡، داؤد سُند زبور۔] اے خداوند، بد انسانس نِش بچٲو میہ بچاو۔ {تشدد...: ہیب۔ تشددُک انسان}\n2.\\tیُس دِلس منز شرارتُک تصور کران چھُ۔ مسلسل چھِ تِم جنگہٕ خٲطرٕ جمع سپدان۔ \n3.\\tتِمو چھُ ناگ ہٕندۍ پٲٹھۍ پنٕنۍ زبان تیز کٔرمٕژ۔ چپنہٕ نِس وَٹھس تَل چُھس زہر {چُھ}۔ سیلہ۔ \n4. اے خداوند، مے بچاوُن بدکارن ہٕندِس اتھہٕ نِش۔ مے بچاوُن ظالم انسانس نِش۔ یِمو میانہِ کُنہِ ہُند ارادٕ چُھ کوٚرمُت۔ \n5. مغرورو چھُ میانہِ خٲطرٕ اکھ جال تہٕ رَزِ ژوٗرِ تھوومُت۔ تِمو چھُ وتہِ نِش جال پھٔہلٲومُت۔ تِمو چھُ میانہِ خٲطرٕ جِن لگٲومُت۔ سیلہ۔ \n6. میہ ووٚن خداوند سٍتـ̡ تہٕ چُھہ میٲنۍ خدایہ: اے خداوند، میانہِ دُعا ہٕنز آواز بوزو۔ \n7. اے خدایہ، میانہِ نجات ہٕندِ طاقتہٕ سٍتـ̡ چُھ جنگہٕ کِس دۅہہٕ مَنٛز میون کلہٕ تھوٚومُت۔ \n8.\\tاے خداوند، بدکارن ہٕنزِ خواہشات مہ دِیُن: تٔمۍ سٕندِس بدکار سٍتـ̡ تہِ گژھہِ نہٕ تٔمۍ سٕندِس بدکار سٍتـ̡ دِنہٕ۔ {یێلہِ} تِم گژھن پانس تھزراونہٕ۔ سلہٕ۔ {یێلہِ...: نتہٕ گژھن نہٕ تِمن تھزراونہٕ یِن}\n9.\\tیِمن ہٕندِس کلہٕ سٍتۍ یِم میہ اندۍ پکھۍ گٔژھِتھ چھِ، تِمن ہٕندِس وُٹھن ہٕنز شرارت کرٕنۍ۔ \n10.\\tتِمن پیٹھ دزنہٕ یِن تہٕ نارس مَنٛز تراونہٕ یُن۔ سرٛنِس گۄڑنَس مَنٛز، یُتھ نہٕ تِم دُبارٕ تھوٚد۔ \n11.\\tزمینس منز گژھہِ نہ کانہہ بدکار بولن وول قایم سپدُن: بد کار گژھہِ ظالم انسانس شکار کرُن۔ {an...: یا، اکھ بدکار بولن وول (عبرانی۔ زبانۍ ہند انسان)، اکھ بدکار انسان، زمینس پیٹھ قایم گژھُن: تس گژھہِ شکار کرنہٕ یُن تٔمۍ سُند تختہٕ الٹنہٕ خٲطرٕ}\n12. بہٕ چُھس پتاہ زِ خداوند کرِ مُصیبت زَن ہُند مقصد، {تہٕ}غریبن ہُند حق۔ \n13. یٔقیٖنی صٔحیح چُھہ تُہٕندِس ناوُک شُکر ادا کَرُن: نیک روزِ تُہٕندِس حٲضِرَس مَنٛز۔","1. [داؤد سُند زبور۔] خداوند، بہٕ چُھس ژے کُن فریاد کران: جلدی کٔرِو میانہِ خٲطرٕ۔ ییلہ بہٕ ژے فریاد کران چُھس میانہِ آوازِ بوز۔ \n2. میٲنۍ دُعا گژھہِ ژے برونہہ کُن پیش کرنہٕ یُن؛ {تہٕ} میانہِ اتھہٕ تُلُن {یِتھ} شامٕچ قربانی۔ {سیٹ...: ہیب۔ ہدایت}\n3. اے خدا، میانہِ ٲسس برونہہ کنہِ تھاو اکھ واچ۔ میانہِ چپُک دروازہ تھوو۔ \n4.\\tمیانہِ دِل کُنہِ تہِ بد چیزس کُن مائل گژھُن، یِمن نفرن سٍتـ̡ بدکار کٲم کٔرِتھ تہٕ بہٕ دِیہ نہٕ تِمن ہٕندِس لذیذس سٍتـ̡ کھٮ۪نہٕ۔ \n5.\\tصالحن دِیُن میہ مارُن؛ {یہِ گژھہِ رحمت: تہٕ سُہ گژھہِ میہ ملامت کرُن؛ {یہِ آسہِ} اکھ بہترین تیٖل، {یُس} میون کلہٕ پھُٹراوِ نہٕ، تکیازِ توتہِ گژھہِ میون دُعا تہِ تہندِس آفتس مَنٛز۔ {مے؛ یہ گژھہِ اَکہ...: یا، بہٕ مہربانی کٔرِتھ، تہٕ مےٚ دِیُن ملامت کرُن؛ تِہُند قیمتی تیٖل پھُٹُن نہٕ وغیرہ}\n6.\\tییلہ تِہٕندِس قاضس کنٮ۪ن جاین پیٹھ والنہٕ یِن، تِم بوزن میٲنۍ کلام۔ تِکیازِ تِم چھِ میٹھۍ۔ \n7.\\tسانۍ اڈجہ چھیہ قبرِ ہندس ٲسس پیٹھ بکھرِتھ، یتھہ پاٹھۍ کانہہ زمینہِ پیٹھ ژٹان تہ ژٹان چھہ۔ \n8. مگر میٲنۍ أچھ چِھہ توے کُن، اے خدایہ: توے چُھس میٲنۍ بھروسہٕ۔ میانہِ روحس تراوُن نہٕ بے چار۔ {تراوُن...: ہیب۔ میون روح مہٕ کٔرِو ننگہ}\n9.\\tمیہ بچاوُن تِمو پھندٕ نِش یُس تمو میانہِ خٲطرٕ ترٲومُت چھُ، تہٕ بدکار کارن ہٕندِس جِنَس نِش۔ \n10.\\tبدکار گژھہِ پننین جالن منز پنہٕ نِس جالس منز، ییلہ زن بہٕ ژلُن۔ {ژلُن: ہیب۔ گزرُن}","1. [داؤد سُند مشکیل؛ اَکھ دُعا ییٚلہِ سُہ گۅپھِ مَنٛز اوس۔] میہ کٔر پننہِ آوازِ سٍتـ̡ خداوند سٕندِس نِش دُعا۔ ﴿مَسکیل...: یا، داؤد سُند زبور، یُس ہُند دُعا دِوان چُھ}\n2.\\tمیہ کٔر تس برونہہ کنہِ پنٕنۍ شکایت۔ میہ ہٲو تس برونہہ کنہِ پنٕنۍ پریشانی۔ \n3.\\tییلہ میون روح میٲنس اندر مغلوب گوو، تیلہِ ژے ٲس میانہِ وتھ زانان۔ یتھ وتہِ میہ پکان اوس، تتھ منز چھہ تمو میانہِ خاطرہ اکھ جال ترٲومُت۔ \n4.\\tمیہ وچھ {میانۍ} دچھنہِ اتھس پیٹھ تہ وُچھمُت، مگر {اتہِ} اوس نہ کانہہ انسان یُس میہ زانان آسہِ: پناہ گاہ ٲس نہ میہ ناکام۔ کٲنسہ تہِ انسانس کٔر نہ میانہِ روحچ پرواہ۔ {میہ وُچھ...: یا دچھُن اتھس پیٹھ وُچھِتھ وُچھ} {ناکام...: ہیب۔ میہ نِش گٔیہِ} {پرواہ...: ہیب۔ ژھانڈنہٕ آمُت}\n5.\\tاے خداوند، میہ ووٚن ژے میٲنۍ پناہ گاہ تہٕ زندٕ سٕندِس سرزمینس مَنٛز میون حصہ۔ \n6. میانہِ فریاد سٍتـ̡ کٔرِو تِکیازِ بہٕ چُھس سٮ۪ٹھاہ پست کرنہٕ آمُت: میانین ستَن والیو نِش نجات دِیُن؛ تِکیازِ تِم چھِ میانہِ کھۅتہٕ زیادٕ مضبوط۔ \n7. میٲنۍ روح کٔرِو قٲد خانہٕ منزٕ نیبر، یُتھ بہٕ چانہِ ناوٕچ تعریف: نیک کرِ میہ اندۍ پکھۍ۔ تکیازِ ژے کٔرِکھ میہ سٍتـ̡ فیاضی سٍتـ̡","1. [داؤد سُند زبور۔] اے خداوند، میانہِ دُعا بوز میانہِ دُعا بوزُن: پننہِ وفاداری سٍتـ̡ کٔر میہ جواب، {تہٕ} پننہِ نیکی سٍتـ̡ ۔ \n2.\\tتہٕ گژھ نہٕ پننِس خادمس سٍتـ̡ فٲصلہٕ کٔرِتھ، تکیازِ تۅہہِ ہٕندِس نظرس منز گژھہِ نہٕ کانہہ تہِ زندٕ انسان انصاف سپدِ۔ \n3. تکیازِ دشمنن کٔر میانہِ روحس ستاونہٕ۔ تٔمۍ کٔر میون زُو زٔمیٖنس مَنٛز۔ تٔمۍ چھُ مےٚ انہِ گٹہِ منز روزُن، یِتھٕ پٲٹھۍ یِم واریاہ کالہٕ پٮ۪ٹھٕ موٗدمٕتۍ چھِ۔ \n4. اَمہِ کِنۍ چُھ میون روح پانس اندر مغلوب گومُت۔ میون دِل چُھ ویران گومُت۔ \n5. میہ چھہ پرانہِ زمانہ یاد پیوان۔ بہٕ چُھس چانہِ سارنٕے کامین پیٹھ غور کران۔ بہٕ چُھس چانہِ اتھن ہٕنزِ کامہِ پیٹھ غور کران۔ \n6. بہٕ چُھس ژے کُن پنُن اتھہٕ پھٔہلاوان: میون روح {ترش} ژے پتہٕ، پیاسہٕ زمینہٕ ہٕندۍ پٲٹھۍ۔ سیلہ۔ \n7. اے خداوند، میٲنۍ روح چُھ ناکام گژھان، میہ نِش گژھ نہٕ پنُن بُتھ ژوٗر، نتہٕ بہٕ گژھہٕ تِمن ہِش یِم گۄڑس مَنٛز وسان چھِ۔ {مُتٲثِر...: یا بہٕ ہِش بَنُن، وغیرہ}\n8. بہٕ کٔرِو بہٕ صُبحَس پنٕنۍ محبتہٕ بوزناوٕن؛ تِکیازِ بہٕ چُھس پانس پیٹھ بھروسہٕ کران: بہٕ کٔرِس وَتہٕ پَکُن پَکُن؛ تِکیازِ بہٕ چُھس پَنُن روح ژے کُن تُلان۔ \n9.\\tاے خداوند، میانین دُشمنن نِش بچاو، بہٕ ژٔلِتھ\n10. مے ہیچھناوُن پنٕنۍ مرضی کرُن؛ تِکیازِ تُہۍ چُھکھ میٲنۍ خدا: تُہند روح {چُھ} اصل۔ مے کٔرِو سیدھی سٕندِس ملکس مَنٛز نِش۔ \n11.\\tاے خداوند، پننہِ ناوٕ خٲطرٕ کٔر میہ زندٕ: پننہِ نیکی خٲطرٕ کٔرِو میون روح مصیبت نِش نیبر۔ \n12. تہٕ پننہِ رحمتہٕ سٍتـ̡ ژٔٹِتھ میٲنۍ دُشمن ژٹِھ، تہٕ تِم سٲری کٔرِن تباہ یُس میانہِ روحس مُتٲثِر کران چُھس، کیازِ بہٕ چُھس تُہند خادم۔","1. [{زبور} داؤد سُند زبور۔] خداوند سُند مُبارک، یُس میانہِ اتھہٕ جنگ کرُن ہیچھناوان چُھ، {تہٕ} میانہِ اونگجہِ لڑنہٕ خٲطرٕ: {طاقت: ہیب۔ پتھر} {جنگہٕ کُن...: حب۔ جنگہٕ خٲطرٕ، وغیرہ}\n2. میٲنۍ نیکی، تہٕ میٲنۍ قلعہٕ؛ میون تھدِ مینار تہٕ میون نجات دِنہٕ وول؛ میٲنۍ ڈھال، تہٕ {سُہ} یس پیٹھ بہٕ بھروسہٕ کران چھُس؛ یُس میانین لوکن پانس تل زیر کران چھُ۔ {میٲنۍ نیکی: یا، میٲنۍ رحمت}\n3. خداوند، انسان کیا چُھ، یُس توے أمِس مُتعلِق زانان چُھ! {یا} انسان سُند نیچو، یُس توے أمِس سُند حساب دِوان چُھ! \n4.\\tانسان چھہ باطل ہیو آسان: تسند دۅہ چھہ ژھایہ ہیو یُس ژلان چھہ۔ \n5. اے خداوند، پَنُن آسمانہٕ کٔرِو نمُن، تہٕ بۄن وُن: پہاڑن اَتھٕ لاگُن، تہٕ تِم گژھن دھوکہٕ۔ \n6.\\tبجلی تراوُن تہٕ پھیُرِو: پَنٕنۍ تیر لگٲوِو تہٕ تباہ کٔرِو۔ \n7. پَنُن اَتھٕ سوز ہیرِ پیٹھ؛ مے کٔرِو آزاد تہٕ بٔڈِس آبس منز، عجیب شُرین ہٕندِس اتھہٕ نِش بچاو۔ {اتھہٕ پیٹھ: ہیب۔ اتھہٕ پیٹھ}\n8.\\tیمۍ سُند دچھُن اتھٕ چھُ کُٹھُک دٔچھُن اتھہٕ۔ \n9. اے خدایہ، بہٕ گٮ۪وٕ ژے خٲطرٕ اکھ نوٚو بٲت: أکِس زبورس پیٹھ {تہٕ} دَہن تارن ہُند ساز، بہٕ گٮ۪وٕ ژے تعریف۔ \n10. {سُہ چُھ} یُس بادشاہن نجات دِوان چُھ، یُس داؤدس پننِس بندس تکلیف دہ تلوار نِش نجات دِوان چُھ۔ {نجات: یا، فتح}\n11. مے کٔر آزاد تہٕ مے کٔر اجنبی شُرین ہٕندِس اتھہٕ نِش بچاو، یِمن ہٕندِس ٲس ٲس باطل بولان تہٕ تِہُند دٔچھُن اتھٕ چُھہ اپُزُک دٔچھُن اتھٕ: \n12.\\tیُتھ زِ سانۍ نیچوۍ آسن جوانی منز بڑن وٲلس کُلۍ۔ {یہ} سانۍ کورِ {آسن} کُنہِ کُنہِ ہندۍ پٲٹھۍ، پالش کٔرِتھ {پَتہٕ} محلٕچ تشبیہ: {پالش: ہیب۔ ژٹ}\n13.\\t{یہ} سانہِ کۅکرِ {ہێکہ} بٔرِتھ آسہِ، پریتھ قسمہ کِس ذخیرس منز دِتھ: {یُتھ} سانہِ کۅکرِ سانین سڑکن منز ساسہٕ بٔدۍ تہٕ داہ ساسہٕ پٲدٕ کٔرِتھ: {سارِنٕے...: ہیب۔ قسمہ پیٹھہ مہجورس تام}\n14.\\t{یہ} سانہِ بیل {ہێکہ} محنت کرنہٕ خٲطرٕ مضبوط۔ {یُتھ} گژھہِ نہ اژُن، نہ نیبر نیرُن۔ {یُتھ} گژھہِ نہ سانہِ سڑکن منز کانہہ شکایت۔ {مضبوط...: ہیب۔ وزن تُلنس لایق، یا ماز سٍتۍ بٔرِتھ}\n15.\\tخوش {کیا یہ} لوکھ چھہِ، یعنی یتھہ پاٹھۍ چھہ:{ہاں}، خوش {کیا یہ} لوک، یہند خدا {چھہ} خدا۔","1. [داؤد سُند زبور تعریف۔] اے بادشاہ، بہٕ کَرٕ تۅہہِ ہٕنز تعریف۔ تہٕ بہٕ کَرٕ تُہند ناو ہمیشہٕ خٲطرٕ برکت۔ \n2. بہٕ کَرٕ پرٮ۪تھ دۅہہ ژےٚ برکت۔ تہٕ بہٕ کَرٕ چانہِ ناوٕچ ہمیشہٕ خٲطرٕ تعریف۔ \n3. عظیم {چُھ} خداوند تہٕ واریاہ تعریف۔ تہٕ تٔمۍ سٕنز عظمتُک {چُھ} ناقابلِ تلاش۔ {تہٕ تٔمِس...: ہیب۔ تہٕ تٔمۍ سٕنزِ عظمتُک چُھنہٕ کانہہ تلاش}\n4. اَکھ پُر کرِ تُہٕندِس کامہِ ہٕندِس تعریفَس سٍتـ̡ تہٕ تُہٕندِس طاقتور عملن ہُند اعلان کرِ۔ \n5. بہٕ کَرٕ چانہِ عظمتٕچ شاندار عزتٕچ تہٕ چانہِ حیرت انگیز کامہِ مُتلِق کتھ کرنہٕ۔ {کامہِ: ہیب۔ چیز، یا، لفظ}\n6. تہٕ {انسان} کرِ چانہِ خوفناک عملن ہٕنزِ طاقتٕچ کتھ تہٕ بہٕ کٔرٕ چانہِ عظمتُک اعلان۔ {اعلان کرو: ہیب۔ اعلان کرُن}\n7. تِم گژھن تُہٕنزِ بٔڈ نیکی ہٕنز یاد وافر پٲٹھۍ، تہٕ تُہٕنزِ نیکی ہُند گٮ۪وُن۔ \n8. خداوند چُھہ مہربان تہٕ رحم دِل سٍتـ̡ بٔرِتھ۔ غصہٕ سٍتـ̡ سُہ چُھہ سُہ سُہ سٍتـ̡ رحمتـ̡ سٍ\n9. خداوند چُھہ سارِنٕے سٍتـ̡ نیکی تہٕ تٔمۍ سٕنزِ سارِنٕے کامہِ پى۪ٹھـ̡ رحمتـ̡ ۔ \n10. اے خداوند، چانہِ سارِنٕے کامہِ کٔرِن تۅہہِ سٍتـ̡ تعریف۔ تہٕ تُہٕندِس مقدسس کٔرِن تۅہہِ سٍتـ̡ برکت دِنہٕ۔ \n11. تِم کرِ تُہنزِ بادشاہی ہٕنزِ عظمتٕچ کتھ تہٕ تُہٕندِس طاقتس مُتلق کتھ کرنہٕ۔ \n12. اِنسانن ہٕندِس نیٚچوِس پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھہٕ پى۪ٹھ۔ \n13. تہنز بادشٲہی {چُھ} اَکھ ابدی بادشٲہی تہٕ تُہٕنز سلطنت چھے سارِنٕے نسلن تام قایم۔ {an...: عبرانی۔ پرٮ۪تھ زمانٕچ بادشاہی}\n14.\\tخداوند چُھ سارِنٕے سٍتـ̡ یێلہِ سٍتـ̡ پۯاونہٕ آمُت، تہٕ سارِنٕے سٍتـ̡ یێلہِ سٍتـ̡ تُلـ̡ دِوان۔ \n15.\\tسارِنٕے ہٕنزِ نظرِ چھِ تۅہہِ ہُند انتظار کران۔ تہٕ تِمن دِیُن تِمن ہُند ماز مُقرر وقتس پیٹھ۔ {انتظار...: یا وُچھِو}\n16. ژٕ چُھکھ پَنُن اَتھٕ کھولُن، تہٕ پرٮ۪تھ کُنہِ جاندار سٕنز خواہش پوٗرٕ کٔرِتھ۔ \n17. خداوند چُھہ پنہٕ نِس سارِنٕے طریقس مَنٛز نیک تہٕ پنہٕ نِس سارِنٕے کامہِ مَنٛز پاک۔ {پاک: یا رحمت، یا، فیاض}\n18.\\tخداوند چُھ تِمن سارِنٕے سٍتـ̡ نزدیک، یِم أمِس سٍتـ̡ پٔزۍ پٲٹھـ̡ پُزناوان چھِ۔ \n19. سُہ کرِ تِمن ہٕنز خواہش پورٕ یِم أمِس کھوژان چھِ، سُہ تہِ کرِ تِہٕنز فریاد تہٕ تِمن بچاوِ۔ \n20. خداوند چُھ تِمن سارِنٕے رژھراوان یِم أمِس محبت کران چھِ، مگر سُہ کرِ سارِنٕے بدکار تباہ ۔ \n21.\\tمیون اوس رب سُند حمد کَرُن: تہٕ سارِنٕے ماز کرِ تٔمۍ سُند پاک ناو ہمیشہٕ خٲطرٕ برکت۔","1. خداوند سٕندِ حمد کٔرِو۔ اے میانہِ روح، خداوند سٕنز حمد کٔرِو۔ {تعریف...: ہیب۔ ہلیلوجاہ}\n2. یێلہِ بہٕ زندٕ روزٕ بہٕ خداوند سٕنز حمد کٔرِتھ: بہٕ گٮ۪وٕ پننِس خدایہ سٕندِ تعریف۔ \n3. شہزادن پیٹھ مہٕ تھٲوِو پَنُن بھروسہٕ، {نَہ} انسان سٕندِس نیٚچوِس پیٹھ، یٔمِس {مَنٛز چُھنہٕ کانہہ مدد}۔ {مدد: یا، نجات دِنہٕ}\n4.\\tتٔمۍ سُند شاہ چُھ نیران، سُہ چُھ پننہِ زمینہِ کُن واپس۔ اَمہ دۅہہ چُھ تٔمۍ سُند خیال ختم گژھان۔ \n5.\\tخوش چھہ زِ یعقوب سُند خدا چُھہ تٔمۍ سٕندِس مددتہٕ خٲطرٕ، یٔمۍ سٕنز وۅمید چُھہ خداوند سٕندِس خداہس سٍتـ̡ ۔ \n6. یمۍ آسمان، زمین، سمندر، تہٕ اَتھ مَنٛز موجود سورُے {is} بنوو: یُس حقیقتس ہمیشہٕ خٲطرٕ برقرار تھاوان چُھ: \n7. یُس مظلومن ہُند فیصلہٕ چُھ انجام دِوان: یُس فاقہٕ مَنٛز کھٮ۪ن دِوان چُھ۔ خداوند چُھ قٲدِ یلہٕ دِوان: \n8.\\tخداوند چُھ اَنٮ۪ن ہٕنزِ أچھ کھولان: خداوند چُھ تِمن ہُند رُکاوٹ کٔرِتھ: خداوند چُھ نیکوکارن سٍتـ̡ محبت کران: \n9. خداوند چُھ اَپرٮ۪ن ہٕندِس رٲچھ کَران۔ سُہ چُھ بے باپ تہٕ بیواہ رژھراوان مگر بدکارن ہٕنزِ وتہٕ چُھ سُہ الٹا پھیران۔ \n10. خداوند کرِ ہمیشہٕ خٲطرٕ بادشاہت، اے صیہون، سارِنٕے نسلن خٲطرٕ۔ خداوند سٕنز حمد کٔرِو۔","1.\\tخداوند سٕندِ حمد کرُن: تکیازِ سٲنِس خدایہ سٕندِ حمد گٮ۪وُن چُھہ اصل۔ تکیازِ {یہ} چُھہ خۅش گُزار؛ {تہٕ} تعریف چُھ خوبصورت۔ \n2. خداوند چُھ یروشلمس تعمیر کران: سُہ چُھ اسرٲیلٕکۍ بے دخل گژھن والین یکجا کران۔ \n3. سُہ چُھ دِلَس مَنٛز پھُٹمُت تہٕ تِہٕندِس زخمس بنٛد کَران۔ {زخم: ہیب۔ غم}\n4. سُہ چُھ ستارن ہُند تعداد وَنان۔ سُہ چُھ تِمن سارِنٕے {تِہندِ} ناوٕ سٍتـ̡ وَنان۔ \n5. عظیم {چُھ} سٲنـ̡ رب تہٕ بۆڈ طاقتُک: تٔمۍ سُند فہم {چُھ} لامحدود۔ {تٔمِس...: ہیب۔ تٔمۍ سٕندِس فہم سٍتـ̡ چُھہ نہٕ کانہہ تعداد}\n6. خداوند چُھ نرمس تُلِتھ تُلِتھ دِوان تہٕ سُہ چُھ بدکار زمینس پیٹھ تراوان۔ \n7. شُکرٕ سٍتـ̡ گیو خدایہِ سٕندِ خٲطرٕ؛ سٲنِس خدایہِ سٕندِ خٲطرٕ گٮ۪وُن ہارپَس پیٹھ تعریف: \n8. یُس آسمانس اوٚبرٕ سٍتـ̡ ؤلِتھ چُھ، یُس زمینہٕ خٲطرٕ روٗد تیار چُھ، یُس پہاڑن پیٹھ گاسہٕ وۄپداونہٕ خٲطرٕ چُھ گاسہٕ بناوان ۔ \n9.\\tسُہ چُھ درندٕ سُند کھٮ۪ن دِوان، {تہٕ} یِمن جوان کۅکَن دِوان یِم کرٛٮ۪وان چھِ۔ \n10.\\tسُہ چُھنہٕ گُرِ سٕندِس طاقتس سٍتـ̡ خۅش گژھان: سُہ چُھہ نہٕ انسان سٕندِس زنگہٕ سٍتـ̡ خۅش سپدان۔ \n11. خداوند چُھ تِمن سٍتـ̡ خوشی حٲصل کران یُس أمِس سٍتـ̡ خوفزدہ چُھ، تِمن سٍتـ̡ یِم تٔمۍ سٕنزِ رحمتٕچ وۅمید تھاوان چھِ۔ \n12. اے یروشلم، خداوند سٕنز حمد کرو۔ اے صیہون، پنہٕ نِس خدایہِ سٕنز حمد کٔرِو۔ \n13. تِکیازِ تٔمۍ کٔر تُہٕندِس دروازن ہٕنزِ سلاخہٕ مضبوٗط۔ تٔمۍ کٔر تۅہہِ ہٕندِس شُرِس مَنٛز برکت۔ \n14.\\tسُہ چُھ تُہٕندِس سرحدس سٍتـ̡ امن کَران، {تہٕ} چُھہ ژے کٕنکہٕ سٍتـ̡ بٔرِتھ۔ {سُہ...: ہیب۔ یُس چُھہ تُہٕندِس سرحدس سٍتـ̡ امن بناوان} {بہترین...: ہیب۔ کٕنُک چربی}\n15.\\tسُہ چُھ پَنُن حُکُم دِوان زِ تٔمۍ سُند کلام چُھ سٮ۪ٹھاہ تیزی سان پکان ۔ \n16. سُہ چُھ شیٖن ییرٕکۍ پٲٹھۍدِوان: سُہ چُھ سوٗر ہٕندۍ پٲٹھۍ۔ \n17.\\tسُہ چُھ پنُن شیٖن پٲٹھۍ، کُس ہیکہِ تٔمۍ سٕندِس سردی برونہہ کُن کھڑا گژھِتھ؟ \n18.\\tسُہ چُھ پَنُن کلام سوزان تہٕ تِم پَنُن واو دِوان تہٕ آب چُھ وَسان۔ \n19. سُہ چُھ یعقوبس سٍتـ̡ پنُن کلام ظٲہر کران، پنٕنـ̡ قونونن تہٕ تٔمۍ سٕندِس فٲصلس سٍتـ̡ اسرٲیلـ̡ سٍتـ̡ ۔ {تٔمۍ سُند کلام: حب۔ تٔمۍ سٕندِس کلام}\n20. تٔمۍ چُھ نہٕ کُنہِ تہِ قومس سٍتـ̡ یُتھ سٍتـ̡","1. خداوند سٕندِ حمد کٔرِو۔ اسمانہٕ پیٹھٕ کٔرِو خداوند سٕنز حمد تہٕ تھزرس مَنٛز کٔرِو تٔمِس تعریف۔ {خداوند سٕنز حمد کرو۔ تعریف: حب۔ ہلیلویا، بیترِ}\n2. تٔمۍ سٕندِس سارِنٕے فرشتہٕ سٕندِس تعریف۔ \n3.\\tآفتاب تہٕ زونہِ ہٕنز حمد کرو أمِس سٕنز تعریف۔ \n4. اے آسمانٕکۍ جنت، تہٕ اے آسمانن ہٕندِس آبس سٍتـ̡ کٔرِو تٔمِس تعریف۔ \n5. تِم گٔژھن خداوند سٕندِ ناوٕچ تعریف: تِکیازِ تٔمۍ دِژ حُکُم، تہٕ تِم آیہ تخلیق کرنہٕ۔ \n6. تٔمۍ تہِ چُھ یِم ہمیشہٕ خٲطرٕ قٲیم کٔرۍمٕتۍ: تٔمۍ چُھ اکھ حکم دِژمُت یُس نہٕ گزرِ۔ \n7. اے ڈریگن تہٕ سارِنٕے سرٛنِس زمینہٕ سٍتـ̡ خداوند سٕنز حمد کٔرِو: \n8. نار، تہٕ ڈولہٕ؛ شیٖن تہٕ بخار؛ طوفانی واو چُھ تٔمۍ سُند کلام پورٕ کران: \n9. پہاڑ تہٕ تمام پہاڑ؛ پھلہٕ دار کُلۍ تہٕ تمام دیودار: \n10.\\tجانور تہٕ سارِنٕے چاروٲے وُچھن وٲلۍ، تہٕ وُڑوُن جاناوار: {وُڑوُن...: ہیب۔ پکھہٕ ہٕندۍ جاناوار}\n11. زمینہِ ہٕندِ بادشاہ تہٕ سارِنٕے لُکھ شہزادٕ تہٕ زمینہِ ہٕندِس سارِنٕے قاضی: \n12.\\tدۅشوے جوان تہٕ کورۍ؛ بُزرگ تہٕ شُرۍ: \n13. تِم گژھن خداوند سٕندِس ناوٕچ حمد کرنہٕ: تِکیازِ تٔمۍ سُند ناو چُھ بہترین۔ تٔمۍ سُند جلال {چُھ} زمینہٕ تہٕ آسمانس پیٹھ۔ {بہترین: ہیب۔ بلند}\n14. سُہ چُھ پنہٕ نـ̡ لُکہٕ سٕندِس سارِنٕے مقدسن ہٕندِس حمدس سٍتـ̡ تُلان۔ یێمہِ سٍتـ̡ چُھہ اِسرٲیلـ̡ ہٕندِس سٍتـ̡","1. خداوند سٕندِ حمد کٔرِو۔ خداوند سٕندِ خٲطرٕ گٮ۪وُن اکھ نوٚو گٮ۪وُن، {تہٕ} مُقدسن ہٕنزِ جماعتس مَنٛز تٔمۍ سٕندِ تعریف۔ {تعریف...: حب۔ ہلیلوجاہ}\n2. اسرٲیلِس گژھہِ تٔمِس سٍتـ̡ شاد سپدُن یُس أمِس بنوومُت چُھہ: صییہونٕکۍ شُرۍ گژھن پننِس بادشاہس سٍتـ̡ خۅش گٔژھن۔ {أمِس منز...: حب۔ تٔمۍ سٕندِس بناونس منز}\n3.\\tتِم گٔژھن تٔمۍ سٕندِس ناوٕچ تعریف: تِم گٮ۪وَن تٔمِس سٕندِس ناوس ہٕندِس تعریفس سٍتۍ۔ {منز...: یا، پایپہٕ سٍتۍ}\n4. خداوند چُھ پننِس لوکَس مَنٛز خوشی حٲصِل کران: سُہ کرِ عاجزن نجات سٍتـ̡ خوبصورت۔ \n5.\\tمقدسن گژھن شان و شوکت منز خۅش گژھن: تِم گژھن پننین بسترن پیٹھ بَڑِ گٮ۪ون۔ \n6.\\tخدایہ سُند تھدِ {تعریف} تہٕ تِہندس اتھس مَنٛز دوٚن دھار تلوار۔ {ٲس: ہیب۔ گٹہٕ}\n7. کافرن سٍتـ̡ انتقام دِنہٕ خٲطرٕ، {تہٕ} لوکن سٍتـ̡ سزا۔ \n8.\\tپننین بادشاہن زنجیرو سٍتۍ تہٕ پننین رئیسن ششتٕرٕچ زنجیر لٲگِتھ گٔنڈِن؛ \n9.\\tیِمن پیٹھ لیکھنہٕ آمُت فیصلہٕ انجام دِنہٕ خٲطرٕ: اتھ عزتس چھِ تٔمۍ سٕندِ سارِنٕے مقدس۔ خداوند سٕندِ حمد کٔرِو۔","1. خداوند سٕندِس حمد کٔرِو۔ تٔمۍ سٕندِس مقدس مقامس مَنٛز کٔرِو خدایہِ سٕندِس حمد تہٕ تٔمۍ سٕندِس طاقتہٕ کِس آسمانس مَنٛز کٔرِو تٔمِس تعریف۔ {حمد کرُن...: ہیب۔ ہلیلویا}\n2. تٔمۍ سٕندِ زبردست عملن ہٕنز تعریف: تٔمۍ سٕنزِ عظمتٕ مطٲبق کٔرِو تٔمِس تعریف۔ \n3.\\tتٔمِس تعریف: زبور تہٕ ہارپ سٍتـ̡ تعریف۔ {ٹرمپیٹ: یا، کارنیٹ}\n4.\\tٹمبرل سٍتۍ کرو تٔمِس تعریف: تار دار سازو تہٕ اعضاء سٍتۍ تعریف۔ {نژُن: یا، پایپ}\n5.\\tبَڑِ آوازن پیٹھ کٔرِو أمِس تعریف: تھدِ آوازن پیٹھ کٔرِو أمِس تعریف۔ \n6. پرٮ۪تھ کانہہ چیز یُس شاہ چُھہ دِنہٕ آمُت چُھ، خداوند سٕنز حمد کرٕنۍ۔ خداوند سٕنز حمد کرٕنۍ۔"];
